def _slice_highlight_color(
    index: int,
    total: int,
) -> tuple[tuple[float, float, float], str]:
    """Return matching matplotlib and Plotly colors for highlighted slices."""
    if total <= 1:
        rgb = (1.0, 59.0 / 255.0, 48.0 / 255.0)
    else:
        red, green, blue, _alpha = plt.get_cmap("rainbow")(
            index / max(total - 1, 1)
        )
        rgb = (float(red), float(green), float(blue))
    plotly_color = (
        f"rgba({rgb[0] * 255:.0f},{rgb[1] * 255:.0f},"
        f"{rgb[2] * 255:.0f},1)"
    )
    return rgb, plotly_color


def _apply_slice_perimeter_style(
    fig,
    color: tuple[float, float, float],
    *,
    thickness: float = 2.5,
) -> None:
    """Draw a visible border around a matplotlib slice plot."""
    for axis in fig.axes:
        if getattr(axis, "name", "") != "rectilinear":
            continue
        for spine in axis.spines.values():
            spine.set_edgecolor(color)
            spine.set_linewidth(float(thickness))


def _apply_plotly_slice_perimeter_style(
    fig: go.Figure,
    color: str,
    *,
    thickness: float = 3.0,
) -> None:
    """Draw a visible border around a Plotly 2D slice plot."""
    existing_shapes = [
        shape for shape in list(fig.layout.shapes or ())
        if not (
            getattr(shape, "type", None) == "rect"
            and getattr(shape, "fillcolor", None) == "rgba(0,0,0,0)"
            and getattr(shape, "layer", None) == "above"
            and getattr(getattr(shape, "line", None), "width", None) is not None
            and getattr(shape, "xref", None) in {"paper", "x domain"}
            and getattr(shape, "yref", None) in {"paper", "y domain"}
        )
    ]
    existing_shapes.append({
        "type": "rect",
        "xref": "x domain",
        "yref": "y domain",
        "x0": 0,
        "x1": 1,
        "y0": 0,
        "y1": 1,
        "line": {"color": color, "width": float(thickness)},
        "fillcolor": "rgba(0,0,0,0)",
        "layer": "above",
    })
    fig.update_layout(shapes=existing_shapes)


def _apply_plotly_2d_slice_aspect(
    fig: go.Figure,
    *,
    width: int,
    height: int,
) -> None:
    """Use a stable outer and inner aspect for Plotly 2D slice heatmaps."""
    fig.update_layout(
        width=width,
        height=height,
        autosize=False,
        margin={"l": 72, "r": 116, "t": 64, "b": 68},
    )
    fig.update_xaxes(domain=[0.0, 0.84], automargin=False)
    fig.update_yaxes(domain=[0.0, 1.0], automargin=False)
    for trace in fig.data:
        colorbar = getattr(trace, "colorbar", None)
        if colorbar is not None:
            trace.update(colorbar={
                "x": 0.9,
                "y": 0.5,
                "len": 0.82,
                "thickness": 18,
            })
        marker = getattr(trace, "marker", None)
        if marker is not None and getattr(marker, "colorbar", None) is not None:
            trace.update(marker={
                "colorbar": {
                    "x": 0.9,
                    "y": 0.5,
                    "len": 0.82,
                    "thickness": 18,
                }
            })


def _pick_session_folder() -> str:
    """Open the platform-native folder picker outside the Streamlit thread."""
    if sys.platform == "darwin":
        script = 'POSIX path of (choose folder with prompt "Select BO experiment or session folder")'
        return subprocess.check_output(["osascript", "-e", script], text=True).strip()
    if sys.platform.startswith("win"):
        code = (
            "import tkinter as tk\n"
            "from tkinter import filedialog\n"
            "root=tk.Tk()\n"
            "root.withdraw()\n"
            "root.wm_attributes('-topmost', True)\n"
            "p=filedialog.askdirectory(title='Select BO experiment or session folder')\n"
            "root.destroy()\n"
            "print(p or '')\n"
        )
        return subprocess.check_output([sys.executable, "-c", code], text=True).strip()
    return ""


def _read_json(path: Path) -> dict:
    with path.open("r", encoding="utf-8") as handle:
        value = json.load(handle)
    if not isinstance(value, dict):
        raise ValueError(f"{path.name} must contain a JSON object")
    return value


def discover_bo_session_folders(folder: str | Path) -> list[Path]:
    """Return BO session folders found at or under an experiment folder."""
    root = Path(folder).expanduser().resolve()
    if not root.is_dir():
        raise ValueError(f"BO experiment/session folder does not exist: {root}")
    discovery_root = root
    if (root / "bo_state.json").is_file():
        if root.parent.name == "bo_sessions":
            discovery_root = root.parent
        elif (root.parent / "bo_sessions").is_dir():
            discovery_root = root.parent

    discovered: list[Path] = []
    seen: set[Path] = set()
    for state_path in [
        discovery_root / "bo_state.json",
        *discovery_root.rglob("bo_state.json"),
    ]:
        if not state_path.is_file():
            continue
        session_root = state_path.parent.resolve()
        if session_root in seen:
            continue
        discovered.append(session_root)
        seen.add(session_root)
    return sorted(
        discovered,
        key=lambda path: (
            0 if path == root else 1,
            (
                len(path.relative_to(discovery_root).parts)
                if path != discovery_root and path.is_relative_to(discovery_root)
                else 0
            ),
            path.name.lower(),
            str(path).lower(),
        ),
    )


def _bo_session_choice_label(path: Path, search_root: Path) -> str:
    """Build a compact session picker label without requiring a full load."""
    try:
        relative = path.relative_to(search_root)
        folder_label = path.name if str(relative) == "." else str(relative)
    except ValueError:
        folder_label = path.name
    try:
        state = _read_json(path / "bo_state.json")
    except Exception:
        return folder_label
    session_id = state.get("session_id")
    observations = state.get("observations") or []
    metadata = state.get("simulation_metadata") or {}
    details = []
    if session_id:
        details.append(str(session_id))
    if metadata.get("compact_export"):
        run_count = metadata.get("run_count")
        if run_count is not None:
            details.append(f"{run_count} compact runs")
        else:
            history_path = path / "history.csv"
            if history_path.is_file():
                try:
                    details.append(f"{len(pd.read_csv(history_path))} history rows")
                except Exception:
                    details.append("compact sweep")
            else:
                details.append("compact sweep")
    elif isinstance(observations, list):
        details.append(f"{len(observations)} observations")
    return f"{folder_label} ({', '.join(details)})" if details else folder_label


def _compact_simulation_observations_from_history(history: pd.DataFrame) -> list[dict]:
    """Rebuild lightweight observations for compact simulation exports."""
    observations = []
    if history is None or history.empty:
        return observations
    for _index, row in history.sort_values(
        ["group_id", "iteration"],
        kind="mergesort",
    ).iterrows():
        try:
            iteration = int(row.get("iteration"))
            group_id = int(row.get("group_id", 1))
            q_run = float(row.get("Q_run", row.get("observed_value")))
        except (TypeError, ValueError):
            continue
        channel_text = str(row.get("ground_truth_channel", row.get("channels", group_id)))
        try:
            channels = [
                int(float(part.strip()))
                for part in channel_text.split(",")
                if part.strip()
            ]
        except ValueError:
            channels = [group_id]
        if not channels:
            channels = [group_id]
        params = {
            parameter: float(row[parameter])
            for parameter in PARAMETERS
            if parameter in history.columns and pd.notna(row.get(parameter))
        }
        channel = str(channels[0])
        group_name_value = row.get("group_name")
        group_name = (
            str(group_name_value)
            if pd.notna(group_name_value)
            else f"Group {group_id}"
        )
        run_label_value = row.get("run_label")
        selection_mode_value = row.get("selection_mode")
        objective_value = row.get("objective")
        exploration_value = _finite_float(row.get("exploration"))
        replicate_value = _finite_float(row.get("replicate"))
        seed_value = _finite_float(row.get("seed"))
        observations.append({
            "iteration": iteration,
            "method_id": f"compact_sim_group_{group_id:02d}_iter_{iteration:03d}",
            "params": params,
            "status": "completed",
            "group_id": group_id,
            "group_name": group_name,
            "channels": channels,
            "objective": (
                str(objective_value)
                if pd.notna(objective_value)
                else "compact_simulation"
            ),
            "Q_run": q_run,
            "quality": {
                "Q_run": q_run,
                "simulation_run_label": (
                    str(run_label_value) if pd.notna(run_label_value) else None
                ),
                "simulation_exploration": exploration_value,
                "simulation_replicate": (
                    int(replicate_value) if replicate_value is not None else None
                ),
                "simulation_seed": int(seed_value) if seed_value is not None else None,
                "selection_mode": (
                    str(selection_mode_value)
                    if pd.notna(selection_mode_value)
                    else None
                ),
                "channel_components": {
                    channel: {
                        "Q_channel": q_run,
                        "classic_Q": q_run,
                        "snr_score": q_run,
                        "normalized_SNR": q_run,
                    }
                },
            },
            "channel_metrics": {
                channel: {
                    "Q_channel": q_run,
                    "classic_Q": q_run,
                    "snr": max(0.0, q_run),
                    "snr_unadjusted": max(0.0, q_run),
                    "success_score": q_run,
                    "mean_peak_current_uA": q_run,
                }
            },
        })
    return observations


def _normalize_simulated_channel_identities(
    observations: list[dict],
    history: pd.DataFrame,
    config: dict,
) -> tuple[list[dict], pd.DataFrame, dict]:
    records = config.get("records") if isinstance(config, dict) else {}
    if not records or not records.get("simulated_session"):
        return observations, history, config
    normalized_history = history.copy()
    if (
        not normalized_history.empty
        and "ground_truth_channel" in normalized_history.columns
        and "Q_run" in normalized_history.columns
    ):
        q_channel_columns = [
            column for column in normalized_history.columns
            if re.fullmatch(r"Q_ch\d+", str(column), re.IGNORECASE)
        ]
        normalized_history = normalized_history.drop(
            columns=q_channel_columns,
            errors="ignore",
        )
        for channel in normalized_history["ground_truth_channel"].dropna().astype(str).unique():
            column = _simulation_history_channel_column(channel)
            channel_rows = (
                normalized_history["ground_truth_channel"].astype(str) == channel
            )
            normalized_history.loc[channel_rows, column] = normalized_history.loc[
                channel_rows,
                "Q_run",
            ]
        normalized_history["channels"] = normalized_history[
            "ground_truth_channel"
        ].astype(str)
    normalized_observations = []
    for observation in observations:
        if not isinstance(observation, dict):
            normalized_observations.append(observation)
            continue
        normalized = dict(observation)
        quality = dict(normalized.get("quality") or {})
        simulation_truth = dict(normalized.get("simulation_truth") or {})
        channel = (
            quality.get("ground_truth_channel")
            or simulation_truth.get("ground_truth_channel")
        )
        if channel is not None:
            channel_text = str(channel)
            channel_values = _simulation_channel_list_value(channel_text)
            q_run = _finite_float(
                normalized.get("Q_run", quality.get("Q_run"))
            )
            normalized["channels"] = channel_values
            components = dict(quality.get("channel_components") or {})
            source_component = {}
            if components:
                source_component = dict(next(iter(components.values())) or {})
            if q_run is not None:
                source_component.setdefault("Q_channel", q_run)
                source_component.setdefault("classic_Q", q_run)
                source_component.setdefault("snr_score", q_run)
                source_component.setdefault("normalized_SNR", q_run)
            quality["channel_components"] = {channel_text: source_component}
            normalized["quality"] = quality
            channel_metrics = dict(normalized.get("channel_metrics") or {})
            source_metrics = {}
            if channel_metrics:
                source_metrics = dict(next(iter(channel_metrics.values())) or {})
            if q_run is not None:
                source_metrics.setdefault("Q_channel", q_run)
                source_metrics.setdefault("classic_Q", q_run)
                source_metrics.setdefault("snr", max(0.0, q_run))
                source_metrics.setdefault("snr_unadjusted", max(0.0, q_run))
                source_metrics.setdefault("success_score", q_run)
                source_metrics.setdefault("mean_peak_current_uA", q_run)
            normalized["channel_metrics"] = {channel_text: source_metrics}
        normalized_observations.append(normalized)
    normalized_config = config
    if (
        isinstance(config, dict)
        and not normalized_history.empty
        and "ground_truth_channel" in normalized_history.columns
    ):
        normalized_config = json.loads(json.dumps(config))
        real_channels = sorted(
            normalized_history["ground_truth_channel"].dropna().astype(str).unique(),
            key=_channel_sort_key,
        )
        normalized_config["channels"] = [
            int(float(channel))
            if _finite_float(channel) is not None
            and float(_finite_float(channel)).is_integer()
            else channel
            for channel in real_channels
        ]
        for group in normalized_config.get("channel_groups") or []:
            if not isinstance(group, dict):
                continue
            group_id = _finite_float(group.get("id"))
            if group_id is None or "group_id" not in normalized_history.columns:
                continue
            rows = normalized_history.loc[
                pd.to_numeric(
                    normalized_history["group_id"],
                    errors="coerce",
                ) == int(group_id)
            ]
            if rows.empty or rows["ground_truth_channel"].dropna().empty:
                continue
            channel = rows["ground_truth_channel"].dropna().astype(str).iloc[0]
            group["ground_truth_channel"] = channel
            group["channels"] = _simulation_channel_list_value(channel)
    return normalized_observations, normalized_history, normalized_config


def load_bo_session(folder: str | Path) -> dict:
    """Load a BO record folder without depending on experiment_automation."""
    root = Path(folder).expanduser().resolve()
    state_path = root / "bo_state.json"
    history_path = root / "history.csv"
    simulation_ground_truth_path = root / "simulation_ground_truth_tensor.csv"
    if not root.is_dir():
        raise ValueError(f"BO session folder does not exist: {root}")
    if not state_path.is_file():
        raise ValueError(f"Not a BO session: {state_path.name} is missing")
    state = _read_json(state_path)
    observations = state.get("observations") or []
    if not isinstance(observations, list):
        raise ValueError("bo_state.json observations must be a list")
    history = pd.read_csv(history_path) if history_path.is_file() else pd.DataFrame()
    config_path = root / "bo_config_snapshot.json"
    config = _read_json(config_path) if config_path.is_file() else {}
    if not observations and not history.empty:
        metadata = state.get("simulation_metadata") or {}
        records = config.get("records") if isinstance(config, dict) else {}
        if metadata.get("compact_export") or records.get("compact_simulation_export"):
            observations = _compact_simulation_observations_from_history(history)
    simulation_ground_truth = (
        pd.read_csv(simulation_ground_truth_path)
        if simulation_ground_truth_path.is_file()
        else pd.DataFrame()
    )
    observations, history, config = _normalize_simulated_channel_identities(
        observations,
        history,
        config,
    )
    return {
        "root": root,
        "state": state,
        "config": config,
        "observations": observations,
        "history": history,
        "simulation_ground_truth": simulation_ground_truth,
    }


def _session_channel_groups(session: dict) -> list[dict]:
    """Return the persisted groups that have observations in this session."""
    def as_list(value) -> list:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        if isinstance(value, set):
            return sorted(value)
        return [value]

    observations = session["observations"]
    observed_ids = {
        int(obs.get("group_id", 1))
        for obs in observations
        if obs.get("group_id", 1) is not None
    }
    configured = (
        session["state"].get("channel_groups")
        or session["config"].get("channel_groups")
        or []
    )
    groups = []
    for raw in configured:
        try:
            group_id = int(raw.get("id", 1))
        except (AttributeError, TypeError, ValueError):
            continue
        if observed_ids and group_id not in observed_ids:
            continue
        groups.append({
            "id": group_id,
            "name": str(raw.get("name") or f"Group {group_id}"),
            "channels": as_list(raw.get("channels")),
        })
    known_ids = {group["id"] for group in groups}
    for obs in observations:
        group_id = int(obs.get("group_id", 1))
        if group_id not in known_ids:
            groups.append({
                "id": group_id,
                "name": str(obs.get("group_name") or f"Group {group_id}"),
                "channels": as_list(obs.get("channels")),
            })
            known_ids.add(group_id)
    return sorted(groups, key=lambda group: group["id"])


def _session_for_channel_group(session: dict, group_id: int) -> dict:
    """Create a group-scoped view while leaving the loaded session untouched."""
    scoped = dict(session)
    scoped["observations"] = [
        obs for obs in session["observations"]
        if int(obs.get("group_id", 1)) == int(group_id)
    ]
    history = session["history"]
    if not history.empty and "group_id" in history.columns:
        ids = pd.to_numeric(history["group_id"], errors="coerce")
        scoped["history"] = history.loc[ids == int(group_id)].reset_index(drop=True)
    scoped["selected_group_id"] = int(group_id)
    return scoped


def _channel_group_optimization_metadata(
    session: dict,
    groups: list[dict],
) -> list[dict]:
    """Merge global acquisition defaults with persisted per-group overrides."""
    config = session.get("config") or {}
    acquisition = config.get("acquisition") or {}

    def as_dict(value) -> dict:
        return dict(value) if isinstance(value, dict) else {}

    def as_list(value) -> list:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        if isinstance(value, set):
            return sorted(value)
        return [value]

    def groups_by_id(raw_groups) -> dict[int, dict]:
        result = {}
        for raw_group in raw_groups or []:
            if not isinstance(raw_group, dict):
                continue
            try:
                result[int(raw_group["id"])] = raw_group
            except (KeyError, TypeError, ValueError):
                continue
        return result

    config_groups = groups_by_id(config.get("channel_groups"))
    state_groups = groups_by_id(
        (session.get("state") or {}).get("channel_groups")
    )
    history = session.get("history")
    history_groups: dict[int, dict] = {}
    if (
        isinstance(history, pd.DataFrame)
        and not history.empty
        and "group_id" in history.columns
    ):
        metadata_columns = {
            "exploration",
            "initial_random_points",
            "candidate_pool_size",
            "local_candidate_pool_size",
            "gp_noise_level",
            "gp_optimizer_restarts",
            "replicate",
            "seed",
        }
        available_metadata_columns = [
            column for column in metadata_columns
            if column in history.columns
        ]
        falloff_columns = [
            column for column in ("gp_falloff_parameter", "gp_falloff_value")
            if column in history.columns
        ]
        name_columns = [
            column for column in ("group_name", "run_label")
            if column in history.columns
        ]
        channel_columns = [
            column for column in ("channels", "ground_truth_channel")
            if column in history.columns
        ]
        for raw_group_id, rows in history.groupby(
            "group_id",
            sort=False,
            dropna=True,
        ):
            group_id_value = _finite_float(raw_group_id)
            if group_id_value is None:
                continue
            group_id = int(group_id_value)
            row_settings: dict[str, Any] = {}
            for column in available_metadata_columns:
                values = rows[column].dropna()
                if values.empty:
                    continue
                numeric_value = _finite_float(values.iloc[0])
                setting_key = {
                    "initial_random_points": "n_initial_points",
                    "replicate": "simulation_replicate",
                    "seed": "simulation_seed",
                }.get(column, column)
                row_settings[setting_key] = (
                    numeric_value
                    if numeric_value is not None
                    else values.astype(str).iloc[0]
                )
            for column in name_columns:
                values = rows[column].dropna()
                if not values.empty:
                    row_settings["name"] = str(values.astype(str).iloc[0])
                    break
            for column in channel_columns:
                values = rows[column].dropna()
                if values.empty:
                    continue
                raw_channels = str(values.astype(str).iloc[0])
                channels = [
                    part.strip()
                    for part in raw_channels.split(",")
                    if part.strip()
                ]
                if channels:
                    row_settings["channels"] = channels
                    break
            if set(falloff_columns) == {
                "gp_falloff_parameter",
                "gp_falloff_value",
            }:
                parameter_values = rows["gp_falloff_parameter"].dropna()
                value_values = rows["gp_falloff_value"].dropna()
                if not parameter_values.empty and not value_values.empty:
                    falloff_value = _finite_float(value_values.iloc[0])
                    if falloff_value is not None:
                        row_settings["gp_falloff_fractions"] = {
                            str(parameter_values.astype(str).iloc[0]): falloff_value
                        }
            if row_settings:
                history_groups[group_id] = row_settings
    metadata = []
    for group in groups:
        if not isinstance(group, dict):
            continue
        try:
            group_id = int(group.get("id", 1))
        except (TypeError, ValueError):
            continue
        settings = {
            "exploration": acquisition.get(
                "exploration", config.get("exploration")
            ),
            "n_initial_points": config.get("n_initial_points"),
            "candidate_pool_size": acquisition.get(
                "candidate_pool_size", config.get("candidate_pool_size")
            ),
            "local_candidate_pool_size": acquisition.get(
                "local_candidate_pool_size",
                config.get("local_candidate_pool_size"),
            ),
            "initial_point_mode": acquisition.get(
                "initial_point_mode", config.get("initial_point_mode")
            ),
            "use_gp": acquisition.get("use_gp", config.get("use_gp")),
            "gp_optimizer_restarts": acquisition.get(
                "gp_optimizer_restarts", config.get("gp_optimizer_restarts")
            ),
            "gp_falloff_fractions": as_dict(
                acquisition.get("gp_falloff_fractions")
            ),
            "gp_length_scales": as_dict(acquisition.get("gp_length_scales")),
            "initial_parameters": as_dict(config.get("initial_parameters")),
        }
        settings.update(as_dict(config_groups.get(group_id)))
        settings.update(as_dict(state_groups.get(group_id)))
        settings.update(as_dict(history_groups.get(group_id)))
        exploration = settings.get("exploration")
        try:
            exploration = float(exploration)
            if not np.isfinite(exploration):
                exploration = None
                exploitation = None
            else:
                exploitation = (
                    1.0 - exploration if 0.0 <= exploration <= 1.0 else None
                )
        except (TypeError, ValueError):
            exploration = None
            exploitation = None
        metadata.append({
            "id": group_id,
            "name": str(settings.get("name") or group.get("name") or f"Group {group_id}"),
            "channels": as_list(settings.get("channels") or group.get("channels")),
            "exploration": exploration,
            "exploitation": exploitation,
            "n_initial_points": settings.get("n_initial_points"),
            "candidate_pool_size": settings.get("candidate_pool_size"),
            "local_candidate_pool_size": settings.get(
                "local_candidate_pool_size"
            ),
            "initial_point_mode": settings.get("initial_point_mode"),
            "use_gp": settings.get("use_gp"),
            "gp_optimizer_restarts": settings.get("gp_optimizer_restarts"),
            "gp_falloff_fractions": as_dict(
                settings.get("gp_falloff_fractions")
            ),
            "gp_length_scales": as_dict(settings.get("gp_length_scales")),
            "initial_parameters": as_dict(settings.get("initial_parameters")),
            "gp_noise_level": settings.get("gp_noise_level"),
            "simulation_seed": settings.get("simulation_seed"),
            "simulation_replicate": settings.get("simulation_replicate"),
            "simulated_session": bool(settings.get("simulated_session", False)),
        })
    return metadata


def _metadata_family_value_token(value: Any) -> str:
    numeric = _finite_float(value)
    if numeric is not None:
        return f"{numeric:.12g}"
    return re.sub(r"[^A-Za-z0-9._-]+", "_", str(value)).strip("_")


def _metadata_family_value_label(value: Any) -> str:
    numeric = _finite_float(value)
    if numeric is not None:
        return f"{numeric:g}"
    return str(value)


def _observation_group_family_options(
    metadata: list[dict],
    available_group_ids: set[int],
) -> dict[str, dict]:
    families: dict[tuple[str, str, str], set[int]] = {}

    def add_family(kind: str, label: str, value: Any, group_id: Any) -> None:
        numeric_group_id = _finite_float(group_id)
        if numeric_group_id is None:
            return
        group_int = int(numeric_group_id)
        if group_int not in available_group_ids:
            return
        numeric_value = _finite_float(value)
        if numeric_value is None:
            return
        token = _metadata_family_value_token(numeric_value)
        families.setdefault((kind, label, token), set()).add(group_int)

    for item in metadata:
        group_id = item.get("id")
        add_family(
            "exploration",
            f"Explore weight = {_metadata_family_value_label(item.get('exploration'))}",
            item.get("exploration"),
            group_id,
        )
        add_family(
            "initial",
            (
                "Initial maximin points = "
                f"{_metadata_family_value_label(item.get('n_initial_points'))}"
            ),
            item.get("n_initial_points"),
            group_id,
        )
        for parameter, value in (item.get("gp_falloff_fractions") or {}).items():
            add_family(
                f"gp_falloff:{parameter}",
                (
                    f"{_metric_label(parameter)} GP falloff = "
                    f"{_metadata_family_value_label(value)}"
                ),
                value,
                group_id,
            )

    options: dict[str, dict] = {}
    for (kind, label, token), group_ids in sorted(
        families.items(),
        key=lambda entry: (entry[0][0], entry[0][1], entry[0][2]),
    ):
        if not group_ids:
            continue
        key = f"family:{kind}:{token}"
        sorted_ids = sorted(group_ids)
        options[key] = {
            "ids": sorted_ids,
            "label": f"{label} ({len(sorted_ids)} groups)",
        }
    return options


def _observation_table(session: dict) -> pd.DataFrame:
    def add_best_q_column(frame: pd.DataFrame) -> pd.DataFrame:
        if frame.empty or "Q_run" not in frame.columns:
            return frame
        result = frame.copy()
        q_values = pd.to_numeric(result["Q_run"], errors="coerce")
        iterations = pd.to_numeric(
            result.get(
                "iteration",
                pd.Series(range(1, len(result) + 1), index=result.index),
            ),
            errors="coerce",
        )
        group_ids = pd.to_numeric(
            result.get("group_id", pd.Series(1, index=result.index)),
            errors="coerce",
        ).fillna(1)
        best_q = pd.Series(np.nan, index=result.index, dtype=float)
        order_frame = pd.DataFrame({
            "group_id": group_ids,
            "iteration": iterations,
            "q_value": q_values,
            "_source_order": range(len(result)),
        }, index=result.index)
        for _group_id, group_rows in order_frame.groupby("group_id", sort=False):
            ordered = group_rows.sort_values(
                ["iteration", "_source_order"],
                kind="mergesort",
            )
            best_q.loc[ordered.index] = ordered["q_value"].cummax()
        result["best_Q"] = best_q
        return result

    history = session["history"].copy()
    rows = []
    for obs in session["observations"]:
        row = {
            "iteration": obs.get("iteration"),
            "group_id": obs.get("group_id", 1),
            "group_name": obs.get("group_name", "Group 1"),
            "channels": ",".join(str(channel) for channel in obs.get("channels", [])),
            "Q_run": obs.get("Q_run"),
            "objective": obs.get("objective"),
            "completed_at": obs.get("completed_at"),
        }
        row.update(obs.get("params") or {})
        for key, value in (obs.get("quality") or {}).items():
            if np.isscalar(value) and not isinstance(value, (str, bytes)):
                row[key] = value
        for source_name, prefix in (
            ("channel_metrics", ""),
            ("buffer_channel_metrics", "buffer_"),
            ("target_channel_metrics", "target_"),
        ):
            for channel, metrics in (obs.get(source_name) or {}).items():
                for key, value in (metrics or {}).items():
                    if np.isscalar(value) and not isinstance(value, (str, bytes)):
                        row[f"ch{channel}_{prefix}{key}"] = value
        components = (obs.get("quality") or {}).get("channel_components") or {}
        for channel, metrics in components.items():
            for key, value in (metrics or {}).items():
                if np.isscalar(value) and not isinstance(value, (str, bytes)):
                    row.setdefault(f"ch{channel}_{key}", value)
        rows.append(row)
    observation_frame = pd.DataFrame(rows)
    if history.empty:
        return add_best_q_column(observation_frame)
    if observation_frame.empty:
        return add_best_q_column(history)

    missing_columns = [
        column for column in observation_frame.columns
        if column not in history.columns
    ]
    if missing_columns:
        history = pd.concat(
            [
                history,
                pd.DataFrame(
                    np.nan,
                    index=history.index,
                    columns=missing_columns,
                ),
            ],
            axis=1,
        )
    history_group = pd.to_numeric(
        history.get("group_id", pd.Series(1, index=history.index)),
        errors="coerce",
    ).fillna(1).astype(int)
    history_iteration = pd.to_numeric(history["iteration"], errors="coerce")
    for _, row in observation_frame.iterrows():
        mask = (
            (history_group == int(row.get("group_id", 1)))
            & (history_iteration == int(row["iteration"]))
        )
        matching = history.index[mask]
        if matching.empty:
            continue
        index = matching[0]
        for column, value in row.items():
            if pd.notna(value):
                history.at[index, column] = value
    return add_best_q_column(history)


def _numeric_columns(frame: pd.DataFrame) -> list[str]:
    excluded = {
        "iteration", "group_id", "paired_cycle", "paired_batch_index",
        "buffer_trace_number", "target_trace_number",
    }
    return [
        column for column in frame.columns
        if (
            column not in excluded
            and pd.to_numeric(frame[column], errors="coerce").nunique(dropna=True) > 1
        )
    ]


def _channel_metric_columns(frame: pd.DataFrame) -> dict[str, dict[str, str]]:
    """Return metric -> channel -> history-column mappings."""
    metrics: dict[str, dict[str, str]] = {}
    for column in frame.columns:
        q_match = re.fullmatch(r"Q_ch(\d+)", str(column), re.IGNORECASE)
        component_match = re.fullmatch(r"ch(\d+)_(.+)", str(column), re.IGNORECASE)
        if q_match:
            channel, metric = q_match.group(1), "Q_channel"
        elif component_match:
            channel, metric = component_match.group(1), component_match.group(2)
        else:
            continue
        if pd.to_numeric(frame[column], errors="coerce").nunique(dropna=True) > 1:
            metrics.setdefault(metric, {})[channel] = column
    return metrics


def _metric_label(metric: str) -> str:
    replacements = {
        "best_Q": "Best Q",
        "Q_channel": "Channel Q",
        "Q_run": "Q run",
        "frequency_at_best_q": "Frequency at best Q",
        "amplitude_at_best_q": "Amplitude at best Q",
        "step_potential_at_best_q": "Step size at best Q",
        "mean_peak_current_uA": "Peak height (µA)",
        "median_peak_current_uA": "Peak height (µA)",
        "snr_unadjusted": "Raw SNR",
        "uA": "µA",
    }
    if metric in replacements:
        return replacements[metric]
    return metric.replace("_", " ").strip().title().replace("Ua", "µA").replace("Snr", "SNR")


def _metadata_group_color(
    group_id: Any,
    values: dict[int, float] | None,
) -> str | None:
    if not values:
        return None
    try:
        value = float(values[int(group_id)])
    except (KeyError, TypeError, ValueError):
        return None
    minimum = min(values.values())
    maximum = max(values.values())
    fraction = (
        (value - minimum) / (maximum - minimum)
        if maximum > minimum else .5
    )
    red, green, blue, _alpha = plt.get_cmap("viridis")(fraction)
    return f"rgb({red * 255:.0f},{green * 255:.0f},{blue * 255:.0f})"


def _categorical_group_color(group_id: Any) -> str | None:
    try:
        index = int(group_id) - 1
    except (TypeError, ValueError):
        return None
    return GROUP_CATEGORICAL_COLORS[index % len(GROUP_CATEGORICAL_COLORS)]


def _metadata_value_color(
    value: Any,
    values: dict[int, float] | None,
) -> str | None:
    if not values:
        return None
    numeric = _finite_float(value)
    if numeric is None:
        return None
    minimum = min(values.values())
    maximum = max(values.values())
    fraction = (
        (numeric - minimum) / (maximum - minimum)
        if maximum > minimum else .5
    )
    fraction = min(1.0, max(0.0, fraction))
    red, green, blue, _alpha = plt.get_cmap("viridis")(fraction)
    return f"rgb({red * 255:.0f},{green * 255:.0f},{blue * 255:.0f})"


def _metadata_value_label(value: Any) -> str:
    numeric = _finite_float(value)
    if numeric is not None:
        return f"{numeric:g}"
    if value is None:
        return "missing"
    return str(value)


def _add_metadata_colorbar(
    fig: go.Figure,
    values: dict[int, float] | None,
    label: str | None,
) -> None:
    if not values or not label:
        return
    finite_values = sorted({
        float(value)
        for value in values.values()
        if _finite_float(value) is not None
    })
    if not finite_values:
        return
    minimum = min(finite_values)
    maximum = max(finite_values)
    if minimum == maximum:
        maximum = minimum + 1.0
    colorbar = {
        "title": {"text": label, "side": "right"},
        "tickformat": ".4g",
        "ticks": "outside",
        "thickness": 18,
        "xpad": 8,
    }
    if len(finite_values) <= 10:
        colorbar.update({
            "tickmode": "array",
            "tickvals": finite_values,
            "ticktext": [_metadata_value_label(value) for value in finite_values],
        })
    fig.add_trace(go.Scatter(
        x=[None, None],
        y=[None, None],
        mode="markers",
        marker={
            "color": [minimum, maximum],
            "colorscale": "Viridis",
            "cmin": minimum,
            "cmax": maximum,
            "showscale": True,
            "colorbar": colorbar,
        },
        hoverinfo="skip",
        showlegend=False,
    ))


def _apply_metadata_coloraxis(
    fig: go.Figure,
    values: dict[int, float] | None,
    label: str | None,
) -> None:
    if not values or not label:
        return
    finite_values = sorted({
        float(value)
        for value in values.values()
        if _finite_float(value) is not None
    })
    if not finite_values:
        return
    minimum = min(finite_values)
    maximum = max(finite_values)
    if minimum == maximum:
        maximum = minimum + 1.0
    colorbar = {
        "title": {"text": label, "side": "right"},
        "tickformat": ".4g",
        "ticks": "outside",
        "thickness": 18,
        "xpad": 8,
    }
    if len(finite_values) <= 10:
        colorbar.update({
            "tickmode": "array",
            "tickvals": finite_values,
            "ticktext": [_metadata_value_label(value) for value in finite_values],
        })
    fig.update_layout(
        coloraxis={
            "colorscale": "Viridis",
            "cmin": minimum,
            "cmax": maximum,
            "colorbar": colorbar,
        }
    )


def _strip_plotly_color_references(fig: go.Figure) -> go.Figure:
    """Remove colorbar/coloraxis state from traces that should be categorical."""
    for trace in fig.data:
        marker = getattr(trace, "marker", None)
        if marker is not None:
            marker.showscale = False
            marker.coloraxis = None
            marker.colorbar = None
            marker.colorscale = None
        if hasattr(trace, "showscale"):
            trace.showscale = False
        if hasattr(trace, "coloraxis"):
            trace.coloraxis = None
        if hasattr(trace, "colorbar"):
            trace.colorbar = None
        if hasattr(trace, "colorscale"):
            trace.colorscale = None
    fig.update_layout(coloraxis=None)
    return fig


def _strip_categorical_plot_colorbars(fig: go.Figure) -> go.Figure:
    """Remove accidental continuous colorbars from categorical Plotly traces."""
    return _strip_plotly_color_references(fig)


def _finite_float(value) -> float | None:
    try:
        numeric = float(value)
    except (TypeError, ValueError):
        return None
    return numeric if np.isfinite(numeric) else None


def _value_range_from_frame(
    frame: pd.DataFrame | None,
    value_column: str = "value",
) -> tuple[float, float] | None:
    if frame is None or frame.empty or value_column not in frame.columns:
        return None
    values = pd.to_numeric(frame[value_column], errors="coerce")
    values = values[np.isfinite(values)]
    if values.empty:
        return None
    value_min = float(values.min())
    value_max = float(values.max())
    if np.isclose(value_min, value_max):
        padding = max(abs(value_min) * 0.05, 1e-9)
        value_min -= padding
        value_max += padding
    return value_min, value_max


def _parse_float_sweep_values(
    text: str,
    *,
    minimum: float,
    maximum: float,
    label: str,
) -> list[float]:
    values = []
    for token in str(text).replace(";", ",").split(","):
        token = token.strip()
        if not token:
            continue
        if ":" in token:
            parts = [part.strip() for part in token.split(":")]
            if len(parts) != 3:
                raise ValueError(f"Invalid {label} range '{token}'. Use start:stop:step.")
            start, stop, step = map(float, parts)
            if step <= 0:
                raise ValueError(f"{label} range step must be positive.")
            current = start
            while current <= stop + step * 1e-9:
                values.append(round(current, 10))
                current += step
        else:
            values.append(float(token))
    validated = []
    for value in values:
        if not minimum <= value <= maximum:
            raise ValueError(
                f"{label} values must be between {minimum:g} and {maximum:g}."
            )
        validated.append(value)
    if not validated:
        raise ValueError(f"Enter at least one {label} value.")
    return validated


def _parse_int_sweep_values(
    text: str,
    *,
    minimum: int,
    maximum: int,
    label: str,
) -> list[int]:
    values = []
    for token in str(text).replace(";", ",").split(","):
        token = token.strip()
        if not token:
            continue
        if ":" in token:
            parts = [part.strip() for part in token.split(":")]
            if len(parts) != 3:
                raise ValueError(f"Invalid {label} range '{token}'. Use start:stop:step.")
            start, stop, step = map(int, parts)
            if step <= 0:
                raise ValueError(f"{label} range step must be positive.")
            current = start
            while current <= stop:
                values.append(current)
                current += step
        else:
            numeric = float(token)
            if not numeric.is_integer():
                raise ValueError(f"{label} values must be whole numbers.")
            values.append(int(numeric))
    validated = []
    for value in values:
        if not minimum <= value <= maximum:
            raise ValueError(
                f"{label} values must be between {minimum:g} and {maximum:g}."
            )
        validated.append(value)
    if not validated:
        raise ValueError(f"Enter at least one {label} value.")
    return validated


def _simulation_optimum_reference_from_frame(
    ground_truth: pd.DataFrame,
    value_column: str = "ground_truth_value",
) -> dict[str, float] | None:
    if ground_truth is None or ground_truth.empty:
        return None
    frame = ground_truth.copy()
    if value_column not in frame.columns:
        numeric_candidates = [
            column for column in frame.columns
            if column not in {"source_index", "candidate_index"}
            and pd.api.types.is_numeric_dtype(frame[column])
        ]
        if not numeric_candidates:
            return None
        value_column = (
            "interpolated_value"
            if "interpolated_value" in numeric_candidates
            else numeric_candidates[-1]
        )
    values = pd.to_numeric(frame[value_column], errors="coerce")
    if values.notna().sum() == 0:
        return None
    best_index = values.idxmax()
    best_row = frame.loc[best_index]
    reference = {"Q_run": float(values.loc[best_index])}
    for parameter in ("frequency", "amplitude", "step_potential"):
        if parameter in frame.columns:
            parameter_value = _finite_float(best_row.get(parameter))
            if parameter_value is not None:
                reference[parameter] = parameter_value
    return reference


def _simulation_optimum_value_column(frame: pd.DataFrame) -> str | None:
    for candidate in (
        "ground_truth_value",
        "interpolated_value",
        "Q_run",
        "value",
    ):
        if candidate in frame.columns:
            return candidate
    numeric_candidates = [
        column for column in frame.columns
        if column not in {
            "source_index",
            "candidate_index",
            "ground_truth_channel",
        }
        and pd.api.types.is_numeric_dtype(frame[column])
    ]
    return numeric_candidates[-1] if numeric_candidates else None


def _simulation_channel_optima_frame(session: dict) -> pd.DataFrame:
    ground_truth = session.get("simulation_ground_truth")
    if not isinstance(ground_truth, pd.DataFrame) or ground_truth.empty:
        return pd.DataFrame()
    value_column = _simulation_optimum_value_column(ground_truth)
    if value_column is None:
        return pd.DataFrame()
    work = ground_truth.copy()
    work[value_column] = pd.to_numeric(work[value_column], errors="coerce")
    work = work.dropna(subset=[value_column])
    if work.empty:
        return pd.DataFrame()
    metadata = (session.get("state") or {}).get("simulation_metadata") or {}
    if "ground_truth_channel" not in work.columns:
        channel = metadata.get("ground_truth_channel")
        if channel is None:
            return pd.DataFrame()
        work["ground_truth_channel"] = str(channel)
    rows = []
    for channel, channel_rows in work.groupby("ground_truth_channel", dropna=False):
        if channel_rows.empty:
            continue
        best_index = channel_rows[value_column].idxmax()
        best_row = channel_rows.loc[best_index]
        row = {
            "Channel": f"Ch {channel}",
            "Maximum possible Q": float(best_row[value_column]),
        }
        for column, label in (
            ("frequency", "Best frequency"),
            ("amplitude", "Best amplitude"),
            ("step_potential", "Best step size"),
        ):
            if column in channel_rows.columns:
                value = _finite_float(best_row.get(column))
                if value is not None:
                    row[label] = value
        rows.append(row)
    if not rows:
        return pd.DataFrame()
    return pd.DataFrame(rows).sort_values(
        "Channel",
        key=lambda series: series.map(
            lambda value: _channel_sort_key(str(value).replace("Ch ", ""))
        ),
    ).reset_index(drop=True)


def _session_simulation_optimum_reference(session: dict) -> dict[str, float] | None:
    metadata = (session.get("state") or {}).get("simulation_metadata") or {}
    reference = metadata.get("ground_truth_optimum")
    if isinstance(reference, dict):
        parsed = {
            str(key): float(value)
            for key, value in reference.items()
            if _finite_float(value) is not None
        }
        if parsed:
            return parsed
    ground_truth = session.get("simulation_ground_truth")
    if isinstance(ground_truth, pd.DataFrame) and not ground_truth.empty:
        return _simulation_optimum_reference_from_frame(ground_truth)
    return None


def _session_simulation_group_optimum_references(
    session: dict,
    frame: pd.DataFrame,
) -> dict[int, dict[str, float]]:
    ground_truth = session.get("simulation_ground_truth")
    if (
        not isinstance(ground_truth, pd.DataFrame)
        or ground_truth.empty
        or "ground_truth_channel" not in ground_truth.columns
        or frame is None
        or frame.empty
        or "group_id" not in frame.columns
    ):
        return {}
    value_column = _simulation_optimum_value_column(ground_truth)
    if value_column is None:
        return {}
    group_channels: dict[int, str] = {}
    for raw_group_id, rows in frame.groupby("group_id", sort=False, dropna=True):
        group_id_value = _finite_float(raw_group_id)
        if group_id_value is None:
            continue
        group_id = int(group_id_value)
        channel = None
        if "ground_truth_channel" in rows.columns:
            channels = rows["ground_truth_channel"].dropna().astype(str)
            if not channels.empty:
                channel = channels.iloc[0]
        if channel is None:
            group_metadata = (
                (session.get("config") or {}).get("channel_groups")
                or (session.get("state") or {}).get("channel_groups")
                or []
            )
            for group in group_metadata:
                if not isinstance(group, dict):
                    continue
                if _finite_float(group.get("id")) != group_id:
                    continue
                saved_channel = group.get("ground_truth_channel")
                if saved_channel is not None:
                    channel = str(saved_channel)
                    break
        if channel is not None:
            group_channels[group_id] = str(channel)
    if not group_channels:
        return {}
    references: dict[int, dict[str, float]] = {}
    truth_channels = ground_truth["ground_truth_channel"].astype(str)
    for group_id, channel in group_channels.items():
        channel_truth = ground_truth.loc[truth_channels == channel]
        reference = _simulation_optimum_reference_from_frame(
            channel_truth,
            value_column=value_column,
        )
        if reference:
            references[group_id] = reference
    return references


def _add_global_optimum_marker(
    fig: go.Figure,
    reference: dict[str, float] | None,
    x_name: str,
    y_name: str,
    z_name: str | None = None,
    *,
    label: str = "Global optimum",
    slice_axis: str | None = None,
    slice_value: float | None = None,
) -> None:
    if not reference:
        return
    if z_name is None and slice_axis is not None and slice_value is not None:
        optimum_slice_value = _finite_float(reference.get(slice_axis))
        if optimum_slice_value is None or not np.isclose(
            optimum_slice_value,
            float(slice_value),
            rtol=1e-5,
            atol=1e-8,
        ):
            return
    x_value = _finite_float(reference.get(x_name))
    y_value = _finite_float(reference.get(y_name))
    z_value = _finite_float(reference.get(z_name)) if z_name is not None else None
    if x_value is None or y_value is None or (z_name is not None and z_value is None):
        return
    q_value = _finite_float(reference.get("Q_run"))
    hover_lines = [
        label,
        f"{x_name}: {x_value:.4g}",
        f"{y_name}: {y_value:.4g}",
    ]
    if z_name is not None:
        hover_lines.append(f"{z_name}: {z_value:.4g}")
    if q_value is not None:
        hover_lines.append(f"Q: {q_value:.4g}")
    marker = {
        "symbol": "diamond",
        "size": 15,
        "color": "#ff2d2d",
        "line": {"color": "white", "width": 3},
    }
    kwargs = {
        "x": [x_value],
        "y": [y_value],
        "mode": "markers",
        "name": label,
        "marker": marker,
        "hovertemplate": "<br>".join(hover_lines) + "<extra></extra>",
        "showlegend": True,
    }
    if z_name is not None:
        kwargs["z"] = [z_value]
        fig.add_trace(go.Scatter3d(**kwargs))
    else:
        fig.add_trace(go.Scatter(**kwargs))


def _add_horizontal_reference_line(
    fig: go.Figure,
    y_value: float | None,
    label: str,
) -> None:
    if y_value is None or not np.isfinite(float(y_value)):
        return
    try:
        fig.add_hline(
            y=float(y_value),
            line_dash="dash",
            line_color="#d62728",
            line_width=2,
            annotation_text=label,
            annotation_position="top left",
        )
    except Exception:
        fig.add_trace(go.Scatter(
            x=[None],
            y=[float(y_value)],
            mode="lines",
            name=label,
            line={"dash": "dash", "color": "#d62728", "width": 2},
            hovertemplate=f"{label}: %{{y:.4g}}<extra></extra>",
        ))


def _add_group_reference_line(
    fig: go.Figure,
    x_values,
    y_value: float | None,
    label: str,
    *,
    showlegend: bool = True,
    row: int | None = None,
    col: int | None = None,
) -> None:
    if y_value is None or not np.isfinite(float(y_value)):
        return
    numeric_x = pd.to_numeric(pd.Series(list(x_values)), errors="coerce").dropna()
    if numeric_x.empty:
        return
    trace = go.Scatter(
        x=[float(numeric_x.min()), float(numeric_x.max())],
        y=[float(y_value), float(y_value)],
        mode="lines",
        name=label,
        line={"dash": "dash", "color": "#d62728", "width": 1.5},
        hovertemplate=f"{label}: %{{y:.4g}}<extra></extra>",
        showlegend=showlegend,
    )
    if row is not None and col is not None:
        fig.add_trace(trace, row=row, col=col)
    else:
        fig.add_trace(trace)


@st.cache_data(show_spinner=False, max_entries=128)
def _plot_trend(
    frame: pd.DataFrame,
    metric: str,
    group_layout: str = "Plot groups overlaid",
    group_color_values: dict[int, float] | None = None,
    group_color_label: str | None = None,
    group_average_values: dict[int, float] | None = None,
    group_average_label: str | None = None,
    reference_value: float | None = None,
    reference_label: str | None = None,
    reference_values_by_group: dict[int, float] | None = None,
    trace_opacity: float = 1.0,
):
    if metric not in frame.columns:
        fig = go.Figure()
        fig.add_annotation(
            text="No changing trend metrics are available.",
            x=.5, y=.5, xref="paper", yref="paper", showarrow=False,
        )
        fig.update_layout(height=340)
        return fig
    values = pd.to_numeric(frame[metric], errors="coerce")
    x = pd.to_numeric(frame.get("iteration", pd.Series(range(1, len(frame) + 1))), errors="coerce")
    valid = values.notna() & x.notna()
    fig = go.Figure()
    trace_opacity = min(1.0, max(0.05, float(trace_opacity)))
    grouped = "group_id" in frame.columns and frame.loc[valid, "group_id"].nunique() > 1
    reference_values_by_group = reference_values_by_group or {}
    if grouped and group_average_values:
        average_data = pd.DataFrame({
            "iteration": x[valid].astype(int),
            "value": values[valid],
            "group_id": pd.to_numeric(
                frame.loc[valid, "group_id"],
                errors="coerce",
            ),
        }).dropna(subset=["group_id"])
        average_data["average_value"] = [
            group_average_values.get(int(group_id))
            for group_id in average_data["group_id"]
        ]
        average_data["color_value"] = [
            group_color_values.get(int(group_id))
            if group_color_values else None
            for group_id in average_data["group_id"]
        ]
        average_data = average_data.dropna(subset=["average_value"])
        if not average_data.empty:
            averaged = average_data.groupby(
                ["average_value", "iteration"],
                as_index=False,
            ).agg({"value": "mean", "color_value": "mean"})
            for average_value, rows in averaged.groupby("average_value", sort=True):
                value_label = _metadata_value_label(average_value)
                trace_name = (
                    f"{group_average_label} {value_label}"
                    if group_average_label else value_label
                )
                rows = rows.sort_values("iteration")
                group_color = _metadata_value_color(
                    rows["color_value"].iloc[0],
                    group_color_values,
                )
                color_value = _finite_float(rows["color_value"].iloc[0])
                marker = {"size": 8}
                if group_color_values and color_value is not None:
                    marker.update({
                        "color": [color_value] * len(rows),
                        "coloraxis": "coloraxis",
                    })
                elif group_color:
                    marker["color"] = group_color
                fig.add_trace(go.Scatter(
                    x=rows["iteration"],
                    y=rows["value"],
                    mode="lines+markers",
                    name=trace_name,
                    marker=marker,
                    line={"color": group_color} if group_color else None,
                    opacity=trace_opacity,
                    customdata=rows["iteration"],
                    hovertemplate=(
                        f"{trace_name}<br>Iteration %{{x}}<br>"
                        f"Average {metric}: %{{y:.4g}}<extra></extra>"
                    ),
                ))
            fig.update_layout(
                title=(
                    f"{metric} over BO iterations — average by "
                    f"{group_average_label or 'group metadata'}"
                ),
                xaxis_title="BO iteration",
                yaxis_title=metric,
                height=340,
                margin={"l": 65, "r": 20, "t": 50, "b": 90},
                legend={
                    "orientation": "h",
                    "x": 0,
                    "xanchor": "left",
                    "y": -0.22,
                    "yanchor": "top",
                },
                clickmode="event+select",
            )
            _apply_metadata_coloraxis(fig, group_color_values, group_color_label)
            if reference_values_by_group:
                reference_frame = average_data.copy()
                reference_frame["reference_value"] = [
                    reference_values_by_group.get(int(group_id))
                    for group_id in reference_frame["group_id"]
                ]
                reference_frame = reference_frame.dropna(
                    subset=["average_value", "reference_value"]
                )
                for reference_index, (average_value, rows) in enumerate(
                    reference_frame.groupby("average_value", sort=True)
                ):
                    averaged_reference = pd.to_numeric(
                        rows["reference_value"],
                        errors="coerce",
                    ).dropna()
                    if averaged_reference.empty:
                        continue
                    value_label = _metadata_value_label(average_value)
                    _add_group_reference_line(
                        fig,
                        rows["iteration"],
                        float(averaged_reference.mean()),
                        (
                            f"{reference_label or 'Ground-truth optimum'} "
                            f"({group_average_label or 'metadata'} {value_label})"
                        ),
                        showlegend=reference_index == 0,
                    )
            else:
                _add_horizontal_reference_line(
                    fig,
                    reference_value,
                    reference_label or "Ground-truth optimum",
                )
            return fig
    if grouped and group_layout == "Average groups together":
        averaged = pd.DataFrame({
            "iteration": x[valid].astype(int),
            "value": values[valid],
        }).groupby("iteration", as_index=False)["value"].mean()
        fig.add_trace(go.Scatter(
            x=averaged["iteration"],
            y=averaged["value"],
            mode="lines+markers",
            name="Group average",
            marker={"size": 8},
            opacity=trace_opacity,
            customdata=averaged["iteration"],
            hovertemplate=(
                "Iteration %{x}<br>Group average: %{y:.4g}<extra></extra>"
            ),
        ))
        fig.update_layout(
            title=f"{metric} over BO iterations — average across groups",
            xaxis_title="BO iteration",
            yaxis_title=metric,
            height=340,
            margin={"l": 65, "r": 20, "t": 50, "b": 55},
            clickmode="event+select",
        )
        if reference_values_by_group:
            reference_values = [
                value for value in reference_values_by_group.values()
                if _finite_float(value) is not None
            ]
            if reference_values:
                _add_horizontal_reference_line(
                    fig,
                    float(np.mean(reference_values)),
                    reference_label or "Average ground-truth optimum",
                )
        else:
            _add_horizontal_reference_line(
                fig,
                reference_value,
                reference_label or "Ground-truth optimum",
            )
        return fig
    if grouped and group_layout == "Plot groups separately":
        grouped_rows = list(frame.loc[valid].groupby("group_id", sort=True))
        columns = 2 if len(grouped_rows) > 1 else 1
        rows_count = max(1, (len(grouped_rows) + columns - 1) // columns)
        titles = [
            (
                str(rows["group_name"].iloc[0])
                if "group_name" in rows.columns
                else f"Group {int(group_id)}"
            )
            for group_id, rows in grouped_rows
        ]
        fig = make_subplots(
            rows=rows_count,
            cols=columns,
            subplot_titles=titles,
        )
        for index, ((group_id, rows), group_name) in enumerate(
            zip(grouped_rows, titles)
        ):
            subplot_row, subplot_column = divmod(index, columns)
            rows = rows.sort_values("iteration")
            iterations = pd.to_numeric(
                rows["iteration"],
                errors="coerce",
            ).astype(int)
            row_values = pd.to_numeric(rows[metric], errors="coerce")
            group_color = _metadata_group_color(
                group_id,
                group_color_values,
            )
            if group_color is None:
                group_color = _categorical_group_color(group_id)
            color_value = (
                group_color_values.get(int(group_id))
                if group_color_values and _finite_float(group_id) is not None
                else None
            )
            color_value = _finite_float(color_value)
            marker = {}
            if group_color_values and color_value is not None:
                marker.update({
                    "color": [color_value] * len(rows),
                    "coloraxis": "coloraxis",
                })
            elif group_color:
                marker["color"] = group_color
            fig.add_trace(
                go.Scatter(
                    x=iterations,
                    y=row_values,
                    mode="lines+markers",
                    name=group_name,
                    marker=marker or None,
                    line={"color": group_color} if group_color else None,
                    opacity=trace_opacity,
                    customdata=iterations,
                    hovertemplate=(
                        f"{group_name}<br>Iteration %{{x}}<br>"
                        f"{metric}: %{{y:.4g}}<extra></extra>"
                    ),
                ),
                row=subplot_row + 1,
                col=subplot_column + 1,
            )
            fig.update_xaxes(
                title_text="BO iteration",
                row=subplot_row + 1,
                col=subplot_column + 1,
            )
            fig.update_yaxes(
                title_text=metric,
                matches="y",
                row=subplot_row + 1,
                col=subplot_column + 1,
            )
            group_reference = reference_values_by_group.get(int(group_id))
            if group_reference is not None:
                _add_group_reference_line(
                    fig,
                    iterations,
                    group_reference,
                    f"{reference_label or 'Ground-truth optimum'}: {group_name}",
                    showlegend=False,
                    row=subplot_row + 1,
                    col=subplot_column + 1,
                )
        _apply_metadata_coloraxis(
            fig,
            group_color_values,
            group_color_label,
        )
        fig.update_layout(
            title=f"{metric} over BO iterations — separate groups",
            height=max(
                420 if group_color_values else 360,
                280 * rows_count,
            ),
            margin={
                "l": 65,
                "r": 80 if group_color_values else 20,
                "t": 65,
                "b": 55,
            },
            showlegend=False,
            clickmode="event+select",
        )
        _add_horizontal_reference_line(
            fig,
            None if reference_values_by_group else reference_value,
            reference_label or "Ground-truth optimum",
        )
        return fig
    group_series = (
        frame.loc[valid].groupby("group_id", sort=True)
        if grouped
        else [(None, frame.loc[valid])]
    )
    for group_id, rows in group_series:
        rows = rows.sort_values("iteration")
        row_values = pd.to_numeric(rows[metric], errors="coerce")
        iterations = pd.to_numeric(rows["iteration"], errors="coerce").astype(int)
        group_name = (
            str(rows["group_name"].iloc[0])
            if grouped and "group_name" in rows.columns
            else metric
        )
        group_color = _metadata_group_color(group_id, group_color_values)
        if group_color is None and grouped:
            group_color = _categorical_group_color(group_id)
        color_value = (
            group_color_values.get(int(group_id))
            if group_color_values and grouped and _finite_float(group_id) is not None
            else None
        )
        color_value = _finite_float(color_value)
        marker = {"size": 8}
        if group_color_values and color_value is not None:
            marker.update({
                "color": [color_value] * len(rows),
                "coloraxis": "coloraxis",
            })
        elif group_color:
            marker["color"] = group_color
        fig.add_trace(go.Scatter(
            x=iterations,
            y=row_values,
            mode="lines+markers",
            name=group_name,
            marker=marker,
            line={"color": group_color} if group_color else None,
            opacity=trace_opacity,
            customdata=iterations,
            hovertemplate=(
                f"{group_name}<br>Iteration %{{x}}<br>"
                f"{metric}: %{{y:.4g}}<extra></extra>"
            ),
        ))
        group_reference = (
            reference_values_by_group.get(int(group_id))
            if grouped and _finite_float(group_id) is not None
            else None
        )
        if group_reference is not None:
            _add_group_reference_line(
                fig,
                iterations,
                group_reference,
                f"{reference_label or 'Ground-truth optimum'}: {group_name}",
                showlegend=True,
            )
    if grouped:
        _apply_metadata_coloraxis(fig, group_color_values, group_color_label)
    fig.update_layout(
        title=f"{metric} over BO iterations",
        xaxis_title="BO iteration",
        yaxis_title=metric,
        height=420 if group_color_values else 340,
        margin={
            "l": 65,
            "r": 80 if group_color_values else 20,
            "t": 50,
            "b": 115 if grouped else 55,
        },
        legend=(
            {
                "orientation": "h",
                "x": 0,
                "xanchor": "left",
                "y": -0.22,
                "yanchor": "top",
            }
            if grouped else None
        ),
        clickmode="event+select",
    )
    if grouped and not group_color_values:
        fig.update_traces(marker_showscale=False)
    if not reference_values_by_group:
        _add_horizontal_reference_line(
            fig,
            reference_value,
            reference_label or "Ground-truth optimum",
        )
    return _apply_plotly_colorbar_height(fig)


def _hyperparameter_response_columns(frame: pd.DataFrame) -> list[str]:
    preferred = [
        "exploration",
        "initial_random_points",
        "gp_falloff_value",
        "candidate_pool_size",
        "local_candidate_pool_size",
        "gp_noise_level",
    ]
    columns = []
    for column in preferred:
        if (
            column in frame.columns
            and pd.to_numeric(frame[column], errors="coerce").nunique(dropna=True) > 1
        ):
            columns.append(column)
    for column in frame.columns:
        if (
            str(column).startswith("falloff_")
            and column not in columns
            and pd.to_numeric(frame[column], errors="coerce").nunique(dropna=True) > 1
        ):
            columns.append(column)
    return columns


def _hyperparameter_response_channel_label(rows: pd.DataFrame) -> str:
    channel_values: list[str] = []
    for column in ("ground_truth_channel", "channels"):
        if column not in rows.columns:
            continue
        for value in rows[column].dropna().astype(str).unique():
            for part in re.split(r"[,;|]", value):
                text = part.strip().strip("[]()")
                if not text or text.lower() in {"nan", "none"}:
                    continue
                if text.endswith(".0") and text[:-2].isdigit():
                    text = text[:-2]
                channel_values.append(text)
    unique_channels = sorted(set(channel_values), key=_channel_sort_key)
    if not unique_channels:
        return "Unknown"
    return ", ".join(f"Ch {channel}" for channel in unique_channels)


def _join_hyperparameter_response_channels(values: pd.Series) -> str:
    channels: list[str] = []
    for value in values.dropna().astype(str):
        for part in value.split(","):
            text = part.strip()
            if text and text != "Unknown":
                channels.append(text)
    if not channels:
        return "Unknown"
    return ", ".join(
        sorted(
            set(channels),
            key=lambda value: _channel_sort_key(
                str(value).removeprefix("Ch ").strip()
            ),
        )
    )


@st.cache_data(show_spinner=False, max_entries=128)
def _hyperparameter_response_frame(
    frame: pd.DataFrame,
    metric: str,
    summary_mode: str,
    iteration: int | None = None,
    q_target: float | None = None,
    include_misses: bool = False,
    at_best_q_parameter: str | None = None,
) -> pd.DataFrame:
    if frame.empty:
        return pd.DataFrame()
    best_q_column = None
    if at_best_q_parameter is not None:
        if at_best_q_parameter not in frame.columns:
            return pd.DataFrame()
        for candidate in ("Q_run", "best_Q", "best_so_far", "observed_value"):
            if candidate in frame.columns:
                best_q_column = candidate
                break
        if best_q_column is None:
            return pd.DataFrame()
    elif metric not in frame.columns:
        return pd.DataFrame()
    hyper_columns = _hyperparameter_response_columns(frame)
    if len(hyper_columns) < 2:
        return pd.DataFrame()
    work = frame.copy()
    source_metric = at_best_q_parameter or metric
    work["_metric_value"] = pd.to_numeric(work[source_metric], errors="coerce")
    if best_q_column is not None:
        work["_best_q_value"] = pd.to_numeric(work[best_q_column], errors="coerce")
    work["_iteration_value"] = pd.to_numeric(
        work.get("iteration", pd.Series(range(1, len(work) + 1), index=work.index)),
        errors="coerce",
    )
    for column in hyper_columns:
        work[column] = pd.to_numeric(work[column], errors="coerce")
    valid = work["_metric_value"].notna() & work["_iteration_value"].notna()
    if best_q_column is not None:
        valid &= work["_best_q_value"].notna()
    for column in hyper_columns:
        valid &= work[column].notna()
    work = work.loc[valid].copy()
    if work.empty:
        return pd.DataFrame()
    group_columns = [
        column for column in [
            "group_id",
            "group_name",
            "run_label",
            "replicate",
            "repeat_index",
            "seed",
            *hyper_columns,
        ]
        if column in work.columns
    ]
    if not group_columns:
        group_columns = hyper_columns
    rows = []
    for key, rows_for_run in work.groupby(group_columns, dropna=False, sort=False):
        rows_for_run = rows_for_run.sort_values("_iteration_value")
        if at_best_q_parameter is not None:
            if iteration is not None:
                rows_for_run = rows_for_run.loc[
                    rows_for_run["_iteration_value"] <= int(iteration)
                ]
                if rows_for_run.empty:
                    continue
            idx = rows_for_run["_best_q_value"].idxmax()
            metric_value = float(rows_for_run.loc[idx, "_metric_value"])
            source_iteration = int(rows_for_run.loc[idx, "_iteration_value"])
        elif summary_mode == "Iterations to Q target":
            if q_target is None or not np.isfinite(float(q_target)):
                continue
            metric_series = rows_for_run["_metric_value"]
            if metric != "best_Q":
                metric_series = metric_series.cummax()
            reached = rows_for_run.loc[metric_series >= float(q_target)]
            if reached.empty:
                if not include_misses:
                    continue
                metric_value = float(rows_for_run["_iteration_value"].max()) + 1.0
                source_iteration = np.nan
            else:
                source_iteration = int(reached["_iteration_value"].iloc[0])
                metric_value = float(source_iteration)
        elif summary_mode == "Final iteration":
            metric_value = float(rows_for_run["_metric_value"].iloc[-1])
            source_iteration = int(rows_for_run["_iteration_value"].iloc[-1])
        elif summary_mode == "Best over iterations":
            idx = rows_for_run["_metric_value"].idxmax()
            metric_value = float(rows_for_run.loc[idx, "_metric_value"])
            source_iteration = int(rows_for_run.loc[idx, "_iteration_value"])
        elif summary_mode == "Mean over iterations":
            metric_value = float(rows_for_run["_metric_value"].mean())
            source_iteration = np.nan
        else:
            target_iteration = int(iteration or rows_for_run["_iteration_value"].max())
            at_iteration = rows_for_run[
                rows_for_run["_iteration_value"].astype(int) == target_iteration
            ]
            if at_iteration.empty:
                continue
            metric_value = float(at_iteration["_metric_value"].iloc[-1])
            source_iteration = target_iteration
        if isinstance(key, tuple):
            row = dict(zip(group_columns, key))
        else:
            row = {group_columns[0]: key}
        row.update({
            "metric_value": metric_value,
            "source_iteration": source_iteration,
            "response_channels": _hyperparameter_response_channel_label(
                rows_for_run
            ),
        })
        rows.append(row)
    return pd.DataFrame(rows)


@st.cache_data(show_spinner=False, max_entries=128)
def _hyperparameter_response_grouped(
    response: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str | None,
    aggregate: str,
) -> pd.DataFrame:
    aggregate_func = {
        "Mean": "mean",
        "Median": "median",
        "Maximum": "max",
        "Minimum": "min",
    }[aggregate]
    group_axes = [x_axis, y_axis, *([z_axis] if z_axis else [])]
    if "response_channels" not in response.columns:
        response = response.copy()
        response["response_channels"] = "Unknown"
    return (
        response.groupby(group_axes, as_index=False, dropna=False)
        .agg(
            metric_value=("metric_value", aggregate_func),
            repeats=("metric_value", "count"),
            std=("metric_value", "std"),
            channels=(
                "response_channels",
                _join_hyperparameter_response_channels,
            ),
        )
        .sort_values(group_axes)
    )


@st.cache_data(show_spinner=False, max_entries=128)
def _hyperparameter_response_voxel_bounds(
    grouped: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str,
) -> tuple[dict[float, tuple[float, float]], dict[float, tuple[float, float]], dict[float, tuple[float, float]]]:
    def bounds_for(values: list[float]) -> dict[float, tuple[float, float]]:
        values = sorted(float(value) for value in values)
        if len(values) == 1:
            width = max(1e-6, abs(values[0]) * 0.08, 0.08)
            return {values[0]: (values[0] - width / 2, values[0] + width / 2)}
        midpoints = [
            (left + right) / 2.0 for left, right in zip(values[:-1], values[1:])
        ]
        edges = [
            values[0] - (midpoints[0] - values[0]),
            *midpoints,
            values[-1] + (values[-1] - midpoints[-1]),
        ]
        return {
            value: (edges[index], edges[index + 1])
            for index, value in enumerate(values)
        }

    x_bounds = bounds_for(grouped[x_axis].dropna().unique().tolist())
    y_bounds = bounds_for(grouped[y_axis].dropna().unique().tolist())
    z_bounds = bounds_for(grouped[z_axis].dropna().unique().tolist())
    return x_bounds, y_bounds, z_bounds


@st.cache_data(show_spinner=False, max_entries=128)
def _hyperparameter_response_voxel_geometry(
    grouped: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str,
) -> tuple[
    list[float],
    list[float],
    list[float],
    list[float],
    list[int],
    list[int],
    list[int],
]:
    x_bounds, y_bounds, z_bounds = _hyperparameter_response_voxel_bounds(
        grouped,
        x_axis=x_axis,
        y_axis=y_axis,
        z_axis=z_axis,
    )
    vertices_x: list[float] = []
    vertices_y: list[float] = []
    vertices_z: list[float] = []
    intensities: list[float] = []
    i_faces: list[int] = []
    j_faces: list[int] = []
    k_faces: list[int] = []
    cube_faces = [
        (0, 1, 2), (0, 2, 3),
        (4, 6, 5), (4, 7, 6),
        (0, 4, 5), (0, 5, 1),
        (3, 2, 6), (3, 6, 7),
        (0, 3, 7), (0, 7, 4),
        (1, 5, 6), (1, 6, 2),
    ]
    for _row_index, row in grouped.iterrows():
        x0, x1 = x_bounds[float(row[x_axis])]
        y0, y1 = y_bounds[float(row[y_axis])]
        z0, z1 = z_bounds[float(row[z_axis])]
        base = len(vertices_x)
        cube_vertices = [
            (x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0),
            (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1),
        ]
        for vx, vy, vz in cube_vertices:
            vertices_x.append(vx)
            vertices_y.append(vy)
            vertices_z.append(vz)
            intensities.append(float(row["metric_value"]))
        for face in cube_faces:
            i_faces.append(base + face[0])
            j_faces.append(base + face[1])
            k_faces.append(base + face[2])
    return vertices_x, vertices_y, vertices_z, intensities, i_faces, j_faces, k_faces


@st.cache_data(show_spinner=False, max_entries=128)
def _hyperparameter_response_voxel_interior_points(
    grouped: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str,
    point_count: int = 27,
    ) -> tuple[list[float], list[float], list[float], list[list[Any]]]:
    x_bounds, y_bounds, z_bounds = _hyperparameter_response_voxel_bounds(
        grouped,
        x_axis=x_axis,
        y_axis=y_axis,
        z_axis=z_axis,
    )
    if int(point_count) == 1:
        fraction_points = [(0.5, 0.5, 0.5)]
    elif int(point_count) == 4:
        fraction_points = [
            (1.0 / 3.0, 1.0 / 3.0, 1.0 / 3.0),
            (1.0 / 3.0, 2.0 / 3.0, 2.0 / 3.0),
            (2.0 / 3.0, 1.0 / 3.0, 2.0 / 3.0),
            (2.0 / 3.0, 2.0 / 3.0, 1.0 / 3.0),
        ]
    else:
        samples_per_axis = 4 if int(point_count) == 64 else 3
        fractions = np.linspace(
            1.0 / (samples_per_axis + 1),
            samples_per_axis / (samples_per_axis + 1),
            samples_per_axis,
        )
        fraction_points = [
            (float(xf), float(yf), float(zf))
            for xf in fractions
            for yf in fractions
            for zf in fractions
        ]
    interior_x: list[float] = []
    interior_y: list[float] = []
    interior_z: list[float] = []
    interior_values: list[float] = []
    interior_customdata: list[list[Any]] = []
    for _row_index, row in grouped.iterrows():
        x0, x1 = x_bounds[float(row[x_axis])]
        y0, y1 = y_bounds[float(row[y_axis])]
        z0, z1 = z_bounds[float(row[z_axis])]
        value = float(row["metric_value"])
        for x_fraction, y_fraction, z_fraction in fraction_points:
            interior_x.append(float(x0 + x_fraction * (x1 - x0)))
            interior_y.append(float(y0 + y_fraction * (y1 - y0)))
            interior_z.append(float(z0 + z_fraction * (z1 - z0)))
            interior_values.append(value)
            interior_customdata.append([
                value,
                float(row.get("repeats", np.nan)),
                float(row.get("std", np.nan)),
                str(row.get("channels", "Unknown")),
            ])
    return interior_x, interior_y, interior_z, interior_customdata


def _add_hyperparameter_slice_plane(
    fig: go.Figure,
    grouped: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str,
    slice_axis: str | None,
    slice_value: float | None,
) -> None:
    if slice_axis not in {x_axis, y_axis, z_axis} or slice_value is None:
        return

    x_bounds, y_bounds, z_bounds = _hyperparameter_response_voxel_bounds(
        grouped,
        x_axis=x_axis,
        y_axis=y_axis,
        z_axis=z_axis,
    )
    axis_ranges = {
        x_axis: (
            min(edge[0] for edge in x_bounds.values()),
            max(edge[1] for edge in x_bounds.values()),
        ),
        y_axis: (
            min(edge[0] for edge in y_bounds.values()),
            max(edge[1] for edge in y_bounds.values()),
        ),
        z_axis: (
            min(edge[0] for edge in z_bounds.values()),
            max(edge[1] for edge in z_bounds.values()),
        ),
    }

    x0, x1 = axis_ranges[x_axis]
    y0, y1 = axis_ranges[y_axis]
    z0, z1 = axis_ranges[z_axis]
    value = float(slice_value)
    if slice_axis == x_axis:
        x_grid = [[value, value], [value, value]]
        y_grid = [[y0, y1], [y0, y1]]
        z_grid = [[z0, z0], [z1, z1]]
    elif slice_axis == y_axis:
        x_grid = [[x0, x1], [x0, x1]]
        y_grid = [[value, value], [value, value]]
        z_grid = [[z0, z0], [z1, z1]]
    else:
        x_grid = [[x0, x1], [x0, x1]]
        y_grid = [[y0, y0], [y1, y1]]
        z_grid = [[value, value], [value, value]]

    fig.add_trace(go.Surface(
        x=x_grid,
        y=y_grid,
        z=z_grid,
        surfacecolor=[[1, 1], [1, 1]],
        colorscale=[[0, "rgba(220,0,0,1)"], [1, "rgba(220,0,0,1)"]],
        opacity=0.34,
        showscale=False,
        name=f"Selected slice: {slice_axis}={value:g}",
        hovertemplate=(
            f"Selected slice<br>{slice_axis}: {value:g}<extra></extra>"
        ),
    ))


def _add_plotly_slice_plane(
    fig: go.Figure,
    points: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str,
    slice_axis: str | None,
    slice_value: float | None,
    slice_sweep_values: Sequence[float] | None = None,
    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
) -> None:
    if (
        points is None
        or points.empty
        or slice_axis not in {x_axis, y_axis, z_axis}
        or (slice_value is None and not slice_sweep_values)
    ):
        return
    valid_slice_values = []
    if slice_sweep_values:
        for raw_slice_value in slice_sweep_values:
            numeric_slice_value = _finite_float(raw_slice_value)
            if numeric_slice_value is not None:
                valid_slice_values.append(float(numeric_slice_value))
    elif slice_value is not None:
        numeric_slice_value = _finite_float(slice_value)
        if numeric_slice_value is not None:
            valid_slice_values = [float(numeric_slice_value)]
    if not valid_slice_values:
        return
    axis_bounds = {}
    for axis_name in (x_axis, y_axis, z_axis):
        if axis_name not in points.columns:
            return
        bounds = (axis_ranges or {}).get(axis_name)
        if bounds is not None:
            lower = float(bounds[0])
            upper = float(bounds[1])
        else:
            axis_values = pd.to_numeric(points[axis_name], errors="coerce")
            axis_values = axis_values[np.isfinite(axis_values)]
            if axis_values.empty:
                return
            lower = float(axis_values.min())
            upper = float(axis_values.max())
        if np.isclose(lower, upper):
            padding = max(abs(lower) * 0.05, 1e-9)
            lower -= padding
            upper += padding
        axis_bounds[axis_name] = (lower, upper)

    x0, x1 = axis_bounds[x_axis]
    y0, y1 = axis_bounds[y_axis]
    z0, z1 = axis_bounds[z_axis]
    for slice_index, current_slice_value in enumerate(valid_slice_values):
        value = float(current_slice_value)
        if slice_axis == x_axis:
            plane_x = [[value, value], [value, value]]
            plane_y = [[y0, y1], [y0, y1]]
            plane_z = [[z0, z0], [z1, z1]]
            outline_x = [value, value, value, value, value]
            outline_y = [y0, y1, y1, y0, y0]
            outline_z = [z0, z0, z1, z1, z0]
        elif slice_axis == y_axis:
            plane_x = [[x0, x1], [x0, x1]]
            plane_y = [[value, value], [value, value]]
            plane_z = [[z0, z0], [z1, z1]]
            outline_x = [x0, x1, x1, x0, x0]
            outline_y = [value, value, value, value, value]
            outline_z = [z0, z0, z1, z1, z0]
        else:
            plane_x = [[x0, x1], [x0, x1]]
            plane_y = [[y0, y0], [y1, y1]]
            plane_z = [[value, value], [value, value]]
            outline_x = [x0, x1, x1, x0, x0]
            outline_y = [y0, y0, y1, y1, y0]
            outline_z = [value, value, value, value, value]
        _mpl_color, color = _slice_highlight_color(
            slice_index,
            len(valid_slice_values),
        )
        trace_name = (
            f"Slice {slice_index + 1}: {slice_axis}={value:g}"
            if len(valid_slice_values) > 1
            else "Highlighted slice"
        )
        fig.add_trace(go.Surface(
            x=plane_x,
            y=plane_y,
            z=plane_z,
            surfacecolor=[[1, 1], [1, 1]],
            colorscale=[[0, color], [1, color]],
            opacity=0.34 if len(valid_slice_values) > 1 else 0.23,
            showscale=False,
            showlegend=False,
            name=trace_name,
            hovertemplate=(
                f"{slice_axis}: {value:.4g}<extra>Highlighted slice</extra>"
            ),
        ))
        fig.add_trace(go.Scatter3d(
            x=outline_x,
            y=outline_y,
            z=outline_z,
            mode="lines",
            line={"color": color, "width": 7},
            name=f"{trace_name} outline",
            showlegend=False,
            hovertemplate=(
                f"{slice_axis}: {value:.4g}"
                "<extra>Highlighted slice outline</extra>"
            ),
        ))


@st.cache_data(show_spinner=False, max_entries=128)
def _plot_hyperparameter_response(
    response: pd.DataFrame,
    *,
    x_axis: str,
    y_axis: str,
    z_axis: str | None = None,
    metric_label: str,
    aggregate: str,
    voxel_face_opacity: float = 0.1,
    voxel_internal_opacity: float = 1.0,
    voxel_internal_point_size: int = 20,
    voxel_internal_point_count: int = 1,
    slice_axis: str | None = None,
    slice_value: float | None = None,
) -> go.Figure:
    response_colorscale = "Plasma"

    def response_colorbar() -> dict[str, Any]:
        return {
            "title": {"text": metric_label, "side": "right"},
            "tickformat": ".4g",
            "ticks": "outside",
            "thickness": 18,
            "x": 1.03,
            "xpad": 8,
        }

    if response.empty:
        fig = go.Figure()
        fig.add_annotation(
            text="No hyperparameter response values are available.",
            x=.5,
            y=.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        fig.update_layout(height=360)
        return fig
    grouped = _hyperparameter_response_grouped(
        response,
        x_axis=x_axis,
        y_axis=y_axis,
        z_axis=z_axis,
        aggregate=aggregate,
    )
    if z_axis:
        response_values = pd.to_numeric(grouped["metric_value"], errors="coerce")
        finite_response_values = response_values[np.isfinite(response_values)]
        response_min = (
            float(finite_response_values.min())
            if not finite_response_values.empty else None
        )
        response_max = (
            float(finite_response_values.max())
            if not finite_response_values.empty else None
        )
        if (
            response_min is not None
            and response_max is not None
            and np.isclose(response_min, response_max)
        ):
            response_max = response_min + 1.0
        show_internal_points = float(voxel_internal_opacity) > 0
        (
            vertices_x,
            vertices_y,
            vertices_z,
            intensities,
            i_faces,
            j_faces,
            k_faces,
        ) = _hyperparameter_response_voxel_geometry(
            grouped,
            x_axis=x_axis,
            y_axis=y_axis,
            z_axis=z_axis,
        )
        fig = go.Figure()
        if show_internal_points:
            interior_x, interior_y, interior_z, interior_customdata = (
                _hyperparameter_response_voxel_interior_points(
                    grouped,
                    x_axis=x_axis,
                    y_axis=y_axis,
                    z_axis=z_axis,
                    point_count=voxel_internal_point_count,
                )
            )
            interior_values = [
                row[0] for row in interior_customdata
            ]
            fig.add_trace(go.Scatter3d(
                x=interior_x,
                y=interior_y,
                z=interior_z,
                mode="markers",
                marker={
                    "size": int(voxel_internal_point_size),
                    "color": interior_values,
                    "colorscale": response_colorscale,
                    "cmin": response_min,
                    "cmax": response_max,
                    "opacity": float(voxel_internal_opacity),
                    "showscale": True,
                    "colorbar": response_colorbar(),
                },
                name="Response voxel interior",
                showlegend=False,
                customdata=interior_customdata,
                hovertemplate=(
                    f"{x_axis}: %{{x}}<br>{y_axis}: %{{y}}<br>{z_axis}: %{{z}}<br>"
                    f"{aggregate} {metric_label}: %{{customdata[0]:.4g}}<br>"
                    "Runs: %{customdata[1]:.0f}<br>"
                    "Std: %{customdata[2]:.4g}<br>"
                    "Channels: %{customdata[3]}<extra></extra>"
                ),
            ))
        if float(voxel_face_opacity) > 0:
            fig.add_trace(go.Mesh3d(
                x=vertices_x,
                y=vertices_y,
                z=vertices_z,
                i=i_faces,
                j=j_faces,
                k=k_faces,
                intensity=intensities,
                colorscale=response_colorscale,
                cmin=response_min,
                cmax=response_max,
                showscale=not show_internal_points,
                colorbar=response_colorbar() if not show_internal_points else None,
                opacity=float(voxel_face_opacity),
                flatshading=True,
                name="Response voxels",
                hoverinfo="skip",
            ))
        fig.add_trace(go.Scatter3d(
            x=grouped[x_axis],
            y=grouped[y_axis],
            z=grouped[z_axis],
            mode="markers",
            marker={
                "size": 6,
                "color": "rgba(0,0,0,0.01)",
                "opacity": 0.01,
                "showscale": False,
            },
            name="Voxel hover points",
            showlegend=False,
            customdata=grouped[["metric_value", "repeats", "std", "channels"]],
            hovertemplate=(
                f"{x_axis}: %{{x}}<br>{y_axis}: %{{y}}<br>{z_axis}: %{{z}}<br>"
                f"{aggregate} {metric_label}: %{{customdata[0]:.4g}}<br>"
                "Runs: %{customdata[1]:.0f}<br>"
                "Std: %{customdata[2]:.4g}<br>"
                "Channels: %{customdata[3]}<br>"
                "Click to set highlighted slice<extra></extra>"
            ),
        ))
        _add_hyperparameter_slice_plane(
            fig,
            grouped,
            x_axis=x_axis,
            y_axis=y_axis,
            z_axis=z_axis,
            slice_axis=slice_axis,
            slice_value=slice_value,
        )
        fig.update_layout(
            title=f"{aggregate} {metric_label} by hyperparameters",
            scene={
                "xaxis_title": x_axis,
                "yaxis_title": y_axis,
                "zaxis_title": z_axis,
            },
            height=560,
            margin={"l": 0, "r": 100, "t": 55, "b": 20},
        )
        return _apply_plotly_colorbar_height(fig)
    x_values = sorted(grouped[x_axis].dropna().unique())
    y_values = sorted(grouped[y_axis].dropna().unique())
    if len(x_values) >= 2 and len(y_values) >= 2:
        value_grid = (
            grouped.pivot(index=y_axis, columns=x_axis, values="metric_value")
            .reindex(index=y_values, columns=x_values)
        )
        repeats_grid = (
            grouped.pivot(index=y_axis, columns=x_axis, values="repeats")
            .reindex(index=y_values, columns=x_values)
        )
        fig = go.Figure(go.Heatmap(
            x=x_values,
            y=y_values,
            z=value_grid.to_numpy(dtype=float),
            colorscale=response_colorscale,
            colorbar=response_colorbar(),
            customdata=repeats_grid.to_numpy(dtype=float),
            hovertemplate=(
                f"{x_axis}: %{{x}}<br>{y_axis}: %{{y}}<br>"
                f"{aggregate} {metric_label}: %{{z:.4g}}<br>"
                "Runs: %{customdata:.0f}<extra></extra>"
            ),
        ))
        fig.update_layout(
            title=f"{aggregate} {metric_label} by hyperparameters",
            xaxis_title=x_axis,
            yaxis_title=y_axis,
            height=460,
            margin={"l": 70, "r": 110, "t": 55, "b": 65},
        )
        return _apply_plotly_colorbar_height(fig)
    fig = go.Figure(go.Scatter(
        x=grouped[x_axis],
        y=grouped[y_axis],
        mode="markers",
        marker={
            "color": grouped["metric_value"],
            "colorscale": response_colorscale,
            "showscale": True,
            "colorbar": response_colorbar(),
            "size": np.maximum(8, np.minimum(26, 6 + grouped["repeats"] * 2)),
            "line": {"color": "white", "width": 0.7},
        },
        customdata=grouped[["metric_value", "repeats", "std"]],
        hovertemplate=(
            f"{x_axis}: %{{x}}<br>{y_axis}: %{{y}}<br>"
            f"{aggregate} {metric_label}: %{{customdata[0]:.4g}}<br>"
            "Runs: %{customdata[1]:.0f}<br>"
            "Std: %{customdata[2]:.4g}<extra></extra>"
        ),
    ))
    fig.update_layout(
        title=f"{aggregate} {metric_label} by hyperparameters",
        xaxis_title=x_axis,
        yaxis_title=y_axis,
        height=420,
        margin={"l": 70, "r": 110, "t": 55, "b": 65},
    )
    return _apply_plotly_colorbar_height(fig)


@st.cache_data(show_spinner=False, max_entries=128)
def _plot_channel_trend(
    frame: pd.DataFrame,
    metric: str,
    channel_columns: dict[str, str],
    selected_channels: list[str],
    layout: str,
    group_layout: str = "Plot groups overlaid",
    group_color_values: dict[int, float] | None = None,
    group_color_label: str | None = None,
    group_average_values: dict[int, float] | None = None,
    group_average_label: str | None = None,
    reference_values_by_group: dict[int, float] | None = None,
    reference_label: str | None = None,
    trace_opacity: float = 1.0,
):
    iterations = pd.to_numeric(
        frame.get("iteration", pd.Series(range(1, len(frame) + 1))),
        errors="coerce",
    )
    label = _metric_label(metric)
    trace_opacity = min(1.0, max(0.05, float(trace_opacity)))
    group_ids = (
        frame["group_id"]
        if "group_id" in frame.columns
        else pd.Series(1, index=frame.index)
    )
    group_names = (
        frame["group_name"].fillna("").astype(str)
        if "group_name" in frame.columns
        else pd.Series("", index=frame.index)
    )
    records = []
    frame_channels = (
        frame["ground_truth_channel"].astype(str)
        if "ground_truth_channel" in frame.columns
        else None
    )
    for channel in selected_channels:
        values = pd.to_numeric(frame[channel_columns[channel]], errors="coerce")
        valid = iterations.notna() & values.notna()
        if frame_channels is not None:
            valid = valid & (frame_channels == str(channel))
        for index in frame.index[valid]:
            group_id = group_ids.loc[index]
            group_name = group_names.loc[index] or f"Group {group_id}"
            records.append({
                "iteration": int(iterations.loc[index]),
                "value": float(values.loc[index]),
                "group_id": group_id,
                "group_name": group_name,
                "channel": str(channel),
            })
    data = pd.DataFrame(records)
    if data.empty:
        fig = go.Figure()
        fig.add_annotation(
            text="No values are available for the selected channels.",
            x=.5, y=.5, xref="paper", yref="paper", showarrow=False,
        )
        fig.update_layout(height=340)
        return fig

    # Normalize duplicate rows before applying either display-level average.
    data = data.groupby(
        ["group_id", "group_name", "channel", "iteration"],
        as_index=False,
        dropna=False,
    )["value"].mean()
    reference_values_by_group = reference_values_by_group or {}
    if reference_values_by_group:
        data["reference_value"] = [
            reference_values_by_group.get(int(group_id))
            if _finite_float(group_id) is not None else None
            for group_id in data["group_id"]
        ]
    multiple_groups = data["group_id"].nunique(dropna=False) > 1

    if multiple_groups and group_average_values:
        aggregation = {"value": "mean", "color_value": "mean"}
        if "reference_value" in data.columns:
            aggregation["reference_value"] = "mean"
        data["average_value"] = [
            group_average_values.get(int(group_id))
            if _finite_float(group_id) is not None else None
            for group_id in data["group_id"]
        ]
        data["color_value"] = [
            group_color_values.get(int(group_id))
            if group_color_values and _finite_float(group_id) is not None else None
            for group_id in data["group_id"]
        ]
        data = data.dropna(subset=["average_value"])
        if data.empty:
            fig = go.Figure()
            fig.add_annotation(
                text="No group metadata values are available for this average.",
                x=.5, y=.5, xref="paper", yref="paper", showarrow=False,
            )
            fig.update_layout(height=340)
            return fig
        data = data.groupby(
            ["average_value", "channel", "iteration"],
            as_index=False,
        ).agg(aggregation)
        data["group_id"] = [
            f"average::{_metadata_value_label(value)}"
            for value in data["average_value"]
        ]
        data["group_name"] = [
            (
                f"{group_average_label} {_metadata_value_label(value)}"
                if group_average_label else _metadata_value_label(value)
            )
            for value in data["average_value"]
        ]
        multiple_groups = data["group_id"].nunique(dropna=False) > 1

    if multiple_groups and group_layout == "Average groups together":
        aggregation = {"value": "mean"}
        if "reference_value" in data.columns:
            aggregation["reference_value"] = "mean"
        data = data.groupby(
            ["channel", "iteration"],
            as_index=False,
        ).agg(aggregation)
        data["group_id"] = "__average__"
        data["group_name"] = "Group average"

    if layout == "Average selected channels":
        value_columns = {"value": "mean"}
        if "color_value" in data.columns:
            value_columns["color_value"] = "mean"
        if "reference_value" in data.columns:
            value_columns["reference_value"] = "mean"
        data = data.groupby(
            ["group_id", "group_name", "iteration"],
            as_index=False,
            dropna=False,
        ).agg(value_columns)
        data["channel"] = "average"

    separate_groups = (
        multiple_groups
        and group_layout == "Plot groups separately"
    )
    separate_channels = layout == "Separate plots"
    if separate_groups and separate_channels:
        facets = [
            ((group_id, channel), f"{group_name} — Channel {channel}")
            for (group_id, group_name, channel), _rows
            in data.groupby(["group_id", "group_name", "channel"], sort=True)
        ]
    elif separate_groups:
        facets = [
            (group_id, group_name)
            for (group_id, group_name), _rows
            in data.groupby(["group_id", "group_name"], sort=True)
        ]
    elif separate_channels:
        facets = [
            (channel, f"Channel {channel}")
            for channel in sorted(data["channel"].unique(), key=_channel_sort_key)
        ]
    else:
        facets = [(None, "")]

    subplot_columns = 2 if len(facets) > 1 else 1
    subplot_rows = max(1, (len(facets) + subplot_columns - 1) // subplot_columns)
    faceted = len(facets) > 1 or facets[0][0] is not None
    if faceted:
        fig = make_subplots(
            rows=subplot_rows,
            cols=subplot_columns,
            subplot_titles=[title for _key, title in facets],
        )
    else:
        fig = go.Figure()

    reference_traces_added: set[tuple[int, str]] = set()
    for facet_index, (facet_key, _facet_title) in enumerate(facets):
        facet_data = data
        if separate_groups and separate_channels:
            facet_data = data[
                (data["group_id"] == facet_key[0])
                & (data["channel"] == facet_key[1])
            ]
        elif separate_groups:
            facet_data = data[data["group_id"] == facet_key]
        elif separate_channels:
            facet_data = data[data["channel"] == facet_key]

        series_columns = []
        if not separate_groups and facet_data["group_id"].nunique(dropna=False) > 1:
            series_columns.extend(["group_id", "group_name"])
        if not separate_channels and facet_data["channel"].nunique() > 1:
            series_columns.append("channel")
        series = (
            facet_data.groupby(series_columns, sort=True, dropna=False)
            if series_columns
            else [(None, facet_data)]
        )
        for _series_key, rows in series:
            rows = rows.sort_values("iteration")
            group_name = str(rows["group_name"].iloc[0])
            channel = str(rows["channel"].iloc[0])
            name_parts = []
            if group_name != "Group average" and (
                not separate_groups or not separate_channels
            ):
                if multiple_groups:
                    name_parts.append(group_name)
            elif group_name == "Group average":
                name_parts.append(group_name)
            if channel == "average":
                name_parts.append("channel average")
            elif not separate_channels:
                name_parts.append(f"Ch {channel}")
            trace_name = " · ".join(name_parts) or (
                f"Ch {channel}" if channel != "average" else "Channel average"
            )
            group_color = _metadata_group_color(
                rows["group_id"].iloc[0],
                group_color_values,
            )
            if group_color is None and "color_value" in rows.columns:
                group_color = _metadata_value_color(
                    rows["color_value"].iloc[0],
                    group_color_values,
                )
            if group_color is None and multiple_groups:
                group_color = _categorical_group_color(rows["group_id"].iloc[0])
            color_value = None
            if "color_value" in rows.columns:
                color_value = _finite_float(rows["color_value"].iloc[0])
            elif group_color_values and _finite_float(rows["group_id"].iloc[0]) is not None:
                color_value = _finite_float(
                    group_color_values.get(int(rows["group_id"].iloc[0]))
                )
            marker = {}
            if group_color_values and color_value is not None:
                marker.update({
                    "color": [color_value] * len(rows),
                    "coloraxis": "coloraxis",
                })
            elif group_color:
                marker["color"] = group_color
            trace = go.Scatter(
                x=rows["iteration"],
                y=rows["value"],
                mode="lines+markers",
                name=trace_name,
                marker=marker or None,
                line={"color": group_color} if group_color else None,
                opacity=trace_opacity,
                customdata=rows["iteration"],
                hovertemplate=(
                    f"{trace_name}<br>Iteration %{{x}}<br>"
                    f"{label}: %{{y:.4g}}<extra></extra>"
                ),
            )
            if faceted:
                subplot_row, subplot_column = divmod(facet_index, subplot_columns)
                fig.add_trace(
                    trace,
                    row=subplot_row + 1,
                    col=subplot_column + 1,
                )
            else:
                fig.add_trace(trace)
            reference_value = None
            if "reference_value" in rows.columns:
                reference_value = _finite_float(rows["reference_value"].iloc[0])
            elif (
                reference_values_by_group
                and _finite_float(rows["group_id"].iloc[0]) is not None
            ):
                reference_value = reference_values_by_group.get(
                    int(rows["group_id"].iloc[0])
                )
            reference_value = _finite_float(reference_value)
            reference_key = (facet_index, str(rows["group_id"].iloc[0]))
            if reference_value is not None and reference_key not in reference_traces_added:
                reference_traces_added.add(reference_key)
                reference_name = reference_label or "Best possible Q"
                if multiple_groups and group_name:
                    reference_name = f"{reference_name}: {group_name}"
                if faceted:
                    subplot_row, subplot_column = divmod(facet_index, subplot_columns)
                    _add_group_reference_line(
                        fig,
                        rows["iteration"],
                        reference_value,
                        reference_name,
                        showlegend=False,
                        row=subplot_row + 1,
                        col=subplot_column + 1,
                    )
                else:
                    _add_group_reference_line(
                        fig,
                        rows["iteration"],
                        reference_value,
                        reference_name,
                        showlegend=True,
                    )

    if multiple_groups:
        _apply_metadata_coloraxis(fig, group_color_values, group_color_label)

    if faceted:
        for facet_index in range(len(facets)):
            subplot_row, subplot_column = divmod(facet_index, subplot_columns)
            fig.update_xaxes(
                title_text="BO iteration",
                row=subplot_row + 1,
                col=subplot_column + 1,
            )
            fig.update_yaxes(
                title_text=label,
                matches="y",
                row=subplot_row + 1,
                col=subplot_column + 1,
            )
    title = label
    if layout == "Average selected channels":
        title += ": average across selected channels"
    elif layout == "Overlay selected channels":
        title += ": selected channels overlaid"
    else:
        title += " by channel"
    if group_average_values:
        title += f" — average by {group_average_label or 'group metadata'}"
    elif multiple_groups and group_layout == "Average groups together":
        title += " — average across groups"
    elif separate_groups:
        title += " — separate groups"
    fig.update_layout(
        title=title,
        xaxis_title=None if faceted else "BO iteration",
        yaxis_title=None if faceted else label,
        height=max(420 if group_color_values else 340, 270 * subplot_rows),
        margin={
            "l": 65,
            "r": 80 if group_color_values else 20,
            "t": 65,
            "b": 115 if multiple_groups else 55,
        },
        legend=(
            {
                "orientation": "h",
                "x": 0,
                "xanchor": "left",
                "y": -0.22,
                "yanchor": "top",
            }
            if multiple_groups else None
        ),
        clickmode="event+select",
    )
    if multiple_groups and not group_color_values:
        fig.update_traces(marker_showscale=False)
    return _apply_plotly_colorbar_height(fig)


def _figure_y_bounds(fig: go.Figure) -> tuple[float, float] | None:
    values = []
    for trace in fig.data:
        y_values = getattr(trace, "y", None)
        if y_values is None:
            continue
        numeric = pd.to_numeric(pd.Series(y_values), errors="coerce")
        values.extend(numeric[np.isfinite(numeric)].tolist())
    if not values:
        return None
    return float(min(values)), float(max(values))


def _apply_y_axis_range(fig: go.Figure, y_min: float, y_max: float) -> None:
    fig.update_yaxes(range=[y_min, y_max], autorange=False)


def _manual_y_axis_range_control(
    label: str,
    key_prefix: str,
    figures: list[go.Figure],
) -> tuple[float, float] | None:
    bounds = [
        figure_bounds
        for figure in figures
        if (figure_bounds := _figure_y_bounds(figure)) is not None
    ]
    if not bounds:
        return None
    default_y_min = min(bound[0] for bound in bounds)
    default_y_max = max(bound[1] for bound in bounds)
    manual_y_limits = st.checkbox(
        f"Set {label} y-axis limits manually",
        key=f"{key_prefix}_manual_y_limits",
    )
    if not manual_y_limits:
        return None
    if default_y_min == default_y_max:
        default_y_min -= 0.5
        default_y_max += 0.5
    y_limit_columns = st.columns(2)
    manual_y_min = float(y_limit_columns[0].number_input(
        f"{label} y-axis minimum",
        value=default_y_min,
        key=f"{key_prefix}_y_min",
        format="%.6g",
    ))
    manual_y_max = float(y_limit_columns[1].number_input(
        f"{label} y-axis maximum",
        value=default_y_max,
        key=f"{key_prefix}_y_max",
        format="%.6g",
    ))
    if manual_y_min < manual_y_max:
        return manual_y_min, manual_y_max
    st.warning(
        f"{label} y-axis minimum must be less than the maximum; "
        "autoscale is being used."
    )
    return None


def _paired_trend_values(observations: list[dict], metric_label: str) -> dict[str, dict[str, list]]:
    """Build channel-wise buffer/target series from paired BO observations."""
    source, primary_key, fallback_key = PAIRED_TREND_METRICS[metric_label]
    result: dict[str, dict[str, list]] = {}
    for observation in observations:
        iteration = int(observation.get("iteration", 0))
        quality = observation.get("quality") or {}
        components = quality.get("channel_components") or {}
        phase_metrics = {
            "buffer": observation.get("buffer_channel_metrics") or {},
            "target": observation.get("target_channel_metrics") or {},
        }
        channels = set(phase_metrics["buffer"]) | set(phase_metrics["target"]) | set(components)
        for channel in channels:
            series = result.setdefault(
                str(channel),
                {"iteration": [], "buffer": [], "target": []},
            )
            buffer_value = target_value = None
            if source == "channel":
                for phase in ("buffer", "target"):
                    metrics = phase_metrics[phase].get(str(channel), {}) or phase_metrics[phase].get(channel, {}) or {}
                    value = metrics.get(primary_key)
                    if value is None and fallback_key:
                        value = metrics.get(fallback_key)
                    if phase == "buffer":
                        buffer_value = value
                    else:
                        target_value = value
            else:
                component = components.get(str(channel), {}) or components.get(channel, {}) or {}
                buffer_value = component.get(f"buffer_{primary_key}")
                target_value = component.get(f"target_{primary_key}")
            series["iteration"].append(iteration)
            series["buffer"].append(buffer_value)
            series["target"].append(target_value)
    return result


@st.cache_data(show_spinner=False, max_entries=128)
def _plot_paired_phase_trend(
    series_by_channel: dict[str, dict[str, list]],
    metric_label: str,
    selected_channels: list[str],
    layout: str,
):
    phase_colors = {"buffer": "#1f77b4", "target": "#ff7f0e"}
    if layout == "Separate plots":
        columns = 2 if len(selected_channels) > 1 else 1
        rows = max(1, (len(selected_channels) + columns - 1) // columns)
        fig = make_subplots(
            rows=rows,
            cols=columns,
            subplot_titles=[f"Channel {channel}" for channel in selected_channels],
        )
        for index, channel in enumerate(selected_channels):
            row, column = divmod(index, columns)
            series = series_by_channel[channel]
            for phase in ("buffer", "target"):
                values = pd.to_numeric(pd.Series(series[phase]), errors="coerce")
                iterations = pd.Series(series["iteration"])
                valid = values.notna()
                fig.add_trace(
                    go.Scatter(
                        x=iterations[valid],
                        y=values[valid],
                        mode="lines+markers",
                        name=phase.title(),
                        legendgroup=phase,
                        showlegend=index == 0,
                        line={"color": phase_colors[phase]},
                        customdata=iterations[valid],
                        hovertemplate=(
                            f"Iteration %{{x}}<br>{phase.title()} {metric_label}: "
                            "%{y:.4g}<extra></extra>"
                        ),
                    ),
                    row=row + 1,
                    col=column + 1,
                )
            fig.update_xaxes(title_text="BO iteration", row=row + 1, col=column + 1)
            fig.update_yaxes(
                title_text=metric_label,
                matches="y",
                row=row + 1,
                col=column + 1,
            )
        fig.update_layout(
            title=f"Buffer vs target {metric_label}",
            height=max(340, 270 * rows),
            clickmode="event+select",
        )
        return _strip_categorical_plot_colorbars(fig)

    fig = go.Figure()
    if layout == "Average selected channels":
        all_iterations = sorted({
            iteration
            for channel in selected_channels
            for iteration in series_by_channel[channel]["iteration"]
        })
        for phase in ("buffer", "target"):
            values = []
            for iteration in all_iterations:
                iteration_values = []
                for channel in selected_channels:
                    series = series_by_channel[channel]
                    for idx, recorded_iteration in enumerate(series["iteration"]):
                        if recorded_iteration == iteration and pd.notna(series[phase][idx]):
                            iteration_values.append(float(series[phase][idx]))
                values.append(float(np.mean(iteration_values)) if iteration_values else None)
            fig.add_trace(go.Scatter(
                x=all_iterations,
                y=values,
                mode="lines+markers",
                name=phase.title(),
                line={"color": phase_colors[phase]},
                customdata=all_iterations,
                hovertemplate=(
                    f"Iteration %{{x}}<br>Average {phase} {metric_label}: "
                    "%{y:.4g}<extra></extra>"
                ),
            ))
        title = f"Buffer vs target {metric_label}: selected-channel average"
    else:
        use_generic_phase_legend = len(selected_channels) > 4
        for channel_index, channel in enumerate(selected_channels):
            series = series_by_channel[channel]
            for phase in ("buffer", "target"):
                values = pd.to_numeric(pd.Series(series[phase]), errors="coerce")
                iterations = pd.Series(series["iteration"])
                valid = values.notna()
                fig.add_trace(go.Scatter(
                    x=iterations[valid],
                    y=values[valid],
                    mode="lines+markers",
                    name=phase.title() if use_generic_phase_legend else f"Ch {channel} {phase}",
                    legendgroup=phase,
                    showlegend=not use_generic_phase_legend or channel_index == 0,
                    line={"color": phase_colors[phase]},
                    customdata=iterations[valid],
                    hovertemplate=(
                        f"Iteration %{{x}}<br>Ch {channel} {phase} {metric_label}: "
                        "%{y:.4g}<extra></extra>"
                    ),
                ))
        title = f"Buffer vs target {metric_label}: selected channels"
    fig.update_layout(
        title=title,
        xaxis_title="BO iteration",
        yaxis_title=metric_label,
        height=360,
        clickmode="event+select",
    )
    return _strip_categorical_plot_colorbars(fig)


def _chronological_points(
    observations: list[dict],
    config: dict,
    metric_label: str,
    selected_channels: list[str],
    average_channels: bool,
) -> tuple[pd.DataFrame, list[tuple[float, str]]]:
    """Expand paired observations into their actual buffer-then-target order."""
    source, primary_key, fallback_key = PAIRED_TREND_METRICS[metric_label]
    batch_size = max(1, int((config or {}).get("paired_batch_size", 1) or 1))
    grouped: dict[int, list[dict]] = {}
    for observation in observations:
        iteration = int(observation.get("iteration", 0) or 0)
        cycle = observation.get("paired_cycle")
        if cycle in (None, ""):
            cycle = ((iteration - 1) // batch_size) + 1
        grouped.setdefault(int(cycle), []).append(observation)

    rows = []
    transitions: list[tuple[float, str]] = []
    position = 0
    cycles = sorted(grouped)
    for cycle_index, cycle in enumerate(cycles):
        cycle_observations = grouped[cycle]
        for phase in ("buffer", "target"):
            trace_key = f"{phase}_trace_number"

            def order_key(observation):
                iteration = int(observation.get("iteration", 0) or 0)
                batch = observation.get("paired_batch_index")
                if batch in (None, ""):
                    batch = ((iteration - 1) % batch_size) + 1
                trace = observation.get(trace_key)
                try:
                    trace_value = int(trace)
                except (TypeError, ValueError):
                    trace_value = int(batch)
                return trace_value, int(batch), iteration

            for observation in sorted(cycle_observations, key=order_key):
                position += 1
                iteration = int(observation.get("iteration", 0) or 0)
                batch = observation.get("paired_batch_index")
                if batch in (None, ""):
                    batch = ((iteration - 1) % batch_size) + 1
                phase_metrics = observation.get(f"{phase}_channel_metrics") or {}
                components = (observation.get("quality") or {}).get("channel_components") or {}
                event_rows = []
                for channel in selected_channels:
                    if source == "channel":
                        metrics = phase_metrics.get(channel, {}) or {}
                        value = metrics.get(primary_key)
                        if value is None and fallback_key:
                            value = metrics.get(fallback_key)
                    else:
                        component = components.get(channel, {}) or {}
                        value = component.get(f"{phase}_{primary_key}")
                    try:
                        numeric_value = float(value)
                    except (TypeError, ValueError):
                        continue
                    event_rows.append({
                        "position": position,
                        "cycle": cycle,
                        "batch": int(batch),
                        "iteration": iteration,
                        "phase": phase,
                        "channel": channel,
                        "value": numeric_value,
                    })
                if average_channels and event_rows:
                    averaged = dict(event_rows[0])
                    averaged["channel"] = "Average"
                    averaged["value"] = float(np.mean([row["value"] for row in event_rows]))
                    rows.append(averaged)
                else:
                    rows.extend(event_rows)
            if phase == "buffer":
                transitions.append((position + .5, "Buffer → Target"))
        if cycle_index < len(cycles) - 1:
            transitions.append((position + .5, "Target → Buffer"))
    return pd.DataFrame(rows), transitions


@st.cache_data(show_spinner=False, max_entries=128)
def _plot_chronological(
    points: pd.DataFrame,
    transitions: list[tuple[float, str]],
    metric_label: str,
    layout: str,
):
    colors = {"buffer": "#1f77b4", "target": "#ff7f0e"}
    channels = list(dict.fromkeys(points["channel"].astype(str)))
    if layout == "Separate plots":
        columns = 2 if len(channels) > 1 else 1
        rows = max(1, (len(channels) + columns - 1) // columns)
        transition_line_y = pd.to_numeric(points["value"], errors="coerce")
        transition_line_y = transition_line_y[np.isfinite(transition_line_y)]
        if transition_line_y.empty:
            transition_y_min, transition_y_max = 0.0, 1.0
        else:
            transition_y_min = float(transition_line_y.min())
            transition_y_max = float(transition_line_y.max())
            if transition_y_min == transition_y_max:
                transition_y_min -= 0.5
                transition_y_max += 0.5
        transition_x = []
        transition_y = []
        for x_position, _label in transitions:
            transition_x.extend([x_position, x_position, None])
            transition_y.extend([transition_y_min, transition_y_max, None])
        fig = make_subplots(
            rows=rows,
            cols=columns,
            subplot_titles=[
                f"Channel {channel}" if channel != "Average" else "Channel average"
                for channel in channels
            ],
        )
        for channel_index, channel in enumerate(channels):
            row_index, column_index = divmod(channel_index, columns)
            row, column = row_index + 1, column_index + 1
            channel_points = points[
                points["channel"].astype(str) == channel
            ].sort_values("position")
            if transition_x:
                fig.add_trace(
                    go.Scatter(
                        x=transition_x,
                        y=transition_y,
                        mode="lines",
                        line={
                            "color": "rgba(90,107,132,0.45)",
                            "dash": "dash",
                            "width": 1.2,
                        },
                        showlegend=False,
                        hoverinfo="skip",
                    ),
                    row=row,
                    col=column,
                )
            fig.add_trace(
                go.Scatter(
                    x=channel_points["position"],
                    y=channel_points["value"],
                    mode="lines",
                    line={"color": "rgba(90,90,90,0.28)", "width": 1},
                    showlegend=False,
                    hoverinfo="skip",
                ),
                row=row,
                col=column,
            )
            for phase in ("buffer", "target"):
                phase_points = channel_points[channel_points["phase"] == phase]
                if phase_points.empty:
                    continue
                fig.add_trace(
                    go.Scatter(
                        x=phase_points["position"],
                        y=phase_points["value"],
                        mode="markers",
                        name=phase.title(),
                        legendgroup=phase,
                        showlegend=channel_index == 0,
                        marker={"color": colors[phase], "size": 8},
                        customdata=phase_points[["iteration", "cycle", "batch", "channel"]],
                        hovertemplate=(
                            f"{phase.title()} {metric_label}: %{{y:.4g}}<br>"
                            "Iteration %{customdata[0]} | Cycle %{customdata[1]} | "
                            "Batch %{customdata[2]} | Channel %{customdata[3]}<extra></extra>"
                        ),
                    ),
                    row=row,
                    col=column,
                )
            fig.update_xaxes(
                title_text="Chronological order",
                row=row,
                col=column,
            )
            fig.update_yaxes(
                title_text=metric_label,
                matches="y",
                row=row,
                col=column,
            )
        fig.update_layout(
            title=f"Chronological buffer/target measurements | {metric_label}",
            height=max(400, 280 * rows),
            margin={"l": 65, "r": 30, "t": 60, "b": 55},
        )
        return _strip_categorical_plot_colorbars(fig)

    fig = go.Figure()
    generic_legend = len(channels) > 4
    for channel_index, channel in enumerate(channels):
        channel_points = points[points["channel"].astype(str) == channel].sort_values("position")
        fig.add_trace(go.Scatter(
            x=channel_points["position"],
            y=channel_points["value"],
            mode="lines",
            line={"color": "rgba(90,90,90,0.28)", "width": 1},
            showlegend=False,
            hoverinfo="skip",
        ))
        for phase in ("buffer", "target"):
            phase_points = channel_points[channel_points["phase"] == phase]
            if phase_points.empty:
                continue
            if channel == "Average":
                name = phase.title()
                showlegend = True
            elif generic_legend:
                name = phase.title()
                showlegend = channel_index == 0
            else:
                name = f"Ch {channel} {phase}"
                showlegend = True
            fig.add_trace(go.Scatter(
                x=phase_points["position"],
                y=phase_points["value"],
                mode="markers",
                name=name,
                legendgroup=phase if generic_legend else f"{channel}_{phase}",
                showlegend=showlegend,
                marker={"color": colors[phase], "size": 8},
                customdata=phase_points[["iteration", "cycle", "batch", "channel"]],
                hovertemplate=(
                    f"{phase.title()} {metric_label}: %{{y:.4g}}<br>"
                    "Iteration %{customdata[0]} | Cycle %{customdata[1]} | "
                    "Batch %{customdata[2]} | Channel %{customdata[3]}<extra></extra>"
                ),
            ))
    for x_position, label in transitions:
        color = "#2ca02c" if label.startswith("Buffer") else "#9467bd"
        fig.add_vline(x=x_position, line_dash="dash", line_color=color, line_width=1.5)
        fig.add_annotation(
            x=x_position,
            y=1,
            yref="paper",
            text=label,
            showarrow=False,
            textangle=-90,
            xanchor="left",
            yanchor="top",
            font={"size": 10, "color": color},
        )
    fig.update_layout(
        title=f"Chronological buffer/target measurements | {metric_label}",
        xaxis_title="Chronological measurement order",
        yaxis_title=metric_label,
        height=400,
        margin={"l": 65, "r": 30, "t": 60, "b": 55},
    )
    return _strip_categorical_plot_colorbars(fig)


def _real_data_channels(observations: list[dict]) -> list[str]:
    channels = set()
    for observation in observations:
        channels.update(str(key) for key in (observation.get("buffer_channel_metrics") or {}))
        channels.update(str(key) for key in (observation.get("target_channel_metrics") or {}))
        channels.update(str(key) for key in (observation.get("channel_metrics") or {}))
        channels.update(
            str(key)
            for key in ((observation.get("quality") or {}).get("channel_components") or {})
        )
    return sorted(channels, key=_channel_sort_key)


def _real_metric_points(
    observations: list[dict],
    metric_label: str,
    phase: str,
    selected_channels: list[str],
    average_channels: bool,
) -> pd.DataFrame:
    source, primary_key, fallback_key = REAL_DATA_METRICS[metric_label]
    rows = []
    for observation in observations:
        params = observation.get("params") or {}
        if source == "observation":
            per_iteration = []
            quality = observation.get("quality") or {}
            q_channels = quality.get("Q_channels") or {}
            components = quality.get("channel_components") or {}
            for channel in selected_channels:
                component = components.get(str(channel), {}) or components.get(channel, {}) or {}
                value = (
                    q_channels.get(str(channel))
                    if isinstance(q_channels, dict)
                    else None
                )
                if value is None and isinstance(q_channels, dict):
                    value = q_channels.get(channel)
                if value is None:
                    value = component.get("Q_channel")
                if value is None:
                    value = component.get("paired_Q_channel")
                if value is None:
                    value = component.get("paired_Q")
                try:
                    numeric_value = float(value)
                except (TypeError, ValueError):
                    continue
                row = {
                    "iteration": int(observation.get("iteration", 0)),
                    "channel": str(channel),
                    "group_id": int(observation.get("group_id", 1)),
                    "group_name": str(
                        observation.get("group_name")
                        or f"Group {observation.get('group_id', 1)}"
                    ),
                    "value": numeric_value,
                }
                row.update({
                    name: float(params[name])
                    for name in PARAMETERS
                    if params.get(name) is not None
                })
                per_iteration.append(row)
            if average_channels and per_iteration:
                averaged = dict(per_iteration[0])
                averaged["channel"] = "Average"
                averaged["value"] = float(
                    np.mean([row["value"] for row in per_iteration])
                )
                rows.append(averaged)
            elif per_iteration:
                rows.extend(per_iteration)
            else:
                try:
                    numeric_value = float(observation.get(primary_key))
                except (TypeError, ValueError):
                    continue
                row = {
                    "iteration": int(observation.get("iteration", 0)),
                    "channel": "Run",
                    "group_id": int(observation.get("group_id", 1)),
                    "group_name": str(
                        observation.get("group_name")
                        or f"Group {observation.get('group_id', 1)}"
                    ),
                    "value": numeric_value,
                }
                row.update({
                    name: float(params[name])
                    for name in PARAMETERS
                    if params.get(name) is not None
                })
                rows.append(row)
            continue
        per_iteration = []
        phase_metrics = (
            observation.get("channel_metrics") or {}
            if phase == "measurement"
            else observation.get(f"{phase}_channel_metrics") or {}
        )
        components = (observation.get("quality") or {}).get("channel_components") or {}
        for channel in selected_channels:
            if source == "channel":
                metrics = phase_metrics.get(channel, {}) or {}
                value = metrics.get(primary_key)
                if value is None and fallback_key:
                    value = metrics.get(fallback_key)
            else:
                component = components.get(channel, {}) or {}
                if phase == "measurement" and primary_key == "classic_Q":
                    value = component.get("Q_channel")
                elif phase == "measurement" and primary_key == "snr_score":
                    value = component.get("normalized_SNR")
                else:
                    value = component.get(f"{phase}_{primary_key}")
            try:
                numeric_value = float(value)
            except (TypeError, ValueError):
                continue
            row = {
                "iteration": int(observation.get("iteration", 0)),
                "channel": channel,
                "group_id": int(observation.get("group_id", 1)),
                "group_name": str(
                    observation.get("group_name")
                    or f"Group {observation.get('group_id', 1)}"
                ),
                "value": numeric_value,
            }
            row.update({
                name: float(params[name])
                for name in PARAMETERS
                if params.get(name) is not None
            })
            per_iteration.append(row)
        if average_channels and per_iteration:
            averaged = dict(per_iteration[0])
            averaged["channel"] = "Average"
            averaged["value"] = float(np.mean([row["value"] for row in per_iteration]))
            rows.append(averaged)
        else:
            rows.extend(per_iteration)
    return pd.DataFrame(rows)


def _real_group_metric_points(
    observations: list[dict],
    metric_label: str,
    phase: str,
    selected_groups: list[dict],
) -> pd.DataFrame:
    """Average member channels into one real-data series per channel group."""
    frames = []
    for group in selected_groups:
        group_id = int(group["id"])
        group_observations = [
            observation for observation in observations
            if int(observation.get("group_id", 1)) == group_id
        ]
        points = _real_metric_points(
            group_observations,
            metric_label,
            phase,
            [str(channel) for channel in group.get("channels", [])],
            average_channels=True,
        )
        if not points.empty:
            points["channel"] = str(group.get("name") or f"Group {group_id}")
            points["group_id"] = group_id
            frames.append(points)
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def _real_comparison_payload(
    points: pd.DataFrame,
    *,
    metric: str,
    phase: str,
    channel_mode: str,
    session_path: Path,
) -> dict:
    return {
        "points": points.copy(),
        "metric": metric,
        "phase": phase,
        "channel_mode": channel_mode,
        "session_path": str(session_path),
        "row_count": int(len(points)),
    }


def _real_comparison_join_columns(
    current: pd.DataFrame,
    cached: pd.DataFrame,
) -> list[str]:
    parameter_columns = [
        parameter for parameter in PARAMETERS
        if parameter in current.columns and parameter in cached.columns
    ]
    series_columns = [
        column for column in ("phase", "channel", "group_id")
        if column in current.columns and column in cached.columns
    ]
    return [*parameter_columns, *series_columns]


def _comparison_join_frame(frame: pd.DataFrame, join_columns: list[str]) -> pd.DataFrame:
    prepared = frame.copy()
    for column in join_columns:
        if column in PARAMETERS:
            prepared[column] = pd.to_numeric(prepared[column], errors="coerce").round(12)
        elif column == "group_id":
            prepared[column] = pd.to_numeric(prepared[column], errors="coerce")
        else:
            prepared[column] = prepared[column].astype(str)
    prepared["value"] = pd.to_numeric(prepared["value"], errors="coerce")
    prepared = prepared.dropna(subset=[*join_columns, "value"])
    metadata_columns = [
        column for column in prepared.columns
        if column not in {*join_columns, "value"}
    ]
    aggregations = {"value": "mean"}
    aggregations.update({column: "first" for column in metadata_columns})
    return prepared.groupby(join_columns, as_index=False, dropna=False).agg(aggregations)


def _real_comparison_delta_points(
    current: pd.DataFrame,
    cached: pd.DataFrame,
) -> tuple[pd.DataFrame, str | None]:
    if current.empty or cached.empty:
        return pd.DataFrame(), "Current and cached comparison tables must both contain rows."
    join_columns = _real_comparison_join_columns(current, cached)
    parameter_columns = [column for column in join_columns if column in PARAMETERS]
    if not parameter_columns:
        return pd.DataFrame(), "No shared parameter columns are available for comparison."
    series_columns = [column for column in join_columns if column not in parameter_columns]
    current_join = _comparison_join_frame(current, [*parameter_columns, *series_columns])
    cached_join = _comparison_join_frame(cached, [*parameter_columns, *series_columns])

    output_frames = []
    skipped_series = []
    if series_columns:
        cached_groups = cached_join.groupby(series_columns, sort=False, dropna=False)
    else:
        cached_groups = [((), cached_join)]
    for series_key, cached_series in cached_groups:
        if series_columns:
            if not isinstance(series_key, tuple):
                series_key = (series_key,)
            current_series = current_join
            label_parts = []
            for column, value in zip(series_columns, series_key):
                current_series = current_series[current_series[column] == value]
                label_parts.append(f"{column}={value}")
            series_label = ", ".join(label_parts)
        else:
            current_series = current_join
            series_label = "all rows"

        active_parameters = [
            column for column in parameter_columns
            if pd.to_numeric(current_series[column], errors="coerce").nunique(dropna=True) > 1
        ]
        if not active_parameters:
            skipped_series.append(series_label)
            continue
        current_valid = current_series.dropna(subset=[*active_parameters, "value"])
        cached_valid = cached_series.dropna(subset=active_parameters)
        if len(current_valid) < len(active_parameters) + 1 or cached_valid.empty:
            skipped_series.append(series_label)
            continue
        coordinates = np.column_stack([
            pd.to_numeric(current_valid[column], errors="coerce").to_numpy(dtype=float)
            for column in active_parameters
        ])
        query_coordinates = np.column_stack([
            pd.to_numeric(cached_valid[column], errors="coerce").to_numpy(dtype=float)
            for column in active_parameters
        ])
        values = pd.to_numeric(current_valid["value"], errors="coerce").to_numpy(dtype=float)
        finite_source = np.isfinite(coordinates).all(axis=1) & np.isfinite(values)
        finite_query = np.isfinite(query_coordinates).all(axis=1)
        if finite_source.sum() < len(active_parameters) + 1 or not finite_query.any():
            skipped_series.append(series_label)
            continue
        try:
            interpolated_current = np.full(len(cached_valid), np.nan, dtype=float)
            interpolated_current[finite_query] = _rbf_interpolation_values(
                coordinates[finite_source],
                values[finite_source],
                query_coordinates[finite_query],
            )
        except Exception:
            skipped_series.append(series_label)
            continue

        cached_lookup = cached_valid.reset_index(drop=True).copy()
        cached_lookup["_comparison_row"] = np.arange(len(cached_lookup))
        exact_current = (
            current_valid
            .groupby(active_parameters, as_index=False, dropna=False)["value"]
            .mean()
            .rename(columns={"value": "exact_current_value"})
        )
        exact_matches = cached_lookup.merge(
            exact_current,
            on=active_parameters,
            how="left",
            sort=False,
        )
        exact_values = pd.to_numeric(
            exact_matches.sort_values("_comparison_row")["exact_current_value"],
            errors="coerce",
        ).to_numpy(dtype=float)
        exact_mask = np.isfinite(exact_values)
        interpolated_current[exact_mask] = exact_values[exact_mask]

        compared = cached_valid.copy()
        compared["cached_value"] = pd.to_numeric(
            compared["value"],
            errors="coerce",
        ).to_numpy(dtype=float)
        compared["current_value"] = interpolated_current
        compared = compared[np.isfinite(compared["current_value"])]
        compared = compared[np.isfinite(compared["cached_value"])]
        if compared.empty:
            skipped_series.append(series_label)
            continue
        compared["value"] = compared["current_value"] - compared["cached_value"]
        compared["comparison_delta"] = compared["value"]
        output_frames.append(compared)

    if not output_frames:
        return (
            pd.DataFrame(),
            "RBF comparison could not evaluate any cached parameter coordinates "
            "from the current session data.",
        )
    result = pd.concat(output_frames, ignore_index=True)
    if skipped_series:
        skipped_preview = "; ".join(skipped_series[:4])
        suffix = "..." if len(skipped_series) > 4 else ""
        return (
            result,
            f"RBF comparison skipped {len(skipped_series)} sparse series: "
            f"{skipped_preview}{suffix}",
        )
    return result, None


def _split_real_points_by_phase(points: pd.DataFrame, phases: Sequence[str]) -> dict[str, pd.DataFrame]:
    if points.empty or "phase" not in points.columns:
        return {phase: pd.DataFrame() for phase in phases}
    return {
        phase: points.loc[points["phase"].astype(str) == str(phase)]
        .drop(columns=["phase"])
        .reset_index(drop=True)
        for phase in phases
    }


def _plot_real_comparison_3d(
    points: pd.DataFrame,
    *,
    value_column: str,
    value_label: str,
    x_name: str,
    y_name: str,
    z_name: str,
    colorscale: str,
    value_range: tuple[float, float] | None = None,
    slice_axis: str | None = None,
    slice_value: float | None = None,
) -> go.Figure:
    columns = [x_name, y_name, z_name, value_column]
    metadata = [
        column for column in (
            "phase",
            "channel",
            "group_id",
            "cached_value",
            "current_value",
            "comparison_delta",
        )
        if column in points.columns and column not in columns
    ]
    valid = points[columns + metadata].copy()
    valid[columns] = valid[columns].apply(pd.to_numeric, errors="coerce")
    valid = valid.dropna(subset=columns)
    fig = go.Figure()
    if valid.empty:
        fig.add_annotation(
            text="No comparison values are available for these axes.",
            x=.5,
            y=.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        fig.update_layout(height=420)
        return fig
    value_min = (
        float(value_range[0])
        if value_range is not None
        else float(valid[value_column].min())
    )
    value_max = (
        float(value_range[1])
        if value_range is not None
        else float(valid[value_column].max())
    )
    if value_min == value_max:
        value_max = value_min + 1.0
    custom_columns = [
        column for column in (
            "phase",
            "channel",
            "cached_value",
            "current_value",
            "comparison_delta",
        )
        if column in valid.columns
    ]
    customdata = valid[custom_columns] if custom_columns else None
    hover_lines = [
        f"{x_name}: %{{x:.4g}}",
        f"{y_name}: %{{y:.4g}}",
        f"{z_name}: %{{z:.4g}}",
        f"{value_label}: %{{marker.color:.4g}}",
    ]
    for index, column in enumerate(custom_columns):
        if column in {"cached_value", "current_value", "comparison_delta"}:
            hover_lines.append(f"{column}: %{{customdata[{index}]:.4g}}")
        else:
            hover_lines.append(f"{column}: %{{customdata[{index}]}}")
    fig.add_trace(go.Scatter3d(
        x=valid[x_name],
        y=valid[y_name],
        z=valid[z_name],
        mode="markers",
        marker={
            "size": 5,
            "opacity": 0.8,
            "color": valid[value_column],
            "colorscale": colorscale,
            "cmin": value_min,
            "cmax": value_max,
            "colorbar": {"title": value_label},
        },
        customdata=customdata,
        hovertemplate="<br>".join(hover_lines) + "<extra></extra>",
        name=value_label,
    ))
    _add_plotly_slice_plane(
        fig,
        valid,
        x_axis=x_name,
        y_axis=y_name,
        z_axis=z_name,
        slice_axis=slice_axis,
        slice_value=slice_value,
    )
    fig.update_layout(
        title=f"{value_label} at cached parameter coordinates",
        scene={
            "dragmode": "turntable",
            "xaxis": {"title": x_name},
            "yaxis": {"title": y_name},
            "zaxis": {"title": z_name},
        },
        height=440,
        margin={"l": 0, "r": 0, "t": 45, "b": 0},
    )
    return _apply_plotly_colorbar_height(fig)


def _plot_real_comparison_2d_slice(
    points: pd.DataFrame,
    *,
    value_column: str,
    value_label: str,
    x_name: str,
    y_name: str,
    slice_axis: str,
    slice_value: float,
    colorscale: str,
    value_range: tuple[float, float] | None = None,
    log_frequency: bool = False,
) -> go.Figure:
    columns = [x_name, y_name, slice_axis, value_column]
    fig = go.Figure()
    if any(column not in points.columns for column in columns):
        fig.add_annotation(
            text="No comparison values are available for this slice.",
            x=0.5,
            y=0.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        title_note = _numeric_slice_title_note(slice_axis, slice_value)
        fig.update_layout(
            title=(
                f"{value_label} comparison 2D slice"
                + (f"<br>{title_note}" if title_note else "")
            ),
            xaxis_title=x_name,
            yaxis_title=y_name,
            height=420,
            margin={"l": 65, "r": 90, "t": 65, "b": 65},
        )
        _apply_plotly_colorbar_height(fig)
        _apply_plotly_2d_slice_aspect(
            fig,
            width=800,
            height=int(round(800 / SURROGATE_2D_FIGURE_ASPECT)),
        )
        return fig
    available_columns = [column for column in columns if column in points.columns]
    source = points[available_columns].copy()
    for column in columns:
        if column in source.columns:
            source[column] = pd.to_numeric(source[column], errors="coerce")
    source = source.dropna(subset=columns)
    if source.empty:
        fig.add_annotation(
            text="No comparison values are available for this slice.",
            x=0.5,
            y=0.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
    else:
        working = source.rename(columns={value_column: "value"})
        axis_ranges = {}
        for axis_name in (x_name, y_name):
            axis_values = pd.to_numeric(working[axis_name], errors="coerce")
            axis_values = axis_values[np.isfinite(axis_values)]
            if not axis_values.empty:
                axis_ranges[axis_name] = (
                    float(axis_values.min()),
                    float(axis_values.max()),
                )
        _valid, grid_frame, _error = _interpolated_3d_grid(
            working,
            x_name,
            y_name,
            slice_axis,
            resolution=60,
            method="rbf",
            fill_nearest=True,
            log_frequency=log_frequency,
            axis_include_values={slice_axis: [float(slice_value)]},
            axis_ranges=axis_ranges,
        )
        slice_grid = _apply_numeric_slice(
            grid_frame,
            slice_axis,
            slice_value,
        ).reset_index(drop=True)
        if slice_grid.empty:
            slice_points = _apply_numeric_slice(
                working,
                slice_axis,
                slice_value,
            )
            _slice_valid, fallback_grid = _interpolated_2d_grid(
                slice_points,
                x_name,
                y_name,
                resolution=120,
                log_frequency=log_frequency,
            )
            if fallback_grid is not None:
                grid_x, grid_y, grid_values = fallback_grid
            else:
                grid_x = grid_y = grid_values = None
        else:
            heatmap_grid = (
                slice_grid
                .pivot_table(
                    index=y_name,
                    columns=x_name,
                    values="interpolated_value",
                    aggfunc="mean",
                )
                .sort_index()
                .sort_index(axis=1)
            )
            grid_x = heatmap_grid.columns.to_numpy(dtype=float)
            grid_y = heatmap_grid.index.to_numpy(dtype=float)
            grid_values = heatmap_grid.to_numpy(dtype=float)
        if grid_values is None:
            fig.add_annotation(
                text="No interpolated comparison grid could be generated.",
                x=0.5,
                y=0.5,
                xref="paper",
                yref="paper",
                showarrow=False,
            )
        else:
            display_value_range = value_range or _value_range_from_frame(
                source.rename(columns={value_column: "value"}),
                "value",
            )
            fig.add_trace(go.Heatmap(
                x=grid_x,
                y=grid_y,
                z=grid_values,
                colorscale=colorscale,
                zmin=(
                    display_value_range[0]
                    if display_value_range is not None else None
                ),
                zmax=(
                    display_value_range[1]
                    if display_value_range is not None else None
                ),
                colorbar={"title": value_label},
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"{value_label}: %{{z:.4g}}<extra></extra>"
                ),
                connectgaps=False,
            ))
    title_note = _numeric_slice_title_note(slice_axis, slice_value)
    fig.update_layout(
        title=(
            f"{value_label} comparison 2D slice"
            + (f"<br>{title_note}" if title_note else "")
        ),
        xaxis_title=x_name,
        yaxis_title=y_name,
        xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
        yaxis_type="log" if log_frequency and y_name == "frequency" else "linear",
        height=420,
        margin={"l": 65, "r": 90, "t": 65, "b": 65},
    )
    _apply_plotly_colorbar_height(fig)
    _apply_plotly_2d_slice_aspect(
        fig,
        width=800,
        height=int(round(800 / SURROGATE_2D_FIGURE_ASPECT)),
    )
    return fig


def _real_count_occurrences(
    observations: list[dict],
    selected_channels: list[str],
) -> pd.DataFrame:
    """Return one row per completed observation and participating channel."""
    rows = []
    selected = set(map(str, selected_channels))
    for observation in observations:
        params = observation.get("params") or {}
        channels = selected.intersection(_real_data_channels([observation]))
        for channel in channels:
            row = {
                "iteration": int(observation.get("iteration", 0)),
                "channel": channel,
                "group_id": int(observation.get("group_id", 1)),
                "group_name": str(
                    observation.get("group_name")
                    or f"Group {observation.get('group_id', 1)}"
                ),
                "value": 1.0,
            }
            row.update({
                name: float(params[name])
                for name in PARAMETERS
                if params.get(name) is not None
            })
            rows.append(row)
    return pd.DataFrame(rows)


def _bin_real_count_points(
    points: pd.DataFrame,
    dimensions: list[str],
    bin_sizes: dict[str, float],
    average_channels: bool,
) -> pd.DataFrame:
    """Aggregate observation occurrences into parameter-space bins."""
    if points.empty:
        return points
    binned = points.copy()
    for dimension in dimensions:
        size = float(bin_sizes[dimension])
        values = pd.to_numeric(binned[dimension], errors="coerce")
        binned[dimension] = (
            np.floor(values / size) * size + size / 2.0
        ).round(12)
    group_columns = ["group_id", "group_name", "channel", *dimensions]
    counts = (
        binned.dropna(subset=dimensions)
        .groupby(group_columns, as_index=False, dropna=False)
        .size()
        .rename(columns={"size": "value"})
    )
    bin_values = [
        list(np.round(np.arange(
            float(binned[dimension].min()),
            float(binned[dimension].max()) + bin_sizes[dimension] * 0.5,
            bin_sizes[dimension],
        ), 12))
        for dimension in dimensions
    ]
    series_rows = binned[
        ["group_id", "group_name", "channel"]
    ].drop_duplicates()
    complete_rows = []
    for _, series in series_rows.iterrows():
        for coordinates in itertools.product(*bin_values):
            complete_rows.append({
                "group_id": series["group_id"],
                "group_name": series["group_name"],
                "channel": series["channel"],
                **dict(zip(dimensions, coordinates)),
            })
    if complete_rows:
        counts = pd.DataFrame(complete_rows).merge(
            counts,
            on=group_columns,
            how="left",
        )
        counts["value"] = counts["value"].fillna(0.0)
    counts["iteration"] = counts["value"]
    if average_channels and not counts.empty:
        counts = (
            counts.groupby(
                ["group_id", "group_name", *dimensions],
                as_index=False,
                dropna=False,
            )["value"]
            .mean()
        )
        counts["channel"] = "Average"
        counts["iteration"] = counts["value"]
    return counts


def _add_plotly_iteration_path(
    fig: go.Figure,
    x,
    y,
    iterations,
    z=None,
    *,
    show_colorbar: bool = True,
) -> None:
    """Add chronological red-to-black line segments to a Plotly figure."""
    x_values = list(x)
    y_values = list(y)
    z_values = list(z) if z is not None else None
    iteration_values = np.asarray(list(iterations), dtype=float)
    if len(iteration_values) < 2:
        return
    norm = _iteration_norm(iteration_values)
    is_3d = z_values is not None
    scatter_type = go.Scatter3d if is_3d else go.Scatter
    for index in range(1, len(iteration_values)):
        color = OBSERVED_PATH_CMAP(norm(iteration_values[index]))
        trace_kwargs = {
            "x": x_values[index - 1:index + 1],
            "y": y_values[index - 1:index + 1],
            "mode": "lines",
            "line": {
                "color": (
                    f"rgb({color[0] * 255:.0f},"
                    f"{color[1] * 255:.0f},"
                    f"{color[2] * 255:.0f})"
                ),
                "width": 4,
            },
            "hoverinfo": "skip",
            "showlegend": False,
        }
        if is_3d:
            trace_kwargs["z"] = z_values[index - 1:index + 1]
        fig.add_trace(scatter_type(**trace_kwargs))
    if show_colorbar:
        marker = {
            "color": [norm.vmin, norm.vmax],
            "colorscale": [
                [0, OBSERVED_PATH_COLORS[0]],
                [1, OBSERVED_PATH_COLORS[1]],
            ],
            "cmin": norm.vmin,
            "cmax": norm.vmax,
            "showscale": True,
            "colorbar": {
                "title": "Iteration",
                "x": 1.12,
                "len": 0.78,
            },
        }
        invisible_kwargs = {
            "x": [None, None],
            "y": [None, None],
            "mode": "markers",
            "marker": marker,
            "hoverinfo": "skip",
            "showlegend": False,
        }
        if is_3d:
            invisible_kwargs["z"] = [None, None]
        fig.add_trace(scatter_type(**invisible_kwargs))


@st.cache_data(show_spinner=False, max_entries=64)
def _plot_real_data_landscape(
    points: pd.DataFrame,
    metric_label: str,
    phase: str,
    view: str,
    x_name: str,
    y_name: str | None,
    z_name: str | None,
    tensor_height: int = 480,
    dot_size: int = 6,
    dot_opacity: float = 0.45,
    log_frequency: bool = False,
    color_by: str = "Measured value",
    group_color_values: dict[int, float] | None = None,
    group_color_label: str | None = None,
    iteration_path: pd.DataFrame | None = None,
    show_iteration_path: bool = True,
    count_bin_sizes: dict[str, float] | None = None,
    axis_ranges: dict[str, tuple[float, float]] | None = None,
    value_range: tuple[float, float] | None = None,
    title_note: str | None = None,
    slice_axis: str | None = None,
    slice_value: float | None = None,
    slice_sweep_values: Sequence[float] | None = None,
    tensor_interpolation_source: pd.DataFrame | None = None,
    show_measured_points: bool = False,
    value_colorscale: str = "Viridis",
):
    def series_label(value: Any) -> str:
        text = str(value)
        if text == "Average":
            return "Channel average"
        if text.lower().startswith("group"):
            return text
        return f"Ch {text}"

    hover_data = ["iteration", "channel"]
    series_columns = ["group_id", "group_name", "channel"]
    multiple_groups = points["group_id"].nunique() > 1
    multiple_series = len(points[series_columns].drop_duplicates()) > 1
    move_legend_below = multiple_series and (
        color_by == "Measured value" or bool(group_color_values)
    )

    def colored_series():
        grouped = list(points.groupby(series_columns, sort=True))
        channel_values = sorted(points["channel"].astype(str).unique(), key=_channel_sort_key)
        group_values = sorted(points["group_id"].astype(int).unique())
        for (group_id, group_name, channel), group in grouped:
            if color_by == "Channel":
                color_index = channel_values.index(str(channel))
                color = plt.get_cmap("tab10")(color_index % 10)
            elif color_by == "Group":
                color_index = group_values.index(int(group_id))
                color = plt.get_cmap("tab10")(color_index % 10)
            else:
                color = _metadata_group_color(group_id, group_color_values)
                yield group_id, group_name, channel, group, color
                continue
            yield (
                group_id,
                group_name,
                channel,
                group,
                f"rgb({color[0] * 255:.0f},{color[1] * 255:.0f},{color[2] * 255:.0f})",
            )

    def trace_label(group_name, channel) -> str:
        channel_label = series_label(channel)
        return (
            f"{group_name} · {channel_label}"
            if multiple_groups else channel_label
        )

    def metadata_color_value(group_id: Any) -> float | None:
        if not group_color_values:
            return None
        numeric_group_id = _finite_float(group_id)
        if numeric_group_id is None:
            return None
        return _finite_float(group_color_values.get(int(numeric_group_id)))

    display_value_range = value_range
    if (
        view == "2D map"
        and display_value_range is None
        and tensor_interpolation_source is not None
        and not tensor_interpolation_source.empty
    ):
        display_value_range = _value_range_from_frame(
            tensor_interpolation_source,
        )

    if metric_label == "Count" and view == "3D tensor":
        fig = go.Figure()
        bin_sizes = count_bin_sizes or {}
        value_min = (
            float(display_value_range[0])
            if display_value_range is not None
            else float(points["value"].min())
        )
        value_max = (
            float(display_value_range[1])
            if display_value_range is not None
            else float(points["value"].max())
        )
        if value_min == value_max:
            value_max = value_min + 1.0
        cube_faces = (
            (0, 1, 2), (0, 2, 3), (4, 6, 5), (4, 7, 6),
            (0, 4, 5), (0, 5, 1), (1, 5, 6), (1, 6, 2),
            (2, 6, 7), (2, 7, 3), (3, 7, 4), (3, 4, 0),
        )
        for trace_index, (
            _group_id,
            group_name,
            channel,
            group,
            _series_color,
        ) in enumerate(colored_series()):
            vertices_x, vertices_y, vertices_z = [], [], []
            face_i, face_j, face_k = [], [], []
            intensities, hover_text = [], []
            half_x = float(bin_sizes.get(x_name, 1.0)) / 2.0
            half_y = float(bin_sizes.get(y_name, 1.0)) / 2.0
            half_z = float(bin_sizes.get(z_name, 1.0)) / 2.0
            for _, row in group.loc[group["value"] > 0].iterrows():
                base = len(vertices_x)
                x0, x1 = row[x_name] - half_x, row[x_name] + half_x
                y0, y1 = row[y_name] - half_y, row[y_name] + half_y
                z0, z1 = row[z_name] - half_z, row[z_name] + half_z
                vertices_x.extend((x0, x1, x1, x0, x0, x1, x1, x0))
                vertices_y.extend((y0, y0, y1, y1, y0, y0, y1, y1))
                vertices_z.extend((z0, z0, z0, z0, z1, z1, z1, z1))
                intensities.extend([float(row["value"])] * 8)
                hover_text.extend([
                    f"Count: {float(row['value']):g}<br>"
                    f"{x_name}: {float(row[x_name]):g}<br>"
                    f"{y_name}: {float(row[y_name]):g}<br>"
                    f"{z_name}: {float(row[z_name]):g}"
                ] * 8)
                for first, second, third in cube_faces:
                    face_i.append(base + first)
                    face_j.append(base + second)
                    face_k.append(base + third)
            fig.add_trace(go.Mesh3d(
                x=vertices_x,
                y=vertices_y,
                z=vertices_z,
                i=face_i,
                j=face_j,
                k=face_k,
                intensity=intensities,
                colorscale=value_colorscale,
                cmin=value_min,
                cmax=value_max,
                showscale=trace_index == 0,
                colorbar={"title": "Count"},
                opacity=dot_opacity,
                flatshading=True,
                name=trace_label(group_name, channel),
                text=hover_text,
                hovertemplate="%{text}<extra></extra>",
            ))
        if (
            show_iteration_path
            and iteration_path is not None
            and not iteration_path.empty
        ):
            path_colorbar_added = False
            for _group_id, group_path in iteration_path.groupby("group_id"):
                ordered_path = group_path.dropna(
                    subset=[x_name, y_name, z_name]
                ).sort_values("iteration")
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path[y_name],
                    ordered_path["iteration"],
                    z=ordered_path[z_name],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = (
                    path_colorbar_added or len(ordered_path) >= 2
                )
        _add_plotly_slice_plane(
            fig,
            points,
            x_axis=x_name,
            y_axis=y_name,
            z_axis=z_name,
            slice_axis=slice_axis,
            slice_value=slice_value,
            slice_sweep_values=slice_sweep_values,
            axis_ranges=axis_ranges,
        )
        fig.update_layout(
            scene={
                "xaxis": {
                    "title": x_name,
                    "type": "log" if log_frequency and x_name == "frequency" else "linear",
                },
                "yaxis": {
                    "title": y_name,
                    "type": "log" if log_frequency and y_name == "frequency" else "linear",
                },
                "zaxis": {
                    "title": z_name,
                    "type": "log" if log_frequency and z_name == "frequency" else "linear",
                },
            },
            height=tensor_height,
        )
    elif metric_label == "Count" and view == "2D map":
        fig = go.Figure()
        heatmap_points = (
            points.groupby([x_name, y_name], as_index=False)["value"].sum()
        )
        count_grid = heatmap_points.pivot(
            index=y_name,
            columns=x_name,
            values="value",
        ).sort_index().sort_index(axis=1).fillna(0.0)
        fig.add_trace(go.Heatmap(
            x=count_grid.columns.to_numpy(),
            y=count_grid.index.to_numpy(),
            z=count_grid.to_numpy(),
            colorscale=value_colorscale,
            zmin=(
                display_value_range[0]
                if display_value_range is not None else None
            ),
            zmax=(
                display_value_range[1]
                if display_value_range is not None else None
            ),
            colorbar={"title": "Count"},
            hovertemplate=(
                f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}"
                "<br>Count: %{z:g}<extra></extra>"
            ),
            xgap=1,
            ygap=1,
        ))
        if (
            show_iteration_path
            and iteration_path is not None
            and not iteration_path.empty
        ):
            path_colorbar_added = False
            for _group_id, group_path in iteration_path.groupby("group_id"):
                ordered_path = group_path.dropna(
                    subset=[x_name, y_name]
                ).sort_values("iteration")
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path[y_name],
                    ordered_path["iteration"],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = (
                    path_colorbar_added or len(ordered_path) >= 2
                )
        fig.update_layout(
            xaxis_title=x_name,
            yaxis_title=y_name,
            xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
            yaxis_type="log" if log_frequency and y_name == "frequency" else "linear",
            height=420,
        )
    elif view == "3D tensor":
        fig = go.Figure()
        value_min = (
            float(display_value_range[0])
            if display_value_range is not None
            else float(points["value"].min())
        )
        value_max = (
            float(display_value_range[1])
            if display_value_range is not None
            else float(points["value"].max())
        )
        if value_min == value_max:
            value_max = value_min + 1.0
        for group_id, group_name, channel, group, series_color in colored_series():
            marker = {"size": dot_size, "opacity": dot_opacity}
            if color_by == "Measured value":
                marker.update({
                    "color": group["value"],
                    "colorscale": value_colorscale,
                    "cmin": value_min,
                    "cmax": value_max,
                    "showscale": len(fig.data) == 0,
                    "colorbar": {"title": metric_label},
                })
            else:
                marker["color"] = series_color
            fig.add_trace(go.Scatter3d(
                x=group[x_name],
                y=group[y_name],
                z=group[z_name],
                mode="markers",
                name=trace_label(group_name, channel),
                marker=marker,
                customdata=group[hover_data],
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"{z_name}: %{{z:.4g}}<br>{metric_label}: %{{marker.color:.4g}}"
                    "<br>Iteration %{customdata[0]}<br>Series %{customdata[1]}<extra></extra>"
                ),
            ))
        if (
            show_iteration_path
            and iteration_path is not None
            and not iteration_path.empty
        ):
            path_colorbar_added = False
            for _group_id, group_path in iteration_path.groupby("group_id"):
                ordered_path = group_path.dropna(
                    subset=[x_name, y_name, z_name]
                ).sort_values("iteration")
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path[y_name],
                    ordered_path["iteration"],
                    z=ordered_path[z_name],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = (
                    path_colorbar_added or len(ordered_path) >= 2
                )
        if group_color_values:
            _add_metadata_colorbar(fig, group_color_values, group_color_label)
        _add_plotly_slice_plane(
            fig,
            points,
            x_axis=x_name,
            y_axis=y_name,
            z_axis=z_name,
            slice_axis=slice_axis,
            slice_value=slice_value,
            slice_sweep_values=slice_sweep_values,
            axis_ranges=axis_ranges,
        )
        fig.update_layout(
            scene={
                "xaxis": {
                    "title": x_name,
                    "type": "log" if log_frequency and x_name == "frequency" else "linear",
                },
                "yaxis": {
                    "title": y_name,
                    "type": "log" if log_frequency and y_name == "frequency" else "linear",
                },
                "zaxis": {
                    "title": z_name,
                    "type": "log" if log_frequency and z_name == "frequency" else "linear",
                },
            },
            height=tensor_height,
        )
    elif view == "2D map":
        columns = [x_name, y_name, "value"]
        metadata = [
            name for name in ("iteration", "channel")
            if name in points.columns
        ]
        valid = points[columns + metadata].copy()
        valid[columns] = valid[columns].apply(pd.to_numeric, errors="coerce")
        valid = valid.dropna(subset=columns)
        grid = None
        attempted_tensor_slice = False
        if (
            tensor_interpolation_source is not None
            and not tensor_interpolation_source.empty
            and slice_axis is not None
            and slice_value is not None
        ):
            attempted_tensor_slice = True
            _tensor_valid, tensor_grid, _tensor_error = _interpolated_3d_grid(
                tensor_interpolation_source,
                x_name,
                y_name,
                slice_axis,
                resolution=50,
                method="rbf",
                fill_nearest=True,
                log_frequency=log_frequency,
                axis_include_values={slice_axis: [float(slice_value)]},
                axis_ranges={
                    axis_name: axis_ranges[axis_name]
                    for axis_name in (x_name, y_name)
                    if axis_ranges and axis_name in axis_ranges
                },
            )
            slice_grid = _apply_numeric_slice(
                tensor_grid,
                slice_axis,
                slice_value,
            )
            if not slice_grid.empty:
                heatmap_grid = (
                    slice_grid
                    .pivot_table(
                        index=y_name,
                        columns=x_name,
                        values="interpolated_value",
                        aggfunc="mean",
                    )
                    .sort_index()
                    .sort_index(axis=1)
                )
                grid = (
                    heatmap_grid.columns.to_numpy(dtype=float),
                    heatmap_grid.index.to_numpy(dtype=float),
                    heatmap_grid.to_numpy(dtype=float),
                )
        if grid is None and not attempted_tensor_slice:
            valid, grid = _interpolated_2d_grid(
                points,
                x_name,
                y_name,
                log_frequency=log_frequency,
            )
        fig = go.Figure()
        if grid is not None:
            grid_x, grid_y, grid_values = grid
            fig.add_trace(go.Heatmap(
                x=grid_x,
                y=grid_y,
                z=grid_values,
                colorscale=value_colorscale,
                zmin=(
                    display_value_range[0]
                    if display_value_range is not None else None
                ),
                zmax=(
                    display_value_range[1]
                    if display_value_range is not None else None
                ),
                colorbar={"title": metric_label},
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"Interpolated {metric_label}: %{{z:.4g}}<extra></extra>"
                ),
                connectgaps=False,
            ))
        if show_measured_points and color_by == "Measured value":
            fig.add_trace(go.Scatter(
                x=valid[x_name], y=valid[y_name], mode="markers",
                marker={
                    "size": 8, "color": valid["value"], "colorscale": value_colorscale,
                    "cmin": (
                        display_value_range[0]
                        if display_value_range is not None else None
                    ),
                    "cmax": (
                        display_value_range[1]
                        if display_value_range is not None else None
                    ),
                    "showscale": grid is None, "colorbar": {"title": metric_label},
                    "line": {"color": "white", "width": 1},
                },
                name="measured points",
                customdata=valid[["iteration", "channel", "value"]],
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"{metric_label}: %{{customdata[2]:.4g}}<br>"
                    "Iteration %{customdata[0]}<br>Channel %{customdata[1]}<extra></extra>"
                ),
            ))
        elif show_measured_points:
            for group_id, group_name, channel, group, series_color in colored_series():
                marker = {"size": 8}
                color_value = metadata_color_value(group_id)
                if group_color_values and color_value is not None:
                    marker.update({
                        "color": [color_value] * len(group),
                        "coloraxis": "coloraxis",
                    })
                else:
                    marker["color"] = series_color
                fig.add_trace(go.Scatter(
                    x=group[x_name], y=group[y_name], mode="markers",
                    marker=marker,
                    name=trace_label(group_name, channel),
                    customdata=group[["iteration", "channel", "value"]],
                    hovertemplate=(
                        f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                        f"{metric_label}: %{{customdata[2]:.4g}}<extra></extra>"
                    ),
                ))
            if group_color_values:
                _apply_metadata_coloraxis(fig, group_color_values, group_color_label)
        if (
            show_iteration_path
            and iteration_path is not None
            and not iteration_path.empty
        ):
            path_colorbar_added = False
            for _group_id, group_path in iteration_path.groupby("group_id"):
                ordered_path = group_path.dropna(
                    subset=[x_name, y_name]
                ).sort_values("iteration")
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path[y_name],
                    ordered_path["iteration"],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = (
                    path_colorbar_added or len(ordered_path) >= 2
                )
        fig.update_layout(
            xaxis_title=x_name,
            yaxis_title=y_name,
            xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
            yaxis_type="log" if log_frequency and y_name == "frequency" else "linear",
            height=420,
        )
    else:
        fig = go.Figure()
        for group_id, group_name, channel, group, series_color in colored_series():
            ordered = group.sort_values(x_name)
            marker = {"size": dot_size, "opacity": dot_opacity}
            line = None
            if color_by != "Measured value":
                color_value = metadata_color_value(group_id)
                if series_color:
                    marker["color"] = series_color
                elif group_color_values and color_value is not None:
                    marker["color"] = _metadata_group_color(
                        group_id,
                        group_color_values,
                    )
                if series_color:
                    line = {"color": series_color}
            fig.add_trace(go.Scatter(
                x=ordered[x_name],
                y=ordered["value"],
                mode="lines+markers",
                name=trace_label(group_name, channel),
                marker=marker,
                line=line,
                customdata=ordered[["iteration", "channel"]],
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{metric_label}: %{{y:.4g}}<br>"
                    "Iteration %{customdata[0]}<br>Channel %{customdata[1]}<extra></extra>"
                ),
            ))
        if show_iteration_path and metric_label != "Count":
            path_colorbar_added = False
            for (
                _group_id,
                _group_name,
                _channel,
                group,
                _series_color,
            ) in colored_series():
                ordered_path = group.sort_values("iteration")
                if len(ordered_path) < 2:
                    continue
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path["value"],
                    ordered_path["iteration"],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = True
        fig.update_layout(
            xaxis_title=x_name,
            yaxis_title=metric_label,
            xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
            height=360,
        )
    figure_title = f"Measured {phase} {metric_label} | {view}"
    if title_note:
        figure_title = f"{figure_title}<br>{title_note}"
    fig.update_layout(
        title=figure_title,
        margin={
            "l": 65,
            "r": (
                150
                if show_iteration_path and (
                    iteration_path is not None or metric_label != "Count"
                )
                else 85 if move_legend_below else 30
            ),
            "t": 55,
            "b": 135 if move_legend_below else 55,
        },
        legend=(
            {
                "orientation": "h",
                "x": 0,
                "xanchor": "left",
                "y": -0.24,
                "yanchor": "top",
            }
            if move_legend_below else None
        ),
        height=(
            int(fig.layout.height or 400) + 100
            if move_legend_below else fig.layout.height
        ),
    )
    if axis_ranges:
        def display_range(name: str) -> list[float] | None:
            bounds = axis_ranges.get(name)
            if bounds is None:
                return None
            if log_frequency and name == "frequency":
                return [
                    float(np.log10(max(bounds[0], 1e-12))),
                    float(np.log10(max(bounds[1], 1e-12))),
                ]
            return [float(bounds[0]), float(bounds[1])]

        if view == "3D tensor":
            fig.update_scenes(
                xaxis_range=display_range(x_name),
                yaxis_range=display_range(y_name),
                zaxis_range=display_range(z_name),
            )
        else:
            fig.update_xaxes(range=display_range(x_name))
            if view in ("2D map", "3D tensor"):
                fig.update_yaxes(range=display_range(y_name))
            elif display_value_range is not None:
                fig.update_yaxes(range=list(map(float, display_value_range)))
    return fig


@st.cache_data(show_spinner=False, max_entries=64)
def _plot_real_data_both_1d(
    buffer_points: pd.DataFrame,
    target_points: pd.DataFrame,
    metric_label: str,
    x_name: str,
    dot_size: int = 6,
    dot_opacity: float = 0.45,
    log_frequency: bool = False,
    color_by: str = "Measured value",
    group_color_values: dict[int, float] | None = None,
    group_color_label: str | None = None,
    show_iteration_path: bool = True,
    axis_ranges: dict[str, tuple[float, float]] | None = None,
    value_range: tuple[float, float] | None = None,
):
    fig = go.Figure()
    colors = {"buffer": "#1f77b4", "target": "#ff7f0e"}
    for phase, points in (("buffer", buffer_points), ("target", target_points)):
        if points.empty:
            continue
        channel_values = sorted(
            points["channel"].astype(str).unique(),
            key=_channel_sort_key,
        )
        group_values = sorted(points["group_id"].astype(int).unique())
        for channel_index, (
            (group_id, group_name, channel),
            group,
        ) in enumerate(points.groupby(
            ["group_id", "group_name", "channel"],
            sort=False,
        )):
            ordered = group.sort_values(x_name)
            series_color = colors[phase]
            if color_by == "Channel":
                rgba = plt.get_cmap("tab10")(
                    channel_values.index(str(channel)) % 10
                )
                series_color = (
                    f"rgb({rgba[0] * 255:.0f},{rgba[1] * 255:.0f},"
                    f"{rgba[2] * 255:.0f})"
                )
            elif color_by == "Group":
                rgba = plt.get_cmap("tab10")(
                    group_values.index(int(group_id)) % 10
                )
                series_color = (
                    f"rgb({rgba[0] * 255:.0f},{rgba[1] * 255:.0f},"
                    f"{rgba[2] * 255:.0f})"
                )
            elif group_color_values:
                series_color = _metadata_group_color(
                    group_id,
                    group_color_values,
                )
            fig.add_trace(go.Scatter(
                x=ordered[x_name],
                y=ordered["value"],
                mode="lines+markers",
                name=f"{phase.title()} · {group_name} · Ch {channel}",
                legendgroup=phase,
                showlegend=True,
                line={
                    "color": series_color,
                    "dash": "dash" if phase == "buffer" else "solid",
                },
                marker={
                    "color": series_color,
                    "size": dot_size,
                    "opacity": dot_opacity,
                },
                customdata=ordered[["iteration", "channel"]],
                hovertemplate=(
                    f"{phase.title()}<br>{x_name}: %{{x:.4g}}<br>"
                    f"{metric_label}: %{{y:.4g}}<br>"
                    "Iteration %{customdata[0]}<br>Channel %{customdata[1]}<extra></extra>"
                ),
            ))
    if show_iteration_path:
        path_colorbar_added = False
        for _phase, points in (("buffer", buffer_points), ("target", target_points)):
            if points.empty:
                continue
            for _series, group in points.groupby(
                ["group_id", "group_name", "channel"],
                sort=False,
            ):
                ordered_path = group.sort_values("iteration")
                if len(ordered_path) < 2:
                    continue
                _add_plotly_iteration_path(
                    fig,
                    ordered_path[x_name],
                    ordered_path["value"],
                    ordered_path["iteration"],
                    show_colorbar=not path_colorbar_added,
                )
                path_colorbar_added = True
    fig.update_layout(
        title=f"Measured buffer vs target {metric_label} | 1D slice",
        xaxis_title=x_name,
        yaxis_title=metric_label,
        xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
        height=480 if group_color_values else 380,
        margin={
            "l": 65,
            "r": 150 if show_iteration_path else 85,
            "t": 55,
            "b": 135 if group_color_values else 55,
        },
        legend=(
            {
                "orientation": "h",
                "x": 0,
                "xanchor": "left",
                "y": -0.24,
                "yanchor": "top",
            }
            if group_color_values else None
        ),
    )
    if axis_ranges and x_name in axis_ranges:
        x_range = list(map(float, axis_ranges[x_name]))
        if log_frequency and x_name == "frequency":
            x_range = [
                float(np.log10(max(x_range[0], 1e-12))),
                float(np.log10(max(x_range[1], 1e-12))),
            ]
        fig.update_xaxes(range=x_range)
    if value_range is not None:
        fig.update_yaxes(range=list(map(float, value_range)))
    return fig


def _clicked_iteration(event: Any) -> int | None:
    """Extract an iteration from Streamlit's Plotly selection event."""
    try:
        points = event.selection.points
    except (AttributeError, KeyError, TypeError):
        return None
    if not points:
        return None
    point = points[-1]
    raw = point.get("customdata", point.get("x"))
    if isinstance(raw, (list, tuple)):
        raw = raw[0] if raw else None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _selected_3d_coordinate(event: Any, selected_axis: str, axes: tuple[str, str, str]) -> float | None:
    """Extract one displayed coordinate from a Streamlit Plotly 3D point selection."""
    try:
        points = event.selection.points
    except (AttributeError, KeyError, TypeError):
        return None
    if not points or selected_axis not in axes:
        return None
    point = points[-1]
    plotly_axis = ("x", "y", "z")[axes.index(selected_axis)]
    try:
        value = float(point.get(plotly_axis))
    except (TypeError, ValueError):
        return None
    return value if np.isfinite(value) else None


def _clicked_3d_coordinate(
    clicked_points: list[dict] | None,
    selected_axis: str,
    axes: tuple[str, str, str],
) -> float | None:
    """Extract one displayed coordinate from streamlit-plotly-events click data."""
    if not clicked_points or selected_axis not in axes:
        return None
    point = clicked_points[-1]
    plotly_axis = ("x", "y", "z")[axes.index(selected_axis)]
    raw = point.get(plotly_axis)
    if raw is None and isinstance(point.get("point"), dict):
        raw = point["point"].get(plotly_axis)
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    return value if np.isfinite(value) else None


def _pdf_text_page(pdf: PdfPages, title: str, lines: list[str]) -> None:
    fig = plt.figure(figsize=(8.5, 11))
    fig.text(.08, .94, title, fontsize=20, weight="bold", va="top")
    fig.text(.08, .89, "\n".join(lines), fontsize=10, va="top", family="monospace", wrap=True)
    pdf.savefig(fig, bbox_inches="tight")
    plt.close(fig)


def _pdf_text_pages(
    pdf: PdfPages,
    title: str,
    lines: list[str],
    lines_per_page: int = 44,
) -> None:
    chunks = [
        lines[index:index + lines_per_page]
        for index in range(0, max(len(lines), 1), lines_per_page)
    ]
    for index, chunk in enumerate(chunks):
        page_title = title if len(chunks) == 1 else f"{title} ({index + 1}/{len(chunks)})"
        _pdf_text_page(pdf, page_title, chunk)


def _format_duration(seconds: float | None) -> str:
    if seconds is None or not np.isfinite(seconds) or seconds < 0:
        return "calculating..."
    seconds = int(round(seconds))
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    if hours:
        return f"{hours}h {minutes}m"
    if minutes:
        return f"{minutes}m {seconds}s"
    return f"{seconds}s"


def _pdf_save(pdf: PdfPages, fig, title: str | None = None) -> None:
    if title and fig.axes:
        fig.suptitle(title, fontsize=13, y=.995)
    parameter_context = getattr(pdf, "_bo_parameter_context", "")
    if parameter_context:
        fig.text(
            .01, .023,
            f"BO parameter context: {parameter_context}",
            fontsize=5,
            va="bottom",
            wrap=True,
        )
    fig.tight_layout(rect=(0, .05, 1, .97) if title else (0, .05, 1, 1))
    pdf.savefig(fig, bbox_inches="tight")
    plt.close(fig)


def _pdf_equation_footer(fig, label: str, equation: str) -> None:
    compact = " | ".join(line.strip() for line in equation.splitlines() if line.strip())
    fig.text(.01, .008, f"{label}: {compact}", fontsize=4.5, va="bottom", wrap=True)


def _has_numeric_variation(values) -> bool:
    return pd.to_numeric(pd.Series(values), errors="coerce").dropna().nunique() > 1


def _interpolated_2d_grid(
    points: pd.DataFrame,
    x_name: str,
    y_name: str,
    resolution: int = 120,
    log_frequency: bool = False,
) -> tuple[pd.DataFrame, tuple[np.ndarray, np.ndarray, np.ndarray] | None]:
    """Build an RBF-smoothed measured map on a complete rectangular grid."""
    columns = [x_name, y_name, "value"]
    metadata = [name for name in ("iteration", "channel") if name in points.columns]
    valid = points[columns + metadata].copy()
    valid[columns] = valid[columns].apply(pd.to_numeric, errors="coerce")
    valid = valid.dropna(subset=columns)

    unique = valid.groupby([x_name, y_name], as_index=False)["value"].mean()
    if (
        len(unique) < 2
        or unique[x_name].nunique() < 2
        or unique[y_name].nunique() < 2
    ):
        return valid, None

    x_axis = _interpolation_axis_values(
        unique[x_name],
        x_name,
        resolution,
        log_frequency,
    )
    y_axis = _interpolation_axis_values(
        unique[y_name],
        y_name,
        resolution,
        log_frequency,
    )
    if x_axis is None or y_axis is None:
        return valid, None
    transformed_x, grid_x = x_axis
    transformed_y, grid_y = y_axis
    mesh_x, mesh_y = np.meshgrid(transformed_x, transformed_y)
    try:
        coordinates = np.column_stack([
            _transform_interpolation_values(
                unique[x_name],
                x_name,
                log_frequency,
            ).to_numpy(dtype=float),
            _transform_interpolation_values(
                unique[y_name],
                y_name,
                log_frequency,
            ).to_numpy(dtype=float),
        ])
        values = unique["value"].to_numpy()
        finite = np.isfinite(coordinates).all(axis=1) & np.isfinite(values)
        coordinates = coordinates[finite]
        values = values[finite]
        if len(values) < 2:
            return valid, None
        query_coordinates = np.column_stack([mesh_x.ravel(), mesh_y.ravel()])
        grid_values = _rbf_interpolation_values(
            coordinates,
            values,
            query_coordinates,
        ).reshape(mesh_x.shape)
    except Exception:
        return valid, None
    if not np.isfinite(grid_values).any():
        return valid, None
    return valid, (grid_x, grid_y, grid_values)


def _interpolation_axis_values(
    values: pd.Series,
    name: str,
    resolution: int,
    log_frequency: bool,
) -> tuple[np.ndarray, np.ndarray] | None:
    numeric = pd.to_numeric(values, errors="coerce").dropna()
    if numeric.empty:
        return None
    if log_frequency and name == "frequency":
        numeric = numeric[numeric > 0]
        if numeric.empty:
            return None
        transformed = np.log10(numeric.to_numpy(dtype=float))
        grid_transformed = np.linspace(
            float(np.min(transformed)),
            float(np.max(transformed)),
            resolution,
        )
        return grid_transformed, np.power(10.0, grid_transformed)
    grid_values = np.linspace(
        float(numeric.min()),
        float(numeric.max()),
        resolution,
    )
    return grid_values, grid_values


def _transform_interpolation_values(
    values: pd.Series,
    name: str,
    log_frequency: bool,
) -> pd.Series:
    numeric = pd.to_numeric(values, errors="coerce")
    if log_frequency and name == "frequency":
        numeric = numeric.where(numeric > 0)
        return np.log10(numeric)
    return numeric


def _normalized_interpolation_coordinates(
    coordinates: np.ndarray,
    query_coordinates: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    lower = np.nanmin(coordinates, axis=0)
    upper = np.nanmax(coordinates, axis=0)
    span = np.where(np.abs(upper - lower) < 1e-12, 1.0, upper - lower)
    return (coordinates - lower) / span, (query_coordinates - lower) / span


def _rbf_interpolation_values(
    coordinates: np.ndarray,
    values: np.ndarray,
    query_coordinates: np.ndarray,
) -> np.ndarray:
    normalized_coordinates, normalized_query = _normalized_interpolation_coordinates(
        coordinates,
        query_coordinates,
    )
    source_axes = [
        normalized_coordinates[:, index]
        for index in range(coordinates.shape[1])
    ]
    query_axes = [
        normalized_query[:, index]
        for index in range(coordinates.shape[1])
    ]
    value_scale = max(float(np.nanstd(values)), float(np.nanmean(np.abs(values))), 1.0)
    base_smooth = max(value_scale * 0.02, 1e-8)
    last_error: Exception | None = None
    for function_name in ("multiquadric", "linear", "inverse"):
        for smooth_multiplier in (1.0, 5.0, 25.0, 100.0):
            try:
                rbf = Rbf(
                    *source_axes,
                    values,
                    function=function_name,
                    smooth=base_smooth * smooth_multiplier,
                )
                result = np.asarray(rbf(*query_axes), dtype=float)
                if np.isfinite(result).any():
                    return result
            except Exception as exc:
                last_error = exc
                continue
    if last_error is not None:
        raise last_error
    raise RuntimeError("RBF interpolation produced no finite values.")


def _gp_smoothed_interpolation_values(
    coordinates: np.ndarray,
    values: np.ndarray,
    query_coordinates: np.ndarray,
    *,
    noise: float = 1e-4,
) -> np.ndarray:
    normalized_coordinates, normalized_query = _normalized_interpolation_coordinates(
        coordinates,
        query_coordinates,
    )
    try:
        source_scale = float(np.nanstd(values))
        means, _stds = _simulation_gp_predict(
            normalized_coordinates,
            values,
            normalized_query,
            np.full(normalized_coordinates.shape[1], 0.25, dtype=float),
            max(float(noise), 1e-10),
            config={
                "random_seed": 42,
                "acquisition": {"gp_optimizer_restarts": 1},
            },
            fixed_length_scales=True,
        )
        means = np.asarray(means, dtype=float)
        if (
            source_scale > 1e-9
            and float(np.nanstd(means)) < max(1e-9, source_scale * 1e-3)
        ):
            return _rbf_interpolation_values(
                coordinates,
                values,
                query_coordinates,
            )
        return means
    except Exception:
        return _rbf_interpolation_values(
            coordinates,
            values,
            query_coordinates,
        )


def _interpolated_3d_grid(
    points: pd.DataFrame,
    x_name: str,
    y_name: str,
    z_name: str,
    *,
    resolution: int = 25,
    method: str = "linear",
    fill_nearest: bool = True,
    log_frequency: bool = False,
    axis_include_values: Mapping[str, Sequence[float]] | None = None,
    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame, str | None]:
    """Interpolate measured 3D points onto a regular grid for export/simulation."""
    columns = [x_name, y_name, z_name, "value"]
    valid = points[columns].copy()
    valid[columns] = valid[columns].apply(pd.to_numeric, errors="coerce")
    valid = valid.dropna(subset=columns)
    if valid.empty:
        return valid, pd.DataFrame(), "No numeric observations are available."

    unique = valid.groupby([x_name, y_name, z_name], as_index=False)["value"].mean()
    if (
        len(unique) < 4
        or unique[x_name].nunique() < 2
        or unique[y_name].nunique() < 2
        or unique[z_name].nunique() < 2
    ):
        return (
            valid,
            pd.DataFrame(),
            "At least four observations with variation on all three axes are required.",
        )

    size = max(6, min(60, int(resolution)))
    axis_specs = {
        name: _interpolation_axis_values(
            unique[name],
            name,
            size,
            log_frequency,
        )
        for name in (x_name, y_name, z_name)
    }
    if any(spec is None for spec in axis_specs.values()):
        return valid, pd.DataFrame(), "Could not build one or more interpolation axes."
    if axis_ranges:
        for name in (x_name, y_name, z_name):
            requested_range = axis_ranges.get(name)
            if requested_range is None:
                continue
            range_values = pd.to_numeric(
                pd.Series(list(requested_range)),
                errors="coerce",
            ).dropna()
            if len(range_values) < 2:
                continue
            lower = float(range_values.iloc[0])
            upper = float(range_values.iloc[1])
            if not np.isfinite(lower) or not np.isfinite(upper):
                continue
            if np.isclose(lower, upper):
                center = lower
                padding = max(abs(center) * 0.05, 1e-9)
                lower, upper = center - padding, center + padding
            if lower > upper:
                lower, upper = upper, lower
            if log_frequency and name == "frequency":
                if lower <= 0 or upper <= 0:
                    continue
                transformed_axis = np.linspace(
                    float(np.log10(lower)),
                    float(np.log10(upper)),
                    size,
                )
                display_axis = np.power(10.0, transformed_axis)
            else:
                display_axis = np.linspace(lower, upper, size)
                transformed_axis = display_axis
            axis_specs[name] = (
                transformed_axis.astype(float),
                display_axis.astype(float),
            )
    if axis_include_values:
        for name in (x_name, y_name, z_name):
            include_values = axis_include_values.get(name)
            if not include_values:
                continue
            include_series = pd.Series(include_values, dtype=float)
            transformed_include = _transform_interpolation_values(
                include_series,
                name,
                log_frequency,
            )
            display_include = pd.to_numeric(include_series, errors="coerce")
            included = pd.DataFrame({
                "transformed": transformed_include,
                "display": display_include,
            }).dropna()
            included = included[np.isfinite(included["transformed"])]
            included = included[np.isfinite(included["display"])]
            if included.empty:
                continue
            axis_frame = pd.DataFrame({
                "transformed": axis_specs[name][0],
                "display": axis_specs[name][1],
            })
            axis_frame = pd.concat(
                [axis_frame, included],
                ignore_index=True,
            )
            axis_frame = (
                axis_frame
                .sort_values("transformed")
                .drop_duplicates("transformed", keep="first")
            )
            axis_specs[name] = (
                axis_frame["transformed"].to_numpy(dtype=float),
                axis_frame["display"].to_numpy(dtype=float),
            )

    transformed_axes = [axis_specs[name][0] for name in (x_name, y_name, z_name)]
    display_axes = [axis_specs[name][1] for name in (x_name, y_name, z_name)]
    mesh_transformed = np.meshgrid(*transformed_axes, indexing="ij")
    mesh_display = np.meshgrid(*display_axes, indexing="ij")
    coordinates = np.column_stack([
        _transform_interpolation_values(
            unique[name],
            name,
            log_frequency,
        ).to_numpy(dtype=float)
        for name in (x_name, y_name, z_name)
    ])
    values = unique["value"].to_numpy(dtype=float)
    finite_coordinates = np.isfinite(coordinates).all(axis=1) & np.isfinite(values)
    coordinates = coordinates[finite_coordinates]
    values = values[finite_coordinates]
    if len(values) < 4:
        return valid, pd.DataFrame(), "Too few finite observations after axis transform."

    query_coordinates = np.column_stack([
        mesh.ravel()
        for mesh in mesh_transformed
    ])
    grid_method = method if method in {"linear", "nearest", "rbf", "gp_smooth"} else "linear"
    if grid_method == "rbf":
        try:
            grid_values = _rbf_interpolation_values(
                coordinates,
                values,
                query_coordinates,
            ).reshape(mesh_transformed[0].shape)
        except Exception as exc:
            return valid, pd.DataFrame(), f"3D RBF interpolation failed: {exc}"
    elif grid_method == "gp_smooth":
        try:
            grid_values = _gp_smoothed_interpolation_values(
                coordinates,
                values,
                query_coordinates,
            ).reshape(mesh_transformed[0].shape)
        except Exception as exc:
            return valid, pd.DataFrame(), f"3D GP smoothing failed: {exc}"
    else:
        try:
            grid_values = griddata(
                coordinates,
                values,
                tuple(mesh_transformed),
                method=grid_method,
                rescale=True,
            )
        except Exception:
            if grid_method == "nearest":
                return valid, pd.DataFrame(), "3D nearest-neighbor interpolation failed."
            grid_values = griddata(
                coordinates,
                values,
                tuple(mesh_transformed),
                method="nearest",
                rescale=True,
            )
            grid_method = "nearest"
        if fill_nearest and not np.isfinite(grid_values).all():
            nearest_values = griddata(
                coordinates,
                values,
                tuple(mesh_transformed),
                method="nearest",
                rescale=True,
            )
            grid_values = np.where(
                np.isfinite(grid_values),
                grid_values,
                nearest_values,
            )
    if not np.isfinite(grid_values).any():
        return valid, pd.DataFrame(), "Interpolation produced no finite grid values."

    grid_frame = pd.DataFrame({
        x_name: mesh_display[0].ravel(),
        y_name: mesh_display[1].ravel(),
        z_name: mesh_display[2].ravel(),
        "interpolated_value": grid_values.ravel(),
    })
    grid_frame = grid_frame[np.isfinite(grid_frame["interpolated_value"])].copy()
    grid_frame["interpolation_method"] = grid_method
    grid_frame["grid_resolution_per_axis"] = size
    return valid, grid_frame, None


def _frame_fingerprint(frame: pd.DataFrame, columns: list[str]) -> str:
    """Stable-enough fingerprint for rerun caches inside one Streamlit session."""
    if frame.empty:
        return "empty"
    available = [column for column in columns if column in frame.columns]
    if not available:
        return f"rows:{len(frame)}"
    normalized = frame[available].copy()
    normalized = normalized.sort_values(available, kind="mergesort").reset_index(drop=True)
    hashed = pd.util.hash_pandas_object(normalized, index=True).to_numpy(dtype=np.uint64)
    return f"{len(normalized)}:{int(hashed.sum(dtype=np.uint64))}:{int(np.bitwise_xor.reduce(hashed))}"


@st.cache_data(show_spinner=False, max_entries=32)
def _plot_interpolated_3d_landscape(
    observed_points: pd.DataFrame,
    grid_frame: pd.DataFrame,
    metric_label: str,
    x_name: str,
    y_name: str,
    z_name: str,
    *,
    tensor_height: int = 520,
    dot_size: int = 5,
    dot_opacity: float = 0.50,
    log_frequency: bool = False,
    value_range: tuple[float, float] | None = None,
    slice_axis: str | None = None,
    slice_value: float | None = None,
    value_colorscale: str = "Viridis",
) -> go.Figure:
    """Render interpolated values as a discrete 3D tensor of grid points."""
    value_min = (
        float(value_range[0])
        if value_range is not None
        else float(grid_frame["interpolated_value"].min())
    )
    value_max = (
        float(value_range[1])
        if value_range is not None
        else float(grid_frame["interpolated_value"].max())
    )
    if np.isclose(value_min, value_max):
        value_max = value_min + 1.0
    fig = go.Figure()
    plot_grid = grid_frame
    max_plot_points = 60000
    if len(plot_grid) > max_plot_points:
        step = int(math.ceil(len(plot_grid) / max_plot_points))
        plot_grid = plot_grid.iloc[::step].copy()
    fig.add_trace(go.Scatter3d(
        x=plot_grid[x_name],
        y=plot_grid[y_name],
        z=plot_grid[z_name],
        mode="markers",
        name="Interpolated tensor grid",
        marker={
            "size": max(2, dot_size - 1),
            "color": plot_grid["interpolated_value"],
            "colorscale": value_colorscale,
            "cmin": value_min,
            "cmax": value_max,
            "opacity": dot_opacity,
            "showscale": True,
            "colorbar": {
                "title": f"Interpolated {metric_label}",
                "x": 0.92,
                "y": 0.48,
                "len": 0.68,
            },
        },
        customdata=plot_grid["interpolated_value"],
        hovertemplate=(
            f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
            f"{z_name}: %{{z:.4g}}<br>Interpolated {metric_label}: "
            "%{customdata:.4g}<extra>Grid point</extra>"
        ),
    ))
    if (
        slice_axis in {x_name, y_name, z_name}
        and slice_value is not None
        and np.isfinite(float(slice_value))
    ):
        axis_bounds = {}
        for axis_name in (x_name, y_name, z_name):
            axis_values = pd.to_numeric(
                grid_frame[axis_name],
                errors="coerce",
            ).dropna()
            if axis_values.empty:
                axis_bounds[axis_name] = (0.0, 1.0)
            else:
                axis_bounds[axis_name] = (
                    float(axis_values.min()),
                    float(axis_values.max()),
                )
            if np.isclose(axis_bounds[axis_name][0], axis_bounds[axis_name][1]):
                center = axis_bounds[axis_name][0]
                padding = max(abs(center) * 0.05, 1e-9)
                axis_bounds[axis_name] = (center - padding, center + padding)
        plane_x = np.array([
            [axis_bounds[x_name][0], axis_bounds[x_name][1]],
            [axis_bounds[x_name][0], axis_bounds[x_name][1]],
        ], dtype=float)
        plane_y = np.array([
            [axis_bounds[y_name][0], axis_bounds[y_name][0]],
            [axis_bounds[y_name][1], axis_bounds[y_name][1]],
        ], dtype=float)
        plane_z = np.array([
            [axis_bounds[z_name][0], axis_bounds[z_name][0]],
            [axis_bounds[z_name][1], axis_bounds[z_name][1]],
        ], dtype=float)
        if slice_axis == x_name:
            plane_x = np.full_like(plane_x, float(slice_value))
        elif slice_axis == y_name:
            plane_y = np.full_like(plane_y, float(slice_value))
        else:
            plane_z = np.full_like(plane_z, float(slice_value))
        fig.add_trace(go.Surface(
            x=plane_x,
            y=plane_y,
            z=plane_z,
            surfacecolor=np.zeros_like(plane_x),
            colorscale=[[0, "rgba(255,59,48,1)"], [1, "rgba(255,59,48,1)"]],
            opacity=0.23,
            showscale=False,
            name="Highlighted slice",
            hovertemplate=(
                f"{slice_axis}: {float(slice_value):.4g}"
                "<extra>Highlighted slice</extra>"
            ),
        ))
    observed = observed_points.dropna(subset=[x_name, y_name, z_name, "value"])
    if not observed.empty:
        fig.add_trace(go.Scatter3d(
            x=observed[x_name],
            y=observed[y_name],
            z=observed[z_name],
            mode="markers",
            name="Observed measurements",
            showlegend=False,
            marker={
                "size": dot_size + 3,
                "color": observed["value"],
                "colorscale": "Viridis",
                "cmin": value_min,
                "cmax": value_max,
                "line": {"color": "#111111", "width": 2},
                "symbol": "diamond",
                "opacity": min(1.0, dot_opacity + 0.25),
                "showscale": False,
            },
            customdata=observed["value"],
            hovertemplate=(
                f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                f"{z_name}: %{{z:.4g}}<br>Observed {metric_label}: "
                "%{customdata:.4g}<extra></extra>"
            ),
        ))
    fig.update_layout(
        title=f"Interpolated measured {metric_label} tensor grid",
        scene={
            "xaxis": {
                "title": x_name,
                "type": "log" if log_frequency and x_name == "frequency" else "linear",
            },
            "yaxis": {
                "title": y_name,
                "type": "log" if log_frequency and y_name == "frequency" else "linear",
            },
            "zaxis": {
                "title": z_name,
                "type": "log" if log_frequency and z_name == "frequency" else "linear",
            },
            "domain": {"x": [0, 0.78], "y": [0.08, 0.92]},
        },
        height=tensor_height,
        margin={"l": 10, "r": 115, "t": 55, "b": 35},
    )
    return fig


@st.cache_data(show_spinner=False, max_entries=64)
def _plot_interpolated_2d_slice(
    observed_points: pd.DataFrame,
    grid_frame: pd.DataFrame,
    metric_label: str,
    x_name: str,
    y_name: str,
    slice_axis: str,
    slice_value: float,
    *,
    log_frequency: bool = False,
    value_range: tuple[float, float] | None = None,
    reverse_x: bool = False,
    reverse_y: bool = False,
    show_measured_points: bool = False,
    value_colorscale: str = "Viridis",
) -> go.Figure:
    """Render a 2D map from one fixed slice of an interpolated 3D grid."""
    slice_grid = _apply_numeric_slice(
        grid_frame,
        slice_axis,
        slice_value,
    ).reset_index(drop=True)
    display_value_range = value_range or _value_range_from_frame(
        grid_frame,
        "interpolated_value",
    )
    fig = go.Figure()
    if not slice_grid.empty:
        heatmap_grid = (
            slice_grid
            .pivot_table(
                index=y_name,
                columns=x_name,
                values="interpolated_value",
                aggfunc="mean",
            )
            .sort_index()
            .sort_index(axis=1)
        )
        fig.add_trace(go.Heatmap(
            x=heatmap_grid.columns.to_numpy(dtype=float),
            y=heatmap_grid.index.to_numpy(dtype=float),
            z=heatmap_grid.to_numpy(dtype=float),
            colorscale=value_colorscale,
            zmin=(
                display_value_range[0]
                if display_value_range is not None else None
            ),
            zmax=(
                display_value_range[1]
                if display_value_range is not None else None
            ),
            colorbar={"title": f"Interpolated {metric_label}"},
            hovertemplate=(
                f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                f"Interpolated {metric_label}: %{{z:.4g}}<extra></extra>"
            ),
            connectgaps=False,
        ))
    observed = _apply_numeric_slice(
        observed_points,
        slice_axis,
        slice_value,
    )
    observed = observed.dropna(subset=[x_name, y_name, "value"])
    if show_measured_points and not observed.empty:
        fig.add_trace(go.Scatter(
            x=observed[x_name],
            y=observed[y_name],
            mode="markers",
            name="Observed measurements",
            marker={
                "size": 8,
                "color": "#111111",
                "symbol": "diamond",
                "line": {"color": "white", "width": 1},
            },
            customdata=observed["value"],
            hovertemplate=(
                f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                f"Observed {metric_label}: %{{customdata:.4g}}<extra></extra>"
            ),
        ))
    if slice_grid.empty:
        fig.add_annotation(
            text="No interpolated grid values match this highlighted slice.",
            x=0.5,
            y=0.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
    title_note = _numeric_slice_title_note(slice_axis, slice_value)
    fig.update_layout(
        title=(
            f"Interpolated measured {metric_label} 2D slice"
            + (f"<br>{title_note}" if title_note else "")
        ),
        xaxis_title=x_name,
        yaxis_title=y_name,
        xaxis_type="log" if log_frequency and x_name == "frequency" else "linear",
        yaxis_type="log" if log_frequency and y_name == "frequency" else "linear",
        height=460,
        margin={"l": 65, "r": 90, "t": 65, "b": 65},
    )
    fig.update_xaxes(autorange="reversed" if reverse_x else True)
    fig.update_yaxes(autorange="reversed" if reverse_y else True)
    return fig


def _simulation_parameter_bounds(
    frame: pd.DataFrame,
    parameters: list[str],
    config: dict | None = None,
) -> dict[str, tuple[float, float, str]]:
    parameter_config = (config or {}).get("parameters") or {}
    bounds: dict[str, tuple[float, float, str]] = {}
    for name in parameters:
        numeric = pd.to_numeric(frame[name], errors="coerce")
        finite = numeric[np.isfinite(numeric)]
        definition = parameter_config.get(name) or {}
        lower = definition.get("min")
        upper = definition.get("max")
        try:
            lower = float(lower)
            upper = float(upper)
        except (TypeError, ValueError):
            if finite.empty:
                lower, upper = 0.0, 1.0
            else:
                lower = float(finite.min())
                upper = float(finite.max())
        if not np.isfinite(lower) or not np.isfinite(upper) or lower == upper:
            if finite.empty:
                lower, upper = 0.0, 1.0
            else:
                lower = float(finite.min())
                upper = float(finite.max())
        if lower == upper:
            upper = lower + 1.0
        scale = str(
            definition.get("scale", definition.get("encoding", ""))
        ).lower()
        bounds[name] = (lower, upper, scale)
    return bounds


def _simulation_encode_parameters(
    frame: pd.DataFrame,
    parameters: list[str],
    bounds: dict[str, tuple[float, float, str]],
) -> np.ndarray:
    encoded = []
    for name in parameters:
        lower, upper, scale = bounds[name]
        values = pd.to_numeric(frame[name], errors="coerce").to_numpy(dtype=float)
        if scale in ("log", "log10") or name == "frequency":
            values = np.log10(np.maximum(values, 1e-12))
            lower = np.log10(max(lower, 1e-12))
            upper = np.log10(max(upper, 1e-12))
        encoded.append((values - lower) / (upper - lower + 1e-12))
    return np.column_stack(encoded)


def _simulation_matern52_kernel(
    left: np.ndarray,
    right: np.ndarray,
    length_scales: np.ndarray,
) -> np.ndarray:
    scaled = (left[:, None, :] - right[None, :, :]) / length_scales[None, None, :]
    distance = np.sqrt(np.sum(scaled * scaled, axis=2))
    root5_distance = np.sqrt(5.0) * distance
    return (
        1.0
        + root5_distance
        + root5_distance ** 2 / 3.0
    ) * np.exp(-root5_distance)


def _simulation_gp_predict(
    x_train: np.ndarray,
    y_train: np.ndarray,
    x_candidates: np.ndarray,
    length_scales: np.ndarray,
    noise: float,
    *,
    config: dict | None = None,
    fixed_length_scales: bool = True,
) -> tuple[np.ndarray, np.ndarray]:
    if len(y_train) < 2:
        raise ValueError("At least two observations are required for GP fitting.")
    if config is not None:
        try:
            from sklearn.exceptions import ConvergenceWarning
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import ConstantKernel
            from sklearn.gaussian_process.kernels import Matern as SklearnMatern
            from sklearn.gaussian_process.kernels import WhiteKernel as SklearnWhiteKernel
            import warnings

            if fixed_length_scales:
                matern = SklearnMatern(
                    length_scale=np.asarray(length_scales, dtype=float),
                    length_scale_bounds="fixed",
                    nu=2.5,
                )
                restarts = 0
            else:
                matern = SklearnMatern(
                    length_scale=np.ones(x_train.shape[1]),
                    nu=2.5,
                )
                restarts = max(
                    0,
                    int(
                        ((config or {}).get("acquisition") or {}).get(
                            "gp_optimizer_restarts",
                            2,
                        )
                    ),
                )
            kernel = (
                ConstantKernel(1.0, constant_value_bounds="fixed")
                * matern
                + SklearnWhiteKernel(
                    noise_level=max(float(noise), 1e-10),
                    noise_level_bounds=(1e-8, 1e-1),
                )
            )
            gp = GaussianProcessRegressor(
                kernel=kernel,
                normalize_y=True,
                random_state=int((config or {}).get("random_seed", 42)),
                n_restarts_optimizer=restarts,
            )
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", ConvergenceWarning)
                gp.fit(x_train, y_train)
            means, stds = gp.predict(x_candidates, return_std=True)
            return np.asarray(means, dtype=float), np.asarray(stds, dtype=float)
        except Exception:
            pass
    y_mean = float(np.mean(y_train))
    y_scale = float(np.std(y_train))
    if y_scale < 1e-12:
        y_scale = 1.0
    normalized_y = (y_train - y_mean) / y_scale
    covariance = _simulation_matern52_kernel(
        x_train,
        x_train,
        length_scales,
    )
    identity = np.eye(len(x_train), dtype=float)
    jitter = max(1e-10, float(noise))
    cholesky = None
    for _attempt in range(8):
        try:
            cholesky = np.linalg.cholesky(covariance + identity * jitter)
            break
        except np.linalg.LinAlgError:
            jitter *= 10.0
    if cholesky is None:
        raise np.linalg.LinAlgError("GP covariance is not positive definite")
    alpha = np.linalg.solve(
        cholesky.T,
        np.linalg.solve(cholesky, normalized_y),
    )
    cross_covariance = _simulation_matern52_kernel(
        x_candidates,
        x_train,
        length_scales,
    )
    means = y_mean + y_scale * (cross_covariance @ alpha)
    projected = np.linalg.solve(cholesky, cross_covariance.T)
    variance = np.maximum(
        1.0 + jitter - np.sum(projected * projected, axis=0),
        1e-12,
    )
    return means, y_scale * np.sqrt(variance)


def _simulation_clip01(value: Any) -> float:
    try:
        numeric = float(value)
    except (TypeError, ValueError):
        numeric = 0.0
    return max(0.0, min(1.0, numeric))


def _simulation_is_log_parameter(definition: dict) -> bool:
    scale = str(definition.get("scale", definition.get("encoding", ""))).lower()
    return scale in ("log", "log10")


def _simulation_parameter_discrete_values(definition: dict, name: str) -> list[float]:
    raw_values = definition.get("values", [definition.get("value")])
    values = []
    for value in raw_values:
        try:
            values.append(float(value))
        except (TypeError, ValueError):
            continue
    if not values:
        values = [float(definition.get("value", DEFAULT_INITIAL_METHOD.get(name, 0.0)))]
    step = definition.get("step")
    if step in (None, "", 0, "0"):
        return values
    step_value = float(step)
    if step_value <= 0:
        return values
    lower = float(definition.get("min", min(values)))
    return [
        float(f"{lower + round((value - lower) / step_value) * step_value:.12g}")
        for value in values
    ]


def _simulation_normalized_bo_config(config: dict | None) -> dict:
    cfg = json.loads(json.dumps(config or {}))
    cfg.setdefault("n_initial_points", 8)
    cfg.setdefault("random_seed", 42)
    cfg.setdefault("initial_parameters", {})
    for name, default_value in DEFAULT_INITIAL_METHOD.items():
        cfg["initial_parameters"].setdefault(name, default_value)
    cfg.setdefault("parameters", {})
    for name in PARAMETERS:
        definition = dict(cfg["parameters"].get(name) or {})
        definition.setdefault("mode", "locked")
        definition.setdefault("space", "discrete")
        definition.setdefault("value", cfg["initial_parameters"].get(name, DEFAULT_INITIAL_METHOD[name]))
        definition.setdefault("values", [definition["value"]])
        numeric_values = [
            float(value)
            for value in definition.get("values", [definition["value"]])
            if value is not None
        ]
        if numeric_values:
            definition.setdefault("min", min(numeric_values))
            definition.setdefault("max", max(numeric_values))
        else:
            definition.setdefault("min", definition["value"])
            definition.setdefault("max", definition["value"])
        definition.setdefault("scale", definition.get("encoding", "linear"))
        if name == "frequency" and not definition.get("scale"):
            definition["scale"] = "log"
        if name == "conditioning_potential":
            definition.setdefault("tie_to", "begin_potential")
        cfg["parameters"][name] = definition
    cfg.setdefault("acquisition", {})
    acquisition = cfg["acquisition"]
    acquisition.setdefault("exploration", 0.35)
    acquisition.setdefault("candidate_pool_size", 600)
    acquisition.setdefault("local_candidate_pool_size", 120)
    acquisition.setdefault("initial_point_mode", "specific")
    acquisition.setdefault("optimization_direction", "maximize")
    acquisition.setdefault("use_gp", True)
    acquisition.setdefault("gp_optimizer_restarts", 2)
    default_falloffs = {name: 0.2 for name in PARAMETERS}
    acquisition.setdefault("gp_length_scales", dict(default_falloffs))
    acquisition.setdefault(
        "gp_falloff_fractions",
        acquisition.get("gp_length_scales", dict(default_falloffs)),
    )
    cfg.setdefault("constraints", {})
    constraints = cfg["constraints"]
    constraints.setdefault("min_scan_window", 0.4)
    constraints.setdefault("max_effective_scan_rate", 5.0)
    constraints.setdefault("max_amplitude", 0.50)
    constraints.setdefault("conditioning_must_be_in_scan_window", False)
    constraints.setdefault("require_end_after_begin", True)
    return cfg


def _simulation_resolve_candidate(candidate: dict, config: dict) -> dict:
    cfg = _simulation_normalized_bo_config(config)
    resolved = {
        name: float(candidate.get(name, cfg["initial_parameters"].get(name, DEFAULT_INITIAL_METHOD[name])))
        for name in PARAMETERS
    }
    for name in PARAMETERS:
        definition = cfg["parameters"][name]
        if str(definition.get("mode", "locked")).lower() == "locked":
            resolved[name] = float(definition.get("value", resolved[name]))
    for name in PARAMETERS:
        definition = cfg["parameters"][name]
        if str(definition.get("mode", "locked")).lower() == "tied":
            tie_to = definition.get("tie_to") or "begin_potential"
            resolved[name] = float(resolved[tie_to])
    return resolved


def _simulation_config_with_initial_parameters(
    config: dict | None,
    initial_parameters: dict[str, float],
) -> dict:
    cfg = json.loads(json.dumps(config or {}))
    cfg.setdefault("initial_parameters", {})
    cfg.setdefault("parameters", {})
    for name, value in initial_parameters.items():
        if name not in PARAMETERS:
            continue
        numeric_value = _finite_float(value)
        if numeric_value is None:
            continue
        cfg["initial_parameters"][name] = numeric_value
        if name in cfg["parameters"]:
            definition = dict(cfg["parameters"].get(name) or {})
            if str(definition.get("mode", "locked")).lower() == "locked":
                definition["value"] = numeric_value
            cfg["parameters"][name] = definition
    return cfg


def _simulation_candidate_key(candidate: dict) -> tuple[float, ...]:
    return tuple(round(float(candidate[name]), 9) for name in PARAMETERS)


def _simulation_encode_bo_candidates(candidates: list[dict], config: dict) -> np.ndarray:
    cfg = _simulation_normalized_bo_config(config)
    encoded_columns = []
    for name in PARAMETERS:
        definition = cfg["parameters"][name]
        values = np.asarray([float(candidate[name]) for candidate in candidates], dtype=float)
        if str(definition.get("space", "discrete")).lower() == "continuous":
            lower = float(definition.get("min", np.nanmin(values)))
            upper = float(definition.get("max", np.nanmax(values)))
            if _simulation_is_log_parameter(definition):
                lower = math.log10(max(lower, 1e-12))
                upper = math.log10(max(upper, 1e-12))
                values = np.log10(np.maximum(values, 1e-12))
        else:
            discrete_values = _simulation_parameter_discrete_values(definition, name)
            if _simulation_is_log_parameter(definition):
                discrete_values = [math.log10(max(value, 1e-12)) for value in discrete_values]
                values = np.log10(np.maximum(values, 1e-12))
            lower = min(discrete_values)
            upper = max(discrete_values)
        if upper < lower:
            lower, upper = upper, lower
        encoded_columns.append((values - lower) / (upper - lower + 1e-12))
    return np.column_stack(encoded_columns)


def _simulation_validate_candidate(candidate: dict, config: dict) -> list[str]:
    cfg = _simulation_normalized_bo_config(config)
    constraints = cfg["constraints"]
    errors = []
    begin = float(candidate["begin_potential"])
    end = float(candidate["end_potential"])
    step = float(candidate["step_potential"])
    frequency = float(candidate["frequency"])
    conditioning = float(candidate["conditioning_potential"])
    amplitude = float(candidate["amplitude"])
    if constraints.get("require_end_after_begin", True) and end <= begin:
        errors.append("end_potential must be greater than begin_potential")
    scan_window = end - begin
    min_window = float(constraints.get("min_scan_window", 0.4))
    if scan_window < min_window - 1e-12:
        errors.append("end_potential - begin_potential is below min_scan_window")
    max_scan_rate = float(constraints.get("max_effective_scan_rate", 5.0))
    if step * frequency > max_scan_rate + 1e-12:
        errors.append("step_potential * frequency exceeds max_effective_scan_rate")
    max_amplitude = float(constraints.get("max_amplitude", 0.50))
    if amplitude > max_amplitude + 1e-12:
        errors.append("amplitude exceeds max_amplitude")
    if constraints.get("conditioning_must_be_in_scan_window", False):
        lower, upper = min(begin, end), max(begin, end)
        if conditioning < lower - 1e-12 or conditioning > upper + 1e-12:
            errors.append("conditioning_potential must be within scan window")
    conditioning_definition = cfg["parameters"].get("conditioning_potential", {})
    if (
        str(conditioning_definition.get("mode", "")).lower() == "tied"
        and abs(conditioning - begin) > 1e-9
    ):
        errors.append("conditioning_potential is tied to begin_potential")
    return errors


def _simulation_objective_value(value: float, config: dict) -> float:
    raw = str(
        (_simulation_normalized_bo_config(config).get("acquisition") or {}).get(
            "optimization_direction",
            "maximize",
        )
    ).strip().lower()
    return -float(value) if raw in {"minimize", "min", "more_negative", "negative"} else float(value)


def _simulation_acquisition_score(
    mean: float,
    std: float,
    best_score: float,
    exploration: float,
) -> float:
    exploration = _simulation_clip01(exploration)
    std = max(float(std), 1e-12)
    improvement = float(mean) - float(best_score) - 0.01
    z_score = improvement / std
    expected_improvement = (
        improvement * ndtr(z_score)
        + std * np.exp(-0.5 * z_score ** 2) / np.sqrt(2.0 * np.pi)
    )
    return (
        (1.0 - exploration) * (float(mean) + 0.25 * expected_improvement)
        + exploration * std
    )


def _simulation_distance_surrogate_choice(
    available: pd.DataFrame,
    observations: list[dict],
    config: dict,
) -> tuple[int, float, float, float, float]:
    available_params = available["params"].tolist()
    encoded_available = _simulation_encode_bo_candidates(available_params, config)
    observed_params = [observation["params"] for observation in observations]
    encoded_observed = _simulation_encode_bo_candidates(observed_params, config)
    observed_values = [
        _simulation_objective_value(float(observation["Q_run"]), config)
        for observation in observations
    ]
    best_objective = max(observed_values)
    exploration = _simulation_clip01(
        (_simulation_normalized_bo_config(config).get("acquisition") or {}).get(
            "exploration",
            0.35,
        )
    )
    best_position = 0
    best_score = -np.inf
    best_predicted = best_std = best_ei = np.nan
    for position, encoded in enumerate(encoded_available):
        distances = np.sqrt(np.sum((encoded_observed - encoded[None, :]) ** 2, axis=1))
        nearest = float(np.min(distances)) if len(distances) else 1.0
        weighted_sum = 0.0
        weight_total = 0.0
        for distance, q_value in zip(distances, observed_values):
            weight = 1.0 / (float(distance) + 0.05)
            weighted_sum += weight * q_value
            weight_total += weight
        predicted = weighted_sum / max(weight_total, 1e-12)
        improvement = max(0.0, predicted - best_objective)
        exploit_score = predicted + 0.05 * improvement
        score = (1.0 - exploration) * exploit_score + exploration * nearest
        if score > best_score:
            best_position = position
            best_score = float(score)
            best_predicted = float(predicted)
            best_std = float(nearest)
            best_ei = float(improvement)
    return best_position, best_predicted, best_std, best_ei, best_score


def _simulation_sample_continuous_value(
    definition: dict,
    rng: random.Random,
    center: float | None = None,
) -> float:
    lower = float(definition.get("min", definition.get("value", 0.0)))
    upper = float(definition.get("max", definition.get("value", lower)))
    if upper < lower:
        lower, upper = upper, lower
    if _simulation_is_log_parameter(definition):
        lower_t = math.log10(max(lower, 1e-12))
        upper_t = math.log10(max(upper, 1e-12))
        if center is None:
            value_t = rng.uniform(lower_t, upper_t)
        else:
            center_t = math.log10(max(float(center), 1e-12))
            sigma = max(1e-6, float(definition.get("proposal_sigma", 0.25))) * max(
                upper_t - lower_t,
                1e-9,
            )
            value_t = max(lower_t, min(upper_t, rng.gauss(center_t, sigma)))
        value = 10 ** value_t
    else:
        if center is None:
            value = rng.uniform(lower, upper)
        else:
            sigma = max(1e-6, float(definition.get("proposal_sigma", 0.15))) * max(
                upper - lower,
                1e-9,
            )
            value = max(lower, min(upper, rng.gauss(float(center), sigma)))
    step = definition.get("step")
    if step not in (None, "", 0, "0"):
        step_value = float(step)
        if step_value > 0:
            value = max(
                lower,
                min(
                    upper,
                    float(f"{lower + round((value - lower) / step_value) * step_value:.12g}"),
                ),
            )
    return float(value)


def _simulation_local_continuous_candidates(
    observations: list[dict],
    tried: set[tuple[float, ...]],
    config: dict,
) -> list[dict]:
    cfg = _simulation_normalized_bo_config(config)
    active_continuous = [
        name for name in PARAMETERS
        if str(cfg["parameters"][name].get("mode", "")).lower() == "active"
        and str(cfg["parameters"][name].get("space", "discrete")).lower() == "continuous"
    ]
    target = max(
        0,
        int((cfg.get("acquisition") or {}).get("local_candidate_pool_size", 120)),
    )
    if not active_continuous or target <= 0 or not observations:
        return []
    best = max(
        observations,
        key=lambda observation: _simulation_objective_value(
            float(observation.get("Q_run", 0.0)),
            cfg,
        ),
    )
    center = dict(best["params"])
    rng = random.Random(
        int(cfg.get("random_seed", 42)) + 1009 * (len(observations) + 1)
    )
    candidates = []
    seen = set(tried)
    max_attempts = max(target * 25, target + 1000)
    for _attempt in range(max_attempts):
        if len(candidates) >= target:
            break
        candidate = dict(center)
        for name in PARAMETERS:
            definition = cfg["parameters"][name]
            mode = str(definition.get("mode", "locked")).lower()
            if mode == "tied":
                continue
            if (
                mode == "active"
                and str(definition.get("space", "discrete")).lower() == "continuous"
            ):
                local_definition = dict(definition)
                if name == "frequency" and candidate.get("step_potential") is not None:
                    max_scan_rate = float(
                        cfg.get("constraints", {}).get(
                            "max_effective_scan_rate",
                            5.0,
                        )
                    )
                    max_frequency = max_scan_rate / max(
                        float(candidate["step_potential"]),
                        1e-12,
                    )
                    local_definition["max"] = min(
                        float(local_definition.get("max", max_frequency)),
                        max_frequency,
                    )
                candidate[name] = _simulation_sample_continuous_value(
                    local_definition,
                    rng,
                    center.get(name),
                )
            elif mode == "active":
                candidate[name] = rng.choice(
                    _simulation_parameter_discrete_values(definition, name)
                )
            elif mode == "locked":
                candidate[name] = float(definition.get("value", center.get(name)))
        candidate = _simulation_resolve_candidate(candidate, cfg)
        if _simulation_validate_candidate(candidate, cfg):
            continue
        key = _simulation_candidate_key(candidate)
        if key in seen:
            continue
        candidates.append(candidate)
        seen.add(key)
    return candidates


def _simulation_nearest_truth_value(
    params: dict,
    candidate_rows: pd.DataFrame,
    config: dict,
    value_name: str,
) -> float:
    if candidate_rows.empty:
        return float("nan")
    if "params" not in candidate_rows.columns:
        coordinate_names = [
            name for name in params
            if name in candidate_rows.columns
            and pd.api.types.is_numeric_dtype(candidate_rows[name])
        ]
        coordinate_names = [
            name for name in ("step_potential", "amplitude", "frequency")
            if name in coordinate_names
        ] or coordinate_names[:3]
        if coordinate_names:
            coords = candidate_rows[coordinate_names].apply(
                pd.to_numeric,
                errors="coerce",
            ).to_numpy(dtype=float)
            target = np.asarray(
                [float(params[name]) for name in coordinate_names],
                dtype=float,
            )
            spans = np.nanmax(coords, axis=0) - np.nanmin(coords, axis=0)
            spans = np.where(np.isfinite(spans) & (spans > 0), spans, 1.0)
            distances = np.sqrt(np.nansum(((coords - target[None, :]) / spans) ** 2, axis=1))
            nearest_position = int(np.nanargmin(distances))
            return float(candidate_rows.iloc[nearest_position][value_name])
    encoded_rows = _simulation_encode_bo_candidates(
        candidate_rows["params"].tolist(),
        config,
    )
    encoded_target = _simulation_encode_bo_candidates([params], config)[0]
    distances = np.sqrt(np.sum((encoded_rows - encoded_target[None, :]) ** 2, axis=1))
    nearest_position = int(np.argmin(distances))
    return float(candidate_rows.iloc[nearest_position][value_name])


def _simulation_interpolated_truth_value(
    params: dict,
    tensor_rows: pd.DataFrame,
    config: dict,
    axes: tuple[str, str, str],
    value_name: str,
) -> float:
    """Evaluate a candidate against the simulated tensor with continuous interpolation."""
    if tensor_rows.empty:
        return float("nan")
    x_name, y_name, z_name = axes
    if value_name not in tensor_rows.columns:
        return _simulation_nearest_truth_value(params, tensor_rows, config, value_name)
    try:
        work = tensor_rows[[x_name, y_name, z_name, value_name]].copy()
        work[[x_name, y_name, z_name, value_name]] = work[
            [x_name, y_name, z_name, value_name]
        ].apply(pd.to_numeric, errors="coerce")
        work = work.dropna(subset=[x_name, y_name, z_name, value_name])
        if work.empty:
            raise ValueError("No finite tensor rows")
        axes_values = [
            np.asarray(sorted(work[name].unique()), dtype=float)
            for name in (x_name, y_name, z_name)
        ]
        if any(len(values) < 2 for values in axes_values):
            raise ValueError("Tensor axis has fewer than two values")
        expected_size = int(np.prod([len(values) for values in axes_values]))
        grouped = (
            work.groupby([x_name, y_name, z_name], as_index=False)[value_name]
            .mean()
            .sort_values([x_name, y_name, z_name])
        )
        if len(grouped) != expected_size:
            raise ValueError("Tensor grid is incomplete")
        value_grid = (
            grouped[value_name]
            .to_numpy(dtype=float)
            .reshape(tuple(len(values) for values in axes_values))
        )
        interpolator = RegularGridInterpolator(
            tuple(axes_values),
            value_grid,
            method="linear",
            bounds_error=False,
            fill_value=np.nan,
        )
        point = np.asarray([
            float(params[x_name]),
            float(params[y_name]),
            float(params[z_name]),
        ], dtype=float)
        interpolated = float(interpolator(point))
        if np.isfinite(interpolated):
            return interpolated
    except Exception:
        pass
    return _simulation_nearest_truth_value(params, tensor_rows, config, value_name)


def _run_landscape_bo_simulation(
    ground_truth: pd.DataFrame,
    x_name: str,
    y_name: str,
    z_name: str,
    value_name: str,
    *,
    config: dict | None = None,
    iterations: int = 50,
    initial_random_points: int = 5,
    exploration: float = 0.2,
    candidate_pool_size: int = 1000,
    local_candidate_pool_size: int | None = None,
    seed: int = 1,
    falloff_fractions: dict[str, float] | None = None,
    noise: float = 1e-4,
    force_initial_point: bool = True,
    measurement_callback: Callable[[dict[str, float], int, float], tuple[float, dict]] | None = None,
    progress_callback: Callable[[int, int, dict], None] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Run a BO backtest against a discrete 3D ground-truth tensor."""
    cfg = _simulation_normalized_bo_config(config)
    acquisition = cfg.get("acquisition") or {}
    acquisition["exploration"] = _simulation_clip01(exploration)
    acquisition["candidate_pool_size"] = max(1, int(candidate_pool_size))
    if local_candidate_pool_size is not None:
        acquisition["local_candidate_pool_size"] = max(
            0,
            int(local_candidate_pool_size),
        )
    cfg["n_initial_points"] = max(0, int(initial_random_points))
    parameters = [x_name, y_name, z_name]
    columns = [*parameters, value_name]
    candidates = ground_truth[columns].copy()
    candidates[columns] = candidates[columns].apply(pd.to_numeric, errors="coerce")
    candidates = candidates.dropna(subset=columns).drop_duplicates(
        subset=parameters,
        keep="first",
    ).reset_index(drop=True)
    if candidates.empty:
        return pd.DataFrame(), candidates
    candidate_records = []
    seen_keys = set()
    for index, row in candidates.iterrows():
        params = _simulation_resolve_candidate(
            {
                **cfg.get("initial_parameters", {}),
                **{
                    name: float(row[name])
                    for name in parameters
                    if name in PARAMETERS
                },
            },
            cfg,
        )
        if _simulation_validate_candidate(params, cfg):
            continue
        key = _simulation_candidate_key(params)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        candidate_records.append({
            "source_index": int(index),
            "params": params,
            **{name: float(row[name]) for name in parameters},
            value_name: float(row[value_name]),
        })
    candidates = pd.DataFrame(candidate_records)
    if candidates.empty:
        return pd.DataFrame(), candidates
    rng = random.Random(int(seed))
    initial_rng = random.Random(int(seed) + 1_000_003)
    pool_size = max(1, min(int(candidate_pool_size), len(candidates)))
    initial_params = _simulation_resolve_candidate(cfg.get("initial_parameters", {}), cfg)
    initial_key = _simulation_candidate_key(initial_params)
    exact_initial_rows = [
        int(index)
        for index, row in candidates.iterrows()
        if _simulation_candidate_key(row["params"]) == initial_key
    ]
    if len(candidates) > pool_size:
        mandatory = exact_initial_rows[:1] if force_initial_point else []
        remaining_indices = [
            int(index) for index in candidates.index
            if int(index) not in set(mandatory)
        ]
        sampled = rng.sample(
            remaining_indices,
            k=max(0, pool_size - len(mandatory)),
        )
        pool_indices = sorted([*mandatory, *sampled])
        candidates = candidates.loc[pool_indices].reset_index(drop=True)
    else:
        candidates = candidates.reset_index(drop=True)
    total_iterations = max(1, min(int(iterations), len(candidates)))
    initial_count = max(0, min(int(initial_random_points), total_iterations))
    merged_falloffs = dict(acquisition.get("gp_falloff_fractions") or {})
    merged_falloffs.update(falloff_fractions or {})
    acquisition["gp_falloff_fractions"] = dict(merged_falloffs)
    acquisition["gp_length_scales"] = dict(merged_falloffs)
    fixed_length_scales = all(
        name in merged_falloffs and float(merged_falloffs[name]) > 0
        for name in PARAMETERS
    )
    length_scales = np.asarray(
        [
            max(1e-9, float(merged_falloffs.get(name, 1.0)))
            for name in PARAMETERS
        ],
        dtype=float,
    )
    observations: list[dict] = []
    history_rows = []
    for iteration in range(1, total_iterations + 1):
        tried = {
            _simulation_candidate_key(observation["params"])
            for observation in observations
        }
        base_available = candidates[
            ~candidates["params"].apply(
                lambda params: _simulation_candidate_key(params) in tried
            )
        ].copy()
        base_available["candidate_index"] = base_available.index.astype(int)
        if (
            force_initial_point
            and
            not _simulation_validate_candidate(initial_params, cfg)
            and initial_key not in tried
            and not any(
                _simulation_candidate_key(params) == initial_key
                for params in base_available["params"]
            )
        ):
            base_available = pd.concat(
                [
                    pd.DataFrame([{
                        "source_index": None,
                        "params": dict(initial_params),
                        **{name: float(initial_params[name]) for name in parameters},
                        value_name: _simulation_interpolated_truth_value(
                            initial_params,
                            ground_truth,
                            cfg,
                            (x_name, y_name, z_name),
                            value_name,
                        ),
                        "candidate_index": -1000000,
                    }]),
                    base_available,
                ],
                ignore_index=True,
            )
        local_records = []
        for local_index, local_params in enumerate(
            _simulation_local_continuous_candidates(observations, tried, cfg),
            1,
        ):
            local_records.append({
                "source_index": None,
                "params": local_params,
                **{name: float(local_params[name]) for name in parameters},
                value_name: _simulation_interpolated_truth_value(
                    local_params,
                    ground_truth,
                    cfg,
                    (x_name, y_name, z_name),
                    value_name,
                ),
                "candidate_index": -local_index,
            })
        available = pd.concat(
            [base_available, pd.DataFrame(local_records)],
            ignore_index=True,
        ) if local_records else base_available.reset_index(drop=True)
        if available.empty:
            break
        available_keys = {
            _simulation_candidate_key(params): int(index)
            for index, params in zip(available["candidate_index"], available["params"])
        }
        if force_initial_point and initial_key not in tried and initial_key in available_keys:
            chosen_index = int(available_keys[initial_key])
            chosen_row = available[
                available["candidate_index"] == chosen_index
            ].iloc[0].to_dict()
            mean = std = acquisition_value = expected_improvement = np.nan
            selection_mode = "initial"
        elif (not observations and not force_initial_point) or len(observations) < initial_count:
            anchors = (
                ([initial_params] if force_initial_point else [])
                + [observation["params"] for observation in observations]
            )
            if not anchors:
                position = initial_rng.randrange(len(available))
                chosen_row = available.iloc[position].to_dict()
                mean = std = acquisition_value = expected_improvement = np.nan
                selection_mode = "seed random initial"
                row = chosen_row
                params = dict(row["params"])
                tensor_value = float(row[value_name])
                measurement_metadata = {}
                value = tensor_value
                if measurement_callback is not None:
                    try:
                        measured_value, measurement_metadata = measurement_callback(
                            params,
                            iteration,
                            tensor_value,
                        )
                        if np.isfinite(float(measured_value)):
                            value = float(measured_value)
                    except Exception as exc:
                        measurement_metadata = {
                            "measurement_error": str(exc),
                            "simulation_fidelity": "trace-realistic",
                        }
                best_so_far = max(
                    [float(existing["observed_value"]) for existing in history_rows]
                    + [value]
                )
                observations.append({
                    "params": params,
                    "Q_run": value,
                    "iteration": iteration,
                })
                history_rows.append({
                    "iteration": iteration,
                    "selection_mode": selection_mode,
                    x_name: float(row[x_name]),
                    y_name: float(row[y_name]),
                    z_name: float(row[z_name]),
                    "observed_value": value,
                    "tensor_value": tensor_value,
                    "best_so_far": best_so_far,
                    "predicted_mean": mean,
                    "predicted_std": std,
                    "expected_improvement": expected_improvement,
                    "acquisition_value": acquisition_value,
                    "measurement_metadata": measurement_metadata,
                })
                if progress_callback is not None:
                    progress_callback(iteration, total_iterations, history_rows[-1])
                continue
            encoded_available = _simulation_encode_bo_candidates(
                available["params"].tolist(),
                cfg,
            )
            encoded_anchors = _simulation_encode_bo_candidates(anchors, cfg)
            distances = np.sqrt(
                np.sum(
                    (
                        encoded_available[:, None, :]
                        - encoded_anchors[None, :, :]
                    ) ** 2,
                    axis=2,
                )
            )
            position = int(np.argmax(np.min(distances, axis=1)))
            chosen_row = available.iloc[position].to_dict()
            mean = std = acquisition_value = expected_improvement = np.nan
            selection_mode = "maximin"
        else:
            used_gp = False
            if bool(acquisition.get("use_gp", True)) and len(observations) >= 2:
                try:
                    x_train = _simulation_encode_bo_candidates(
                        [observation["params"] for observation in observations],
                        cfg,
                    )
                    y_train = np.asarray(
                        [float(observation["Q_run"]) for observation in observations],
                        dtype=float,
                    )
                    x_available = _simulation_encode_bo_candidates(
                        available["params"].tolist(),
                        cfg,
                    )
                    means, stds = _simulation_gp_predict(
                        x_train,
                        y_train,
                        x_available,
                        length_scales,
                        noise,
                        config=cfg,
                        fixed_length_scales=fixed_length_scales,
                    )
                    best_objective = max(
                        _simulation_objective_value(float(observation["Q_run"]), cfg)
                        for observation in observations
                    )
                    scores = np.asarray([
                        _simulation_acquisition_score(
                            _simulation_objective_value(float(mu), cfg),
                            float(sigma),
                            best_objective,
                            exploration,
                        )
                        for mu, sigma in zip(means, stds)
                    ])
                    position = int(np.nanargmax(scores))
                    chosen_row = available.iloc[position].to_dict()
                    mean = float(means[position])
                    std = float(stds[position])
                    improvement = (
                        _simulation_objective_value(mean, cfg)
                        - best_objective
                        - 0.01
                    )
                    z_score = improvement / max(std, 1e-12)
                    expected_improvement = float(
                        improvement * ndtr(z_score)
                        + std * np.exp(-0.5 * z_score ** 2) / np.sqrt(2.0 * np.pi)
                    )
                    acquisition_value = float(scores[position])
                    selection_mode = "GP acquisition"
                    used_gp = True
                except Exception:
                    used_gp = False
            if not used_gp:
                (
                    position,
                    mean,
                    std,
                    expected_improvement,
                    acquisition_value,
                ) = _simulation_distance_surrogate_choice(
                    available,
                    observations,
                    cfg,
                )
                chosen_row = available.iloc[position].to_dict()
                selection_mode = "distance surrogate"
        row = chosen_row
        params = dict(row["params"])
        tensor_value = float(row[value_name])
        measurement_metadata = {}
        value = tensor_value
        if measurement_callback is not None:
            try:
                measured_value, measurement_metadata = measurement_callback(
                    params,
                    iteration,
                    tensor_value,
                )
                if np.isfinite(float(measured_value)):
                    value = float(measured_value)
            except Exception as exc:
                measurement_metadata = {
                    "measurement_error": str(exc),
                    "simulation_fidelity": "trace-realistic",
                }
        best_so_far = max(
            [float(existing["observed_value"]) for existing in history_rows]
            + [value]
        )
        observations.append({
            "params": params,
            "Q_run": value,
            "iteration": iteration,
        })
        history_rows.append({
            "iteration": iteration,
            "selection_mode": selection_mode,
            x_name: float(row[x_name]),
            y_name: float(row[y_name]),
            z_name: float(row[z_name]),
            "observed_value": value,
            "tensor_value": tensor_value,
            "best_so_far": best_so_far,
            "predicted_mean": mean,
            "predicted_std": std,
            "expected_improvement": expected_improvement,
            "acquisition_value": acquisition_value,
            "measurement_metadata": measurement_metadata,
        })
        if progress_callback is not None:
            progress_callback(iteration, total_iterations, history_rows[-1])
    return pd.DataFrame(history_rows), candidates


def _plot_simulation_history(
    history: pd.DataFrame,
    value_label: str,
    optimum_reference: dict[str, float] | None = None,
) -> go.Figure:
    fig = go.Figure()
    if history.empty:
        fig.add_annotation(
            text="No simulation results.",
            x=.5,
            y=.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        fig.update_layout(height=340)
        return _apply_plotly_colorbar_height(fig)
    fig.add_trace(go.Scatter(
        x=history["iteration"],
        y=history["observed_value"],
        mode="lines+markers",
        name=f"Observed {value_label}",
        marker={"size": 7},
    ))
    fig.add_trace(go.Scatter(
        x=history["iteration"],
        y=history["best_so_far"],
        mode="lines+markers",
        name="Best so far",
        line={"width": 3, "color": "#111111"},
        marker={"size": 7},
    ))
    if optimum_reference:
        _add_horizontal_reference_line(
            fig,
            optimum_reference.get("Q_run"),
            "Best possible Q",
        )
    fig.update_layout(
        title=f"Simulated BO backtest | {value_label}",
        xaxis_title="Simulation iteration",
        yaxis_title=value_label,
        height=420,
        margin={"l": 65, "r": 30, "t": 55, "b": 55},
    )
    return fig


def _plot_simulation_comparison(
    runs: list[dict],
    value_label: str,
    y_column: str = "best_so_far",
    color_by: str | None = None,
    optimum_reference: dict[str, float] | None = None,
) -> go.Figure:
    fig = go.Figure()
    if not runs:
        fig.add_annotation(
            text="No simulation runs to compare.",
            x=.5,
            y=.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        fig.update_layout(height=420)
        return fig
    color_columns = {
        "exploration": ("exploration", "Explore weight"),
        "initial_random_points": ("initial_random_points", "Initial maximin points"),
        "gp_falloff_value": ("gp_falloff_value", "GP falloff"),
    }
    color_key, color_label = color_columns.get(color_by, (None, None))
    categorical_key = "ground_truth_channel" if color_by == "Ground-truth channel" else None
    categorical_values = []
    if categorical_key:
        categorical_values = sorted({
            str(run.get(categorical_key))
            for run in runs
            if run.get(categorical_key) is not None
        }, key=_channel_sort_key)
    categorical_colors = {
        value: GROUP_CATEGORICAL_COLORS[index % len(GROUP_CATEGORICAL_COLORS)]
        for index, value in enumerate(categorical_values)
    }
    color_values = [
        float(run.get(color_key))
        for run in runs
        if color_key
        and run.get(color_key) is not None
        and np.isfinite(float(run.get(color_key)))
    ]
    color_min = min(color_values) if color_values else 0.0
    color_max = max(color_values) if color_values else 1.0
    if np.isclose(color_min, color_max):
        color_max = color_min + 1.0

    def scale_color(value: float) -> str:
        cmap = plt.get_cmap("viridis")
        fraction = (float(value) - color_min) / (
            color_max - color_min + 1e-12
        )
        red, green, blue, _alpha = cmap(min(1.0, max(0.0, fraction)))
        return f"rgb({red * 255:.0f},{green * 255:.0f},{blue * 255:.0f})"

    for run in runs:
        history = run.get("history")
        if history is None or history.empty or y_column not in history.columns:
            continue
        label = str(run.get("label") or "Simulation")
        color_value = run.get(color_key) if color_key else None
        numeric_color_value = _finite_float(color_value)
        trace_color = (
            categorical_colors.get(str(run.get(categorical_key)))
            if categorical_key and run.get(categorical_key) is not None
            else
            scale_color(numeric_color_value)
            if color_key and color_values and numeric_color_value is not None
            else None
        )
        marker = {"size": 7}
        if color_key and color_values and numeric_color_value is not None:
            marker.update({
                "color": [numeric_color_value] * len(history),
                "coloraxis": "coloraxis",
            })
        elif trace_color:
            marker["color"] = trace_color
        fig.add_trace(go.Scatter(
            x=history["iteration"],
            y=history[y_column],
            mode="lines+markers",
            name=label,
            line=({"color": trace_color} if trace_color else None),
            marker=marker,
            customdata=history[["observed_value", "selection_mode"]],
            hovertemplate=(
                f"{label}<br>Iteration %{{x}}<br>"
                f"{'Best so far' if y_column == 'best_so_far' else 'Observed'}: "
                "%{y:.4g}<br>Observed: %{customdata[0]:.4g}<br>"
                "Mode: %{customdata[1]}<extra></extra>"
            ),
        ))
    if color_key and color_label and color_values:
        _apply_metadata_coloraxis(
            fig,
            {index: value for index, value in enumerate(color_values)},
            color_label,
        )
    if optimum_reference:
        _add_horizontal_reference_line(
            fig,
            optimum_reference.get("Q_run"),
            "Best possible Q",
        )
    fig.update_layout(
        title=(
            f"Simulation hyperparameter comparison | {value_label} "
            f"{'best-so-far' if y_column == 'best_so_far' else 'observed'}"
        ),
        xaxis_title="Simulation iteration",
        yaxis_title=(
            f"Best {value_label} so far"
            if y_column == "best_so_far" else value_label
        ),
        height=460,
        margin={"l": 65, "r": 30, "t": 55, "b": 95},
        legend={
            "orientation": "h",
            "x": 0,
            "xanchor": "left",
            "y": -0.18,
            "yanchor": "top",
        },
    )
    return fig


def _simulation_history_display_frame(history: pd.DataFrame) -> pd.DataFrame:
    if history is None or history.empty:
        return pd.DataFrame()
    display = history.copy()
    if "measurement_metadata" in display.columns:
        display["measurement_mode"] = [
            (
                metadata.get("simulation_fidelity")
                if isinstance(metadata, dict)
                else None
            )
            for metadata in display["measurement_metadata"]
        ]
        display["trace_warnings"] = [
            (
                len(metadata.get("trace_errors") or [])
                if isinstance(metadata, dict)
                else 0
            )
            for metadata in display["measurement_metadata"]
        ]
        display = display.drop(columns=["measurement_metadata"])
    return display


def _plot_simulation_3d_path(
    ground_truth: pd.DataFrame,
    history: pd.DataFrame,
    value_label: str,
    x_name: str,
    y_name: str,
    z_name: str,
    *,
    tensor_height: int = 620,
    dot_size: int = 6,
    dot_opacity: float = 0.35,
) -> go.Figure:
    fig = _plot_interpolated_3d_landscape(
        history.rename(columns={"observed_value": "value"})[
            ["iteration", x_name, y_name, z_name, "value"]
        ] if not history.empty else pd.DataFrame(columns=[
            "iteration",
            x_name,
            y_name,
            z_name,
            "value",
        ]),
        ground_truth.rename(columns={"ground_truth_value": "interpolated_value"}),
        value_label,
        x_name,
        y_name,
        z_name,
        tensor_height=tensor_height,
        dot_size=dot_size,
        dot_opacity=dot_opacity,
    )
    if not history.empty:
        ordered = history.sort_values("iteration")
        _add_plotly_iteration_path(
            fig,
            ordered[x_name],
            ordered[y_name],
            ordered["iteration"],
            z=ordered[z_name],
            show_colorbar=True,
        )
    fig.update_layout(title=f"Simulated BO path on {value_label} tensor")
    return fig


def _is_loaded_simulated_sweep_session(session: dict) -> bool:
    state = session.get("state") or {}
    config = session.get("config") or {}
    metadata = state.get("simulation_metadata") or {}
    records = config.get("records") if isinstance(config, dict) else {}
    history = session.get("history")
    if not metadata or not records or not records.get("simulated_session"):
        return False
    run_count = _finite_float(metadata.get("run_count"))
    if run_count is not None and int(run_count) > 1:
        return True
    if metadata.get("compact_export"):
        return True
    if history is not None and not history.empty and "group_id" in history.columns:
        return pd.to_numeric(
            history["group_id"],
            errors="coerce",
        ).nunique(dropna=True) > 1
    return False


def _simulation_loaded_sweep_runs(
    session: dict,
    axes: Sequence[str],
) -> list[dict]:
    history = session.get("history")
    if history is None or history.empty:
        return []
    required_columns = {"iteration", *axes}
    if not required_columns.issubset(history.columns):
        return []
    value_column = (
        "observed_value"
        if "observed_value" in history.columns
        else "Q_run" if "Q_run" in history.columns
        else None
    )
    if value_column is None:
        return []
    group_column = "group_id" if "group_id" in history.columns else None
    grouped = (
        history.groupby(group_column, sort=False, dropna=False)
        if group_column is not None else [(1, history)]
    )
    runs = []
    for group_id, group in grouped:
        run_history = group.copy()
        for column in ("iteration", value_column, *axes):
            run_history[column] = pd.to_numeric(
                run_history[column],
                errors="coerce",
            )
        run_history = run_history.dropna(
            subset=["iteration", value_column, *axes],
        ).sort_values("iteration", kind="mergesort")
        if run_history.empty:
            continue
        label_candidates = [
            run_history[column].dropna().astype(str).iloc[0]
            for column in ("run_label", "group_name", "channels")
            if column in run_history.columns
            and not run_history[column].dropna().empty
        ]
        label = label_candidates[0] if label_candidates else f"Run {group_id}"
        channel_candidates = [
            run_history[column].dropna().astype(str).iloc[0]
            for column in ("ground_truth_channel", "channels")
            if column in run_history.columns
            and not run_history[column].dropna().empty
        ]
        channel = channel_candidates[0] if channel_candidates else str(group_id)
        runs.append({
            "label": label,
            "channel": channel,
            "group_id": group_id,
            "history": run_history.rename(columns={value_column: "observed_value"}),
        })
    return runs


def _filter_simulation_runs_for_channels(
    runs: Sequence[dict],
    selected_channels: Sequence[Any],
) -> list[dict]:
    selected = {str(channel) for channel in selected_channels}
    if not selected:
        return list(runs)
    filtered = []
    for run in runs:
        candidates = {
            str(run.get("channel")),
            str(run.get("group_id")),
        }
        history = run.get("history")
        if history is not None and not history.empty:
            if "channels" in history.columns:
                candidates.update(
                    str(value)
                    for value in history["channels"].dropna().astype(str).unique()
                )
            if "ground_truth_channel" in history.columns:
                candidates.update(
                    str(value)
                    for value
                    in history["ground_truth_channel"].dropna().astype(str).unique()
                )
        candidates.discard("None")
        if candidates & selected:
            filtered.append(run)
    return filtered


def _simulation_ground_truth_grid(
    ground_truth: pd.DataFrame,
    axes: Sequence[str],
    *,
    value_column: str,
    background_channel: str | None = None,
) -> pd.DataFrame:
    if ground_truth is None or ground_truth.empty:
        return pd.DataFrame()
    frame = ground_truth.copy()
    if background_channel is not None and "ground_truth_channel" in frame.columns:
        frame = frame.loc[
            frame["ground_truth_channel"].astype(str) == str(background_channel)
        ].copy()
    if frame.empty or value_column not in frame.columns:
        return pd.DataFrame()
    columns = [*axes, value_column]
    frame = frame[columns].copy()
    frame[columns] = frame[columns].apply(pd.to_numeric, errors="coerce")
    frame = frame.dropna(subset=columns)
    if frame.empty:
        return pd.DataFrame()
    frame = (
        frame.groupby(list(axes), as_index=False, dropna=False)[value_column]
        .mean()
        .rename(columns={value_column: "interpolated_value"})
    )
    return frame


def _channel_color_with_opacity(color: str, fraction: float) -> str:
    return _channel_color_with_alpha(color, 0.22 + 0.78 * min(1.0, max(0.0, float(fraction))))


def _channel_color_with_alpha(color: str, alpha: float) -> str:
    if color.startswith("rgba(") or color.startswith("rgb("):
        numeric_parts = [
            _finite_float(part.strip())
            for part in color[color.find("(") + 1:color.rfind(")")].split(",")[:3]
        ]
        if any(part is None for part in numeric_parts):
            return color
        red, green, blue = [int(part) for part in numeric_parts]
    else:
        base = color.lstrip("#")
        if len(base) != 6:
            return color
        try:
            red = int(base[0:2], 16)
            green = int(base[2:4], 16)
            blue = int(base[4:6], 16)
        except ValueError:
            return color
    alpha = min(1.0, max(0.0, float(alpha)))
    return f"rgba({red},{green},{blue},{alpha:.3f})"


def _strip_simulation_path_colorbars(fig: go.Figure) -> None:
    for trace in fig.data:
        if not str(getattr(trace, "legendgroup", "")).startswith(
            "simulation_path:"
        ):
            continue
        marker = getattr(trace, "marker", None)
        if marker is not None:
            marker.showscale = False
            marker.coloraxis = None
            marker.colorbar = None
            marker.colorscale = None
        if hasattr(trace, "showscale"):
            trace.showscale = False
        if hasattr(trace, "coloraxis"):
            trace.coloraxis = None
        if hasattr(trace, "colorbar"):
            trace.colorbar = None


def _simulation_path_legend_group(channel: str) -> str:
    return f"simulation_path:{channel}"


def _simulation_path_trace_color(
    color: str,
    fraction: float,
) -> str:
    return _channel_color_with_opacity(color, fraction)


def _add_real_channel_iteration_paths(
    fig: go.Figure,
    points: pd.DataFrame,
    x_name: str,
    y_name: str,
    z_name: str | None = None,
    *,
    line_width: int = 4,
    marker_size: int = 6,
) -> None:
    if points.empty or "channel" not in points.columns:
        return
    required = [x_name, y_name, "iteration", "channel", "value"]
    if z_name is not None:
        required.append(z_name)
    if not set(required).issubset(points.columns):
        return
    plot_points = points.copy()
    numeric_columns = [
        x_name,
        y_name,
        "iteration",
        "value",
        *([z_name] if z_name else []),
    ]
    for column in numeric_columns:
        plot_points[column] = pd.to_numeric(plot_points[column], errors="coerce")
    plot_points = plot_points.dropna(subset=required)
    if plot_points.empty:
        return
    channel_values = sorted(
        plot_points["channel"].astype(str).unique(),
        key=_channel_sort_key,
    )
    if len(channel_values) < 2:
        return
    channel_colors = {
        channel: _slice_highlight_color(index, len(channel_values))[1]
        for index, channel in enumerate(channel_values)
    }
    iteration_values = plot_points["iteration"].to_numpy(dtype=float)
    iteration_min = float(np.nanmin(iteration_values))
    iteration_max = float(np.nanmax(iteration_values))
    if np.isclose(iteration_min, iteration_max):
        iteration_max = iteration_min + 1.0

    def iteration_fraction(iteration: Any) -> float:
        numeric = _finite_float(iteration)
        if numeric is None:
            return 0.0
        return (numeric - iteration_min) / (iteration_max - iteration_min)

    is_3d = z_name is not None
    scatter_type = go.Scatter3d if is_3d else go.Scatter
    legend_channels_shown: set[str] = set()
    for channel, channel_points in plot_points.groupby("channel", sort=False):
        channel = str(channel)
        ordered = channel_points.sort_values("iteration", kind="mergesort")
        if ordered.empty:
            continue
        base_color = channel_colors.get(channel, "#1f77b4")
        legendgroup = f"real_channel_path:{channel}"
        show_channel_legend = channel not in legend_channels_shown
        legend_channels_shown.add(channel)
        for segment_index in range(1, len(ordered)):
            segment_rows = ordered.iloc[segment_index - 1:segment_index + 1]
            segment_kwargs = {
                "x": segment_rows[x_name],
                "y": segment_rows[y_name],
                "mode": "lines",
                "name": f"Ch {channel} path",
                "legendgroup": legendgroup,
                "line": {
                    "color": _simulation_path_trace_color(
                        base_color,
                        iteration_fraction(segment_rows["iteration"].iloc[-1]),
                    ),
                    "width": int(line_width),
                },
                "hoverinfo": "skip",
                "showlegend": False,
            }
            if is_3d:
                segment_kwargs["z"] = segment_rows[z_name]
            fig.add_trace(scatter_type(**segment_kwargs))
        customdata = np.column_stack((
            ordered["iteration"].to_numpy(dtype=float),
            ordered["value"].to_numpy(dtype=float),
            np.repeat(channel, len(ordered)),
        ))
        marker_colors = [
            _simulation_path_trace_color(
                base_color,
                iteration_fraction(iteration),
            )
            for iteration in ordered["iteration"]
        ]
        marker_kwargs = {
            "x": ordered[x_name],
            "y": ordered[y_name],
            "mode": "markers",
            "name": f"Ch {channel} path",
            "legendgroup": legendgroup,
            "showlegend": show_channel_legend,
            "marker": {
                "color": marker_colors,
                "size": int(marker_size),
                "line": {"color": "white", "width": 1},
                "showscale": False,
            },
            "customdata": customdata,
            "hovertemplate": (
                f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                + (f"{z_name}: %{{z:.4g}}<br>" if is_3d else "")
                + "Iteration: %{customdata[0]:.0f}<br>"
                + "Measured value: %{customdata[1]:.4g}<br>"
                + "Channel: %{customdata[2]}<extra></extra>"
            ),
        }
        if is_3d:
            marker_kwargs["z"] = ordered[z_name]
        fig.add_trace(scatter_type(**marker_kwargs))


def _add_simulation_sweep_paths(
    fig: go.Figure,
    runs: Sequence[dict],
    x_name: str,
    y_name: str,
    z_name: str | None = None,
    *,
    slice_axis: str | None = None,
    slice_value: float | None = None,
    line_width: int = 4,
    marker_size: int = 6,
    path_style: str = "full",
    tail_length: int = 8,
) -> None:
    channel_values = sorted({
        str(run.get("channel") or run.get("label") or index)
        for index, run in enumerate(runs)
    }, key=_channel_sort_key)
    channel_colors = {
        channel: _slice_highlight_color(index, len(channel_values))[1]
        for index, channel in enumerate(channel_values)
    }
    iteration_values = []
    for run in runs:
        history = run.get("history")
        if history is None or history.empty or "iteration" not in history.columns:
            continue
        iteration_values.extend(
            pd.to_numeric(history["iteration"], errors="coerce").dropna().tolist()
        )
    iteration_min = min(iteration_values) if iteration_values else 0.0
    iteration_max = max(iteration_values) if iteration_values else 1.0
    if np.isclose(iteration_min, iteration_max):
        iteration_max = iteration_min + 1.0

    def iteration_fraction(iteration: Any) -> float:
        numeric = _finite_float(iteration)
        if numeric is None:
            return 0.0
        return (numeric - iteration_min) / (iteration_max - iteration_min)

    is_3d = z_name is not None
    scatter_type = go.Scatter3d if is_3d else go.Scatter
    legend_channels_shown: set[str] = set()
    for run_index, run in enumerate(runs):
        history = run.get("history")
        if history is None or history.empty:
            continue
        plot_history = history.copy()
        if slice_axis is not None and slice_value is not None:
            plot_history = _apply_numeric_slice(
                plot_history,
                slice_axis,
                slice_value,
            ).reset_index(drop=True)
        required = [x_name, y_name, "iteration", "observed_value"]
        if is_3d:
            required.append(z_name)
        if not set(required).issubset(plot_history.columns):
            continue
        plot_history = plot_history.dropna(subset=required).sort_values(
            "iteration",
            kind="mergesort",
        )
        if plot_history.empty:
            continue
        channel = str(run.get("channel") or run.get("label") or run_index)
        label = str(run.get("label") or f"Run {run_index + 1}")
        legend_label = f"Channel {channel}"
        show_channel_legend = channel not in legend_channels_shown
        legend_channels_shown.add(channel)
        base_color = channel_colors.get(
            channel,
            _slice_highlight_color(run_index, max(1, len(runs)))[1],
        )
        legendgroup = _simulation_path_legend_group(channel)
        customdata = np.column_stack((
            plot_history["iteration"].to_numpy(dtype=float),
            plot_history["observed_value"].to_numpy(dtype=float),
            np.repeat(channel, len(plot_history)),
        ))
        if path_style == "start_end_tail":
            if len(plot_history) >= 2:
                full_kwargs = {
                    "x": plot_history[x_name],
                    "y": plot_history[y_name],
                    "mode": "lines",
                    "name": label,
                    "legendgroup": legendgroup,
                    "line": {
                        "color": _channel_color_with_alpha(base_color, 0.12),
                        "width": max(1, int(line_width) - 2),
                    },
                    "hoverinfo": "skip",
                    "showlegend": False,
                }
                if is_3d:
                    full_kwargs["z"] = plot_history[z_name]
                fig.add_trace(scatter_type(**full_kwargs))
            tail_count = max(2, int(tail_length))
            tail_history = plot_history.tail(tail_count)
            for segment_index in range(1, len(tail_history)):
                segment_rows = tail_history.iloc[segment_index - 1:segment_index + 1]
                fraction = segment_index / max(1, len(tail_history) - 1)
                segment_kwargs = {
                    "x": segment_rows[x_name],
                    "y": segment_rows[y_name],
                    "mode": "lines",
                    "name": label,
                    "legendgroup": legendgroup,
                    "line": {
                        "color": _channel_color_with_alpha(
                            base_color,
                            0.22 + 0.78 * fraction,
                        ),
                        "width": int(line_width),
                    },
                    "hoverinfo": "skip",
                    "showlegend": False,
                }
                if is_3d:
                    segment_kwargs["z"] = segment_rows[z_name]
                fig.add_trace(scatter_type(**segment_kwargs))
            tail_indices = list(tail_history.index)
            for point_index, (row_index, point_row) in enumerate(
                tail_history.iterrows()
            ):
                tail_fraction = point_index / max(1, len(tail_history) - 1)
                trace_kwargs = {
                    "x": [point_row[x_name]],
                    "y": [point_row[y_name]],
                    "mode": "markers",
                    "name": legend_label,
                    "legendgroup": legendgroup,
                    "showlegend": (
                        row_index == tail_indices[0] and show_channel_legend
                    ),
                    "marker": {
                        "color": _channel_color_with_alpha(
                            base_color,
                            0.28 + 0.72 * tail_fraction,
                        ),
                        "size": int(marker_size + round(2 * tail_fraction)),
                        "line": {"color": "white", "width": 1},
                        "showscale": False,
                    },
                    "customdata": [customdata[plot_history.index.get_loc(row_index)]],
                    "hovertemplate": (
                        f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                        + (f"{z_name}: %{{z:.4g}}<br>" if is_3d else "")
                        + "Iteration: %{customdata[0]:.0f}<br>"
                        + "Observed value: %{customdata[1]:.4g}<br>"
                        + "Channel: %{customdata[2]}<extra>"
                        + label
                        + "</extra>"
                    ),
                }
                if is_3d:
                    trace_kwargs["z"] = [point_row[z_name]]
                fig.add_trace(scatter_type(**trace_kwargs))
            endpoint_rows = [
                ("Start", plot_history.iloc[0], 0, marker_size + 4, "white"),
                ("Final", plot_history.iloc[-1], len(plot_history) - 1, marker_size + 7, "black"),
            ]
            for endpoint_name, point_row, point_index, size, outline in endpoint_rows:
                trace_kwargs = {
                    "x": [point_row[x_name]],
                    "y": [point_row[y_name]],
                    "mode": "markers",
                    "name": f"{legend_label} {endpoint_name.lower()}",
                    "legendgroup": legendgroup,
                    "showlegend": False,
                    "marker": {
                        "color": _channel_color_with_alpha(base_color, 1.0),
                        "size": int(size),
                        "line": {"color": outline, "width": 3},
                        "showscale": False,
                    },
                    "customdata": [customdata[point_index]],
                    "hovertemplate": (
                        f"{endpoint_name}<br>"
                        f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                        + (f"{z_name}: %{{z:.4g}}<br>" if is_3d else "")
                        + "Iteration: %{customdata[0]:.0f}<br>"
                        + "Observed value: %{customdata[1]:.4g}<br>"
                        + "Channel: %{customdata[2]}<extra>"
                        + label
                        + "</extra>"
                    ),
                }
                if is_3d:
                    trace_kwargs["z"] = [point_row[z_name]]
                fig.add_trace(scatter_type(**trace_kwargs))
            continue
        for segment_index in range(1, len(plot_history)):
            segment_rows = plot_history.iloc[segment_index - 1:segment_index + 1]
            segment_kwargs = {
                "x": segment_rows[x_name],
                "y": segment_rows[y_name],
                "mode": "lines",
                "name": label,
                "legendgroup": legendgroup,
                "line": {
                    "color": _simulation_path_trace_color(
                        base_color,
                        iteration_fraction(segment_rows["iteration"].iloc[-1]),
                    ),
                    "width": int(line_width),
                },
                "hoverinfo": "skip",
                "showlegend": False,
            }
            if is_3d:
                segment_kwargs["z"] = segment_rows[z_name]
            fig.add_trace(scatter_type(**segment_kwargs))
        for point_index, (_row_index, point_row) in enumerate(
            plot_history.iterrows()
        ):
            marker_color = _simulation_path_trace_color(
                base_color,
                iteration_fraction(point_row["iteration"]),
            )
            trace_kwargs = {
                "x": [point_row[x_name]],
                "y": [point_row[y_name]],
                "mode": "markers",
                "name": legend_label,
                "legendgroup": legendgroup,
                "showlegend": point_index == 0 and show_channel_legend,
                "marker": {
                    "color": marker_color,
                    "size": int(marker_size),
                    "line": {"color": "white", "width": 1},
                    "showscale": False,
                },
                "customdata": [customdata[point_index]],
                "hovertemplate": (
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    + (f"{z_name}: %{{z:.4g}}<br>" if is_3d else "")
                    + "Iteration: %{customdata[0]:.0f}<br>"
                    + "Observed value: %{customdata[1]:.4g}<br>"
                    + "Channel: %{customdata[2]}<extra>"
                    + label
                    + "</extra>"
                ),
            }
            if is_3d:
                trace_kwargs["z"] = [point_row[z_name]]
            fig.add_trace(scatter_type(**trace_kwargs))
    _strip_simulation_path_colorbars(fig)


def _plot_interpolated_simulated_trace(
    session: dict,
    observations: list[dict],
    target_params: dict[str, float],
    selected_channels: list[str],
    *,
    corrected: bool,
    analysis: dict,
    correction_label: str,
    normalize_to_peak: bool = False,
    corrected_trace_key: str = "smoothed_corrected_current",
    offset_to_baseline: bool = False,
    nearest_count: int = 4,
) -> tuple[plt.Figure, list[str]]:
    """Interpolate real SWV waveforms near a simulated parameter point."""
    rows = []
    parameters = [
        name for name in PARAMETERS
        if name in target_params
        and any((observation.get("params") or {}).get(name) is not None for observation in observations)
    ]
    if not parameters:
        fig, ax = plt.subplots(figsize=(8, 4))
        ax.text(.5, .5, "No parameter coordinates are available.", ha="center", va="center")
        ax.set_axis_off()
        return fig, []
    source_frame = pd.DataFrame([
        {
            "observation": observation,
            **{
                name: (observation.get("params") or {}).get(name)
                for name in parameters
            },
        }
        for observation in observations
    ])
    numeric_source = source_frame[parameters].apply(pd.to_numeric, errors="coerce")
    valid_mask = numeric_source.notna().all(axis=1)
    source_frame = source_frame.loc[valid_mask].reset_index(drop=True)
    numeric_source = numeric_source.loc[valid_mask].reset_index(drop=True)
    if source_frame.empty:
        fig, ax = plt.subplots(figsize=(8, 4))
        ax.text(.5, .5, "No trace observations have complete coordinates.", ha="center", va="center")
        ax.set_axis_off()
        return fig, []
    bounds = _simulation_parameter_bounds(
        pd.concat(
            [
                numeric_source,
                pd.DataFrame([{name: target_params[name] for name in parameters}]),
            ],
            ignore_index=True,
        ),
        parameters,
        session.get("config") or {},
    )
    encoded_source = _simulation_encode_parameters(
        numeric_source,
        parameters,
        bounds,
    )
    encoded_target = _simulation_encode_parameters(
        pd.DataFrame([{name: target_params[name] for name in parameters}]),
        parameters,
        bounds,
    )[0]
    distances = np.sqrt(np.sum((encoded_source - encoded_target[None, :]) ** 2, axis=1))
    nearest_positions = np.argsort(distances)[:max(1, int(nearest_count))]
    selected_channel_set = set(map(str, selected_channels))
    trace_rows = []
    errors = []
    for position in nearest_positions:
        observation = source_frame.loc[int(position), "observation"]
        distance = float(distances[int(position)])
        weight = 1.0 / max(distance, 1e-6)
        for item in _trace_paths(session, observation):
            channel = _trace_channel_key(item)
            if selected_channel_set and channel not in selected_channel_set:
                continue
            try:
                voltage, y, peak_idx, left_idx, right_idx = _swv_trace_arrays(
                    item["path"],
                    corrected,
                    analysis,
                    corrected_trace_key,
                )
                if offset_to_baseline:
                    y = _offset_trace_to_minima_baseline(y, left_idx, right_idx)
                if normalize_to_peak:
                    y = _normalize_trace_to_peak(y, peak_idx, left_idx, right_idx)
                trace_rows.append({
                    "phase": str(item.get("phase") or "measurement"),
                    "channel": channel,
                    "voltage": np.asarray(voltage, dtype=float),
                    "current": np.asarray(y, dtype=float),
                    "weight": weight,
                    "iteration": int(observation.get("iteration", 0)),
                })
            except Exception as exc:
                errors.append(f"{item['path'].name}: {exc}")
    fig, ax = plt.subplots(figsize=(8, 4))
    if not trace_rows:
        ax.text(.5, .5, "No nearby real SWV traces matched the selected channels.", ha="center", va="center")
        ax.set_axis_off()
        return fig, errors
    colors = plt.get_cmap("tab10")(np.linspace(0, 1, max(2, len(trace_rows))))
    for trace_index, ((phase, channel), group) in enumerate(
        itertools.groupby(
            sorted(trace_rows, key=lambda row: (row["phase"], _channel_sort_key(row["channel"]))),
            key=lambda row: (row["phase"], row["channel"]),
        )
    ):
        group_rows = list(group)
        reference_voltage = group_rows[0]["voltage"]
        weighted_current = np.zeros_like(reference_voltage, dtype=float)
        total_weight = 0.0
        source_iterations = []
        for row in group_rows:
            current = row["current"]
            voltage = row["voltage"]
            if len(current) != len(reference_voltage) or not np.allclose(
                voltage,
                reference_voltage,
                equal_nan=True,
            ):
                current = np.interp(reference_voltage, voltage, current)
            weighted_current += current * float(row["weight"])
            total_weight += float(row["weight"])
            source_iterations.append(row["iteration"])
        if total_weight <= 0:
            continue
        weighted_current /= total_weight
        ax.plot(
            reference_voltage,
            weighted_current,
            color=colors[trace_index % len(colors)],
            linewidth=1.5,
            label=(
                f"{phase} {_trace_channel_label(channel)} "
                f"(from iters {', '.join(map(str, sorted(set(source_iterations))))})"
            ),
        )
    trace_label = _swv_trace_kind_label(
        corrected,
        normalize_to_peak,
        corrected_trace_key,
        offset_to_baseline,
    )
    ax.set_title(f"Interpolated simulated {trace_label} SWV trace ({correction_label})")
    ax.set_xlabel("Voltage (V)")
    ax.set_ylabel("Current")
    ax.grid(True, alpha=.25)
    ax.legend(fontsize=8)
    fig.tight_layout()
    return fig, errors


def _trace_realistic_channel_measurements(
    session: dict,
    observations: list[dict],
    target_params: dict[str, float],
    selected_channels: list[str],
    *,
    analysis: dict,
    nearest_count: int = 4,
) -> tuple[dict[str, dict], list[str]]:
    """Create trace-derived channel measurements near a simulated point."""
    parameters = [
        name for name in PARAMETERS
        if name in target_params
        and any((observation.get("params") or {}).get(name) is not None for observation in observations)
    ]
    if not parameters:
        return {}, ["No parameter coordinates are available for trace interpolation."]
    source_frame = pd.DataFrame([
        {
            "observation": observation,
            **{
                name: (observation.get("params") or {}).get(name)
                for name in parameters
            },
        }
        for observation in observations
    ])
    numeric_source = source_frame[parameters].apply(pd.to_numeric, errors="coerce")
    valid_mask = numeric_source.notna().all(axis=1)
    source_frame = source_frame.loc[valid_mask].reset_index(drop=True)
    numeric_source = numeric_source.loc[valid_mask].reset_index(drop=True)
    if source_frame.empty:
        return {}, ["No real trace observations have complete coordinates."]
    bounds = _simulation_parameter_bounds(
        pd.concat(
            [
                numeric_source,
                pd.DataFrame([{name: target_params[name] for name in parameters}]),
            ],
            ignore_index=True,
        ),
        parameters,
        session.get("config") or {},
    )
    encoded_source = _simulation_encode_parameters(numeric_source, parameters, bounds)
    encoded_target = _simulation_encode_parameters(
        pd.DataFrame([{name: target_params[name] for name in parameters}]),
        parameters,
        bounds,
    )[0]
    distances = np.sqrt(np.sum((encoded_source - encoded_target[None, :]) ** 2, axis=1))
    nearest_positions = np.argsort(distances)[:max(1, int(nearest_count))]
    selected_channel_set = set(map(str, selected_channels))
    trace_rows: list[dict] = []
    errors: list[str] = []
    for position in nearest_positions:
        observation = source_frame.loc[int(position), "observation"]
        distance = float(distances[int(position)])
        weight = 1.0 / max(distance, 1e-6)
        for item in _trace_paths(session, observation):
            channel = _trace_channel_key(item)
            if selected_channel_set and channel not in selected_channel_set:
                continue
            try:
                voltage, current = _cached_swv_arrays(
                    str(item["path"]),
                    int(Path(item["path"]).stat().st_mtime_ns),
                )
                trace_rows.append({
                    "channel": channel,
                    "voltage": np.asarray(voltage, dtype=float),
                    "current": np.asarray(current, dtype=float),
                    "weight": weight,
                    "source_iteration": int(observation.get("iteration", 0)),
                })
            except Exception as exc:
                errors.append(f"{item['path'].name}: {exc}")
    channel_measurements: dict[str, dict] = {}
    for channel, group in itertools.groupby(
        sorted(trace_rows, key=lambda row: _channel_sort_key(row["channel"])),
        key=lambda row: row["channel"],
    ):
        group_rows = list(group)
        if not group_rows:
            continue
        reference_voltage = group_rows[0]["voltage"]
        weighted_current = np.zeros_like(reference_voltage, dtype=float)
        total_weight = 0.0
        source_iterations = []
        for row in group_rows:
            current = row["current"]
            voltage = row["voltage"]
            if len(current) != len(reference_voltage) or not np.allclose(
                voltage,
                reference_voltage,
                equal_nan=True,
            ):
                current = np.interp(reference_voltage, voltage, current)
            weighted_current += current * float(row["weight"])
            total_weight += float(row["weight"])
            source_iterations.append(row["source_iteration"])
        if total_weight <= 0:
            continue
        weighted_current /= total_weight
        try:
            analyzed = analyze_swv_arrays(
                v_raw=reference_voltage,
                i_raw=weighted_current,
                crop_range=(
                    float(analysis.get("crop_min_v", -0.6)),
                    float(analysis.get("crop_max_v", -0.2)),
                ),
                smooth_window=int(analysis.get("smooth_window", 9)),
                smooth_polyorder=int(analysis.get("smooth_polyorder", 2)),
                minima_search_window_V=float(
                    analysis.get("minima_search_window_v", 0.30)
                ),
                use_prominent_minima=bool(
                    analysis.get("use_prominent_minima", False)
                ),
                use_double_correction=bool(
                    analysis.get("use_double_correction", False)
                ),
                min_peak_height_uA=analysis.get("min_peak_height_uA"),
                compute_skew=True,
                compute_wavelet_energy=True,
                compute_wavelet_denoised_trace=bool(
                    analysis.get("compute_wavelet_denoised_trace", False)
                ),
                use_wavelet_for_correction=bool(
                    analysis.get("use_wavelet_for_correction", False)
                ),
            )
            noise = float(analyzed.get("background_current_rms", np.nan))
            peak = float(analyzed.get("peak_current", np.nan))
            snr = peak / max(noise, 1e-12) if np.isfinite(peak) else np.nan
            classic_q = max(0.0, float(snr)) if np.isfinite(snr) else 0.0
            channel_measurements[str(channel)] = {
                "voltage": reference_voltage,
                "current": weighted_current,
                "analysis": analyzed,
                "classic_Q": classic_q,
                "Q_channel": classic_q,
                "snr": float(snr) if np.isfinite(snr) else np.nan,
                "snr_unadjusted": float(snr) if np.isfinite(snr) else np.nan,
                "mean_peak_current_uA": peak,
                "background_current_rms": noise,
                "peak_shape_score": max(0.0, 1.0 - abs(float(analyzed.get("peak_offset_norm", 0.0) or 0.0))),
                "baseline_stability_score": 1.0 / (1.0 + max(0.0, noise)),
                "replicate_consistency_score": 1.0,
                "success_score": 1.0 if classic_q > 0 else 0.0,
                "source_iterations": sorted(set(source_iterations)),
            }
        except Exception as exc:
            errors.append(f"Ch {channel}: {exc}")
    return channel_measurements, errors


def _trace_realistic_measurement_value(
    session: dict,
    observations: list[dict],
    params: dict[str, float],
    selected_channels: list[str],
    *,
    analysis: dict,
    nearest_count: int,
) -> tuple[float, dict]:
    channel_measurements, errors = _trace_realistic_channel_measurements(
        session,
        observations,
        params,
        selected_channels,
        analysis=analysis,
        nearest_count=nearest_count,
    )
    values = [
        float(item.get("Q_channel", np.nan))
        for item in channel_measurements.values()
        if np.isfinite(float(item.get("Q_channel", np.nan)))
    ]
    q_run = float(np.mean(values)) if values else float("nan")
    return q_run, {
        "channel_measurements": channel_measurements,
        "trace_errors": errors,
        "simulation_fidelity": "trace-realistic",
    }


def _synthetic_swv_arrays(q_value: float, params: dict, iteration: int) -> tuple[np.ndarray, np.ndarray]:
    begin = float(params.get("begin_potential", -0.7))
    end = float(params.get("end_potential", -0.1))
    if end <= begin:
        begin, end = min(begin, end), max(begin, end)
        if np.isclose(begin, end):
            begin, end = -0.7, -0.1
    voltage = np.linspace(begin, end, 181)
    center = begin + 0.58 * (end - begin)
    amplitude = max(0.02, float(params.get("amplitude", 0.04)))
    frequency = max(1.0, float(params.get("frequency", 100.0)))
    width = max(0.012, min(0.08, 0.018 + amplitude * 0.22))
    baseline = 0.03 * np.sin(
        np.linspace(0, 2.0 * np.pi, len(voltage))
        * (1.0 + min(frequency, 1000.0) / 1000.0)
    )
    peak_height = max(0.05, float(q_value)) * 0.12
    peak = peak_height * np.exp(-0.5 * ((voltage - center) / width) ** 2)
    deterministic_noise = 0.012 * np.sin(
        np.arange(len(voltage)) * 0.37 + int(iteration) * 0.91
    )
    current = baseline + peak + deterministic_noise
    return voltage, current


def _write_simulated_trace_record(
    session_root: Path,
    observation: dict,
    *,
    channel: int,
) -> str:
    iteration = int(observation.get("iteration", 0))
    group_id = int(observation.get("group_id", 1))
    q_value = float(observation.get("Q_run", 0.0))
    params = dict(observation.get("params") or {})
    raw_dir = session_root / "raw_swv" / f"group_{group_id:02d}" / f"iter_{iteration:03d}"
    raw_dir.mkdir(parents=True, exist_ok=True)
    raw_path = raw_dir / f"ch{int(channel):03d}_measurement_simulated_swv.csv"
    trace_measurements = (
        (observation.get("simulation_trace_measurements") or {})
        if isinstance(observation.get("simulation_trace_measurements"), dict)
        else {}
    )
    trace_measurement = trace_measurements.get(str(channel)) or {}
    if not trace_measurement and trace_measurements:
        trace_measurement = next(iter(trace_measurements.values())) or {}
    if trace_measurement:
        voltage = np.asarray(trace_measurement.get("voltage"), dtype=float)
        current = np.asarray(trace_measurement.get("current"), dtype=float)
    else:
        voltage, current = _synthetic_swv_arrays(q_value, params, iteration)
    pd.DataFrame({
        "Potential (V)": voltage,
        "Current (uA)": current,
    }).to_csv(raw_path, index=False)

    analysis_dir = session_root / "analysis"
    analysis_dir.mkdir(parents=True, exist_ok=True)
    results_csv = analysis_dir / (
        f"group_{group_id:02d}_iter_{iteration:03d}_results.csv"
    )
    trace_classic_q = float(trace_measurement.get("classic_Q", q_value))
    trace_snr = float(trace_measurement.get("snr", max(0.0, q_value)))
    pd.DataFrame([{
        "file_path": str(raw_path),
        "file_name": raw_path.name,
        "channel": int(channel),
        "phase": "measurement",
        "classic_Q": trace_classic_q,
        "Q_channel": trace_classic_q,
        "snr": trace_snr,
        "snr_unadjusted": float(
            trace_measurement.get("snr_unadjusted", trace_snr)
        ),
        "mean_peak_current_uA": float(
            trace_measurement.get(
                "mean_peak_current_uA",
                float(np.nanmax(current) - np.nanmin(current)),
            )
        ),
        "background_current_rms": trace_measurement.get(
            "background_current_rms"
        ),
        "peak_shape_score": trace_measurement.get("peak_shape_score"),
        "baseline_stability_score": trace_measurement.get(
            "baseline_stability_score"
        ),
        "replicate_consistency_score": trace_measurement.get(
            "replicate_consistency_score"
        ),
        "success_score": trace_measurement.get("success_score", q_value),
    }]).to_csv(results_csv, index=False)
    record_path = analysis_dir / (
        f"group_{group_id:02d}_iter_{iteration:03d}_analysis_record.json"
    )
    payload = {
        "schema_version": 1,
        "source": "simulated_bo_session_export",
        "results_csv": str(results_csv),
        "folders": [str(raw_dir)],
    }
    with record_path.open("w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)
    return str(record_path)


def _simulation_surrogate_artifact_frame(
    ground_truth: pd.DataFrame,
    history: pd.DataFrame,
    axes: tuple[str, str, str],
    value_column: str = "ground_truth_value",
) -> pd.DataFrame:
    x_name, y_name, z_name = axes
    frame = ground_truth.copy()
    if value_column not in frame.columns and "interpolated_value" in frame.columns:
        value_column = "interpolated_value"
    if value_column not in frame.columns:
        value_candidates = [
            column for column in frame.columns
            if column not in {x_name, y_name, z_name, "source_index", "candidate_index"}
            and pd.api.types.is_numeric_dtype(frame[column])
        ]
        value_column = value_candidates[0] if value_candidates else frame.columns[-1]
    for name in PARAMETERS:
        if name not in frame.columns:
            if "params" in frame.columns:
                frame[name] = [
                    (params or {}).get(name, DEFAULT_INITIAL_METHOD[name])
                    if isinstance(params, dict) else DEFAULT_INITIAL_METHOD[name]
                    for params in frame["params"]
                ]
            else:
                frame[name] = DEFAULT_INITIAL_METHOD[name]
    frame["predicted_mean_Q"] = pd.to_numeric(frame[value_column], errors="coerce")
    observed = history.dropna(subset=[x_name, y_name, z_name])
    if observed.empty:
        frame["predicted_std_Q"] = 1.0
        frame["already_tested"] = False
    else:
        candidate_coords = frame[[x_name, y_name, z_name]].apply(
            pd.to_numeric,
            errors="coerce",
        ).to_numpy(dtype=float)
        observed_coords = observed[[x_name, y_name, z_name]].apply(
            pd.to_numeric,
            errors="coerce",
        ).to_numpy(dtype=float)
        spans = np.nanmax(candidate_coords, axis=0) - np.nanmin(candidate_coords, axis=0)
        spans = np.where(np.isfinite(spans) & (spans > 0), spans, 1.0)
        distances = np.sqrt(
            np.sum(
                (
                    (candidate_coords[:, None, :] - observed_coords[None, :, :])
                    / spans[None, None, :]
                ) ** 2,
                axis=2,
            )
        )
        nearest = np.nanmin(distances, axis=1)
        frame["predicted_std_Q"] = np.maximum(nearest, 0.02)
        observed_keys = {
            tuple(round(float(row[name]), 9) for name in (x_name, y_name, z_name))
            for _idx, row in observed.iterrows()
        }
        frame["already_tested"] = [
            tuple(round(float(row[name]), 9) for name in (x_name, y_name, z_name))
            in observed_keys
            for _idx, row in frame.iterrows()
        ]
    best = float(pd.to_numeric(history.get("observed_value"), errors="coerce").max())
    if not np.isfinite(best):
        best = float(frame["predicted_mean_Q"].max())
    improvement = frame["predicted_mean_Q"] - best - 0.01
    std = np.maximum(frame["predicted_std_Q"].to_numpy(dtype=float), 1e-12)
    z_score = improvement.to_numpy(dtype=float) / std
    expected = improvement.to_numpy(dtype=float) * ndtr(z_score) + (
        std * np.exp(-0.5 * z_score ** 2) / np.sqrt(2.0 * np.pi)
    )
    frame["acquisition_value"] = frame["predicted_mean_Q"] + 0.25 * expected
    return frame[[*PARAMETERS, "predicted_mean_Q", "predicted_std_Q", "acquisition_value", "already_tested"]]


def _simulation_history_row_params(
    row: pd.Series,
    config: dict,
    axes: tuple[str, str, str],
) -> dict:
    params = {
        name: float(
            (config.get("initial_parameters") or {}).get(
                name,
                DEFAULT_INITIAL_METHOD[name],
            )
        )
        for name in PARAMETERS
    }
    for name in axes:
        if name in PARAMETERS and name in row and pd.notna(row[name]):
            params[name] = float(row[name])
    conditioning_cfg = (
        (config.get("parameters") or {}).get("conditioning_potential")
        or {}
    )
    if str(conditioning_cfg.get("mode", "")).lower() == "tied":
        params["conditioning_potential"] = float(params["begin_potential"])
    return params


def _simulation_first_history_params(
    history: pd.DataFrame,
    config: dict,
    axes: tuple[str, str, str],
) -> dict:
    if history is None or history.empty:
        return {
            name: float(
                (config.get("initial_parameters") or {}).get(
                    name,
                    DEFAULT_INITIAL_METHOD[name],
                )
            )
            for name in PARAMETERS
        }
    sorted_history = history.sort_values("iteration")
    return _simulation_history_row_params(sorted_history.iloc[0], config, axes)


def _simulation_channel_group_metadata(
    *,
    group_id: int,
    name: str,
    channels: list[int],
    first_params: dict,
    settings: dict | None = None,
    exploration: float | None = None,
    replicate: int | None = None,
    seed: int | None = None,
) -> dict:
    settings = dict(settings or {})
    falloffs = dict(settings.get("falloff_fractions") or {})
    resolved_exploration = (
        float(exploration)
        if exploration is not None and np.isfinite(float(exploration))
        else settings.get("exploration")
    )
    return {
        "id": int(group_id),
        "name": str(name),
        "channels": [int(channel) for channel in channels],
        "initial_parameters": {
            name: float(value)
            for name, value in first_params.items()
            if name in PARAMETERS and value is not None
        },
        "configured_initial_parameters": dict(
            settings.get("configured_initial_parameters") or {}
        ),
        "exploration": resolved_exploration,
        "n_initial_points": settings.get("initial_random_points"),
        "candidate_pool_size": settings.get("candidate_pool_size"),
        "local_candidate_pool_size": settings.get("local_candidate_pool_size"),
        "initial_point_mode": settings.get("initial_point_mode", "simulation"),
        "use_gp": settings.get("use_gp", True),
        "gp_optimizer_restarts": settings.get("gp_optimizer_restarts"),
        "gp_noise_level": settings.get("noise"),
        "gp_falloff_fractions": falloffs,
        "gp_length_scales": falloffs,
        "simulation_replicate": replicate,
        "simulation_seed": seed,
        "ground_truth_channel": (
            str(settings.get("ground_truth_channel"))
            if settings.get("ground_truth_channel") is not None else None
        ),
        "simulated_session": True,
    }


def _simulation_saved_channel_identity(
    run: dict,
    fallback_channel: int,
) -> str:
    channel = run.get("ground_truth_channel")
    if channel is None:
        history = run.get("history")
        if (
            isinstance(history, pd.DataFrame)
            and not history.empty
            and "ground_truth_channel" in history.columns
            and not history["ground_truth_channel"].dropna().empty
        ):
            channel = history["ground_truth_channel"].dropna().astype(str).iloc[0]
    if channel is None:
        channel = fallback_channel
    return str(channel)


def _simulation_channel_list_value(channel: str) -> list[int | str]:
    numeric = _finite_float(channel)
    if numeric is not None and float(numeric).is_integer():
        return [int(numeric)]
    return [str(channel)]


def _simulation_history_channel_column(channel: str) -> str:
    safe_channel = re.sub(r"[^A-Za-z0-9]+", "_", str(channel)).strip("_")
    return f"Q_ch{safe_channel or 'simulation'}"


def _simulation_serializable_trace_metadata(metadata: dict) -> dict:
    if not isinstance(metadata, dict):
        return {}
    compact = {
        key: value for key, value in metadata.items()
        if key not in {"channel_measurements"}
    }
    channel_measurements = metadata.get("channel_measurements") or {}
    if isinstance(channel_measurements, dict):
        compact["channel_measurements"] = {
            str(channel): {
                key: value for key, value in measurement.items()
                if key not in {"voltage", "current", "analysis"}
            }
            for channel, measurement in channel_measurements.items()
            if isinstance(measurement, dict)
        }
    return compact


def _write_simulated_surrogate_artifacts(
    session_root: Path,
    ground_truth: pd.DataFrame,
    history: pd.DataFrame,
    *,
    axes: tuple[str, str, str],
    group_id: int,
    candidate_pool: pd.DataFrame | None = None,
) -> None:
    surrogate_dir = session_root / "surrogate"
    surrogate_dir.mkdir(parents=True, exist_ok=True)
    artifact_source = (
        candidate_pool
        if candidate_pool is not None and not candidate_pool.empty
        else ground_truth
    )
    for iteration in sorted(pd.to_numeric(history["iteration"], errors="coerce").dropna().astype(int).unique()):
        partial_history = history[
            pd.to_numeric(history["iteration"], errors="coerce") <= iteration
        ]
        artifact = _simulation_surrogate_artifact_frame(
            artifact_source,
            partial_history,
            axes,
        )
        artifact.to_csv(
            surrogate_dir / f"group_{int(group_id):02d}_iter_{int(iteration):03d}_candidate_predictions.csv",
            index=False,
        )


def _write_simulated_bo_session(
    output_parent: Path,
    source_session: dict,
    history: pd.DataFrame,
    ground_truth: pd.DataFrame,
    *,
    run_label: str,
    value_label: str,
    axes: tuple[str, str, str],
    source_points: pd.DataFrame | None = None,
    candidate_pool: pd.DataFrame | None = None,
    simulation_settings: dict | None = None,
    exploration: float | None = None,
    replicate: int | None = None,
    seed: int | None = None,
) -> Path:
    if history.empty:
        raise ValueError("Cannot write an empty simulation history.")
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    safe_label = re.sub(r"[^A-Za-z0-9_-]+", "_", str(run_label)).strip("_")
    safe_label = safe_label or "simulation"
    output_parent.mkdir(parents=True, exist_ok=True)
    session_root = output_parent / f"bo_session_simulated_{timestamp}_{safe_label}"
    suffix = 2
    while session_root.exists():
        session_root = output_parent / (
            f"bo_session_simulated_{timestamp}_{safe_label}_{suffix}"
        )
        suffix += 1
    session_root.mkdir(parents=True, exist_ok=False)

    config = json.loads(json.dumps(source_session.get("config") or {}))
    config.setdefault("name", "Simulated BO session")
    config.setdefault("records", {})["simulated_session"] = True
    config.setdefault("acquisition", {})
    simulation_settings = dict(simulation_settings or {})
    if exploration is not None and np.isfinite(float(exploration)):
        config["acquisition"]["exploration"] = float(exploration)
    if simulation_settings.get("initial_random_points") is not None:
        config["n_initial_points"] = int(simulation_settings["initial_random_points"])
    for setting_key, config_key in (
        ("candidate_pool_size", "candidate_pool_size"),
        ("local_candidate_pool_size", "local_candidate_pool_size"),
        ("noise", "gp_noise_level"),
        ("use_gp", "use_gp"),
        ("gp_optimizer_restarts", "gp_optimizer_restarts"),
    ):
        if simulation_settings.get(setting_key) is not None:
            config["acquisition"][config_key] = simulation_settings[setting_key]
    if simulation_settings.get("falloff_fractions"):
        config["acquisition"]["gp_falloff_fractions"] = dict(
            simulation_settings["falloff_fractions"]
        )
        config["acquisition"]["gp_length_scales"] = dict(
            simulation_settings["falloff_fractions"]
        )
    if seed is not None:
        config["random_seed"] = int(seed)
    ground_truth_channel = (
        simulation_settings.get("ground_truth_channel")
        if simulation_settings.get("ground_truth_channel") is not None
        else (
            str(history["ground_truth_channel"].dropna().iloc[0])
            if "ground_truth_channel" in history.columns
            and not history["ground_truth_channel"].dropna().empty
            else None
        )
    )
    group_name = str(run_label)
    saved_channel = (
        str(ground_truth_channel)
        if ground_truth_channel is not None
        else "1"
    )
    channel_values = _simulation_channel_list_value(saved_channel)
    channel_column = _simulation_history_channel_column(saved_channel)
    first_params = _simulation_first_history_params(history, config, axes)
    config["initial_parameters"] = dict(first_params)
    group_metadata = _simulation_channel_group_metadata(
        group_id=1,
        name=group_name,
        channels=channel_values,
        first_params=first_params,
        settings=simulation_settings,
        exploration=exploration,
        replicate=replicate,
        seed=seed,
    )
    config["channel_groups"] = [group_metadata]
    config["channels"] = channel_values

    observations = []
    history_rows = []
    x_name, y_name, z_name = axes
    for _index, row in history.sort_values("iteration").iterrows():
        params = _simulation_history_row_params(row, config, axes)
        iteration = int(row["iteration"])
        q_run = float(row["observed_value"])
        measurement_metadata = (
            row.get("measurement_metadata")
            if isinstance(row.get("measurement_metadata"), dict)
            else {}
        )
        observation = {
            "iteration": iteration,
            "method_id": f"simulated_iter_{iteration:03d}",
            "params": params,
            "created_at": timestamp,
            "completed_at": timestamp,
            "status": "completed",
            "group_id": 1,
            "group_name": group_name,
            "channels": channel_values,
            "objective": "simulation",
            "Q_run": q_run,
            "quality": {
                "Q_run": q_run,
                "channel_components": {
                    saved_channel: {
                        "Q_channel": q_run,
                        "classic_Q": q_run,
                        "snr_score": q_run,
                        "normalized_SNR": q_run,
                    }
                },
                "simulation_metric": value_label,
                "simulation_run_label": run_label,
                "simulation_exploration": (
                    float(exploration)
                    if exploration is not None and np.isfinite(float(exploration))
                    else None
                ),
                "simulation_replicate": replicate,
                "simulation_seed": seed,
                "ground_truth_channel": ground_truth_channel,
                "selection_mode": row.get("selection_mode"),
                "predicted_mean_Q": (
                    float(row["predicted_mean"])
                    if "predicted_mean" in row and pd.notna(row["predicted_mean"])
                    else None
                ),
                "predicted_std_Q": (
                    float(row["predicted_std"])
                    if "predicted_std" in row and pd.notna(row["predicted_std"])
                    else None
                ),
                "acquisition_value": (
                    float(row["acquisition_value"])
                    if "acquisition_value" in row and pd.notna(row["acquisition_value"])
                    else None
                ),
            },
            "channel_metrics": {
                saved_channel: {
                    "Q_channel": q_run,
                    "classic_Q": q_run,
                    "snr": max(0.0, q_run),
                    "snr_unadjusted": max(0.0, q_run),
                    "success_score": q_run,
                    "mean_peak_current_uA": q_run,
                    "peak_shape_score": q_run,
                    "baseline_stability_score": q_run,
                    "replicate_consistency_score": q_run,
                }
            },
            "simulation_truth": {
                "ground_truth_metric": value_label,
                "ground_truth_value": q_run,
                "tensor_value": (
                    float(row["tensor_value"])
                    if "tensor_value" in row and pd.notna(row["tensor_value"])
                    else q_run
                ),
                "run_label": run_label,
                "exploration": exploration,
                "replicate": replicate,
                "seed": seed,
                "ground_truth_channel": ground_truth_channel,
                **_simulation_serializable_trace_metadata(measurement_metadata),
            },
        }
        transient_trace_measurements = measurement_metadata.get(
            "channel_measurements",
            {},
        )
        if transient_trace_measurements:
            observation["simulation_trace_measurements"] = transient_trace_measurements
        observation["analysis_record"] = _write_simulated_trace_record(
            session_root,
            observation,
            channel=channel_values[0],
        )
        observation.pop("simulation_trace_measurements", None)
        observations.append(observation)
        history_row = {
            "iteration": iteration,
            "group_id": 1,
            "group_name": group_name,
            "channels": saved_channel,
            "Q_run": q_run,
            "objective": "simulation",
            "completed_at": timestamp,
            "selection_mode": row.get("selection_mode"),
            "exploration": exploration,
            "replicate": replicate,
            "seed": seed,
            "initial_random_points": simulation_settings.get("initial_random_points"),
            "gp_falloff_parameter": row.get("gp_falloff_parameter"),
            "gp_falloff_value": row.get("gp_falloff_value"),
            "run_label": run_label,
            "ground_truth_channel": ground_truth_channel,
            "best_so_far": float(row.get("best_so_far", q_run)),
            channel_column: q_run,
            "predicted_mean_Q": row.get("predicted_mean"),
            "predicted_std_Q": row.get("predicted_std"),
            "acquisition_value": row.get("acquisition_value"),
        }
        history_row.update(params)
        if "tensor_value" in row and pd.notna(row["tensor_value"]):
            history_row["tensor_value"] = float(row["tensor_value"])
        history_rows.append(history_row)

    best_observation = max(
        observations,
        key=lambda observation: float(observation.get("Q_run", 0.0)),
    )
    ground_truth_optimum = _simulation_optimum_reference_from_frame(ground_truth)
    state = {
        "session_id": f"simulated_{timestamp}_{safe_label}",
        "record_dir": str(session_root),
        "analysis_output_dir": str(session_root / "analysis"),
        "candidate_count": int(
            len(candidate_pool)
            if candidate_pool is not None and not candidate_pool.empty
            else len(ground_truth)
        ),
        "active_parameters": list(axes),
        "channel_groups": [group_metadata],
        "pending": None,
        "pending_batch": [],
        "suggestions": [],
        "observations": observations,
        "best_observation": best_observation,
        "simulation_metadata": {
            "source_session": str(source_session.get("root")),
            "run_label": run_label,
            "value_label": value_label,
            "axes": list(axes),
            "ground_truth_optimum": ground_truth_optimum,
            "exploration": exploration,
            "replicate": replicate,
            "seed": seed,
            "ground_truth_channel": ground_truth_channel,
            "settings": simulation_settings,
            "ground_truth_rows": int(len(ground_truth)),
            "candidate_pool_rows": int(
                len(candidate_pool)
                if candidate_pool is not None and not candidate_pool.empty
                else len(ground_truth)
            ),
        },
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
    }
    with (session_root / "bo_state.json").open("w", encoding="utf-8") as handle:
        json.dump(state, handle, indent=2)
    with (session_root / "bo_config_snapshot.json").open("w", encoding="utf-8") as handle:
        json.dump(config, handle, indent=2)
    pd.DataFrame(history_rows).to_csv(session_root / "history.csv", index=False)
    ground_truth.to_csv(session_root / "simulation_ground_truth_tensor.csv", index=False)
    if source_points is not None and not source_points.empty:
        source_points.to_csv(session_root / "simulation_source_observations.csv", index=False)
    _write_simulated_surrogate_artifacts(
        session_root,
        ground_truth,
        history,
        axes=axes,
        group_id=1,
        candidate_pool=candidate_pool,
    )
    return session_root


def _write_simulated_bo_session_bundle(
    output_parent: Path,
    source_session: dict,
    runs: list[dict],
    ground_truth: pd.DataFrame,
    *,
    value_label: str,
    axes: tuple[str, str, str],
    source_points: pd.DataFrame | None = None,
    candidate_pool: pd.DataFrame | None = None,
    simulation_settings: dict | None = None,
) -> Path:
    nonempty_runs = [
        run for run in runs
        if run.get("history") is not None and not run["history"].empty
    ]
    if not nonempty_runs:
        raise ValueError("Cannot write an empty simulation sweep.")
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    output_parent.mkdir(parents=True, exist_ok=True)
    session_root = output_parent / f"bo_session_simulated_{timestamp}_sweep"
    suffix = 2
    while session_root.exists():
        session_root = output_parent / f"bo_session_simulated_{timestamp}_sweep_{suffix}"
        suffix += 1
    session_root.mkdir(parents=True, exist_ok=False)

    config = json.loads(json.dumps(source_session.get("config") or {}))
    config.setdefault("name", "Simulated BO sweep session")
    config.setdefault("records", {})["simulated_session"] = True
    config.setdefault("acquisition", {})
    simulation_settings = dict(simulation_settings or {})
    if simulation_settings.get("initial_random_points") is not None:
        config["n_initial_points"] = int(simulation_settings["initial_random_points"])
    for setting_key, config_key in (
        ("candidate_pool_size", "candidate_pool_size"),
        ("local_candidate_pool_size", "local_candidate_pool_size"),
        ("noise", "gp_noise_level"),
        ("use_gp", "use_gp"),
        ("gp_optimizer_restarts", "gp_optimizer_restarts"),
    ):
        if simulation_settings.get(setting_key) is not None:
            config["acquisition"][config_key] = simulation_settings[setting_key]
    if simulation_settings.get("falloff_fractions"):
        config["acquisition"]["gp_falloff_fractions"] = dict(
            simulation_settings["falloff_fractions"]
        )
        config["acquisition"]["gp_length_scales"] = dict(
            simulation_settings["falloff_fractions"]
        )
    channel_groups = []
    observations = []
    history_rows = []
    x_name, y_name, z_name = axes
    for run_index, run in enumerate(nonempty_runs, start=1):
        group_id = run_index
        channel = _simulation_saved_channel_identity(run, run_index)
        channel_values = _simulation_channel_list_value(channel)
        channel_column = _simulation_history_channel_column(channel)
        run_label = str(run.get("label") or f"Simulation {run_index}")
        exploration = run.get("exploration")
        replicate = run.get("replicate")
        seed = run.get("seed")
        run_settings = dict(simulation_settings)
        if run.get("initial_random_points") is not None:
            run_settings["initial_random_points"] = int(
                run["initial_random_points"]
            )
        if run.get("falloff_fractions"):
            run_settings["falloff_fractions"] = dict(run["falloff_fractions"])
        ground_truth_channel = run.get("ground_truth_channel")
        if ground_truth_channel is not None:
            run_settings["ground_truth_channel"] = str(ground_truth_channel)
        first_params = _simulation_first_history_params(
            run["history"],
            config,
            axes,
        )
        group_metadata = _simulation_channel_group_metadata(
            group_id=group_id,
            name=run_label,
            channels=channel_values,
            first_params=first_params,
            settings=run_settings,
            exploration=exploration,
            replicate=replicate,
            seed=seed,
        )
        channel_groups.append(group_metadata)
        for _row_index, row in run["history"].sort_values("iteration").iterrows():
            params = _simulation_history_row_params(row, config, axes)
            iteration = int(row["iteration"])
            q_run = float(row["observed_value"])
            measurement_metadata = (
                row.get("measurement_metadata")
                if isinstance(row.get("measurement_metadata"), dict)
                else {}
            )
            quality = {
                "Q_run": q_run,
                "simulation_metric": value_label,
                "simulation_run_label": run_label,
                "simulation_exploration": (
                    float(exploration)
                    if exploration is not None and np.isfinite(float(exploration))
                    else None
                ),
                "simulation_replicate": replicate,
                "simulation_seed": seed,
                "ground_truth_channel": (
                    str(ground_truth_channel)
                    if ground_truth_channel is not None
                    else None
                ),
                "selection_mode": row.get("selection_mode"),
                "channel_components": {
                    str(channel): {
                        "Q_channel": q_run,
                        "classic_Q": q_run,
                        "snr_score": q_run,
                        "normalized_SNR": q_run,
                    }
                },
            }
            for source_column, target_key in (
                ("predicted_mean", "predicted_mean_Q"),
                ("predicted_std", "predicted_std_Q"),
                ("acquisition_value", "acquisition_value"),
            ):
                if source_column in row and pd.notna(row[source_column]):
                    quality[target_key] = float(row[source_column])
            observation = {
                "iteration": iteration,
                "method_id": (
                    f"simulated_group_{group_id:02d}_iter_{iteration:03d}"
                ),
                "params": params,
                "created_at": timestamp,
                "completed_at": timestamp,
                "status": "completed",
                "group_id": group_id,
                "group_name": run_label,
                "channels": channel_values,
                "objective": "simulation",
                "Q_run": q_run,
                "quality": quality,
                "channel_metrics": {
                    str(channel): {
                        "Q_channel": q_run,
                        "classic_Q": q_run,
                        "snr": max(0.0, q_run),
                        "snr_unadjusted": max(0.0, q_run),
                        "success_score": q_run,
                        "mean_peak_current_uA": q_run,
                        "peak_shape_score": q_run,
                        "baseline_stability_score": q_run,
                        "replicate_consistency_score": q_run,
                    }
                },
                "simulation_truth": {
                    "ground_truth_metric": value_label,
                    "ground_truth_value": q_run,
                    "tensor_value": (
                        float(row["tensor_value"])
                        if "tensor_value" in row and pd.notna(row["tensor_value"])
                        else q_run
                    ),
                    "run_label": run_label,
                    "ground_truth_channel": (
                        str(ground_truth_channel)
                        if ground_truth_channel is not None
                        else None
                    ),
                    "exploration": exploration,
                    "replicate": replicate,
                    "seed": seed,
                    **_simulation_serializable_trace_metadata(measurement_metadata),
                },
            }
            transient_trace_measurements = measurement_metadata.get(
                "channel_measurements",
                {},
            )
            if transient_trace_measurements:
                observation["simulation_trace_measurements"] = transient_trace_measurements
            observation["analysis_record"] = _write_simulated_trace_record(
                session_root,
                observation,
                channel=channel_values[0],
            )
            observation.pop("simulation_trace_measurements", None)
            observations.append(observation)
            history_row = {
                "iteration": iteration,
                "group_id": group_id,
                "group_name": run_label,
                "channels": str(channel),
                "Q_run": q_run,
                "objective": "simulation",
                "completed_at": timestamp,
                "selection_mode": row.get("selection_mode"),
                "exploration": exploration,
                "replicate": replicate,
                "seed": seed,
                "initial_random_points": run_settings.get("initial_random_points"),
                "gp_falloff_parameter": run.get("gp_falloff_parameter"),
                "gp_falloff_value": run.get("gp_falloff_value"),
                "run_label": run_label,
                "ground_truth_channel": (
                    str(ground_truth_channel)
                    if ground_truth_channel is not None
                    else None
                ),
                "best_so_far": float(row.get("best_so_far", q_run)),
                channel_column: q_run,
            }
            for source_column, target_column in (
                ("predicted_mean", "predicted_mean_Q"),
                ("predicted_std", "predicted_std_Q"),
                ("acquisition_value", "acquisition_value"),
            ):
                history_row[target_column] = row.get(source_column)
            if "tensor_value" in row and pd.notna(row["tensor_value"]):
                history_row["tensor_value"] = float(row["tensor_value"])
            history_row.update(params)
            history_rows.append(history_row)

    config["channel_groups"] = channel_groups
    config["channels"] = sorted(
        {channel for group in channel_groups for channel in group["channels"]},
        key=lambda value: _channel_sort_key(str(value)),
    )
    if channel_groups:
        config["initial_parameters"] = dict(channel_groups[0]["initial_parameters"])
    best_observation = max(
        observations,
        key=lambda observation: float(observation.get("Q_run", 0.0)),
    )
    ground_truth_optimum = _simulation_optimum_reference_from_frame(ground_truth)
    state = {
        "session_id": f"simulated_{timestamp}_sweep",
        "record_dir": str(session_root),
        "analysis_output_dir": str(session_root / "analysis"),
        "candidate_count": int(
            len(candidate_pool)
            if candidate_pool is not None and not candidate_pool.empty
            else len(ground_truth)
        ),
        "active_parameters": list(axes),
        "channel_groups": channel_groups,
        "pending": None,
        "pending_batch": [],
        "suggestions": [],
        "observations": observations,
        "best_observation": best_observation,
        "simulation_metadata": {
            "source_session": str(source_session.get("root")),
            "value_label": value_label,
            "axes": list(axes),
            "ground_truth_optimum": ground_truth_optimum,
            "run_count": len(nonempty_runs),
            "settings": simulation_settings,
            "ground_truth_rows": int(len(ground_truth)),
            "candidate_pool_rows": int(
                len(candidate_pool)
                if candidate_pool is not None and not candidate_pool.empty
                else len(ground_truth)
            ),
        },
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
    }
    with (session_root / "bo_state.json").open("w", encoding="utf-8") as handle:
        json.dump(state, handle, indent=2)
    with (session_root / "bo_config_snapshot.json").open("w", encoding="utf-8") as handle:
        json.dump(config, handle, indent=2)
    pd.DataFrame(history_rows).to_csv(session_root / "history.csv", index=False)
    ground_truth.to_csv(session_root / "simulation_ground_truth_tensor.csv", index=False)
    if source_points is not None and not source_points.empty:
        source_points.to_csv(session_root / "simulation_source_observations.csv", index=False)
    for group_id, run in enumerate(nonempty_runs, start=1):
        run_ground_truth = run.get("ground_truth")
        if run_ground_truth is None or run_ground_truth.empty:
            run_ground_truth = ground_truth
        run_channel = run.get("ground_truth_channel")
        run_candidate_pool = candidate_pool
        if (
            run_channel is not None
            and run_candidate_pool is not None
            and not run_candidate_pool.empty
            and "ground_truth_channel" in run_candidate_pool.columns
        ):
            run_candidate_pool = run_candidate_pool[
                run_candidate_pool["ground_truth_channel"].astype(str)
                == str(run_channel)
            ].copy()
        _write_simulated_surrogate_artifacts(
            session_root,
            run_ground_truth,
            run["history"],
            axes=axes,
            group_id=group_id,
            candidate_pool=run_candidate_pool,
        )
    return session_root


def _simulation_run_summary_frame(runs: list[dict]) -> pd.DataFrame:
    rows = []
    for run in runs:
        history = run.get("history")
        if history is None or history.empty:
            continue
        best_row = history.loc[history["observed_value"].idxmax()]
        final_best = float(history["best_so_far"].iloc[-1])
        threshold = 0.95 * final_best
        reached = history[history["best_so_far"] >= threshold]
        rows.append({
            "run_label": str(run.get("label") or "Simulation"),
            "ground_truth_channel": run.get("ground_truth_channel"),
            "exploration": run.get("exploration"),
            "initial_random_points": run.get("initial_random_points"),
            "gp_falloff_parameter": run.get("gp_falloff_parameter"),
            "gp_falloff_value": run.get("gp_falloff_value"),
            "repeat_index": run.get("repeat_index"),
            "repeat_count": run.get("repeat_count"),
            "replicate": run.get("replicate"),
            "seed": run.get("seed"),
            "best_fitness": float(best_row["observed_value"]),
            "best_iteration": int(best_row["iteration"]),
            "final_best": final_best,
            "iteration_to_95_percent_final": (
                int(reached["iteration"].iloc[0])
                if not reached.empty else np.nan
            ),
        })
    return pd.DataFrame(rows)


def _write_compact_simulated_sweep_session(
    output_parent: Path,
    source_session: dict,
    runs: list[dict],
    *,
    value_label: str,
    axes: tuple[str, str, str],
    simulation_settings: dict | None = None,
) -> Path:
    nonempty_runs = [
        run for run in runs
        if run.get("history") is not None and not run["history"].empty
    ]
    if not nonempty_runs:
        raise ValueError("Cannot write an empty simulation sweep.")
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    output_parent.mkdir(parents=True, exist_ok=True)
    session_root = output_parent / f"bo_session_simulated_{timestamp}_compact_sweep"
    suffix = 2
    while session_root.exists():
        session_root = output_parent / (
            f"bo_session_simulated_{timestamp}_compact_sweep_{suffix}"
        )
        suffix += 1
    session_root.mkdir(parents=True, exist_ok=False)

    config = json.loads(json.dumps(source_session.get("config") or {}))
    config.setdefault("name", "Compact simulated BO sweep")
    config.setdefault("records", {})["simulated_session"] = True
    config.setdefault("records", {})["compact_simulation_export"] = True
    config.setdefault("acquisition", {})
    simulation_settings = dict(simulation_settings or {})
    for setting_key, config_key in (
        ("candidate_pool_size", "candidate_pool_size"),
        ("local_candidate_pool_size", "local_candidate_pool_size"),
        ("noise", "gp_noise_level"),
        ("use_gp", "use_gp"),
        ("gp_optimizer_restarts", "gp_optimizer_restarts"),
    ):
        if simulation_settings.get(setting_key) is not None:
            config["acquisition"][config_key] = simulation_settings[setting_key]

    history_rows = []
    channel_groups = []
    x_name, y_name, z_name = axes
    for run_index, run in enumerate(nonempty_runs, start=1):
        group_id = run_index
        channel = _simulation_saved_channel_identity(run, run_index)
        channel_values = _simulation_channel_list_value(channel)
        channel_column = _simulation_history_channel_column(channel)
        run_label = str(run.get("label") or f"Simulation {run_index}")
        exploration = run.get("exploration")
        run_settings = dict(simulation_settings)
        if run.get("initial_random_points") is not None:
            run_settings["initial_random_points"] = int(run["initial_random_points"])
        if run.get("falloff_fractions"):
            run_settings["falloff_fractions"] = dict(run["falloff_fractions"])
        first_params = _simulation_first_history_params(
            run["history"],
            config,
            axes,
        )
        channel_groups.append(_simulation_channel_group_metadata(
            group_id=group_id,
            name=run_label,
            channels=channel_values,
            first_params=first_params,
            settings=run_settings,
            exploration=exploration,
            replicate=run.get("replicate"),
            seed=run.get("seed"),
        ))
        for _row_index, row in run["history"].sort_values("iteration").iterrows():
            params = _simulation_history_row_params(row, config, axes)
            q_run = float(row["observed_value"])
            history_row = {
                "iteration": int(row["iteration"]),
                "group_id": group_id,
                "group_name": run_label,
                "channels": str(channel),
                "Q_run": q_run,
                channel_column: q_run,
                "objective": "compact_simulation",
                "completed_at": timestamp,
                "selection_mode": row.get("selection_mode"),
                "exploration": exploration,
                "initial_random_points": run_settings.get("initial_random_points"),
                "gp_falloff_parameter": run.get("gp_falloff_parameter"),
                "gp_falloff_value": run.get("gp_falloff_value"),
                "repeat_index": run.get("repeat_index"),
                "repeat_count": run.get("repeat_count"),
                "replicate": run.get("replicate"),
                "seed": run.get("seed"),
                "run_label": run_label,
                "ground_truth_channel": run.get("ground_truth_channel"),
                "best_so_far": float(row.get("best_so_far", q_run)),
                "predicted_mean_Q": row.get("predicted_mean"),
                "predicted_std_Q": row.get("predicted_std"),
                "acquisition_value": row.get("acquisition_value"),
                "tensor_value": row.get("tensor_value"),
            }
            history_row.update(params)
            history_rows.append(history_row)

    config["channel_groups"] = channel_groups
    config["channels"] = sorted(
        {channel for group in channel_groups for channel in group["channels"]},
        key=lambda value: _channel_sort_key(str(value)),
    )
    if channel_groups:
        config["initial_parameters"] = dict(channel_groups[0]["initial_parameters"])
    summary = _simulation_run_summary_frame(nonempty_runs)
    history_frame = pd.DataFrame(history_rows)
    state = {
        "session_id": f"simulated_{timestamp}_compact_sweep",
        "record_dir": str(session_root),
        "analysis_output_dir": str(session_root / "analysis"),
        "candidate_count": None,
        "active_parameters": list(axes),
        "channel_groups": channel_groups,
        "pending": None,
        "pending_batch": [],
        "suggestions": [],
        "observations": [],
        "best_observation": {},
        "simulation_metadata": {
            "source_session": str(source_session.get("root")),
            "value_label": value_label,
            "axes": list(axes),
            "run_count": len(nonempty_runs),
            "settings": simulation_settings,
            "compact_export": True,
            "omitted_files": [
                "raw_swv",
                "analysis records",
                "surrogate artifacts",
                "ground-truth tensor CSV",
                "source observation CSV",
            ],
        },
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
    }
    with (session_root / "bo_state.json").open("w", encoding="utf-8") as handle:
        json.dump(state, handle, indent=2)
    with (session_root / "bo_config_snapshot.json").open("w", encoding="utf-8") as handle:
        json.dump(config, handle, indent=2)
    history_frame.to_csv(session_root / "history.csv", index=False)
    summary.to_csv(session_root / "simulation_run_summary.csv", index=False)
    return session_root


def _simulated_bo_sessions_parent(session_root: Path, search_root: Path) -> Path:
    """Return the experiment-level bo_sessions folder for simulated exports."""
    session_root = Path(session_root).resolve()
    search_root = Path(search_root).resolve()
    if session_root.parent.name == "bo_sessions":
        return session_root.parent
    if search_root.name == "bo_sessions":
        return search_root
    search_bo_sessions = search_root / "bo_sessions"
    if search_bo_sessions.exists() or not (search_root / "bo_state.json").is_file():
        return search_bo_sessions
    return session_root.parent / "bo_sessions"


def _session_parameter_context(observations: list[dict]) -> str:
    labels = {
        "begin_potential": "begin",
        "end_potential": "end",
        "step_potential": "step",
        "amplitude": "amp",
        "frequency": "freq",
        "conditioning_potential": "cond E",
        "conditioning_time": "cond t",
    }
    units = {
        "begin_potential": "V",
        "end_potential": "V",
        "step_potential": "V",
        "amplitude": "V",
        "frequency": "Hz",
        "conditioning_potential": "V",
        "conditioning_time": "s",
    }
    parts = []
    for parameter in PARAMETERS:
        values = sorted({
            float((observation.get("params") or {})[parameter])
            for observation in observations
            if (observation.get("params") or {}).get(parameter) is not None
        })
        if not values:
            continue
        value_text = (
            f"{values[0]:g}"
            if len(values) == 1
            else f"{values[0]:g}–{values[-1]:g}"
        )
        parts.append(f"{labels[parameter]}={value_text} {units[parameter]}")
    return " | ".join(parts)


def _pdf_metric_landscapes(
    pdf: PdfPages,
    points: pd.DataFrame,
    metric: str,
    phase: str,
    dimensions: list[str],
    q_equation: str | None = None,
) -> None:
    metric_varies = (
        not points.empty
        and any(
            _has_numeric_variation(group["value"])
            for _channel, group in points.groupby("channel")
        )
    )
    if not metric_varies or not dimensions:
        return
    # One page of measured 1D projections.
    columns = 2
    rows = (len(dimensions) + 1) // 2
    fig, axes = plt.subplots(rows, columns, figsize=(8.5, max(4, 3.2 * rows)), squeeze=False)
    for ax, parameter in zip(axes.flat, dimensions):
        for channel, group in points.groupby("channel"):
            ordered = group.sort_values(parameter)
            ax.plot(ordered[parameter], ordered["value"], marker="o", label=str(channel))
        ax.set(xlabel=parameter, ylabel=metric, title=f"{metric} vs {parameter}")
        ax.grid(alpha=.25)
    for ax in axes.flat[len(dimensions):]:
        ax.axis("off")
    if points["channel"].nunique() <= 8:
        axes.flat[0].legend(fontsize=7, title="Channel")
    if q_equation:
        _pdf_equation_footer(fig, "Classic Q equation", q_equation)
    _pdf_save(pdf, fig, f"Measured {phase} data — 1D projections")

    # Every available 2D parameter map, grouped four per page.
    pairs = list(itertools.combinations(dimensions, 2))
    for start in range(0, len(pairs), 4):
        page_pairs = pairs[start:start + 4]
        fig, axes = plt.subplots(2, 2, figsize=(8.5, 8), squeeze=False)
        for ax, (x_name, y_name) in zip(axes.flat, page_pairs):
            valid, grid = _interpolated_2d_grid(points, x_name, y_name)
            if grid is not None:
                grid_x, grid_y, grid_values = grid
                scatter = ax.contourf(
                    grid_x, grid_y, grid_values,
                    levels=14, cmap="viridis",
                )
                ax.scatter(
                    valid[x_name], valid[y_name],
                    facecolors="none", edgecolors="white",
                    linewidths=.65, s=20,
                )
            else:
                scatter = ax.scatter(
                    valid[x_name], valid[y_name], c=valid["value"],
                    cmap="viridis", s=28,
                )
            ax.set(xlabel=x_name, ylabel=y_name, title=f"{metric}")
            fig.colorbar(scatter, ax=ax, shrink=.75)
        for ax in axes.flat[len(page_pairs):]:
            ax.axis("off")
        if q_equation:
            _pdf_equation_footer(fig, "Classic Q equation", q_equation)
        _pdf_save(pdf, fig, f"Measured {phase} data — 2D maps")

    # Every available 3D parameter tensor.
    for x_name, y_name, z_name in itertools.combinations(dimensions, 3):
        fig = plt.figure(figsize=(8, 6))
        ax = fig.add_subplot(111, projection="3d")
        scatter = ax.scatter(
            points[x_name], points[y_name], points[z_name],
            c=points["value"], cmap="viridis", s=22,
        )
        ax.set(xlabel=x_name, ylabel=y_name, zlabel=z_name)
        fig.colorbar(scatter, ax=ax, label=metric, shrink=.7)
        if q_equation:
            _pdf_equation_footer(fig, "Classic Q equation", q_equation)
        _pdf_save(
            pdf, fig,
            f"Measured {phase} {metric} — 3D tensor",
        )


def _pdf_chronological_section(
    pdf: PdfPages,
    observations: list[dict],
    config: dict,
    channels: list[str],
    classic_equation: str,
) -> None:
    for metric in _q_relevant_metrics(
        PAIRED_TREND_METRICS, config, paired_objective=True,
    ):
        chronological, transitions = _chronological_points(
            observations, config, metric, channels, average_channels=False,
        )
        if chronological.empty or not _has_numeric_variation(chronological["value"]):
            continue

        summary_fig, (average_ax, overlay_ax) = plt.subplots(1, 2, figsize=(10, 4))
        averaged = (
            chronological.groupby(["position", "phase"], as_index=False)["value"]
            .mean()
            .sort_values("position")
        )
        average_ax.plot(averaged["position"], averaged["value"], color="#777777", alpha=.35)
        for phase, color in (("buffer", "#1f77b4"), ("target", "#ff7f0e")):
            phase_rows = averaged[averaged["phase"] == phase]
            average_ax.scatter(
                phase_rows["position"], phase_rows["value"],
                color=color, s=22, label=phase.title(),
            )
        for channel in channels:
            group = chronological[chronological["channel"] == channel]
            overlay_ax.plot(group["position"], group["value"], color="#777777", alpha=.20)
            for phase, color in (("buffer", "#1f77b4"), ("target", "#ff7f0e")):
                phase_rows = group[group["phase"] == phase]
                overlay_ax.scatter(
                    phase_rows["position"], phase_rows["value"],
                    color=color, s=16,
                )
        for x_value, _label in transitions:
            for ax in (average_ax, overlay_ax):
                ax.axvline(x_value, linestyle="--", color="#5a6b84", linewidth=1)
        average_ax.set_title("Mean across channels")
        overlay_ax.set_title("Channels overlaid")
        average_ax.legend(fontsize=7)
        for ax in (average_ax, overlay_ax):
            ax.set(xlabel="Chronological measurement order", ylabel=metric)
            ax.grid(alpha=.2)
        if metric == "Classic Q":
            _pdf_equation_footer(summary_fig, "Classic Q equation", classic_equation)
        _pdf_save(pdf, summary_fig, f"Chronological {metric} — summary")

        rows = max(1, (len(channels) + 1) // 2)
        individual_fig, individual_axes = plt.subplots(
            rows, 2, figsize=(8.5, max(4, 3 * rows)), squeeze=False,
        )
        for ax, channel in zip(individual_axes.flat, channels):
            group = chronological[
                chronological["channel"] == channel
            ].sort_values("position")
            ax.plot(group["position"], group["value"], color="#777777", alpha=.3)
            for phase, color in (("buffer", "#1f77b4"), ("target", "#ff7f0e")):
                phase_rows = group[group["phase"] == phase]
                ax.scatter(
                    phase_rows["position"], phase_rows["value"],
                    color=color, s=18, label=phase.title(),
                )
            for x_value, _label in transitions:
                ax.axvline(x_value, linestyle="--", color="#5a6b84", linewidth=1)
            ax.set(
                xlabel="Chronological order", ylabel=metric,
                title=f"Channel {channel}",
            )
            ax.grid(alpha=.2)
        for ax in individual_axes.flat[len(channels):]:
            ax.axis("off")
        if channels:
            individual_axes.flat[0].legend(fontsize=7)
        if metric == "Classic Q":
            _pdf_equation_footer(
                individual_fig, "Classic Q equation", classic_equation,
            )
        _pdf_save(
            pdf, individual_fig,
            f"Chronological {metric} — individual channels",
        )


def _pdf_surrogate_iteration(
    pdf: PdfPages,
    artifact_iteration: int,
    path: Path,
    objective_equation_label: str,
    objective_equation: str,
    observations: list[dict],
) -> None:
    predictions = pd.read_csv(path)
    current_observation = next(
        (
            observation for observation in observations
            if int(observation.get("iteration", 0)) == artifact_iteration
        ),
        None,
    )
    parameter_text = _iteration_parameter_text(current_observation)
    surrogate_session = {
        "observations": observations,
        "state": {},
        "config": {},
    }
    tested = [
        observation for observation in observations
        if int(observation.get("iteration", 0)) <= artifact_iteration
    ]
    dimensions = [
        name for name in PARAMETERS
        if name in predictions.columns and predictions[name].nunique(dropna=True) > 1
    ]
    for value_key in SURROGATE_VALUES:
        if (
            value_key not in predictions.columns
            or not _has_numeric_variation(predictions[value_key])
        ):
            continue
        fig, axes = plt.subplots(
            max(1, (len(dimensions) + 1) // 2), 2,
            figsize=(8.5, max(4, 3 * ((len(dimensions) + 1) // 2))),
            squeeze=False,
        )
        for ax, parameter in zip(axes.flat, dimensions):
            ax.scatter(predictions[parameter], predictions[value_key], s=7, alpha=.3)
            grouped = predictions.groupby(parameter)[value_key].median()
            ax.plot(grouped.index, grouped.values, color="#d67b32")
            tested_for_axis = [
                observation for observation in tested
                if (observation.get("params") or {}).get(parameter) is not None
            ]
            if tested_for_axis:
                ax.plot(
                    [observation["params"][parameter] for observation in tested_for_axis],
                    [observation.get("Q_run", np.nan) for observation in tested_for_axis],
                    color="#d67b32",
                    marker="o",
                    linewidth=1.2,
                    label="tested parameter sets",
                )
            ax.set(xlabel=parameter, ylabel=value_key)
            ax.grid(alpha=.2)
        for ax in axes.flat[len(dimensions):]:
            ax.axis("off")
        _pdf_equation_footer(fig, objective_equation_label, objective_equation)
        _pdf_save(
            pdf, fig,
            f"Surrogate iteration {artifact_iteration} — {value_key}\n{parameter_text}",
        )
        pairs = list(itertools.combinations(dimensions, 2))
        for start in range(0, len(pairs), 4):
            page_pairs = pairs[start:start + 4]
            map_fig, map_axes = plt.subplots(2, 2, figsize=(8.5, 8), squeeze=False)
            for ax, (x_name, y_name) in zip(map_axes.flat, page_pairs):
                selected_next = next(
                    (
                        observation for observation in observations
                        if int(observation.get("iteration", 0)) == int(artifact_iteration) + 1
                    ),
                    None,
                )
                selected_next_frame = pd.DataFrame(
                    [selected_next["params"]]
                    if selected_next is not None and selected_next.get("params")
                    else []
                )
                scatter = _plot_surrogate_2d_control_style(
                    ax,
                    surrogate_session,
                    predictions,
                    artifact_iteration,
                    value_key,
                    x_name,
                    y_name,
                    selected_next_frame,
                    dot_size=5,
                    show_iteration_path=True,
                )
                if scatter is not None:
                    colorbar = map_fig.colorbar(scatter, ax=ax, shrink=.75)
                    colorbar.ax.tick_params(labelsize=7)
            for ax in map_axes.flat[len(page_pairs):]:
                ax.axis("off")
            _pdf_equation_footer(
                map_fig, objective_equation_label, objective_equation,
            )
            _pdf_save(
                pdf,
                map_fig,
                f"Surrogate iteration {artifact_iteration} — {value_key} — 2D maps\n"
                f"{parameter_text}",
            )
        for x_name, y_name, z_name in itertools.combinations(dimensions, 3):
            tensor_fig = plt.figure(figsize=(8, 6))
            tensor_ax = tensor_fig.add_subplot(111, projection="3d")
            tensor_scatter = tensor_ax.scatter(
                predictions[x_name],
                predictions[y_name],
                predictions[z_name],
                c=predictions[value_key],
                cmap="viridis",
                s=7,
                alpha=.4,
            )
            tensor_ax.set(xlabel=x_name, ylabel=y_name, zlabel=z_name)
            tested_for_axes = [
                observation for observation in tested
                if all(
                    (observation.get("params") or {}).get(axis) is not None
                    for axis in (x_name, y_name, z_name)
                )
            ]
            if tested_for_axes:
                tensor_ax.plot(
                    [observation["params"][x_name] for observation in tested_for_axes],
                    [observation["params"][y_name] for observation in tested_for_axes],
                    [observation["params"][z_name] for observation in tested_for_axes],
                    color="#d67b32",
                    marker="o",
                    linewidth=1.3,
                    markersize=4,
                )
            tensor_fig.colorbar(
                tensor_scatter,
                ax=tensor_ax,
                label=value_key,
                shrink=.7,
            )
            _pdf_equation_footer(
                tensor_fig, objective_equation_label, objective_equation,
            )
            _pdf_save(
                pdf,
                tensor_fig,
                f"Surrogate iteration {artifact_iteration} — {value_key} — 3D tensor\n"
                f"{parameter_text}",
            )


def _pdf_metadata_lines(
    session: dict,
    observations: list[dict],
    paired: bool,
    best: dict,
    surrogate_iteration_mode: str = "final",
    swv_iteration_mode: str = "milestones",
) -> list[str]:
    def bounded_json_lines(
        value,
        max_lines: int = 120,
        max_line_chars: int = 180,
    ) -> list[str]:
        raw_lines = json.dumps(value, indent=2, default=str).splitlines()
        clipped = [
            line[:max_line_chars] + (" ..." if len(line) > max_line_chars else "")
            for line in raw_lines[:max_lines]
        ]
        if len(raw_lines) > max_lines:
            clipped.append(
                f"... truncated {len(raw_lines) - max_lines} additional metadata lines"
            )
        return clipped

    state = session.get("state") or {}
    config = session.get("config") or {}
    groups = _session_channel_groups(session)
    lines = [
        f"Session: {state.get('session_id', session['root'].name)}",
        f"Root: {session['root']}",
        f"Objective: {'Paired response' if paired else 'Standard quality'}",
        f"Completed observations: {len(observations)}",
        f"Candidate count: {state.get('candidate_count', 'unknown')}",
        (
            f"Best observation: {best.get('group_name', f'Group {best.get('group_id', 1)}')} "
            f"iteration {best.get('iteration')}"
        ),
        f"Best Q_run: {float(best.get('Q_run', 0)):.6g}",
        f"BO parameter context: {_session_parameter_context(observations) or 'none'}",
        "",
        "Report order:",
        "  1. Metadata",
        "  2. History and scores metrics",
        "  3. Real data landscapes: 3D tensors",
        (
            "  4. Surrogate landscapes: 3D tensors and 2D maps "
            f"({'every artifact' if surrogate_iteration_mode == 'all' else 'final artifact per group'})"
        ),
        (
            "  5. Per-iteration SWV traces "
            f"({'every iteration' if swv_iteration_mode == 'all' else 'first/middle/final per group'})"
        ),
        "",
        "Channel groups:",
    ]
    if groups:
        for group in groups:
            channels = ", ".join(str(channel) for channel in group.get("channels", [])) or "unknown"
            lines.append(f"  Group {group['id']}: {group['name']} | channels: {channels}")
    else:
        lines.append("  none")
    lines.extend([
        "",
        "State:",
        *bounded_json_lines(state),
        "",
        "Config:",
        *bounded_json_lines(config),
    ])
    return lines


def _history_metric_specs(
    history: pd.DataFrame,
) -> list[tuple[str, str, dict[str, str] | None]]:
    channel_metrics = _channel_metric_columns(history)
    channel_column_names = {
        column for columns in channel_metrics.values() for column in columns.values()
    }
    global_metrics = [
        column for column in _numeric_columns(history)
        if column not in channel_column_names
    ]
    specs = [("global", metric, None) for metric in global_metrics]
    specs.extend(
        ("channel", metric, columns)
        for metric, columns in sorted(channel_metrics.items())
    )
    return specs


def _pdf_history_metric_page(
    pdf: PdfPages,
    history: pd.DataFrame,
    metric_kind: str,
    metric: str,
    channel_columns: dict[str, str] | None = None,
) -> None:
    if history.empty:
        return
    iterations = pd.to_numeric(
        history.get("iteration", pd.Series(range(1, len(history) + 1), index=history.index)),
        errors="coerce",
    )
    group_ids = (
        pd.to_numeric(history["group_id"], errors="coerce").fillna(1).astype(int)
        if "group_id" in history.columns
        else pd.Series(1, index=history.index)
    )
    group_names = (
        history["group_name"].fillna("").astype(str)
        if "group_name" in history.columns
        else pd.Series("", index=history.index)
    )
    rows = []
    if metric_kind == "channel" and channel_columns:
        for channel, column in channel_columns.items():
            values = pd.to_numeric(history[column], errors="coerce")
            valid = iterations.notna() & values.notna()
            for index in history.index[valid]:
                rows.append({
                    "iteration": int(iterations.loc[index]),
                    "value": float(values.loc[index]),
                    "group_id": int(group_ids.loc[index]),
                    "group_name": group_names.loc[index] or f"Group {int(group_ids.loc[index])}",
                    "channel": str(channel),
                })
    else:
        if metric not in history.columns:
            return
        values = pd.to_numeric(history[metric], errors="coerce")
        valid = iterations.notna() & values.notna()
        for index in history.index[valid]:
            rows.append({
                "iteration": int(iterations.loc[index]),
                "value": float(values.loc[index]),
                "group_id": int(group_ids.loc[index]),
                "group_name": group_names.loc[index] or f"Group {int(group_ids.loc[index])}",
                "channel": "run",
            })
    data = pd.DataFrame(rows)
    if data.empty or not _has_numeric_variation(data["value"]):
        return
    data = (
        data.groupby(["group_id", "group_name", "channel", "iteration"], as_index=False)["value"]
        .mean()
        .sort_values(["group_id", "channel", "iteration"])
    )
    groups = list(data.groupby(["group_id", "group_name"], sort=True))
    bottom_count = max(1, len(groups))
    fig = plt.figure(figsize=(8.5, max(7.5, 3.2 + 2.45 * bottom_count)))
    grid = fig.add_gridspec(bottom_count + 1, 1, height_ratios=[1.25] + [1] * bottom_count)
    overlay_ax = fig.add_subplot(grid[0, 0])
    label = _metric_label(metric)

    for (group_id, group_name, channel), series in data.groupby(["group_id", "group_name", "channel"], sort=True):
        series = series.sort_values("iteration")
        series_label = str(group_name)
        if metric_kind == "channel":
            series_label = f"{series_label} · Ch {channel}"
        overlay_ax.plot(series["iteration"], series["value"], marker="o", linewidth=1.0, label=series_label)
    overlay_ax.set(title=f"{label} — groups overlaid", xlabel="Iteration", ylabel=label)
    overlay_ax.grid(alpha=.25)
    if data[["group_id", "channel"]].drop_duplicates().shape[0] <= 14:
        overlay_ax.legend(fontsize=6, ncol=2)

    for axis_index, ((_group_id, group_name), group) in enumerate(groups):
        ax = fig.add_subplot(grid[axis_index + 1, 0])
        for channel, series in group.groupby("channel", sort=True):
            series = series.sort_values("iteration")
            line_label = f"Ch {channel}" if metric_kind == "channel" else str(group_name)
            ax.plot(series["iteration"], series["value"], marker="o", linewidth=1.0, label=line_label)
        ax.set(title=f"{label} — {group_name}", xlabel="Iteration", ylabel=label)
        ax.grid(alpha=.25)
        if metric_kind == "channel" and group["channel"].nunique() <= 12:
            ax.legend(fontsize=6, ncol=3)
    _pdf_save(pdf, fig, f"History and scores — {label}")


def _pdf_real_data_3d_tensors(
    pdf: PdfPages,
    observations: list[dict],
    config: dict,
    paired: bool,
    channels: list[str],
    status_callback=None,
) -> None:
    del config
    phases = ("buffer", "target") if paired else ("measurement",)
    for phase in phases:
        for metric in REAL_DATA_METRICS:
            points = _real_metric_points(
                observations,
                metric,
                phase,
                channels,
                average_channels=False,
            )
            if points.empty or not _has_numeric_variation(points["value"]):
                continue
            dimensions = [
                name for name in PARAMETERS
                if name in points.columns and points[name].nunique(dropna=True) > 1
            ]
            for x_name, y_name, z_name in itertools.combinations(dimensions, 3):
                if status_callback is not None:
                    status_callback(
                        f"Rendering real data 3D tensor: {phase} {metric} "
                        f"({x_name}, {y_name}, {z_name})..."
                    )
                valid = points[[x_name, y_name, z_name, "value", "channel", "group_name"]].copy()
                valid[[x_name, y_name, z_name, "value"]] = valid[[x_name, y_name, z_name, "value"]].apply(
                    pd.to_numeric,
                    errors="coerce",
                )
                valid = valid.dropna(subset=[x_name, y_name, z_name, "value"])
                if valid.empty:
                    continue
                fig = plt.figure(figsize=(8, 6))
                ax = fig.add_subplot(111, projection="3d")
                scatter = ax.scatter(
                    valid[x_name],
                    valid[y_name],
                    valid[z_name],
                    c=valid["value"],
                    cmap="viridis",
                    s=22,
                    alpha=.75,
                )
                ax.set(xlabel=x_name, ylabel=y_name, zlabel=z_name)
                fig.colorbar(scatter, ax=ax, label=metric, shrink=.7)
                _pdf_save(
                    pdf,
                    fig,
                    f"Real data landscape — {phase} — {metric} — 3D tensor",
                )


def _pdf_surrogate_tensor_maps(
    pdf: PdfPages,
    surrogate_session: dict,
    artifact_iteration: int,
    path: Path,
    objective_equation_label: str,
    objective_equation: str,
    status_callback=None,
) -> None:
    if status_callback is not None:
        status_callback(f"Reading surrogate artifact for iteration {artifact_iteration}...")
    predictions = pd.read_csv(path)
    dimensions = [
        name for name in PARAMETERS
        if name in predictions.columns and predictions[name].nunique(dropna=True) > 1
    ]
    parameter_text = _iteration_parameter_text(next(
        (
            observation for observation in surrogate_session["observations"]
            if int(observation.get("iteration", 0)) == int(artifact_iteration)
        ),
        None,
    ))
    for value_key in SURROGATE_VALUES:
        if value_key not in predictions.columns or not _has_numeric_variation(predictions[value_key]):
            continue
        for x_name, y_name, z_name in itertools.combinations(dimensions, 3):
            if status_callback is not None:
                status_callback(
                    f"Rendering surrogate 3D tensor: iteration {artifact_iteration}, "
                    f"{value_key} ({x_name}, {y_name}, {z_name})..."
                )
            valid = predictions[[x_name, y_name, z_name, value_key]].apply(
                pd.to_numeric,
                errors="coerce",
            ).dropna()
            if valid.empty:
                continue
            fig = plt.figure(figsize=(8, 6))
            ax = fig.add_subplot(111, projection="3d")
            scatter = ax.scatter(
                valid[x_name],
                valid[y_name],
                valid[z_name],
                c=valid[value_key],
                cmap="viridis",
                s=8,
                alpha=.45,
            )
            observed = _observed_points(
                surrogate_session,
                artifact_iteration,
                [x_name, y_name, z_name],
            )
            if observed:
                ax.plot(
                    [obs["params"][x_name] for obs in observed],
                    [obs["params"][y_name] for obs in observed],
                    [obs["params"][z_name] for obs in observed],
                    color="#d67b32",
                    marker="o",
                    linewidth=1.3,
                    markersize=4,
                    label="observed path",
                )
                ax.legend(fontsize=7)
            ax.set(xlabel=x_name, ylabel=y_name, zlabel=z_name)
            fig.colorbar(
                scatter,
                ax=ax,
                label=SURROGATE_VALUE_LABELS.get(value_key, value_key),
                shrink=.7,
            )
            _pdf_equation_footer(fig, objective_equation_label, objective_equation)
            _pdf_save(
                pdf,
                fig,
                f"Surrogate iteration {artifact_iteration} — {value_key} — 3D tensor\n{parameter_text}",
            )
        pairs = list(itertools.combinations(dimensions, 2))
        for x_name, y_name in pairs:
            if status_callback is not None:
                status_callback(
                    f"Rendering surrogate 2D map: iteration {artifact_iteration}, "
                    f"{value_key} ({x_name} vs {y_name})..."
                )
            fig = _plot_surrogate(
                surrogate_session,
                predictions,
                artifact_iteration,
                value_key,
                "2D map",
                x_name,
                y_name,
                None,
                show_iteration_path=True,
            )
            _pdf_equation_footer(fig, objective_equation_label, objective_equation)
            _pdf_save(
                pdf,
                fig,
                f"Surrogate iteration {artifact_iteration} — {value_key} — 2D {x_name} vs {y_name}\n{parameter_text}",
            )


def _pdf_iteration_swv_overlays(
    pdf: PdfPages,
    session: dict,
    observations: list[dict],
    observation: dict,
    trace_analysis: dict,
    correction_label: str,
    status_callback=None,
) -> None:
    group_id = int(observation.get("group_id", 1))
    iteration = int(observation.get("iteration", 0))
    cumulative_observations = [
        previous for previous in observations
        if int(previous.get("group_id", 1)) == group_id
        and int(previous.get("iteration", 0)) <= iteration
    ]
    trace_entries = [
        (previous, trace)
        for previous in cumulative_observations
        for trace in _trace_paths(session, previous)
    ]
    trace_channels = sorted(
        {trace["channel"] for _previous, trace in trace_entries},
        key=_channel_sort_key,
    )
    if not trace_channels:
        return
    group_name = str(observation.get("group_name") or f"Group {group_id}")
    selection_label = f"{group_name} — through iteration {iteration}"
    trace_specs = [
        ("Raw", False, False, "smoothed_corrected_current", False),
        ("Offset raw", True, False, "corrected_current", True),
        ("Corrected", True, False, "smoothed_corrected_current", False),
        ("Normalized corrected", True, True, "smoothed_corrected_current", False),
        ("Normalized raw", True, True, "corrected_current", False),
    ]
    for (
        label,
        corrected,
        normalize_to_peak,
        corrected_trace_key,
        offset_to_baseline,
    ) in trace_specs:
        if status_callback is not None:
            status_callback(
                f"Rendering SWV {label.lower()} traces for {group_name}, "
                f"iteration {iteration}..."
            )
        fig, errors = _plot_iteration_trace_overlay(
            trace_entries,
            corrected,
            trace_channels,
            trace_analysis,
            correction_label,
            selection_label,
            normalize_to_peak,
            corrected_trace_key,
            offset_to_baseline,
        )
        if errors:
            fig.text(.02, .01, " | ".join(errors[:3]), fontsize=6)
        _pdf_save(pdf, fig)


def _pdf_milestone_observation_keys(
    observations_by_key: dict[tuple[int, int], dict],
) -> list[tuple[int, int]]:
    selected: set[tuple[int, int]] = set()
    by_group: dict[int, list[int]] = {}
    for group_id, iteration in observations_by_key:
        by_group.setdefault(int(group_id), []).append(int(iteration))
    for group_id, iterations in by_group.items():
        ordered = sorted(set(iterations))
        if not ordered:
            continue
        candidate_iterations = {
            ordered[0],
            ordered[len(ordered) // 2],
            ordered[-1],
        }
        selected.update((group_id, iteration) for iteration in candidate_iterations)
    return sorted(selected)


def _pdf_final_artifact_keys(
    artifact_entries: dict[tuple[int, int], tuple[dict, Path]],
) -> list[tuple[int, int]]:
    by_group: dict[int, list[int]] = {}
    for group_id, iteration in artifact_entries:
        by_group.setdefault(int(group_id), []).append(int(iteration))
    return sorted(
        (group_id, max(iterations))
        for group_id, iterations in by_group.items()
        if iterations
    )


def build_bo_session_pdf(
    session: dict,
    trace_analysis: dict,
    correction_label: str,
    progress_callback=None,
    surrogate_iteration_mode: str = "final",
    swv_iteration_mode: str = "milestones",
) -> bytes:
    """Build an exhaustive, shareable report from persisted BO artifacts."""
    observations = session["observations"]
    if progress_callback is not None:
        progress_callback(0.01, "Building history and scores table...")
    history = _observation_table(session)
    config = session["config"]
    if progress_callback is not None:
        progress_callback(0.02, "Indexing objective metadata...")
    paired = any(
        str(obs.get("objective", "")).lower() == "paired_response"
        for obs in observations
    )
    classic_equation = _classic_q_equation(config)
    objective_equation = _paired_q_equation(config) if paired else classic_equation
    objective_equation_label = "Paired Q equation" if paired else "Classic Q equation"
    q_values = [float(obs.get("Q_run", np.nan)) for obs in observations]
    best = observations[int(np.nanargmax(q_values))]
    if progress_callback is not None:
        progress_callback(0.025, "Indexing real-data channels...")
    channels = _real_data_channels(observations)
    if progress_callback is not None:
        progress_callback(0.03, "Indexing history and score metrics...")
    metric_specs = _history_metric_specs(history)
    if progress_callback is not None:
        progress_callback(0.035, "Indexing channel groups...")
    multiple_groups = len({
        int(observation.get("group_id", 1))
        for observation in observations
    }) > 1
    groups = _session_channel_groups(session)
    if progress_callback is not None:
        progress_callback(0.04, "Scanning surrogate artifacts...")
    ungrouped_surrogates, grouped_surrogates = _pdf_surrogate_file_index(session["root"])
    artifact_entries: dict[tuple[int, int], tuple[dict, Path]] = {}
    if multiple_groups:
        for group in groups:
            if progress_callback is not None:
                progress_callback(
                    0.045,
                    f"Indexing surrogate artifacts for {group['name']}...",
                )
            group_session = _session_for_channel_group(session, group["id"])
            for iteration, path in grouped_surrogates.get(int(group["id"]), {}).items():
                artifact_entries[(int(group["id"]), int(iteration))] = (group_session, path)
    else:
        selected_group_id = session.get("selected_group_id")
        source_surrogates = (
            grouped_surrogates.get(int(selected_group_id), {})
            if selected_group_id is not None
            else ungrouped_surrogates
        )
        for iteration, path in source_surrogates.items():
            artifact_entries[(1, int(iteration))] = (session, path)
    if progress_callback is not None:
        progress_callback(0.05, "Indexing completed observations...")
    observations_by_key = {
        (int(observation.get("group_id", 1)), int(observation.get("iteration", 0))): observation
        for observation in observations
    }
    artifact_report_keys = (
        sorted(artifact_entries)
        if surrogate_iteration_mode == "all"
        else _pdf_final_artifact_keys(artifact_entries)
    )
    swv_report_keys = (
        sorted(observations_by_key)
        if swv_iteration_mode == "all"
        else _pdf_milestone_observation_keys(observations_by_key)
    )
    total_steps = (
        7
        + len(metric_specs)
        + max(1, len(artifact_report_keys))
        + max(1, len(swv_report_keys))
    )
    completed_steps = max(1, int(total_steps * 0.05))

    def report_progress(text: str, increment: int = 1) -> None:
        nonlocal completed_steps
        completed_steps += increment
        if progress_callback is not None:
            progress_callback(
                min(completed_steps / max(total_steps, 1), 0.99),
                text,
            )

    output = BytesIO()
    with PdfPages(output) as pdf:
        pdf._bo_parameter_context = _session_parameter_context(observations)
        if progress_callback is not None:
            progress_callback(0.06, "Rendering metadata pages...")
        _pdf_text_pages(
            pdf,
            "1. Metadata",
            _pdf_metadata_lines(
                session,
                observations,
                paired,
                best,
                surrogate_iteration_mode,
                swv_iteration_mode,
            ),
        )
        report_progress("Rendered metadata.")
        _pdf_text_page(
            pdf,
            "Q Definition",
            (_paired_q_equation(config) if paired else _classic_q_equation(config)).splitlines(),
        )
        if paired:
            _pdf_text_page(
                pdf,
                "Classic Q Definition (inputs to Paired Q)",
                _classic_q_equation(config).splitlines(),
            )
        report_progress("Rendered Q definitions.")

        _pdf_text_page(pdf, "2. History and Scores Metrics", [
            "Every changing numeric metric from the History & scores tab is plotted.",
            "For each metric, groups are overlaid first; separate group plots appear below.",
        ])
        if not metric_specs:
            _pdf_text_page(pdf, "History and Scores Metrics Not Available", [
                "No changing numeric metrics were found in the history table.",
            ])
        for metric_kind, metric, channel_columns in metric_specs:
            _pdf_history_metric_page(
                pdf,
                history,
                metric_kind,
                metric,
                channel_columns,
            )
            report_progress(f"Rendered history metric: {_metric_label(metric)}.")

        _pdf_text_page(pdf, "3. Real Data Landscapes", [
            "This section includes 3D tensor plots for every available real-data metric",
            "and every varied 3-parameter combination.",
        ])
        _pdf_real_data_3d_tensors(
            pdf,
            observations,
            config,
            paired,
            channels,
            status_callback=lambda text: report_progress(text, 0),
        )
        report_progress("Rendered real data landscapes.")

        _pdf_text_page(pdf, "4. Surrogate Landscapes", [
            "This section includes surrogate 3D tensor plots and 2D maps for every",
            "available surrogate artifact, value, and varied parameter combination.",
        ])
        if not artifact_entries:
            _pdf_text_page(pdf, "Surrogate Landscapes Not Available", [
                "No persisted surrogate candidate prediction files were found.",
            ])
            report_progress("No surrogate landscapes available.")
        for group_id, iteration in artifact_report_keys:
            surrogate_session, artifact_path = artifact_entries[(group_id, iteration)]
            _pdf_surrogate_tensor_maps(
                pdf,
                surrogate_session,
                iteration,
                artifact_path,
                objective_equation_label,
                objective_equation,
                status_callback=lambda text: report_progress(text, 0),
            )
            report_progress(f"Rendered surrogate group {group_id}, iteration {iteration}.")

        _pdf_text_page(pdf, "5. Per-Iteration SWV Traces", [
            "For each completed iteration, cumulative SWV overlays include raw,",
            "offset raw, corrected, normalized corrected, and normalized raw traces.",
        ])
        if not observations_by_key:
            report_progress("No SWV iterations available.")
        for report_key in swv_report_keys:
            observation = observations_by_key[report_key]
            _pdf_iteration_swv_overlays(
                pdf,
                session,
                observations,
                observation,
                trace_analysis,
                correction_label,
                status_callback=lambda text: report_progress(text, 0),
            )
            report_progress(
                f"Rendered SWV traces for group {observation.get('group_id', 1)}, "
                f"iteration {observation.get('iteration', 0)}."
            )
        report_progress("Finalized PDF.")
    if progress_callback is not None:
        progress_callback(1.0, "PDF ready.")
    return output.getvalue()


def _channel_table(observation: dict) -> pd.DataFrame:
    quality = observation.get("quality") or {}
    components = quality.get("channel_components") or {}
    metrics = observation.get("channel_metrics") or {}
    channels = sorted(set(components) | set(metrics), key=lambda value: int(value) if str(value).isdigit() else str(value))
    rows = []
    for channel in channels:
        component = components.get(channel, {}) or {}
        metric = metrics.get(channel, {}) or {}
        rows.append({
            "Channel": channel,
            "Q": (quality.get("Q_channels") or {}).get(channel, component.get("Q_channel")),
            "Peak uA": metric.get("mean_peak_current_uA", metric.get("median_peak_current_uA")),
            "Raw SNR": metric.get("snr_unadjusted", metric.get("snr")),
            "SNR Score": component.get("snr_score", component.get("target_snr_score")),
            "Shape": metric.get("peak_shape_score"),
            "Baseline": metric.get("baseline_stability_score"),
            "Replicate": metric.get("replicate_consistency_score"),
            "Success": metric.get("success_score"),
        })
    return pd.DataFrame(rows)


@lru_cache(maxsize=8192)
def _resolve_recorded_path_cached(
    root_text: str,
    raw_text: str,
) -> str | None:
    root = Path(root_text)
    direct = Path(raw_text)
    try:
        if direct.is_file():
            return direct
    except OSError:
        # A path recorded on another OS may be interpreted as one invalid local
        # filename (for example, a long Windows path loaded on macOS).
        pass
    name = PureWindowsPath(raw_text).name
    if not name:
        return None

    def find_recorded_file(search_root: Path) -> Path | None:
        match = _recorded_file_index(str(search_root)).get(name)
        return Path(match) if match is not None else None

    match = find_recorded_file(root)
    if match is not None:
        return str(match)
    # Archived measurements commonly sit beside bo_sessions in the experiment folder.
    for parent in list(root.parents)[:3]:
        match = find_recorded_file(parent)
        if match is not None:
            return str(match)
    return None


@lru_cache(maxsize=12)
def _recorded_file_index(root_text: str) -> dict[str, str]:
    """Index a search root once instead of recursively scanning per trace."""
    files: dict[str, str] = {}

    def ignore_walk_error(_error: OSError) -> None:
        return None

    for directory, _subdirectories, names in os.walk(
        root_text,
        onerror=ignore_walk_error,
    ):
        for name in names:
            files.setdefault(name, str(Path(directory) / name))
    return files


def _resolve_recorded_path(root: Path, raw: Any) -> Path | None:
    if not raw:
        return None
    resolved = _resolve_recorded_path_cached(str(root), str(raw))
    return Path(resolved) if resolved is not None else None


def _channel_from_path(path: Path) -> str:
    match = re.search(r"(?:^|[_-])ch(?:annel)?[_-]?(\d+)(?:[_\-.]|$)", path.name, re.IGNORECASE)
    return match.group(1) if match else "Unknown"


def _phase_from_path(raw: Any) -> str | None:
    text = str(raw).replace("\\", "/").lower()
    parts = [part for part in text.split("/") if part]
    for part in reversed(parts):
        if "buffer" in part:
            return "buffer"
        if "target" in part:
            return "target"
    return None


def _trace_paths(session: dict, observation: dict) -> list[dict]:
    paths: list[dict] = []
    root = session["root"]

    def add(
        raw_path: Any,
        phase: str | None = None,
        channel: Any = None,
        source_rank: int = 0,
    ) -> None:
        path = _resolve_recorded_path(root, raw_path)
        if not path or not path.is_file() or path.suffix.lower() != ".csv":
            return
        resolved_phase = phase or _phase_from_path(raw_path) or _phase_from_path(path) or "unknown"
        has_channel = channel is not None and pd.notna(channel) and str(channel).strip()
        resolved_channel = str(channel).strip() if has_channel else _channel_from_path(path)
        if resolved_channel.endswith(".0") and resolved_channel[:-2].isdigit():
            resolved_channel = resolved_channel[:-2]
        existing = next((item for item in paths if item["path"] == path), None)
        if existing is not None:
            # Explicit analysis-record metadata is more reliable than path inference.
            if phase in ("buffer", "target", "measurement"):
                existing["phase"] = phase
            if resolved_channel != "Unknown":
                existing["channel"] = resolved_channel
            existing["source_rank"] = max(
                int(existing.get("source_rank", 0)),
                int(source_rank),
            )
            return
        paths.append({
            "phase": resolved_phase,
            "path": path,
            "channel": resolved_channel,
            "source_rank": int(source_rank),
        })

    # Paired records explicitly identify buffer versus target. Standard BO
    # stores one analysis_record for the measurement.
    paired = str(observation.get("objective") or "").lower() == "paired_response"
    record_specs = (
        [
            ("buffer", observation.get("buffer_analysis_record")),
            ("target", observation.get("target_analysis_record")),
        ]
        if paired
        else [("measurement", observation.get("analysis_record"))]
    )
    for phase, raw_record in record_specs:
        record = _resolve_recorded_path(root, raw_record)
        if not record:
            continue
        try:
            payload = _read_json(record)
        except Exception:
            continue
        results_csv = _resolve_recorded_path(root, payload.get("results_csv"))
        if results_csv:
            try:
                results = pd.read_csv(results_csv)
                for _, row in results.iterrows():
                    recorded_path = row.get("file_path")
                    if recorded_path is None or pd.isna(recorded_path) or not str(recorded_path).strip():
                        recorded_path = row.get("file_name")
                    add(
                        recorded_path,
                        phase=phase,
                        channel=row.get("channel"),
                        source_rank=30,
                    )
            except Exception:
                pass
        for raw in payload.get("folders") or []:
            add(raw, phase=phase, source_rank=20)

    for raw in observation.get("archived_measurements") or []:
        add(
            raw,
            phase=_phase_from_path(raw) if paired else "measurement",
            source_rank=10,
        )

    deduped: dict[tuple[str, str], dict] = {}
    for item in paths:
        key = (str(item["phase"]).lower(), str(item["channel"]))
        existing = deduped.get(key)
        if existing is None:
            deduped[key] = item
            continue
        item_rank = int(item.get("source_rank", 0))
        existing_rank = int(existing.get("source_rank", 0))
        if item_rank > existing_rank:
            deduped[key] = item
            continue
        if item_rank == existing_rank:
            try:
                if item["path"].stat().st_mtime_ns > existing["path"].stat().st_mtime_ns:
                    deduped[key] = item
            except OSError:
                pass
    cleaned = []
    for item in deduped.values():
        cleaned.append({
            "phase": item["phase"],
            "path": item["path"],
            "channel": item["channel"],
        })
    return cleaned


def _channel_sort_key(channel: str):
    return (0, int(channel)) if str(channel).isdigit() else (1, str(channel))


def _trace_channel_key(item: dict) -> str:
    return str(item.get("display_channel") or item["channel"])


def _trace_channel_label(channel: Any) -> str:
    text = str(channel)
    if text == "Unknown":
        return "Unknown channel"
    if " · " in text:
        return text
    return f"Ch {text}"


def _group_qualified_trace(
    observation: dict,
    trace: dict,
    include_group: bool,
) -> dict:
    if not include_group:
        return trace
    group_name = str(
        observation.get("group_name")
        or f"Group {observation.get('group_id', 1)}"
    )
    qualified = dict(trace)
    qualified["display_channel"] = (
        f"{group_name} · {_trace_channel_label(trace['channel'])}"
    )
    return qualified


@st.cache_data(show_spinner=False)
def _cached_swv_arrays(
    path_text: str,
    modified_ns: int,
) -> tuple[np.ndarray, np.ndarray, int | None, int | None, int | None]:
    """Load an unchanged SWV file once per Streamlit process."""
    del modified_ns  # Included in the cache key to invalidate changed files.
    return load_swv_csv(path_text)


@st.cache_data(show_spinner=False)
def _cached_corrected_swv_arrays(
    path_text: str,
    modified_ns: int,
    corrected_trace_key: str,
    crop_min_v: float,
    crop_max_v: float,
    smooth_window: int,
    smooth_polyorder: int,
    minima_search_window_v: float,
    use_prominent_minima: bool,
    use_double_correction: bool,
    min_peak_height_uA: float | None,
    compute_wavelet_denoised_trace: bool,
    use_wavelet_for_correction: bool,
) -> tuple[np.ndarray, np.ndarray, int | None, int | None, int | None]:
    voltage, current = _cached_swv_arrays(path_text, modified_ns)
    result = analyze_swv_arrays(
        voltage,
        current,
        crop_range=(crop_min_v, crop_max_v),
        smooth_window=smooth_window,
        smooth_polyorder=smooth_polyorder,
        minima_search_window_V=minima_search_window_v,
        use_prominent_minima=use_prominent_minima,
        use_double_correction=use_double_correction,
        min_peak_height_uA=min_peak_height_uA,
        compute_wavelet_denoised_trace=compute_wavelet_denoised_trace,
        use_wavelet_for_correction=use_wavelet_for_correction,
    )
    corrected_voltage = result.get(
        "cropped_voltage",
        result.get("voltage", voltage),
    )
    corrected_current = result.get(corrected_trace_key)
    if corrected_current is None:
        corrected_current = result.get(
            "smoothed_corrected_current",
            result.get("corrected_current"),
        )
    return (
        corrected_voltage,
        corrected_current,
        result.get("peak_idx_corr"),
        result.get("left_min_idx"),
        result.get("right_min_idx"),
    )


def _swv_trace_arrays(
    path: Path,
    corrected: bool,
    analysis: dict,
    corrected_trace_key: str = "smoothed_corrected_current",
) -> tuple[np.ndarray, np.ndarray, int | None, int | None, int | None]:
    modified_ns = path.stat().st_mtime_ns
    if not corrected:
        voltage, current = _cached_swv_arrays(str(path), modified_ns)
        return voltage, current, None, None, None
    minimum_peak = analysis.get("min_peak_height_uA")
    return _cached_corrected_swv_arrays(
        str(path),
        modified_ns,
        corrected_trace_key,
        float(analysis.get("crop_min_v", -.45)),
        float(analysis.get("crop_max_v", 0)),
        int(analysis.get("smooth_window", 3)),
        int(analysis.get("smooth_polyorder", 2)),
        float(analysis.get("minima_search_window_v", .3)),
        bool(analysis.get("use_prominent_minima", False)),
        bool(analysis.get("use_double_correction", True)),
        float(minimum_peak) if minimum_peak is not None else None,
        bool(analysis.get("compute_wavelet_denoised_trace", False)),
        bool(analysis.get("use_wavelet_for_correction", False)),
    )


def _normalize_trace_to_peak(
    y: np.ndarray,
    peak_idx: int | None = None,
    left_idx: int | None = None,
    right_idx: int | None = None,
) -> np.ndarray:
    y = np.asarray(y, dtype=float)
    if left_idx is not None and right_idx is not None:
        left = max(0, int(left_idx))
        right = min(len(y) - 1, int(right_idx))
        if left <= right:
            peak_region = y[left:right + 1]
            finite_region = peak_region[np.isfinite(peak_region)]
            if len(finite_region):
                peak_height = float(np.nanmax(finite_region))
            else:
                peak_height = np.nan
        else:
            peak_height = np.nan
    elif peak_idx is not None and 0 <= int(peak_idx) < len(y):
        peak_height = float(y[int(peak_idx)])
    else:
        raise ValueError("Trace has no detected peak index to normalize.")
    if not np.isfinite(peak_height) or np.isclose(peak_height, 0.0):
        raise ValueError("Trace peak height is zero or non-finite.")
    return y / peak_height


def _offset_trace_to_minima_baseline(
    y: np.ndarray,
    left_idx: int | None = None,
    right_idx: int | None = None,
) -> np.ndarray:
    y = np.asarray(y, dtype=float)
    if left_idx is None or right_idx is None:
        raise ValueError("Trace has no detected left/right minima to offset.")
    left = int(left_idx)
    right = int(right_idx)
    if left == right:
        if 0 <= left < len(y) and np.isfinite(y[left]):
            return y - float(y[left])
        raise ValueError("Trace minima are outside the trace or non-finite.")
    if not (
        0 <= left < len(y)
        and 0 <= right < len(y)
        and np.isfinite(y[left])
        and np.isfinite(y[right])
    ):
        raise ValueError("Trace minima are outside the trace or non-finite.")
    baseline = np.interp(
        np.arange(len(y), dtype=float),
        [float(left), float(right)],
        [float(y[left]), float(y[right])],
    )
    return y - baseline


def _swv_global_y_limits(
    trace_observations: list[dict],
    session: dict,
    selected_channels: list[str],
    corrected: bool,
    analysis: dict,
    normalize_to_peak: bool,
    corrected_trace_key: str,
    offset_to_baseline: bool = False,
    selected_phases: tuple[str, ...] | None = None,
    voltage_min: float | None = None,
    voltage_max: float | None = None,
) -> tuple[float, float] | None:
    if normalize_to_peak:
        return (-0.2, 1.2)
    values = []
    selected_channel_set = set(selected_channels)
    selected_phase_set = (
        {str(phase).lower() for phase in selected_phases}
        if selected_phases is not None
        else None
    )
    for observation in trace_observations:
        for item in _trace_paths(session, observation):
            if item["channel"] not in selected_channel_set:
                continue
            if (
                selected_phase_set is not None
                and str(item.get("phase", "")).lower() not in selected_phase_set
            ):
                continue
            try:
                voltage, y, _peak_idx, _left_idx, _right_idx = _swv_trace_arrays(
                    item["path"],
                    corrected,
                    analysis,
                    corrected_trace_key,
                )
            except Exception:
                continue
            if offset_to_baseline:
                try:
                    y = _offset_trace_to_minima_baseline(y, left_idx, right_idx)
                except ValueError:
                    continue
            voltage = np.asarray(voltage, dtype=float)
            y = np.asarray(y, dtype=float)
            if voltage_min is not None or voltage_max is not None:
                voltage_mask = np.isfinite(voltage)
                if voltage_min is not None:
                    voltage_mask &= voltage >= float(voltage_min)
                if voltage_max is not None:
                    voltage_mask &= voltage <= float(voltage_max)
                y = y[voltage_mask]
            finite = y[np.isfinite(y)]
            if len(finite):
                values.append(finite)
    if not values:
        return None
    merged = np.concatenate(values)
    y_min = float(np.nanmin(merged))
    y_max = float(np.nanmax(merged))
    if not np.isfinite(y_min) or not np.isfinite(y_max):
        return None
    if np.isclose(y_min, y_max):
        padding = max(abs(y_min) * 0.05, 0.1)
    else:
        padding = (y_max - y_min) * 0.05
    return y_min - padding, y_max + padding


def _swv_trace_kind_label(
    corrected: bool,
    normalize_to_peak: bool,
    corrected_trace_key: str,
    offset_to_baseline: bool = False,
) -> str:
    if offset_to_baseline and corrected_trace_key == "corrected_current":
        return "offset raw"
    if not corrected:
        return "raw"
    if normalize_to_peak and corrected_trace_key == "corrected_current":
        return "normalized raw"
    if normalize_to_peak:
        return "normalized corrected"
    if corrected_trace_key == "corrected_current":
        return "raw corrected"
    return "corrected"


def _plot_traces(
    session: dict,
    observation: dict,
    corrected: bool,
    selected_channels: list[str],
    analysis: dict,
    correction_label: str,
    overlaid: bool,
    trace_items: list[dict] | None = None,
    normalize_to_peak: bool = False,
    corrected_trace_key: str = "smoothed_corrected_current",
    offset_to_baseline: bool = False,
    voltage_min: float | None = None,
    voltage_max: float | None = None,
):
    traces = [
        item for item in (
            trace_items
            if trace_items is not None
            else _trace_paths(session, observation)
        )
        if _trace_channel_key(item) in selected_channels
    ]
    fig, ax = plt.subplots(figsize=(8, 4))
    errors = []
    trace_colors = plt.get_cmap("turbo")(
        np.linspace(.03, .97, max(len(traces), 2))
    )
    phase_styles = {
        "buffer": "--",
        "target": "-",
        "measurement": "-",
        "unknown": ":",
    }
    for trace_index, item in enumerate(traces):
        phase, path, channel = item["phase"], item["path"], item["channel"]
        try:
            voltage, y, peak_idx, left_idx, right_idx = _swv_trace_arrays(
                path,
                corrected,
                analysis,
                corrected_trace_key,
            )
            if offset_to_baseline:
                y = _offset_trace_to_minima_baseline(y, left_idx, right_idx)
            if normalize_to_peak:
                y = _normalize_trace_to_peak(y, peak_idx, left_idx, right_idx)
            voltage = np.asarray(voltage, dtype=float)
            y = np.asarray(y, dtype=float)
            if voltage_min is not None or voltage_max is not None:
                voltage_mask = np.isfinite(voltage) & np.isfinite(y)
                if voltage_min is not None:
                    voltage_mask &= voltage >= float(voltage_min)
                if voltage_max is not None:
                    voltage_mask &= voltage <= float(voltage_max)
                if not voltage_mask.any():
                    raise ValueError(
                        "Trace has no points inside the selected voltage crop."
                    )
                voltage = voltage[voltage_mask]
                y = y[voltage_mask]
            channel_label = _trace_channel_label(_trace_channel_key(item))
            trace_label = f"{phase} {channel_label}: {path.stem}"
            ax.plot(
                voltage,
                y,
                linewidth=1.1,
                color=trace_colors[trace_index],
                linestyle=phase_styles.get(
                    str(phase).lower(),
                    phase_styles["unknown"],
                ),
                label=trace_label,
            )
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
    if not traces:
        message = (
            "No traces match the selected channels."
            if selected_channels else
            "Select at least one channel to display traces."
        )
        ax.text(.5, .5, message, ha="center", va="center")
        ax.set_axis_off()
    else:
        channel_title = ""
        if not overlaid:
            channel_title = " | " + ", ".join(
                _trace_channel_label(channel)
                for channel in selected_channels
            )
        params = observation.get("params") or {}
        parameter_text = (
            f"Frequency={float(params['frequency']):g} Hz"
            if params.get("frequency") is not None else "Frequency=unknown"
        )
        parameter_text += (
            f" | Step size={float(params['step_potential']):g} V"
            if params.get("step_potential") is not None else " | Step size=unknown"
        )
        parameter_text += (
            f" | Amplitude={float(params['amplitude']):g} V"
            if params.get("amplitude") is not None else " | Amplitude=unknown"
        )
        ax.set(
            xlabel="Voltage (V)",
            ylabel="Normalized current (peak = 1)" if normalize_to_peak else "Current (uA)",
            title=(
                f"Iteration {observation.get('iteration')} "
                f"{_swv_trace_kind_label(corrected, normalize_to_peak, corrected_trace_key, offset_to_baseline)} SWV traces"
                f"{channel_title}"
                f"{f' ({correction_label})' if corrected else ''}"
                f"\n{parameter_text}"
            ),
        )
        if normalize_to_peak:
            ax.set_ylim(-0.2, 1.2)
        ax.grid(alpha=.25)
        if len(traces) <= 16:
            ax.legend(fontsize=7)
    # Keep raw and corrected plots geometrically identical. ``tight_layout``
    # otherwise assigns different axes sizes when their titles or tick labels
    # require different amounts of space.
    fig.subplots_adjust(left=.12, right=.97, bottom=.16, top=.76)
    return fig, errors


def _plot_iteration_trace_overlay(
    trace_entries: list[tuple[dict, dict]],
    corrected: bool,
    selected_channels: list[str],
    analysis: dict,
    correction_label: str,
    selection_label: str,
    normalize_to_peak: bool = False,
    corrected_trace_key: str = "smoothed_corrected_current",
    offset_to_baseline: bool = False,
    voltage_min: float | None = None,
    voltage_max: float | None = None,
):
    """Overlay traces from many observations with channel-aware colors."""
    entries = [
        (observation, item)
        for observation, item in trace_entries
        if _trace_channel_key(item) in selected_channels
    ]
    fig, ax = plt.subplots(figsize=(8, 4.8))
    errors = []
    iterations = [
        int(observation.get("iteration", 0))
        for observation, _item in entries
    ]
    plotted_channels = sorted(
        {_trace_channel_key(item) for _observation, item in entries},
        key=_channel_sort_key,
    )
    single_channel = len(plotted_channels) <= 1
    if single_channel:
        iteration_minimum = min(iterations, default=0)
        iteration_maximum = max(iterations, default=0)
        iteration_norm = plt.Normalize(
            vmin=(
                iteration_minimum
                if iteration_maximum > iteration_minimum
                else iteration_minimum - .5
            ),
            vmax=(
                iteration_maximum
                if iteration_maximum > iteration_minimum
                else iteration_maximum + .5
            ),
        )
        iteration_cmap = plt.get_cmap("viridis")
        channel_colors = {}
    else:
        categorical_colors = plt.get_cmap("turbo")(
            np.linspace(.03, .97, max(len(plotted_channels), 2))
        )
        channel_colors = {
            channel: categorical_colors[index]
            for index, channel in enumerate(plotted_channels)
        }
        iteration_norm = None
        iteration_cmap = None
    phase_styles = {
        "buffer": "--",
        "target": "-",
        "measurement": "-",
        "unknown": ":",
    }
    for observation, item in entries:
        phase, path, channel = item["phase"], item["path"], _trace_channel_key(item)
        iteration = int(observation.get("iteration", 0))
        try:
            voltage, y, peak_idx, left_idx, right_idx = _swv_trace_arrays(
                path,
                corrected,
                analysis,
                corrected_trace_key,
            )
            if offset_to_baseline:
                y = _offset_trace_to_minima_baseline(y, left_idx, right_idx)
            if normalize_to_peak:
                y = _normalize_trace_to_peak(y, peak_idx, left_idx, right_idx)
            voltage = np.asarray(voltage, dtype=float)
            y = np.asarray(y, dtype=float)
            if voltage_min is not None or voltage_max is not None:
                voltage_mask = np.isfinite(voltage) & np.isfinite(y)
                if voltage_min is not None:
                    voltage_mask &= voltage >= float(voltage_min)
                if voltage_max is not None:
                    voltage_mask &= voltage <= float(voltage_max)
                if not voltage_mask.any():
                    raise ValueError(
                        "Trace has no points inside the selected voltage crop."
                    )
                voltage = voltage[voltage_mask]
                y = y[voltage_mask]
            ax.plot(
                voltage,
                y,
                linewidth=1.0,
                alpha=.72,
                color=(
                    iteration_cmap(iteration_norm(iteration))
                    if single_channel
                    else channel_colors[channel]
                ),
                linestyle=phase_styles.get(
                    str(phase).lower(),
                    phase_styles["unknown"],
                ),
                label=(
                    f"Iter {iteration} · {str(phase).title()} · "
                    f"{_trace_channel_label(channel)}"
                    f": {path.stem}"
                ),
            )
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
    if not entries:
        ax.text(
            .5,
            .5,
            "No traces match the selected channels.",
            ha="center",
            va="center",
        )
        ax.set_axis_off()
    else:
        channel_text = ", ".join(
            _trace_channel_label(channel)
            for channel in selected_channels
        )
        ax.set(
            xlabel="Voltage (V)",
            ylabel="Normalized current (peak = 1)" if normalize_to_peak else "Current (µA)",
            title=(
                f"{selection_label}\n"
                f"{_swv_trace_kind_label(corrected, normalize_to_peak, corrected_trace_key, offset_to_baseline).capitalize()} SWV traces"
                f"{f' ({correction_label})' if corrected else ''}"
                f" | {channel_text}"
            ),
        )
        if normalize_to_peak:
            ax.set_ylim(-0.2, 1.2)
        ax.grid(alpha=.25)
        if single_channel:
            unique_iterations = sorted(set(iterations))
            colorbar_ticks = (
                unique_iterations
                if len(unique_iterations) <= 10
                else sorted({
                    int(round(value))
                    for value in np.linspace(
                        iteration_minimum,
                        iteration_maximum,
                        8,
                    )
                })
            )
            scalar_map = plt.cm.ScalarMappable(
                norm=iteration_norm,
                cmap=iteration_cmap,
            )
            scalar_map.set_array([])
            fig.colorbar(
                scalar_map,
                ax=ax,
                label="BO iteration",
                ticks=colorbar_ticks,
            )
        if not single_channel:
            channel_handles = [
                Line2D(
                    [0],
                    [0],
                    color=channel_colors[channel],
                    linewidth=2,
                    label=(
                        f"Ch {channel}"
                        if channel != "Unknown"
                        else "Unknown channel"
                    ),
                )
                for channel in plotted_channels
            ]
            ax.legend(
                handles=channel_handles,
                title="Channel color",
                fontsize=7,
                title_fontsize=8,
            )
        elif len(entries) <= 16:
            ax.legend(fontsize=7)
    fig.subplots_adjust(left=.12, right=.97, bottom=.14, top=.78)
    return fig, errors


def _chronological_swv_stack_entries(
    trace_entries: list[tuple[dict, dict]],
    corrected: bool,
    selected_channels: list[str],
    analysis: dict,
    config: dict,
    normalize_to_peak: bool = False,
    corrected_trace_key: str = "smoothed_corrected_current",
    offset_to_baseline: bool = False,
    trace_height_scale: float = 1.0,
    voltage_min: float | None = None,
    voltage_max: float | None = None,
    current_min: float | None = None,
    current_max: float | None = None,
    selected_phases: tuple[str, ...] | None = None,
) -> tuple[list[dict], list[str], list[tuple[dict, dict]]]:
    batch_size = max(1, int((config or {}).get("paired_batch_size", 1) or 1))
    phase_filter = (
        {phase.lower() for phase in selected_phases}
        if selected_phases is not None
        else None
    )

    def stack_sort_key(pair: tuple[dict, dict]) -> tuple:
        observation, item = pair
        iteration = int(observation.get("iteration", 0) or 0)
        group_id = int(observation.get("group_id", 1) or 1)
        channel_key = _channel_sort_key(_trace_channel_key(item))
        paired = str(observation.get("objective") or "").lower() == "paired_response"
        if not paired:
            return (
                group_id,
                iteration,
                channel_key,
                str(item.get("phase", "")),
            )
        cycle = observation.get("paired_cycle")
        if cycle in (None, ""):
            cycle = ((iteration - 1) // batch_size) + 1
        batch = observation.get("paired_batch_index")
        if batch in (None, ""):
            batch = ((iteration - 1) % batch_size) + 1
        phase = str(item.get("phase", "")).lower()
        phase_order = {"buffer": 0, "target": 1}.get(phase, 2)
        trace = observation.get(f"{phase}_trace_number")
        try:
            trace_value = int(trace)
        except (TypeError, ValueError):
            trace_value = int(batch)
        return (
            group_id,
            int(cycle),
            phase_order,
            trace_value,
            int(batch),
            iteration,
            channel_key,
        )

    entries = sorted(
        [
            (observation, item)
            for observation, item in trace_entries
            if _trace_channel_key(item) in selected_channels
            and (
                phase_filter is None
                or str(item.get("phase", "")).lower() in phase_filter
            )
        ],
        key=stack_sort_key,
    )
    errors = []
    loaded = []
    for stack_index, (observation, item) in enumerate(entries):
        phase, path, channel = item["phase"], item["path"], _trace_channel_key(item)
        try:
            voltage, y, peak_idx, left_idx, right_idx = _swv_trace_arrays(
                path,
                corrected,
                analysis,
                corrected_trace_key,
            )
            if offset_to_baseline:
                y = _offset_trace_to_minima_baseline(y, left_idx, right_idx)
            if normalize_to_peak:
                y = _normalize_trace_to_peak(y, peak_idx, left_idx, right_idx)
            voltage = np.asarray(voltage, dtype=float)
            y = np.asarray(y, dtype=float)
            finite = np.isfinite(voltage) & np.isfinite(y)
            if not finite.any():
                raise ValueError("Trace has no finite voltage/current values.")
            voltage = voltage[finite]
            y = y[finite]
            if voltage_min is not None or voltage_max is not None:
                voltage_mask = np.ones_like(voltage, dtype=bool)
                if voltage_min is not None:
                    voltage_mask &= voltage >= float(voltage_min)
                if voltage_max is not None:
                    voltage_mask &= voltage <= float(voltage_max)
                if not voltage_mask.any():
                    raise ValueError(
                        "Trace has no points inside the selected voltage crop."
                    )
                voltage = voltage[voltage_mask]
                y = y[voltage_mask]
            current = y * float(trace_height_scale)
            if current_min is not None or current_max is not None:
                current_mask = np.ones_like(current, dtype=bool)
                if current_min is not None:
                    current_mask &= current >= float(current_min)
                if current_max is not None:
                    current_mask &= current <= float(current_max)
                if not current_mask.any():
                    raise ValueError(
                        "Trace has no points inside the selected current crop."
                    )
                voltage = voltage[current_mask]
                current = current[current_mask]
            loaded.append({
                "iteration": int(observation.get("iteration", 0)),
                "stack_index": stack_index,
                "phase": str(phase),
                "channel": channel,
                "voltage": voltage,
                "current": current,
            })
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
    return loaded, errors, entries


def _chronological_swv_stack_display_bounds(
    loaded: list[dict],
    x_step: float,
    y_step: float,
) -> tuple[float, float, float, float] | None:
    if not loaded:
        return None
    plotted_x_values = np.concatenate([
        row["voltage"] + int(row.get("stack_index", 0)) * x_step
        for row in loaded
    ])
    plotted_y_values = np.concatenate([
        row["current"] + int(row.get("stack_index", 0)) * y_step
        for row in loaded
    ])
    return (
        float(np.nanmin(plotted_x_values)),
        float(np.nanmax(plotted_x_values)),
        float(np.nanmin(plotted_y_values)),
        float(np.nanmax(plotted_y_values)),
    )


def _chronological_swv_stack_steps(
    loaded: list[dict],
    x_offset_per_iteration: float | None = None,
    y_offset_per_iteration: float | None = None,
) -> tuple[float, float]:
    voltage_values = np.concatenate([row["voltage"] for row in loaded])
    current_values = np.concatenate([row["current"] for row in loaded])
    voltage_range = float(np.nanmax(voltage_values) - np.nanmin(voltage_values))
    current_range = float(np.nanmax(current_values) - np.nanmin(current_values))
    x_step = (
        float(x_offset_per_iteration)
        if x_offset_per_iteration is not None
        else voltage_range * 0.035 if voltage_range > 0 else 0.01
    )
    y_step = (
        float(y_offset_per_iteration)
        if y_offset_per_iteration is not None
        else current_range * 0.10 if current_range > 0 else 0.08
    )
    return x_step, y_step


def _plot_chronological_swv_stack(
    trace_entries: list[tuple[dict, dict]],
    corrected: bool,
    selected_channels: list[str],
    analysis: dict,
    config: dict,
    correction_label: str,
    selection_label: str,
    normalize_to_peak: bool = False,
    corrected_trace_key: str = "smoothed_corrected_current",
    offset_to_baseline: bool = False,
    x_offset_per_iteration: float | None = None,
    y_offset_per_iteration: float | None = None,
    trace_height_scale: float = 1.0,
    voltage_min: float | None = None,
    voltage_max: float | None = None,
    y_min: float | None = None,
    y_max: float | None = None,
    selected_phases: tuple[str, ...] | None = None,
):
    """Render SWVs as a diagonal chronological stack."""
    fig, ax = plt.subplots(figsize=(9, 5.5))
    loaded, errors, entries = _chronological_swv_stack_entries(
        trace_entries,
        corrected,
        selected_channels,
        analysis,
        config,
        normalize_to_peak,
        corrected_trace_key,
        offset_to_baseline,
        trace_height_scale,
        voltage_min,
        voltage_max,
        y_min,
        y_max,
        selected_phases,
    )

    if not loaded:
        ax.text(.5, .5, "No traces match the selected channels.", ha="center", va="center")
        ax.set_axis_off()
        return fig, errors

    iteration_values = [row["iteration"] for row in loaded]
    stack_indices = [int(row.get("stack_index", 0)) for row in loaded]
    stack_min = min(stack_indices)
    stack_span = max(1, max(stack_indices) - stack_min)
    x_step, y_step = _chronological_swv_stack_steps(
        loaded,
        x_offset_per_iteration,
        y_offset_per_iteration,
    )
    phase_styles = {
        "buffer": "-",
        "target": "-",
        "measurement": "-",
        "unknown": ":",
    }
    phase_colors = {
        "buffer": "#1f77b4",
        "target": "#ff7f0e",
    }
    use_phase_colors = any(
        str(row["phase"]).lower() in phase_colors for row in loaded
    )
    channel_values = sorted(
        {_trace_channel_key(row) for _obs, row in entries},
        key=_channel_sort_key,
    )
    channel_colors = {
        channel: plt.get_cmap("turbo")(position)
        for channel, position in zip(
            channel_values,
            np.linspace(.03, .97, max(len(channel_values), 2)),
        )
    }
    for row in loaded:
        offset_index = int(row.get("stack_index", 0))
        age = (offset_index - stack_min) / stack_span
        age = min(1.0, max(0.0, float(age)))
        alpha = min(1.0, max(0.0, 0.18 + 0.82 * age))
        ax.plot(
            row["voltage"] + offset_index * x_step,
            row["current"] + offset_index * y_step,
            color=(
                phase_colors.get(str(row["phase"]).lower())
                if use_phase_colors
                else None
            ) or channel_colors.get(row["channel"], "#155e63"),
            linestyle=phase_styles.get(row["phase"].lower(), phase_styles["unknown"]),
            linewidth=1.05 + 0.45 * age,
            alpha=alpha,
        )

    display_bounds = _chronological_swv_stack_display_bounds(
        loaded,
        x_step,
        y_step,
    )
    plotted_x_min, plotted_x_max, plotted_y_min, plotted_y_max = display_bounds
    plotted_x_span = max(plotted_x_max - plotted_x_min, abs(x_step), 1e-9)
    plotted_y_span = max(plotted_y_max - plotted_y_min, abs(y_step), 1e-9)
    oldest_iteration = min(iteration_values)
    newest_iteration = max(iteration_values)

    def stack_left_edge(stack_index: int) -> tuple[float, float]:
        rows = [row for row in loaded if int(row.get("stack_index", 0)) == stack_index]
        edge_points = []
        for row in rows:
            shifted_x = row["voltage"] + stack_index * x_step
            shifted_y = row["current"] + stack_index * y_step
            left_index = int(np.nanargmin(shifted_x))
            edge_points.append((float(shifted_x[left_index]), float(shifted_y[left_index])))
        return (
            float(np.nanmean([point[0] for point in edge_points])),
            float(np.nanmean([point[1] for point in edge_points])),
        )

    oldest_stack_index = min(stack_indices)
    newest_stack_index = max(stack_indices)
    oldest_edge = stack_left_edge(oldest_stack_index)
    newest_edge = stack_left_edge(newest_stack_index)
    axis_dx = newest_edge[0] - oldest_edge[0]
    axis_dy = newest_edge[1] - oldest_edge[1]
    if np.isclose(axis_dx, 0.0) and np.isclose(axis_dy, 0.0):
        axis_dx = plotted_x_span * 0.18
    axis_length = math.hypot(axis_dx, axis_dy)
    normal_x = -axis_dy / axis_length if axis_length > 0 else -1.0
    normal_y = axis_dx / axis_length if axis_length > 0 else 0.0
    if normal_x > 0:
        normal_x *= -1
        normal_y *= -1
    side_gap = plotted_x_span * 0.055
    axis_start = (
        oldest_edge[0] - 0.04 * axis_dx + normal_x * side_gap,
        oldest_edge[1] - 0.04 * axis_dy + normal_y * side_gap,
    )
    axis_end = (
        newest_edge[0] + 0.04 * axis_dx + normal_x * side_gap,
        newest_edge[1] + 0.04 * axis_dy + normal_y * side_gap,
    )
    ax.annotate(
        "",
        xy=axis_end,
        xytext=axis_start,
        arrowprops={
            "arrowstyle": "-|>",
            "color": "#222222",
            "linewidth": 1.8,
            "shrinkA": 0,
            "shrinkB": 0,
            "mutation_scale": 12,
        },
        zorder=8,
    )
    ax.text(
        axis_end[0],
        axis_end[1],
        " chronological order",
        fontsize=8,
        color="#222222",
        ha="left" if axis_dx >= 0 else "right",
        va="bottom" if axis_dy >= 0 else "top",
        zorder=8,
    )

    newest = max(loaded, key=lambda row: int(row.get("stack_index", 0)))
    oldest = min(loaded, key=lambda row: int(row.get("stack_index", 0)))
    ax.annotate(
        f"Oldest: iter {oldest['iteration']}",
        xy=(
            float(np.nanmin(oldest["voltage"])),
            float(np.nanmin(oldest["current"])),
        ),
        xytext=(8, 8),
        textcoords="offset points",
        fontsize=8,
        color="#666666",
    )
    ax.annotate(
        f"Newest: iter {newest['iteration']}",
        xy=(
            float(np.nanmax(newest["voltage"])) + int(newest.get("stack_index", 0)) * x_step,
            float(np.nanmax(newest["current"])) + int(newest.get("stack_index", 0)) * y_step,
        ),
        xytext=(-88, 8),
        textcoords="offset points",
        fontsize=8,
        color="#111111",
    )
    channel_handles = [
        Line2D(
            [0],
            [0],
            color=channel_colors[channel],
            linewidth=2,
            label=f"Ch {channel}" if channel != "Unknown" else "Unknown channel",
        )
        for channel in channel_values
    ]
    phase_values = [
        phase for phase in ("buffer", "target", "measurement", "unknown")
        if any(str(row["phase"]).lower() == phase for row in loaded)
    ]
    phase_handles = [
        Line2D(
            [0],
            [0],
            color=phase_colors.get(phase, "#333333"),
            linestyle=phase_styles.get(phase, phase_styles["unknown"]),
            linewidth=1.8,
            label=phase.title(),
        )
        for phase in phase_values
        if phase in ("buffer", "target")
    ]
    legend_handles = ([] if use_phase_colors else channel_handles) + phase_handles
    if legend_handles:
        ax.legend(
            handles=legend_handles,
            title="Channel / phase",
            loc="upper left",
            fontsize=7,
            title_fontsize=8,
        )
    ax.set(
        title=(
            f"{selection_label}\n"
            f"Chronological diagonal stack | "
            f"{_swv_trace_kind_label(corrected, normalize_to_peak, corrected_trace_key, offset_to_baseline)}"
            f"{f' ({correction_label})' if corrected else ''}"
        ),
    )
    ax.set_xlabel("")
    ax.set_ylabel("")
    ax.set_xticks([])
    ax.set_yticks([])
    ax.grid(False)
    for spine in ax.spines.values():
        spine.set_visible(False)
    ax.set_facecolor("white")
    fig.patch.set_alpha(1)
    fig.add_artist(Line2D([.22, .91], [.055, .055], transform=fig.transFigure, color="#222222", linewidth=1.1))
    fig.text(.50, .025, "Voltage (V)", ha="center", va="center", fontsize=9)
    fig.add_artist(Line2D([.955, .955], [.18, .78], transform=fig.transFigure, color="#222222", linewidth=1.1))
    fig.text(
        .985,
        .46,
        "z: Normalized current (peak = 1)" if normalize_to_peak else "z: Current (uA)",
        ha="center",
        va="center",
        rotation=90,
        fontsize=9,
    )
    fig.subplots_adjust(left=.03, right=.96, bottom=.08, top=.84)
    return fig, errors


def _bo_analysis_settings(config: dict) -> dict:
    analysis = dict((config or {}).get("analysis") or {})
    return {
        "crop_min_v": float(analysis.get("crop_min_v", -.45)),
        "crop_max_v": float(analysis.get("crop_max_v", 0.0)),
        "smooth_window": int(analysis.get("smooth_window", 3)),
        "smooth_polyorder": int(analysis.get("smooth_polyorder", 2)),
        "minima_search_window_v": float(analysis.get("minima_search_window_v", .3)),
        "use_prominent_minima": bool(analysis.get("use_prominent_minima", False)),
        "use_double_correction": bool(analysis.get("use_double_correction", True)),
        "min_peak_height_uA": analysis.get("min_peak_height_ua"),
        "compute_wavelet_denoised_trace": bool(
            analysis.get("compute_wavelet_denoised_trace", False)
        ),
        "use_wavelet_for_correction": bool(
            analysis.get("use_wavelet_for_correction", False)
        ),
    }


def _native_analysis_settings_sidebar() -> dict:
    st.markdown("##### Native SWV processing")
    crop_columns = st.columns(2)
    crop_min = crop_columns[0].number_input(
        "Crop min (V)", value=-0.47, step=0.01, format="%.3f",
        key="bo_native_crop_min",
    )
    crop_max = crop_columns[1].number_input(
        "Crop max (V)", value=-0.15, step=0.01, format="%.3f",
        key="bo_native_crop_max",
    )
    smooth_window = st.slider(
        "Savitzky-Golay window", 3, 31, 15, 2,
        key="bo_native_smooth_window",
    )
    smooth_polyorder = st.slider(
        "Polynomial order", 1, 5, 2,
        key="bo_native_smooth_polyorder",
    )
    minima_window = st.number_input(
        "Minima search window (V)", value=0.30, step=0.01, format="%.3f",
        key="bo_native_minima_window",
    )
    double_correction = st.checkbox(
        "Double baseline correction", value=True,
        key="bo_native_double_correction",
    )
    enforce_peak = st.checkbox(
        "Enforce min peak height", value=True,
        key="bo_native_enforce_peak",
    )
    min_peak = (
        st.number_input(
            "Min peak height (uA)", value=0.001, step=0.001, format="%.3f",
            key="bo_native_min_peak",
        )
        if enforce_peak else None
    )
    with st.expander("Experimental", expanded=False):
        prominent_minima = st.checkbox(
            "Use prominent local minima for bracketing",
            value=False,
            key="bo_native_prominent_minima",
        )
        wavelet_trace = st.checkbox(
            "Compute wavelet-denoised trace",
            value=False,
            key="bo_native_wavelet_trace",
        )
        wavelet_correction = st.checkbox(
            "Use wavelet-denoised trace for baseline correction",
            value=False,
            disabled=not wavelet_trace,
            key="bo_native_wavelet_correction",
        )
    return {
        "crop_min_v": crop_min,
        "crop_max_v": crop_max,
        "smooth_window": smooth_window,
        "smooth_polyorder": smooth_polyorder,
        "minima_search_window_v": minima_window,
        "use_prominent_minima": prominent_minima,
        "use_double_correction": double_correction,
        "min_peak_height_uA": min_peak,
        "compute_wavelet_denoised_trace": wavelet_trace,
        "use_wavelet_for_correction": wavelet_correction,
    }


def _classic_q_equation(config: dict) -> str:
    scoring = dict((config or {}).get("scoring") or {})
    mode = str(scoring.get("mode", "classic") or "classic").strip().lower()
    weights = dict(scoring.get("channel_weights") or {})
    run = dict(scoring.get("run_weights") or {})
    if mode == "signal_priority_unbounded":
        terms = (
            ("log1p(Raw SNR)", float(weights.get("snr", .45))),
            ("log1p(Peak µA)", float(weights.get("peak_height", .35))),
            ("Baseline", float(weights.get("baseline", .12))),
            ("Shape", float(weights.get("peak_shape", .05))),
            ("Replicate", float(weights.get("replicate_consistency", .03))),
            ("Success", float(weights.get("success", 0))),
        )
        total = max(sum(weight for _name, weight in terms), 1e-12)
        numerator = " + ".join(
            f"{weight:g}·{name}" for name, weight in terms if weight
        ) or "0"
        channel_equation = f"Classic Q_channel = ({numerator}) / {total:g}"
    else:
        terms = (
            ("Raw SNR", float(weights.get("snr", .35))),
            ("Peak µA", float(weights.get("peak_height", 0))),
            ("Shape", float(weights.get("peak_shape", .20))),
            ("Baseline", float(weights.get("baseline", .20))),
            ("Replicate", float(weights.get("replicate_consistency", .15))),
            ("Success", float(weights.get("success", .10))),
        )
        numerator = " + ".join(
            f"{weight:g}·{name}" for name, weight in terms if weight
        ) or "0"
        noise = float(weights.get("noise_penalty", 0))
        channel_equation = (
            f"Classic Q_channel = max(0, {numerator} - {noise:g}·Noise µA)"
        )
    run_equation = (
        "Classic Q_run = mean(Q_channel)"
        f" - {float(run.get('lambda_variability', .20)):g}·std(Q_channel)"
        f" - {float(run.get('lambda_failed', .40)):g}·failed_fraction"
        f" - {float(run.get('lambda_low', .20)):g}·"
        f"fraction(Q_channel < {float(run.get('low_channel_threshold', .50)):g})"
    )
    return f"{channel_equation}\n{run_equation}"


def _paired_q_equation(config: dict) -> str:
    scoring = dict((config or {}).get("scoring") or {})
    weights = dict(scoring.get("paired_response_weights") or {})
    if (
        "standard_quality" in weights
        and "buffer_classic_Q" not in weights
        and "target_classic_Q" not in weights
    ):
        legacy = max(0.0, float(weights.get("standard_quality", 0) or 0))
        weights["buffer_classic_Q"] = legacy / 2
        weights["target_classic_Q"] = legacy / 2
    buffer_weight = float(weights.get("buffer_classic_Q", .25))
    target_weight = float(weights.get("target_classic_Q", .25))
    delta_weight = float(weights.get("delta_peak", 1))
    delta_scale = max(float(weights.get("delta_scale_uA", 1)), 1e-12)
    total = max(buffer_weight + target_weight + delta_weight, 1e-12)
    run = dict(scoring.get("run_weights") or {})
    return (
        "Δpeak = target_peak_height_µA - buffer_peak_height_µA\n"
        f"Δpeak_score = log1p(|Δpeak| / {delta_scale:g})\n"
        "Paired Q_channel = "
        f"({buffer_weight:g}·buffer_classic_Q + "
        f"{target_weight:g}·target_classic_Q + "
        f"{delta_weight:g}·Δpeak_score) / {total:g}\n"
        "If buffer_classic_Q ≤ 0 or target_classic_Q ≤ 0, Paired Q_channel = 0\n"
        "Paired Q_run = max(0, mean(Paired Q_channel)"
        f" - {float(run.get('lambda_variability', .20)):g}·std(Paired Q_channel)"
        f" - {float(run.get('lambda_failed', .40)):g}·failed_fraction"
        f" - {float(run.get('lambda_low', .20)):g}·"
        f"fraction(Paired Q_channel < {float(run.get('low_channel_threshold', .50)):g}))"
    )


def _render_q_equation(config: dict, kind: str) -> None:
    if kind == "paired":
        st.markdown("**Paired Q equation**")
        st.code(_paired_q_equation(config), language=None)
    elif kind == "classic":
        st.markdown("**Classic Q equation**")
        st.code(_classic_q_equation(config), language=None)


def _metric_q_kind(metric: str, paired_objective: bool) -> str | None:
    normalized = str(metric).lower()
    if "contribution" in normalized and "q" in normalized:
        return "paired"
    if "classic_q" in normalized or "classic q" in normalized:
        return "classic"
    if "q" in normalized:
        return "paired" if paired_objective else "classic"
    return None


def _q_weight_context(config: dict) -> dict:
    scoring = dict((config or {}).get("scoring") or {})
    channel = dict(scoring.get("channel_weights") or {})
    paired = dict(scoring.get("paired_response_weights") or {})
    if (
        "standard_quality" in paired
        and "buffer_classic_Q" not in paired
        and "target_classic_Q" not in paired
    ):
        legacy = max(0.0, float(paired.get("standard_quality", 0) or 0))
        paired["buffer_classic_Q"] = legacy / 2
        paired["target_classic_Q"] = legacy / 2
    return {
        "snr": float(channel.get("snr", .35)),
        "peak": float(channel.get("peak_height", 0)),
        "shape": float(channel.get("peak_shape", .20)),
        "baseline": float(channel.get("baseline", .20)),
        "replicate": float(channel.get("replicate_consistency", .15)),
        "success": float(channel.get("success", .10)),
        "noise": float(channel.get("noise_penalty", 0)),
        "buffer_classic": float(paired.get("buffer_classic_Q", .25)),
        "target_classic": float(paired.get("target_classic_Q", .25)),
        "delta_peak": float(paired.get("delta_peak", 1)),
    }


def _metric_impacts_q(
    metric_label: str,
    config: dict,
    paired_objective: bool,
    phase: str | None = None,
) -> bool:
    weights = _q_weight_context(config)
    normalized = metric_label.lower().replace("_", " ")
    if "classic q" in normalized:
        if not paired_objective:
            return True
        if phase == "buffer":
            return weights["buffer_classic"] != 0
        if phase == "target":
            return weights["target_classic"] != 0
        return (
            weights["buffer_classic"] != 0
            or weights["target_classic"] != 0
        )
    if "q" in normalized:
        return True
    classic_enabled = True
    if paired_objective:
        if phase == "buffer":
            classic_enabled = weights["buffer_classic"] != 0
        elif phase == "target":
            classic_enabled = weights["target_classic"] != 0
        else:
            classic_enabled = (
                weights["buffer_classic"] != 0
                or weights["target_classic"] != 0
            )
    if "fractional delta" in normalized:
        return False
    if "delta peak" in normalized:
        return paired_objective and weights["delta_peak"] != 0
    if "peak height" in normalized or normalized in {"peak ua", "peak µa"}:
        return (
            paired_objective and weights["delta_peak"] != 0
        ) or (classic_enabled and weights["peak"] != 0)
    if "raw snr" in normalized or "snr raw" in normalized or normalized == "snr":
        return classic_enabled and weights["snr"] != 0
    if "snr score" in normalized:
        return False  # Display-only normalization; Classic Q uses raw SNR.
    if "shape" in normalized:
        return classic_enabled and weights["shape"] != 0
    if "baseline" in normalized:
        return classic_enabled and weights["baseline"] != 0
    if "replicate" in normalized:
        return classic_enabled and weights["replicate"] != 0
    if "success" in normalized:
        return classic_enabled and weights["success"] != 0
    if "noise" in normalized:
        return classic_enabled and weights["noise"] != 0
    return False


def _history_metric_impacts_q(
    metric: str,
    config: dict,
    paired_objective: bool,
) -> bool:
    if metric in PARAMETERS:
        return True
    normalized = str(metric).lower()
    if paired_objective and "classic_q" in normalized:
        weights = _q_weight_context(config)
        if "buffer_classic_q" in normalized:
            return weights["buffer_classic"] != 0
        if "target_classic_q" in normalized:
            return weights["target_classic"] != 0
        return (
            weights["buffer_classic"] != 0
            or weights["target_classic"] != 0
        )
    if "q" in normalized:
        return True
    return _metric_impacts_q(normalized, config, paired_objective)


def _q_relevant_metrics(
    metrics: dict[str, tuple],
    config: dict,
    paired_objective: bool,
    phase: str | None = None,
) -> list[str]:
    return [
        metric
        for metric in metrics
        if _metric_impacts_q(metric, config, paired_objective, phase)
    ]


def _surrogate_files(root: Path, group_id: int | None = None) -> dict[int, Path]:
    result = {}
    surrogate_dir = root / "surrogate"
    pattern = (
        f"group_{group_id:02d}_iter_*_candidate_predictions.csv"
        if group_id is not None
        else "iter_*_candidate_predictions.csv"
    )
    for path in surrogate_dir.glob(pattern):
        try:
            iteration_index = 3 if group_id is not None else 1
            result[int(path.name.split("_")[iteration_index])] = path
        except (ValueError, IndexError):
            continue
    return result


def _pdf_surrogate_file_index(root: Path) -> tuple[dict[int, Path], dict[int, dict[int, Path]]]:
    ungrouped: dict[int, Path] = {}
    grouped: dict[int, dict[int, Path]] = {}
    surrogate_dir = root / "surrogate"
    if not surrogate_dir.is_dir():
        return ungrouped, grouped
    for path in surrogate_dir.iterdir():
        if not path.is_file() or not path.name.endswith("_candidate_predictions.csv"):
            continue
        group_match = re.fullmatch(
            r"group_(\d+)_iter_(\d+)_candidate_predictions\.csv",
            path.name,
        )
        if group_match:
            group_id = int(group_match.group(1))
            iteration = int(group_match.group(2))
            grouped.setdefault(group_id, {})[iteration] = path
            continue
        iteration_match = re.fullmatch(
            r"iter_(\d+)_candidate_predictions\.csv",
            path.name,
        )
        if iteration_match:
            ungrouped[int(iteration_match.group(1))] = path
    return ungrouped, grouped


def _recompute_group_surrogate(
    session: dict,
    frame: pd.DataFrame,
    iteration: int,
) -> pd.DataFrame:
    """Rebuild group-specific GP predictions and acquisition values."""
    corrected = frame.copy()
    observations = [
        observation
        for observation in session["observations"]
        if int(observation.get("iteration", 0)) <= int(iteration)
    ]
    if not observations or corrected.empty:
        return corrected
    selected_next = next(
        (
            observation
            for observation in session["observations"]
            if int(observation.get("iteration", 0)) == int(iteration) + 1
        ),
        None,
    )
    corrected["selected_next"] = False
    if selected_next is not None:
        selected_key = tuple(
            round(float(selected_next["params"][name]), 9)
            for name in PARAMETERS
        )
        candidate_keys = {
            tuple(round(float(row[name]), 9) for name in PARAMETERS)
            for _, row in corrected.iterrows()
        }
        if selected_key not in candidate_keys:
            appended = {
                name: selected_next["params"][name]
                for name in PARAMETERS
            }
            appended["selected_next"] = True
            corrected = pd.concat(
                [corrected, pd.DataFrame([appended])],
                ignore_index=True,
            )
        else:
            selected_mask = [
                tuple(round(float(row[name]), 9) for name in PARAMETERS)
                == selected_key
                for _, row in corrected.iterrows()
            ]
            corrected.loc[selected_mask, "selected_next"] = True
    config = session.get("config") or {}
    group_id = session.get("selected_group_id")
    if group_id is None:
        observed_ids = {
            int(observation.get("group_id", 1))
            for observation in observations
        }
        group_id = next(iter(observed_ids)) if len(observed_ids) == 1 else 1
    group_stub = next(
        (
            group for group in _session_channel_groups(session)
            if int(group["id"]) == int(group_id)
        ),
        {
            "id": int(group_id),
            "name": f"Group {group_id}",
            "channels": [],
        },
    )
    metadata = _channel_group_optimization_metadata(
        session,
        [group_stub],
    )[0]
    exploration = float(metadata.get("exploration") or 0.0)
    parameter_config = config.get("parameters") or {}

    def encode(values) -> np.ndarray:
        encoded = []
        for name in PARAMETERS:
            definition = parameter_config.get(name) or {}
            numeric = np.asarray(values[name], dtype=float)
            lower = float(definition.get("min", np.nanmin(numeric)))
            upper = float(definition.get("max", np.nanmax(numeric)))
            scale = str(
                definition.get(
                    "scale",
                    definition.get("encoding", ""),
                )
            ).lower()
            if scale in ("log", "log10"):
                numeric = np.log10(np.maximum(numeric, 1e-12))
                lower = np.log10(max(lower, 1e-12))
                upper = np.log10(max(upper, 1e-12))
            encoded.append(
                (numeric - lower) / (upper - lower + 1e-12)
            )
        return np.column_stack(encoded)

    best_q = max(float(observation["Q_run"]) for observation in observations)
    means = pd.to_numeric(
        corrected.get("predicted_mean_Q"),
        errors="coerce",
    ).to_numpy(dtype=float)
    stds = pd.to_numeric(
        corrected.get("predicted_std_Q"),
        errors="coerce",
    ).to_numpy(dtype=float)
    if len(observations) >= 2:
        try:
            training_frame = pd.DataFrame([
                observation["params"] for observation in observations
            ])
            x_train = encode(training_frame)
            y_train = np.asarray(
                [float(observation["Q_run"]) for observation in observations],
                dtype=float,
            )
            x_candidates = encode(corrected)
            falloffs = metadata.get("gp_falloff_fractions") or {}
            length_scales = [
                max(1e-9, float(falloffs.get(name, 1.0)))
                for name in PARAMETERS
            ]
            acquisition_config = config.get("acquisition") or {}
            noise = max(
                1e-10,
                float(acquisition_config.get("gp_noise_level", 1e-4) or 1e-4),
            )

            def matern_kernel(left, right):
                scaled = (
                    left[:, None, :] - right[None, :, :]
                ) / np.asarray(length_scales)[None, None, :]
                distance = np.sqrt(np.sum(scaled * scaled, axis=2))
                root5_distance = np.sqrt(5.0) * distance
                return (
                    1.0
                    + root5_distance
                    + root5_distance ** 2 / 3.0
                ) * np.exp(-root5_distance)

            y_mean = float(y_train.mean())
            y_scale = float(y_train.std())
            if y_scale < 1e-12:
                y_scale = 1.0
            normalized_y = (y_train - y_mean) / y_scale
            covariance = matern_kernel(x_train, x_train)
            identity = np.eye(len(x_train), dtype=float)
            jitter = noise
            cholesky = None
            for _attempt in range(8):
                try:
                    cholesky = np.linalg.cholesky(
                        covariance + identity * jitter
                    )
                    break
                except np.linalg.LinAlgError:
                    jitter *= 10.0
            if cholesky is None:
                raise np.linalg.LinAlgError(
                    "GP covariance is not positive definite"
                )
            alpha = np.linalg.solve(
                cholesky.T,
                np.linalg.solve(cholesky, normalized_y),
            )
            cross_covariance = matern_kernel(x_candidates, x_train)
            means = y_mean + y_scale * (cross_covariance @ alpha)
            projected = np.linalg.solve(
                cholesky,
                cross_covariance.T,
            )
            normalized_variance = np.maximum(
                1.0 + jitter - np.sum(projected * projected, axis=0),
                1e-12,
            )
            stds = y_scale * np.sqrt(normalized_variance)
        except Exception:
            # Retain saved predictions, but still correct the acquisition blend.
            pass
    else:
        x_observed = encode(pd.DataFrame([
            observations[0]["params"]
        ]))[0]
        x_candidates = encode(corrected)
        distances = np.sqrt(
            np.sum((x_candidates - x_observed[None, :]) ** 2, axis=1)
        )
        means = np.full(
            len(corrected),
            float(observations[0]["Q_run"]),
        )
        stds = np.maximum(distances, 0.05)
    stds = np.maximum(np.asarray(stds, dtype=float), 1e-12)
    means = np.asarray(means, dtype=float)
    improvement = means - best_q - 0.01
    z_score = improvement / stds
    expected_improvement = (
        improvement * ndtr(z_score)
        + stds * np.exp(-0.5 * z_score ** 2) / np.sqrt(2.0 * np.pi)
    )
    corrected["predicted_mean_Q"] = means
    corrected["predicted_std_Q"] = stds
    corrected["acquisition_value"] = (
        (1.0 - exploration) * (means + 0.25 * expected_improvement)
        + exploration * stds
    )
    corrected["best_observed_Q"] = best_q
    tested = {
        tuple(round(float(observation["params"][name]), 9) for name in PARAMETERS)
        for observation in observations
    }
    corrected["already_tested"] = [
        tuple(round(float(row[name]), 9) for name in PARAMETERS) in tested
        for _, row in corrected.iterrows()
    ]
    return corrected


def _observed_points(session: dict, iteration: int, axes: list[str]):
    """Return history through the next observation chosen from an artifact."""
    rows = []
    for obs in session["observations"]:
        if int(obs.get("iteration", 0)) > iteration + 1:
            continue
        params = obs.get("params") or {}
        if all(params.get(axis) is not None for axis in axes):
            rows.append(obs)
    return sorted(rows, key=lambda obs: int(obs.get("iteration", 0)))


def _observed_iterations(observed: list[dict]) -> np.ndarray:
    return np.asarray([int(obs.get("iteration", 0)) for obs in observed], dtype=float)


def _iteration_norm(iterations: np.ndarray) -> Normalize:
    minimum = float(np.min(iterations))
    maximum = float(np.max(iterations))
    if minimum == maximum:
        maximum = minimum + 1.0
    return Normalize(vmin=minimum, vmax=maximum)


def _plot_observed_path(
    ax,
    x,
    y,
    observed: list[dict],
    *,
    label: str,
    value_norm: Normalize | None,
    marker_size: float = 28,
    show_iteration_path: bool = True,
) -> None:
    iterations = _observed_iterations(observed)
    norm = _iteration_norm(iterations)
    measured = np.asarray([float(obs["Q_run"]) for obs in observed])
    points = np.column_stack((x, y))
    if show_iteration_path and len(points) > 1:
        segments = np.stack((points[:-1], points[1:]), axis=1)
        lines = LineCollection(
            segments,
            cmap=OBSERVED_PATH_CMAP,
            norm=norm,
            linewidth=1.6,
            zorder=4,
        )
        lines.set_array(iterations[1:])
        ax.add_collection(lines)
    marker_colors = (
        {"c": measured, "cmap": "viridis", "norm": value_norm}
        if value_norm is not None
        else {"color": "#111111"}
    )
    ax.scatter(
        x, y, **marker_colors, s=marker_size, label=label, zorder=3
    )
    if show_iteration_path:
        iteration_map = plt.cm.ScalarMappable(
            norm=norm,
            cmap=OBSERVED_PATH_CMAP,
        )
        ax.figure.colorbar(iteration_map, ax=ax, label="Iteration")


def _surrogate_slice_base_params(session: dict, iteration: int) -> dict:
    observations = [
        observation for observation in session["observations"]
        if int(observation.get("iteration", 0)) <= int(iteration) + 1
    ]
    selected = next(
        (
            observation for observation in observations
            if int(observation.get("iteration", 0)) == int(iteration) + 1
        ),
        None,
    )
    if selected is None and observations:
        selected = max(
            observations,
            key=lambda observation: float(observation.get("Q_run", 0.0)),
        )
    base = dict((selected or {}).get("params") or {})
    initial = dict((session.get("config") or {}).get("initial_parameters") or {})
    for name in PARAMETERS:
        if base.get(name) is None and initial.get(name) is not None:
            base[name] = initial[name]
    return base


def _parameter_grid_values(
    session: dict,
    frame: pd.DataFrame,
    name: str,
    grid_size: int,
    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
) -> np.ndarray | None:
    definition = ((session.get("config") or {}).get("parameters") or {}).get(name) or {}
    values = pd.to_numeric(frame.get(name), errors="coerce").dropna()
    bounds = (axis_ranges or {}).get(name)
    if bounds is not None:
        lower = float(bounds[0])
        upper = float(bounds[1])
    else:
        try:
            lower = float(definition.get("min"))
            upper = float(definition.get("max"))
        except (TypeError, ValueError):
            if values.empty:
                return None
            lower = float(values.min())
            upper = float(values.max())
    if bounds is None and (not np.isfinite(lower) or not np.isfinite(upper)):
        if values.empty:
            return None
        lower = float(values.min())
        upper = float(values.max())
    if not np.isfinite(lower) or not np.isfinite(upper):
        return None
    if np.isclose(lower, upper):
        if values.nunique() > 1:
            lower = float(values.min())
            upper = float(values.max())
        else:
            return None
    scale = str(
        definition.get(
            "scale",
            definition.get("encoding", ""),
        )
    ).lower()
    if scale in ("log", "log10"):
        lower = max(lower, 1e-12)
        upper = max(upper, lower * (1.0 + 1e-9))
        return np.logspace(np.log10(lower), np.log10(upper), grid_size)
    return np.linspace(lower, upper, grid_size)


def _base_parameter_value(
    session: dict,
    frame: pd.DataFrame,
    base_params: dict,
    name: str,
) -> float:
    try:
        return float(base_params.get(name))
    except (TypeError, ValueError):
        pass
    initial = (session.get("config") or {}).get("initial_parameters") or {}
    try:
        return float(initial.get(name))
    except (TypeError, ValueError):
        pass
    values = pd.to_numeric(frame.get(name), errors="coerce").dropna()
    if not values.empty:
        return float(values.median())
    return 0.0


def _surrogate_regular_2d_grid(
    session: dict,
    frame: pd.DataFrame,
    iteration: int,
    value: str,
    x_name: str,
    y_name: str,
    base_params: dict,
    grid_size: int = 75,
    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
    if x_name == y_name or value not in SURROGATE_VALUES:
        return None
    size = max(20, min(160, int(grid_size)))
    x_values = _parameter_grid_values(
        session,
        frame,
        x_name,
        size,
        axis_ranges=axis_ranges,
    )
    y_values = _parameter_grid_values(
        session,
        frame,
        y_name,
        size,
        axis_ranges=axis_ranges,
    )
    if x_values is None or y_values is None:
        return None
    mesh_x, mesh_y = np.meshgrid(x_values, y_values)

    def grid_base_value(name: str) -> float:
        if name not in {x_name, y_name} and name in frame.columns:
            values = pd.to_numeric(frame[name], errors="coerce").dropna()
            if not values.empty and values.nunique(dropna=True) == 1:
                return float(values.iloc[0])
        return _base_parameter_value(session, frame, base_params, name)

    grid_frame = pd.DataFrame({
        name: np.full(mesh_x.size, grid_base_value(name))
        for name in PARAMETERS
    })
    grid_frame[x_name] = mesh_x.ravel()
    grid_frame[y_name] = mesh_y.ravel()
    for surrogate_value in SURROGATE_VALUES:
        grid_frame[surrogate_value] = np.nan
    try:
        predicted = _recompute_group_surrogate(
            session,
            grid_frame,
            iteration,
        ).iloc[:len(grid_frame)]
        z_values = pd.to_numeric(
            predicted[value],
            errors="coerce",
        ).to_numpy(dtype=float).reshape(mesh_x.shape)
    except Exception:
        return None
    if not np.isfinite(z_values).any():
        return None
    return x_values, y_values, z_values


def _plot_surrogate_2d_control_style(
    ax,
    session: dict,
    display_frame: pd.DataFrame,
    iteration: int,
    value: str,
    x_name: str,
    y_name: str,
    selected_next_frame: pd.DataFrame,
    *,
    dot_size: int = 6,
    log_frequency: bool = False,
    show_iteration_path: bool = True,
    show_observed_points: bool = True,
    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
    observed_slice_axis: str | None = None,
    observed_slice_value: float | None = None,
):
    """Render 2D surrogate maps with the control-software slice style."""
    base_params = _surrogate_slice_base_params(session, iteration)
    grid = _surrogate_regular_2d_grid(
        session,
        display_frame,
        iteration,
        value,
        x_name,
        y_name,
        base_params,
        axis_ranges=axis_ranges,
    )
    if grid is not None:
        x_values, y_values, z_values = grid
        mesh = ax.pcolormesh(
            x_values,
            y_values,
            np.ma.masked_invalid(z_values),
            cmap="viridis",
            shading="auto",
        )
    else:
        valid = display_frame[[x_name, y_name, value]].apply(
            pd.to_numeric,
            errors="coerce",
        ).dropna()
        if valid.empty:
            ax.text(.5, .5, "No plottable surrogate rows", ha="center", va="center")
            ax.set_axis_off()
            return None
        mesh = ax.scatter(
            valid[x_name],
            valid[y_name],
            c=valid[value],
            cmap="viridis",
            s=max(10, dot_size ** 2),
            alpha=.8,
        )
    observed_axes = [x_name, y_name]
    if (
        observed_slice_axis is not None
        and observed_slice_value is not None
        and observed_slice_axis not in observed_axes
    ):
        observed_axes.append(observed_slice_axis)
    observed = _observed_points(session, iteration, observed_axes)
    if (
        observed
        and observed_slice_axis is not None
        and observed_slice_value is not None
    ):
        filtered_observed = []
        for obs in observed:
            try:
                observed_value = float(
                    (obs.get("params") or {}).get(observed_slice_axis)
                )
            except (TypeError, ValueError):
                continue
            if np.isclose(
                observed_value,
                float(observed_slice_value),
                rtol=1e-9,
                atol=1e-12,
            ):
                filtered_observed.append(obs)
        observed = filtered_observed
    if observed and (show_iteration_path or show_observed_points):
        observed_x = [float(obs["params"][x_name]) for obs in observed]
        observed_y = [float(obs["params"][y_name]) for obs in observed]
        observed_iterations = _observed_iterations(observed)
        iteration_norm = _iteration_norm(observed_iterations)
        if show_iteration_path:
            if len(observed) > 1:
                points = np.column_stack((observed_x, observed_y))
                segments = np.stack((points[:-1], points[1:]), axis=1)
                lines = LineCollection(
                    segments,
                    cmap=OBSERVED_PATH_CMAP,
                    norm=iteration_norm,
                    linewidth=1.6,
                    zorder=4,
                )
                lines.set_array(observed_iterations[1:])
                ax.add_collection(lines)
            if show_observed_points:
                ax.scatter(
                    observed_x,
                    observed_y,
                    color="#111111",
                    edgecolors="white",
                    linewidths=0.4,
                    s=max(18, dot_size ** 2),
                    label="observed runs",
                    zorder=5,
                )
            iteration_map = plt.cm.ScalarMappable(
                norm=iteration_norm,
                cmap=OBSERVED_PATH_CMAP,
            )
            ax.figure.colorbar(iteration_map, ax=ax, label="Iteration")
        elif show_observed_points:
            ax.scatter(
                observed_x,
                observed_y,
                color="#111111",
                edgecolors="#111111",
                linewidths=0.4,
                s=max(18, dot_size ** 2),
                label="observed runs",
                zorder=5,
            )
    if (
        not selected_next_frame.empty
        and x_name in selected_next_frame.columns
        and y_name in selected_next_frame.columns
    ):
        selected_row = selected_next_frame.iloc[0]
        if pd.notna(selected_row[x_name]) and pd.notna(selected_row[y_name]):
            ax.scatter(
                [selected_row[x_name]],
                [selected_row[y_name]],
                color="#ffd166",
                edgecolors="black",
                linewidths=1.0,
                s=(dot_size + 8) ** 2,
                zorder=6,
                label=f"selected next iteration {iteration + 1}",
            )
    ax.set_xlabel(x_name, fontsize=9, labelpad=4)
    ax.set_ylabel(y_name, fontsize=9, labelpad=4)
    if log_frequency and x_name == "frequency":
        ax.set_xscale("log")
    if log_frequency and y_name == "frequency":
        ax.set_yscale("log")
    ax.tick_params(labelsize=8)
    ax.grid(alpha=.2)
    return mesh


def _plot_chronological_surrogate_2d_stack(
    session: dict,
    group_files: dict[int, Path],
    artifact_iteration: int,
    value: str,
    x_name: str,
    y_name: str,
    *,
    x_offset_fraction: float = 0.02,
    y_offset_fraction: float = 0.05,
    map_alpha: float = 0.55,
    log_frequency: bool = False,
    crop_ranges: Mapping[str, tuple[float, float]] | None = None,
    slice_column: str | None = None,
    slice_value: float | None = None,
    progress_callback=None,
):
    """Render saved 2D surrogate maps as a diagonal chronological stack."""
    frame_iterations = [
        iteration
        for iteration in sorted(group_files)
        if int(iteration) <= int(artifact_iteration)
    ]
    maps = []
    errors = []

    def axis_values(values, axis_name):
        output = np.asarray(values, dtype=float)
        if log_frequency and axis_name == "frequency":
            return np.log10(np.clip(output, 1e-12, None))
        return output

    total_frames = len(frame_iterations)
    for frame_index, frame_iteration in enumerate(frame_iterations, start=1):
        if progress_callback is not None:
            progress_callback(frame_index, total_frames, frame_iteration)
        try:
            predictions = pd.read_csv(group_files[frame_iteration])
            predictions = _recompute_group_surrogate(
                session,
                predictions,
                frame_iteration,
            )
            predictions = _apply_numeric_slice(
                predictions,
                slice_column,
                slice_value,
            )
            if crop_ranges:
                predictions = _apply_parameter_crop(
                    predictions,
                    crop_ranges,
                ).reset_index(drop=True)
                if predictions.empty:
                    continue
            if not all(
                name in predictions.columns
                for name in (x_name, y_name, value)
            ):
                continue
            display_frame = _surrogate_display_frame(predictions, value)
            base_params = _surrogate_slice_base_params(session, frame_iteration)
            grid = _surrogate_regular_2d_grid(
                session,
                display_frame,
                frame_iteration,
                value,
                x_name,
                y_name,
                base_params,
                axis_ranges=crop_ranges,
            )
            if grid is None:
                valid = display_frame[[x_name, y_name, value]].apply(
                    pd.to_numeric,
                    errors="coerce",
                ).dropna()
                if valid.empty:
                    continue
                maps.append({
                    "iteration": int(frame_iteration),
                    "kind": "scatter",
                    "x": axis_values(valid[x_name], x_name),
                    "y": axis_values(valid[y_name], y_name),
                    "z": valid[value].to_numpy(dtype=float),
                })
            else:
                x_values, y_values, z_values = grid
                maps.append({
                    "iteration": int(frame_iteration),
                    "kind": "grid",
                    "x": axis_values(x_values, x_name),
                    "y": axis_values(y_values, y_name),
                    "z": z_values,
                })
        except Exception as exc:
            errors.append(f"Artifact iteration {frame_iteration}: {exc}")

    fig, ax = plt.subplots(figsize=(9, 5.8))
    if not maps:
        ax.text(.5, .5, "No plottable 2D surrogate maps.", ha="center", va="center")
        ax.set_axis_off()
        return fig, errors

    x_min = min(float(np.nanmin(item["x"])) for item in maps)
    x_max = max(float(np.nanmax(item["x"])) for item in maps)
    y_min = min(float(np.nanmin(item["y"])) for item in maps)
    y_max = max(float(np.nanmax(item["y"])) for item in maps)
    x_span = max(x_max - x_min, 1e-9)
    y_span = max(y_max - y_min, 1e-9)
    z_values = np.concatenate([
        np.asarray(item["z"], dtype=float).ravel()
        for item in maps
    ])
    z_values = z_values[np.isfinite(z_values)]
    z_min = float(np.nanmin(z_values)) if len(z_values) else 0.0
    z_max = float(np.nanmax(z_values)) if len(z_values) else 1.0
    if np.isclose(z_min, z_max):
        z_max = z_min + 1.0
    value_norm = Normalize(z_min, z_max)
    cmap = plt.get_cmap("viridis")
    iteration_minimum = min(item["iteration"] for item in maps)
    iteration_maximum = max(item["iteration"] for item in maps)
    iteration_span = max(1, iteration_maximum - iteration_minimum)
    x_step = x_span * float(x_offset_fraction)
    y_step = y_span * float(y_offset_fraction)

    for item in maps:
        offset_index = item["iteration"] - iteration_minimum
        age = offset_index / iteration_span
        alpha = max(0.05, min(1.0, 0.12 + float(map_alpha) * age))
        shifted_x = item["x"] + offset_index * x_step
        shifted_y = item["y"] + offset_index * y_step
        if item["kind"] == "grid":
            ax.pcolormesh(
                shifted_x,
                shifted_y,
                np.ma.masked_invalid(item["z"]),
                cmap=cmap,
                norm=value_norm,
                shading="auto",
                alpha=alpha,
                linewidth=0,
            )
        else:
            ax.scatter(
                shifted_x,
                shifted_y,
                c=item["z"],
                cmap=cmap,
                norm=value_norm,
                s=10,
                alpha=alpha,
                linewidths=0,
            )

    shifted_left_edges = [
        (
            float(np.nanmin(item["x"])) + (item["iteration"] - iteration_minimum) * x_step,
            float(np.nanmean(item["y"])) + (item["iteration"] - iteration_minimum) * y_step,
            item["iteration"],
        )
        for item in maps
    ]
    oldest_edge = min(shifted_left_edges, key=lambda item: item[2])
    newest_edge = max(shifted_left_edges, key=lambda item: item[2])
    axis_dx = newest_edge[0] - oldest_edge[0]
    axis_dy = newest_edge[1] - oldest_edge[1]
    if np.isclose(axis_dx, 0.0) and np.isclose(axis_dy, 0.0):
        axis_dx = x_span * 0.18
    axis_length = math.hypot(axis_dx, axis_dy)
    normal_x = -axis_dy / axis_length if axis_length > 0 else -1.0
    normal_y = axis_dx / axis_length if axis_length > 0 else 0.0
    if normal_x > 0:
        normal_x *= -1
        normal_y *= -1
    side_gap = x_span * 0.06
    axis_start = (
        oldest_edge[0] - 0.04 * axis_dx + normal_x * side_gap,
        oldest_edge[1] - 0.04 * axis_dy + normal_y * side_gap,
    )
    axis_end = (
        newest_edge[0] + 0.04 * axis_dx + normal_x * side_gap,
        newest_edge[1] + 0.04 * axis_dy + normal_y * side_gap,
    )
    ax.annotate(
        "",
        xy=axis_end,
        xytext=axis_start,
        arrowprops={
            "arrowstyle": "-|>",
            "color": "#222222",
            "linewidth": 1.8,
            "shrinkA": 0,
            "shrinkB": 0,
            "mutation_scale": 12,
        },
        zorder=8,
    )
    ax.text(
        axis_end[0],
        axis_end[1],
        " increasing iteration",
        fontsize=8,
        color="#222222",
        ha="left" if axis_dx >= 0 else "right",
        va="bottom" if axis_dy >= 0 else "top",
        zorder=8,
    )
    ax.text(
        oldest_edge[0],
        oldest_edge[1],
        f"Oldest: iter {oldest_edge[2]}",
        fontsize=8,
        color="#666666",
    )
    ax.text(
        newest_edge[0],
        newest_edge[1],
        f"Newest: iter {newest_edge[2]}",
        fontsize=8,
        color="#111111",
    )

    colorbar = fig.colorbar(
        plt.cm.ScalarMappable(norm=value_norm, cmap=cmap),
        ax=ax,
        pad=.02,
        shrink=.72,
    )
    colorbar.set_label(SURROGATE_VALUE_LABELS.get(value, value))
    ax.set_title(
        f"Chronological diagonal 2D map stack | {value}",
        fontsize=12,
    )
    ax.set_xlabel("")
    ax.set_ylabel("")
    ax.set_xticks([])
    ax.set_yticks([])
    ax.grid(False)
    for spine in ax.spines.values():
        spine.set_visible(False)
    ax.set_facecolor("white")
    fig.patch.set_alpha(1)
    fig.add_artist(Line2D([.22, .86], [.055, .055], transform=fig.transFigure, color="#222222", linewidth=1.1))
    fig.text(.50, .025, x_name, ha="center", va="center", fontsize=9)
    fig.add_artist(Line2D([.955, .955], [.18, .78], transform=fig.transFigure, color="#222222", linewidth=1.1))
    fig.text(
        .985,
        .46,
        y_name,
        ha="center",
        va="center",
        rotation=90,
        fontsize=9,
    )
    fig.subplots_adjust(left=.03, right=.90, bottom=.08, top=.88)
    return fig, errors


def _iteration_parameter_text(observation: dict | None) -> str:
    params = (observation or {}).get("params") or {}
    parts = []
    for label, key, unit in (
        ("Frequency", "frequency", "Hz"),
        ("Step size", "step_potential", "V"),
        ("Amplitude", "amplitude", "V"),
    ):
        value = params.get(key)
        try:
            parts.append(f"{label}={float(value):g} {unit}")
        except (TypeError, ValueError):
            parts.append(f"{label}=unknown")
    return " | ".join(parts)


def _surrogate_display_frame(frame: pd.DataFrame, value: str) -> pd.DataFrame:
    if value != "acquisition_value" or "already_tested" not in frame.columns:
        return frame
    eligible = ~frame["already_tested"].fillna(False).astype(bool)
    if "selected_next" in frame.columns:
        eligible |= frame["selected_next"].fillna(False).astype(bool)
    return frame.loc[eligible].copy()


def _surrogate_valid_plot_frame(
    frame: pd.DataFrame,
    value: str,
    view: str,
    x_name: str,
    y_name: str | None,
    z_name: str | None,
) -> pd.DataFrame:
    display_frame = _surrogate_display_frame(frame, value)
    if view == "3D tensor":
        plot_columns = [x_name, y_name, z_name, value]
    elif view == "2D map":
        plot_columns = [x_name, y_name, value]
    else:
        plot_columns = [x_name, value]
    plot_columns = [column for column in plot_columns if column is not None]
    valid = display_frame[plot_columns].copy()
    for column in plot_columns:
        valid[column] = pd.to_numeric(valid[column], errors="coerce")
    return valid.dropna(subset=plot_columns)


def _surrogate_candidate_accounting_text(
    session: dict,
    group: dict | None,
    predictions: pd.DataFrame,
    value: str,
    view: str,
    x_name: str,
    y_name: str | None,
    z_name: str | None,
    show_local_pool: bool = True,
) -> str:
    config = session.get("config") or {}
    acquisition = config.get("acquisition") or {}
    requested_pool_size = acquisition.get(
        "candidate_pool_size",
        config.get("candidate_pool_size"),
    )
    requested_local_pool_size = acquisition.get(
        "local_candidate_pool_size",
        config.get("local_candidate_pool_size"),
    )
    group_id = None if group is None else int(group["id"])
    for raw_group in (
        (config.get("channel_groups") or [])
        + ((session.get("state") or {}).get("channel_groups") or [])
    ):
        try:
            if group_id is not None and int(raw_group.get("id")) == group_id:
                requested_pool_size = raw_group.get(
                    "candidate_pool_size",
                    requested_pool_size,
                )
                requested_local_pool_size = raw_group.get(
                    "local_candidate_pool_size",
                    requested_local_pool_size,
                )
        except (TypeError, ValueError):
            continue
    state_candidate_count = (session.get("state") or {}).get("candidate_count")
    valid = _surrogate_valid_plot_frame(
        predictions,
        value,
        view,
        x_name,
        y_name,
        z_name,
    )
    source_column = _surrogate_pool_source_column(predictions)
    prediction_local_mask = _surrogate_local_pool_mask(predictions)
    local_count = int(prediction_local_mask.sum())
    local_mask = prediction_local_mask.reindex(valid.index, fill_value=False)
    selected_mask = (
        predictions["selected_next"].fillna(False).astype(bool)
        if "selected_next" in predictions.columns
        else pd.Series(False, index=predictions.index)
    ).reindex(valid.index, fill_value=False)
    if not show_local_pool and local_count:
        valid = valid.loc[~local_mask | selected_mask].copy()
    displayed_local_count = int(
        local_mask.reindex(valid.index, fill_value=False).sum()
    )
    displayed_columns = [
        column for column in (x_name, y_name, z_name)
        if column is not None and column in valid.columns
    ]
    unique_displayed = (
        len(valid.drop_duplicates(displayed_columns))
        if displayed_columns
        else len(valid)
    )
    parts = [
        "requested pool target: "
        f"{requested_pool_size if requested_pool_size is not None else 'unknown'}",
        (
            "requested local pool target: "
            f"{requested_local_pool_size if requested_local_pool_size is not None else 'unknown'}"
        ),
        "valid saved candidate count: "
        f"{state_candidate_count if state_candidate_count is not None else 'unknown'}",
        f"saved prediction rows: {len(predictions):,}",
        f"plotted rows: {len(valid):,}",
    ]
    try:
        requested_pool_number = int(requested_pool_size)
        saved_pool_number = int(state_candidate_count)
    except (TypeError, ValueError):
        requested_pool_number = None
        saved_pool_number = None
    if (
        requested_pool_number is not None
        and saved_pool_number is not None
        and saved_pool_number < requested_pool_number
    ):
        parts.append(
            "saved pool is smaller than requested because invalid or duplicate "
            "candidate draws were filtered during generation"
        )
    if view != "1D slice":
        parts.append(
            "unique displayed coordinates: "
            f"{unique_displayed:,}"
        )
    if source_column is None:
        parts.append("pool source metadata: absent")
    else:
        parts.append(
            f"pool source metadata: {source_column}; local rows: {local_count:,}; "
            f"plotted local rows: {displayed_local_count:,}; "
            f"local rows {'shown' if show_local_pool else 'hidden'}"
        )
    if {"step_potential", "frequency"}.issubset(predictions.columns):
        step_values = pd.to_numeric(
            predictions["step_potential"],
            errors="coerce",
        )
        frequency_values = pd.to_numeric(
            predictions["frequency"],
            errors="coerce",
        )
        effective_scan_rate = step_values * frequency_values
        finite_scan_rate = effective_scan_rate[np.isfinite(effective_scan_rate)]
        constraints = config.get("constraints") or {}
        max_effective_scan_rate = constraints.get("max_effective_scan_rate")
        if not finite_scan_rate.empty:
            scan_rate_text = (
                "effective scan-rate range: "
                f"{float(finite_scan_rate.min()):.4g}-"
                f"{float(finite_scan_rate.max()):.4g} V/s"
            )
            try:
                max_scan_rate = float(max_effective_scan_rate)
            except (TypeError, ValueError):
                max_scan_rate = None
            if max_scan_rate is not None:
                over_limit = int((finite_scan_rate > max_scan_rate).sum())
                scan_rate_text += (
                    f"; configured max: {max_scan_rate:.4g} V/s; "
                    f"rows over max: {over_limit:,}"
                )
            parts.append(scan_rate_text)
    if value == "acquisition_value" and "already_tested" in predictions.columns:
        tested = int(predictions["already_tested"].fillna(False).astype(bool).sum())
        parts.append(f"already-tested rows hidden from acquisition: {tested:,}")
    return "Candidate accounting: " + "; ".join(parts) + "."


def _surrogate_pool_source_column(frame: pd.DataFrame) -> str | None:
    for column in (
        "is_local_candidate",
        "is_local_pool",
        "local_candidate",
        "local_pool",
        "pool_source",
        "candidate_source",
        "candidate_pool",
        "pool",
        "source",
        "origin",
    ):
        if column in frame.columns:
            return column
    return None


def _surrogate_local_pool_mask(frame: pd.DataFrame) -> pd.Series:
    source_column = _surrogate_pool_source_column(frame)
    if source_column is None:
        return pd.Series(False, index=frame.index)
    values = frame[source_column]
    if pd.api.types.is_bool_dtype(values):
        return values.fillna(False).astype(bool)
    normalized = values.fillna("").astype(str).str.lower()
    if source_column in {
        "is_local_candidate",
        "is_local_pool",
        "local_candidate",
        "local_pool",
    }:
        return normalized.isin({"1", "true", "yes", "y", "local"})
    return normalized.str.contains(
        "local",
        regex=False,
    )


def _surrogate_parameter_context(
    session: dict,
    iteration: int,
) -> str:
    selected_observation = next(
        (
            observation for observation in session["observations"]
            if int(observation.get("iteration", 0)) == int(iteration) + 1
        ),
        None,
    )
    artifact_observation = next(
        (
            observation for observation in session["observations"]
            if int(observation.get("iteration", 0)) == int(iteration)
        ),
        None,
    )
    if selected_observation is not None:
        return (
            f"selected iteration {iteration + 1}: "
            f"{_iteration_parameter_text(selected_observation)}"
        )
    return (
        f"no completed iteration {iteration + 1}; "
        f"artifact iteration {iteration}: "
        f"{_iteration_parameter_text(artifact_observation)}"
    )


def _plot_surrogate(session: dict, frame: pd.DataFrame, iteration: int, value: str, view: str,
                    x_name: str, y_name: str | None, z_name: str | None,
                    tensor_height: int = 620, dot_size: int = 6,
                    dot_opacity: float = 0.45,
                    log_frequency: bool = False,
                    show_iteration_path: bool = True,
                    show_observed_points: bool = True,
                    show_local_pool: bool = False,
                    axis_ranges: Mapping[str, tuple[float, float]] | None = None,
                    slice_axis: str | None = None,
                    slice_value: float | None = None,
                    observed_slice_axis: str | None = None,
                    observed_slice_value: float | None = None,
                    slice_sweep_values: Sequence[float] | None = None,
                    title_note: str | None = None):
    parameter_context = _surrogate_parameter_context(session, iteration)
    title = (
        f"{view} | {value} | artifact iteration {iteration}<br>"
        f"{parameter_context}"
    )
    if title_note:
        title = f"{title}<br>{title_note}"
    display_frame = _surrogate_display_frame(frame, value)
    pool_source_column = _surrogate_pool_source_column(display_frame)
    if (
        pool_source_column is not None
        and not show_local_pool
        and view != "3D tensor"
    ):
        local_mask = _surrogate_local_pool_mask(display_frame)
        selected_mask = (
            display_frame["selected_next"].fillna(False).astype(bool)
            if "selected_next" in display_frame.columns
            else pd.Series(False, index=display_frame.index)
        )
        display_frame = display_frame.loc[~local_mask | selected_mask].copy()
    selected_next_frame = (
        display_frame.loc[
            display_frame["selected_next"].fillna(False).astype(bool)
        ]
        if "selected_next" in display_frame.columns
        else pd.DataFrame()
    )
    if view == "3D tensor":
        plot_columns = [x_name, y_name, z_name, value]
        if pool_source_column is not None:
            plot_columns.append(pool_source_column)
        if "selected_next" in display_frame.columns:
            plot_columns.append("selected_next")
        valid = display_frame[plot_columns].copy()
        for column in (x_name, y_name, z_name, value):
            valid[column] = pd.to_numeric(valid[column], errors="coerce")
        valid = valid.dropna(subset=[x_name, y_name, z_name, value])
        if valid.empty:
            fig = go.Figure()
            fig.add_annotation(
                text=(
                    "No candidate rows to plot. Enable Show local-pool "
                    "candidates if this artifact only contains local-pool rows."
                ),
                x=0.5,
                y=0.5,
                xref="paper",
                yref="paper",
                showarrow=False,
            )
            fig.update_layout(height=tensor_height)
            return fig
        prediction_min = float(valid[value].min())
        prediction_max = float(valid[value].max())
        if prediction_min == prediction_max:
            prediction_max = prediction_min + 1.0
        fig = go.Figure()

        def add_prediction_trace(
            rows: pd.DataFrame,
            name: str,
            hover_extra: str,
            *,
            outline: bool = False,
            opacity: float = dot_opacity,
            line_width: int = 2,
        ) -> None:
            trace_x = rows[x_name] if not rows.empty else [None]
            trace_y = rows[y_name] if not rows.empty else [None]
            trace_z = rows[z_name] if not rows.empty else [None]
            trace_color = rows[value] if not rows.empty else [prediction_min]
            trace_customdata = rows[value] if not rows.empty else [np.nan]
            marker = {
                "size": dot_size,
                "color": trace_color,
                "colorscale": "Viridis",
                "cmin": prediction_min,
                "cmax": prediction_max,
                "opacity": opacity,
                "symbol": "circle",
                "showscale": len(fig.data) == 0,
                "colorbar": {
                    "title": SURROGATE_VALUE_LABELS.get(value, value),
                    "x": 0.84,
                    "y": 0.48,
                    "len": 0.68,
                },
            }
            if outline:
                marker["line"] = {"color": "#111111", "width": line_width}
            fig.add_trace(go.Scatter3d(
                x=trace_x,
                y=trace_y,
                z=trace_z,
                mode="markers",
                name=name,
                marker=marker,
                customdata=trace_customdata,
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"{z_name}: %{{z:.4g}}<br>{value}: %{{customdata:.4g}}"
                    f"<extra>{hover_extra}</extra>"
                ),
            ))

        if pool_source_column is not None:
            valid_local_mask = _surrogate_local_pool_mask(valid)
            selected_mask = (
                valid["selected_next"].fillna(False).astype(bool)
                if "selected_next" in valid.columns
                else pd.Series(False, index=valid.index)
            )
            local_rows = valid.loc[valid_local_mask].copy()
            nonlocal_rows = valid.loc[~valid_local_mask | selected_mask].copy()
            add_prediction_trace(
                nonlocal_rows,
                "Candidate predictions",
                "Candidate",
            )
            add_prediction_trace(
                local_rows,
                "Local-pool candidates",
                "Local pool",
                outline=True,
                opacity=min(1.0, dot_opacity + 0.33) if show_local_pool else 0.0,
                line_width=2 if show_local_pool else 0,
            )
        else:
            add_prediction_trace(
                valid,
                "Candidate predictions",
                "Candidate",
            )
        valid_slice_values = []
        if slice_sweep_values:
            for raw_slice_value in slice_sweep_values:
                numeric_slice_value = _finite_float(raw_slice_value)
                if numeric_slice_value is not None:
                    valid_slice_values.append(float(numeric_slice_value))
        elif slice_value is not None and np.isfinite(float(slice_value)):
            valid_slice_values = [float(slice_value)]
        if slice_axis in {x_name, y_name, z_name} and valid_slice_values:
            axis_bounds = {}
            for axis_name in (x_name, y_name, z_name):
                bounds = (axis_ranges or {}).get(axis_name)
                if bounds is not None:
                    axis_bounds[axis_name] = (
                        float(bounds[0]),
                        float(bounds[1]),
                    )
                else:
                    axis_values = pd.to_numeric(
                        valid[axis_name],
                        errors="coerce",
                    ).dropna()
                    if axis_values.empty:
                        axis_bounds[axis_name] = (0.0, 1.0)
                    else:
                        axis_bounds[axis_name] = (
                            float(axis_values.min()),
                            float(axis_values.max()),
                        )
                if np.isclose(axis_bounds[axis_name][0], axis_bounds[axis_name][1]):
                    center = axis_bounds[axis_name][0]
                    padding = max(abs(center) * 0.05, 1e-9)
                    axis_bounds[axis_name] = (center - padding, center + padding)
            base_plane_x = np.array([
                [axis_bounds[x_name][0], axis_bounds[x_name][1]],
                [axis_bounds[x_name][0], axis_bounds[x_name][1]],
            ], dtype=float)
            base_plane_y = np.array([
                [axis_bounds[y_name][0], axis_bounds[y_name][0]],
                [axis_bounds[y_name][1], axis_bounds[y_name][1]],
            ], dtype=float)
            base_plane_z = np.array([
                [axis_bounds[z_name][0], axis_bounds[z_name][0]],
                [axis_bounds[z_name][1], axis_bounds[z_name][1]],
            ], dtype=float)
            x0, x1 = axis_bounds[x_name]
            y0, y1 = axis_bounds[y_name]
            z0, z1 = axis_bounds[z_name]
            for slice_index, current_slice_value in enumerate(valid_slice_values):
                plane_x = base_plane_x.copy()
                plane_y = base_plane_y.copy()
                plane_z = base_plane_z.copy()
                if slice_axis == x_name:
                    plane_x = np.full_like(plane_x, float(current_slice_value))
                    outline_x = [
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                    ]
                    outline_y = [y0, y1, y1, y0, y0]
                    outline_z = [z0, z0, z1, z1, z0]
                elif slice_axis == y_name:
                    plane_y = np.full_like(plane_y, float(current_slice_value))
                    outline_x = [x0, x1, x1, x0, x0]
                    outline_y = [
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                    ]
                    outline_z = [z0, z0, z1, z1, z0]
                else:
                    plane_z = np.full_like(plane_z, float(current_slice_value))
                    outline_x = [x0, x1, x1, x0, x0]
                    outline_y = [y0, y0, y1, y1, y0]
                    outline_z = [
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                        current_slice_value,
                    ]
                _mpl_color, color = _slice_highlight_color(
                    slice_index,
                    len(valid_slice_values),
                )
                if len(valid_slice_values) > 1:
                    trace_name = f"Slice {slice_index + 1}: {slice_axis}={current_slice_value:g}"
                else:
                    trace_name = "Highlighted slice"
                fig.add_trace(go.Surface(
                    x=plane_x,
                    y=plane_y,
                    z=plane_z,
                    surfacecolor=np.zeros_like(plane_x),
                    colorscale=[[0, color], [1, color]],
                    opacity=0.34 if len(valid_slice_values) > 1 else 0.28,
                    showscale=False,
                    showlegend=False,
                    name=trace_name,
                    hovertemplate=(
                        f"{slice_axis}: {float(current_slice_value):.4g}"
                        "<extra>Highlighted slice</extra>"
                    ),
                ))
                fig.add_trace(go.Scatter3d(
                    x=outline_x,
                    y=outline_y,
                    z=outline_z,
                    mode="lines",
                    line={"color": color, "width": 7},
                    name=f"{trace_name} outline",
                    showlegend=False,
                    hovertemplate=(
                        f"{slice_axis}: {float(current_slice_value):.4g}"
                        "<extra>Highlighted slice outline</extra>"
                    ),
                ))
        if not selected_next_frame.empty:
            selected_row = selected_next_frame.iloc[0]
            fig.add_trace(go.Scatter3d(
                x=[selected_row[x_name]],
                y=[selected_row[y_name]],
                z=[selected_row[z_name]],
                mode="markers",
                name=f"Selected iteration {iteration + 1}",
                marker={
                    "size": dot_size + 4,
                    "color": "#ff2da1",
                    "symbol": "diamond",
                    "line": {"color": "white", "width": 2},
                },
                hovertemplate=(
                    f"Selected iteration {iteration + 1}<br>"
                    f"{value}: {float(selected_row[value]):.4g}"
                    "<extra></extra>"
                ),
            ))
        observed = _observed_points(session, iteration, [x_name, y_name, z_name])
        if observed:
            observed_x = [float(obs["params"][x_name]) for obs in observed]
            observed_y = [float(obs["params"][y_name]) for obs in observed]
            observed_z = [float(obs["params"][z_name]) for obs in observed]
            observed_iterations = _observed_iterations(observed)
            observed_values = np.asarray([float(obs["Q_run"]) for obs in observed])
            norm = _iteration_norm(observed_iterations)
            if show_iteration_path:
                for index in range(1, len(observed)):
                    color = OBSERVED_PATH_CMAP(norm(observed_iterations[index]))
                    fig.add_trace(go.Scatter3d(
                        x=observed_x[index - 1:index + 1],
                        y=observed_y[index - 1:index + 1],
                        z=observed_z[index - 1:index + 1],
                        mode="lines",
                        line={"color": f"rgb({color[0] * 255:.0f},{color[1] * 255:.0f},{color[2] * 255:.0f})", "width": 5},
                        hoverinfo="skip",
                        showlegend=False,
                    ))
                fig.add_trace(go.Scatter3d(
                    x=[None, None],
                    y=[None, None],
                    z=[None, None],
                    mode="markers",
                    marker={
                        "color": [norm.vmin, norm.vmax],
                        "colorscale": [
                            [0, OBSERVED_PATH_COLORS[0]],
                            [1, OBSERVED_PATH_COLORS[1]],
                        ],
                        "cmin": norm.vmin,
                        "cmax": norm.vmax,
                        "showscale": True,
                        "colorbar": {
                            "title": "Iteration",
                            "x": 0.98,
                            "y": 0.48,
                            "len": 0.68,
                        },
                    },
                    hoverinfo="skip",
                    showlegend=False,
                ))
            fig.add_trace(go.Scatter3d(
                x=observed_x,
                y=observed_y,
                z=observed_z,
                mode="markers",
                name="Observed path",
                marker={
                    "color": observed_values,
                    "colorscale": "Viridis",
                    "cmin": prediction_min,
                    "cmax": prediction_max,
                    "size": dot_size,
                    "opacity": dot_opacity,
                    "showscale": False,
                },
                customdata=np.column_stack((observed_iterations, observed_values)),
                hovertemplate=(
                    f"{x_name}: %{{x:.4g}}<br>{y_name}: %{{y:.4g}}<br>"
                    f"{z_name}: %{{z:.4g}}<br>Iteration: %{{customdata[0]:.0f}}"
                    "<br>Measured Q: %{customdata[1]:.4g}<extra>Observed</extra>"
                ),
            ))
        fig.update_layout(
            title={
                "text": title,
                "x": 0.01,
                "xanchor": "left",
                "y": 0.98,
                "yanchor": "top",
                "font": {"size": 16},
            },
            scene={
                "xaxis": {
                    "title": x_name,
                    "type": "log" if log_frequency and x_name == "frequency" else "linear",
                },
                "yaxis": {
                    "title": y_name,
                    "type": "log" if log_frequency and y_name == "frequency" else "linear",
                },
                "zaxis": {
                    "title": z_name,
                    "type": "log" if log_frequency and z_name == "frequency" else "linear",
                },
                "domain": {"x": [0, 0.76], "y": [0.14, 0.82]},
                "uirevision": (
                    "surrogate-3d:"
                    f"{session.get('selected_group_id', 'all')}:"
                    f"{iteration}:{value}:{x_name}:{y_name}:{z_name}:"
                    f"{int(bool(log_frequency))}"
                ),
            },
            legend={
                "orientation": "h",
                "x": 0,
                "xanchor": "left",
                "y": 0.02,
                "yanchor": "bottom",
            },
            height=tensor_height,
            margin={"l": 10, "r": 10, "t": 105, "b": 75},
            uirevision=(
                "surrogate-3d:"
                f"{session.get('selected_group_id', 'all')}:"
                f"{iteration}:{value}:{x_name}:{y_name}:{z_name}:"
                f"{int(bool(log_frequency))}"
            ),
        )
        if axis_ranges:
            def plotly_axis_range(name: str) -> list[float] | None:
                bounds = axis_ranges.get(name)
                if bounds is None:
                    return None
                if log_frequency and name == "frequency":
                    return [
                        float(np.log10(max(bounds[0], 1e-12))),
                        float(np.log10(max(bounds[1], 1e-12))),
                    ]
                return [float(bounds[0]), float(bounds[1])]

            fig.update_scenes(
                xaxis_range=plotly_axis_range(x_name),
                yaxis_range=plotly_axis_range(y_name),
                zaxis_range=plotly_axis_range(z_name),
            )
        return fig
    elif view == "2D map":
        fig, ax = plt.subplots(figsize=(6.4, 4.0))
        mesh = _plot_surrogate_2d_control_style(
            ax,
            session,
            display_frame,
            iteration,
            value,
            x_name,
            y_name,
            selected_next_frame,
            dot_size=dot_size,
            log_frequency=log_frequency,
            show_iteration_path=show_iteration_path,
            show_observed_points=show_observed_points,
            axis_ranges=axis_ranges,
            observed_slice_axis=observed_slice_axis,
            observed_slice_value=observed_slice_value,
        )
        if mesh is not None:
            colorbar = fig.colorbar(
                mesh,
                ax=ax,
                label=SURROGATE_VALUE_LABELS.get(value, value),
            )
            colorbar.ax.tick_params(labelsize=8)
            colorbar.set_label(
                SURROGATE_VALUE_LABELS.get(value, value),
                fontsize=8,
            )
            handles, labels = ax.get_legend_handles_labels()
            if handles:
                ax.legend(loc="best", fontsize=8)
        if axis_ranges:
            if x_name in axis_ranges:
                ax.set_xlim(*map(float, axis_ranges[x_name]))
            if y_name in axis_ranges:
                ax.set_ylim(*map(float, axis_ranges[y_name]))
    else:
        fig, ax = plt.subplots(figsize=(6.4, 3.5))
        valid = display_frame[[x_name, value]].apply(pd.to_numeric, errors="coerce").dropna()
        ax.scatter(
            valid[x_name],
            valid[value],
            color="#155e63",
            s=dot_size ** 2,
            alpha=dot_opacity,
            label="candidate predictions",
        )
        observed = _observed_points(session, iteration, [x_name])
        if observed:
            observed_x = [obs["params"][x_name] for obs in observed]
            observed_q = [obs["Q_run"] for obs in observed]
            _plot_observed_path(
                ax,
                observed_x,
                observed_q,
                observed,
                label="tested parameter sets",
                value_norm=None,
                marker_size=dot_size ** 2,
                show_iteration_path=show_iteration_path,
            )
        if not selected_next_frame.empty:
            selected_row = selected_next_frame.iloc[0]
            ax.scatter(
                [selected_row[x_name]],
                [selected_row[value]],
                marker="*",
                s=(dot_size + 8) ** 2,
                color="#ff2da1",
                edgecolor="white",
                linewidth=1,
                label=f"selected iteration {iteration + 1}",
                zorder=6,
            )
        ax.set(xlabel=x_name, ylabel=value)
        if log_frequency and x_name == "frequency":
            ax.set_xscale("log")
        if axis_ranges and x_name in axis_ranges:
            ax.set_xlim(*map(float, axis_ranges[x_name]))
        ax.legend()
    title_lines = [
        f"{view} | {value} | artifact iteration {iteration}",
        parameter_context,
    ]
    if title_note:
        title_lines.append(title_note)
    ax.set_title("\n".join(title_lines))
    ax.grid(alpha=.2)
    fig.tight_layout()
    return fig


def _sized_plot_container(container, width_percent: int):
    """Create a centered container whose width is known before plot rendering."""
    if width_percent >= 100:
        return container
    side_width = (100 - width_percent) / 2
    _left, plot_column, _right = container.columns(
        [side_width, width_percent, side_width]
    )
    return plot_column


def _safe_download_stem(label: str) -> str:
    stem = re.sub(r"[^A-Za-z0-9._-]+", "_", str(label)).strip("_")
    return stem or "plot"


def _plotly_colorbar_height_fraction() -> float:
    try:
        percent = float(st.session_state.get("bo_colorbar_height_percent", 100))
    except (TypeError, ValueError):
        percent = 100.0
    return min(1.0, max(0.2, percent / 100.0))


def _apply_plotly_3d_turntable_dragmode(fig: go.Figure) -> go.Figure:
    scene_keys: set[str] = set()
    for trace in fig.data:
        if str(getattr(trace, "type", "")).lower() not in PLOTLY_3D_TRACE_TYPES:
            continue
        scene_ref = getattr(trace, "scene", None) or "scene"
        if isinstance(scene_ref, str) and scene_ref.startswith("scene"):
            scene_keys.add(scene_ref)
    for key in fig.layout:
        if str(key).startswith("scene"):
            scene_keys.add(str(key))
    if scene_keys:
        fig.update_layout(**{
            scene_key: {"dragmode": "turntable"}
            for scene_key in scene_keys
        })
    return fig


def _apply_plotly_colorbar_height(fig: go.Figure) -> go.Figure:
    _apply_plotly_3d_turntable_dragmode(fig)
    uses_layout_coloraxis = False
    height_fraction = _plotly_colorbar_height_fraction()
    for trace in fig.data:
        if getattr(trace, "coloraxis", None):
            uses_layout_coloraxis = True
        colorbar = getattr(trace, "colorbar", None)
        if colorbar is not None:
            colorbar.len = height_fraction
            colorbar.y = 0.5
        marker = getattr(trace, "marker", None)
        if getattr(marker, "coloraxis", None):
            uses_layout_coloraxis = True
        marker_colorbar = getattr(marker, "colorbar", None)
        if marker_colorbar is not None:
            marker_colorbar.len = height_fraction
            marker_colorbar.y = 0.5
    if not uses_layout_coloraxis:
        fig.update_layout(coloraxis=None)
    return fig


def _plotly_chart_with_colorbars(container, fig: go.Figure, **kwargs):
    return container.plotly_chart(
        _apply_plotly_colorbar_height(fig),
        **kwargs,
    )


def _parameter_crop_ranges(
    frame: pd.DataFrame,
    axes: Sequence[str | None],
    *,
    key_prefix: str,
    label: str = "Crop heatmap/tensor by parameter",
    help_text: str = "Crop limits are applied before plotting.",
    expanded: bool = False,
) -> dict[str, tuple[float, float]]:
    available_axes = []
    seen_axes = set()
    for axis in axes:
        if axis is None or axis in seen_axes or axis not in frame.columns:
            continue
        values = pd.to_numeric(frame[axis], errors="coerce").dropna()
        if values.empty:
            continue
        available_axes.append((axis, values))
        seen_axes.add(axis)
    if not available_axes:
        return {}
    crop_ranges: dict[str, tuple[float, float]] = {}
    with st.expander(label, expanded=expanded):
        crop_enabled = st.checkbox(
            "Enable parameter crop",
            key=f"{key_prefix}_enabled",
        )
        if crop_enabled:
            st.caption(help_text)
            crop_columns = st.columns(len(available_axes))
            for axis_index, (axis_name, axis_values) in enumerate(available_axes):
                axis_min = float(axis_values.min())
                axis_max = float(axis_values.max())
                axis_step = max(abs(axis_max - axis_min) / 100.0, 1e-9)
                with crop_columns[axis_index]:
                    st.markdown(f"**{_metric_label(axis_name)}**")
                    crop_min = float(st.number_input(
                        "Min",
                        value=axis_min,
                        step=axis_step,
                        format="%.8g",
                        key=f"{key_prefix}_{axis_name}_min",
                    ))
                    crop_max = float(st.number_input(
                        "Max",
                        value=axis_max,
                        step=axis_step,
                        format="%.8g",
                        key=f"{key_prefix}_{axis_name}_max",
                    ))
                if crop_min > crop_max:
                    crop_min, crop_max = crop_max, crop_min
                crop_ranges[axis_name] = (crop_min, crop_max)
    return crop_ranges


def _apply_parameter_crop(
    frame: pd.DataFrame,
    crop_ranges: Mapping[str, tuple[float, float]],
) -> pd.DataFrame:
    cropped = frame
    for axis_name, (crop_min, crop_max) in crop_ranges.items():
        if axis_name not in cropped.columns:
            continue
        axis_values = pd.to_numeric(cropped[axis_name], errors="coerce")
        cropped = cropped.loc[
            axis_values.between(
                float(crop_min),
                float(crop_max),
                inclusive="both",
            )
        ]
    return cropped


def _numeric_slice_values(frame: pd.DataFrame, column: str) -> list[float]:
    if frame is None or frame.empty or column not in frame.columns:
        return []
    values = pd.to_numeric(frame[column], errors="coerce")
    return sorted(float(value) for value in values[np.isfinite(values)].unique())


def _apply_numeric_slice(
    frame: pd.DataFrame,
    column: str | None,
    value: float | None,
) -> pd.DataFrame:
    if (
        frame is None
        or frame.empty
        or column is None
        or value is None
        or column not in frame.columns
    ):
        return frame
    values = pd.to_numeric(frame[column], errors="coerce")
    return frame.loc[
        np.isclose(values, float(value), rtol=1e-9, atol=1e-12)
    ].copy()


def _numeric_slice_token(column: str | None, value: float | None) -> str:
    if column is None or value is None:
        return "all_unplotted"
    return f"{column}={float(value):g}"


def _numeric_slice_values_token(
    column: str | None,
    values: Sequence[float] | None,
) -> str:
    if column is None or not values:
        return "no_sweep"
    return (
        f"{column}="
        + ",".join(f"{float(value):g}" for value in values)
    )


def _numeric_slice_title_note(column: str | None, value: float | None) -> str | None:
    if column is None or value is None:
        return None
    return f"Fixed {_metric_label(column)} = {float(value):g}"


def _matplotlib_png_bytes(fig, *, dpi: int = 150) -> bytes:
    buffer = BytesIO()
    fig.savefig(buffer, format="png", dpi=dpi, bbox_inches=None)
    return buffer.getvalue()


def _render_browser_download_link(
    container,
    label: str,
    data: bytes,
    *,
    file_name: str,
    mime: str,
) -> None:
    encoded = base64.b64encode(data).decode("ascii")
    safe_label = html.escape(str(label))
    safe_file_name = html.escape(str(file_name), quote=True)
    safe_mime = html.escape(str(mime), quote=True)
    container.markdown(
        (
            f'<a href="data:{safe_mime};base64,{encoded}" '
            f'download="{safe_file_name}" '
            'style="display:inline-flex;align-items:center;'
            'justify-content:center;min-height:2.25rem;padding:0.25rem 0.75rem;'
            'border:1px solid rgba(49,51,63,0.2);border-radius:0.5rem;'
            'background:#fff;color:rgb(49,51,63);text-decoration:none;'
            'font-size:0.875rem;line-height:1.6;">'
            f"{safe_label}</a>"
        ),
        unsafe_allow_html=True,
    )


def _render_downloadable_pyplot(
    container,
    fig,
    *,
    key: str,
    file_stem: str,
    width_percent: int,
    dpi: int = 150,
) -> None:
    plot_column = _sized_plot_container(container, width_percent)
    png_bytes = _matplotlib_png_bytes(fig, dpi=dpi)
    plot_column.pyplot(
        fig,
        clear_figure=False,
        use_container_width=True,
        bbox_inches=None,
    )
    _render_browser_download_link(
        plot_column,
        "Download plot",
        png_bytes,
        file_name=f"{_safe_download_stem(file_stem)}.png",
        mime="image/png",
    )
    plt.close(fig)


def _plotly_png_bytes(
    fig: go.Figure,
    *,
    width: int = 1200,
    height: int = 800,
    scale: float = 2,
) -> bytes:
    _apply_plotly_3d_turntable_dragmode(fig)
    try:
        return fig.to_image(
            format="png",
            width=width,
            height=height,
            scale=scale,
        )
    except Exception as exc:
        raise RuntimeError(
            "Plotly PNG export requires kaleido==0.2.1. "
            "Install the updated requirements and restart the app."
        ) from exc


def _plotly_camera_state_key(camera_storage_key: str) -> str:
    digest = hashlib.sha1(camera_storage_key.encode("utf-8")).hexdigest()[:16]
    return f"bo_plotly_camera_state_{digest}"


def _valid_plotly_camera(camera: Any) -> dict | None:
    if not isinstance(camera, dict) or not isinstance(camera.get("eye"), dict):
        return None
    cleaned = {}
    for part in ("eye", "center", "up"):
        values = camera.get(part)
        if not isinstance(values, dict):
            continue
        cleaned_part = {}
        for axis in ("x", "y", "z"):
            numeric = _finite_float(values.get(axis))
            if numeric is not None:
                cleaned_part[axis] = float(numeric)
        if cleaned_part:
            cleaned[part] = cleaned_part
    return cleaned if "eye" in cleaned else None


def _store_plotly_camera(storage_key: str, camera: Any) -> dict | None:
    valid_camera = _valid_plotly_camera(camera)
    if valid_camera is None:
        return None
    st.session_state[_plotly_camera_state_key(storage_key)] = valid_camera
    return valid_camera


def _stored_plotly_camera(camera_storage_key: str | None) -> dict | None:
    if not camera_storage_key:
        return _valid_plotly_camera(
            st.session_state.get(_plotly_camera_state_key(_SHARED_3D_CAMERA_STORAGE_KEY))
        )
    storage_key = f"bo_viewer_camera:{camera_storage_key}"
    camera = _valid_plotly_camera(
        st.session_state.get(_plotly_camera_state_key(storage_key))
    )
    if camera is not None:
        return camera
    return _valid_plotly_camera(
        st.session_state.get(_plotly_camera_state_key(_SHARED_3D_CAMERA_STORAGE_KEY))
    )


def _apply_plotly_camera(fig: go.Figure, camera: dict | None) -> go.Figure:
    valid_camera = _valid_plotly_camera(camera)
    if valid_camera is not None:
        fig.update_layout(scene_camera=valid_camera)
    return fig


def _slice_axis_reverse_flags(
    camera: dict | None,
    axes: tuple[str, str, str],
    x_name: str,
    y_name: str,
) -> tuple[bool, bool]:
    valid_camera = _valid_plotly_camera(camera)
    if valid_camera is None:
        valid_camera = {"eye": {"x": 1.25, "y": 1.25, "z": 1.25}}
    eye = valid_camera.get("eye", {})
    center = valid_camera.get("center", {})
    up = valid_camera.get("up", {})
    eye_vector = np.array(
        [
            float(eye.get("x", 1.25)),
            float(eye.get("y", 1.25)),
            float(eye.get("z", 1.25)),
        ],
        dtype=float,
    )
    center_vector = np.array(
        [
            float(center.get("x", 0.0)),
            float(center.get("y", 0.0)),
            float(center.get("z", 0.0)),
        ],
        dtype=float,
    )
    up_vector = np.array(
        [
            float(up.get("x", 0.0)),
            float(up.get("y", 0.0)),
            float(up.get("z", 1.0)),
        ],
        dtype=float,
    )
    forward = center_vector - eye_vector
    forward_norm = np.linalg.norm(forward)
    up_norm = np.linalg.norm(up_vector)
    if forward_norm <= 0 or up_norm <= 0:
        return False, False
    forward = forward / forward_norm
    up_vector = up_vector / up_norm
    right = np.cross(forward, up_vector)
    right_norm = np.linalg.norm(right)
    if right_norm <= 0:
        return False, False
    right = right / right_norm
    screen_up = np.cross(right, forward)
    screen_up_norm = np.linalg.norm(screen_up)
    if screen_up_norm <= 0:
        return False, False
    screen_up = screen_up / screen_up_norm

    def axis_vector(axis_name: str) -> np.ndarray | None:
        if axis_name not in axes:
            return None
        vector = np.zeros(3, dtype=float)
        vector[axes.index(axis_name)] = 1.0
        return vector

    x_vector = axis_vector(x_name)
    y_vector = axis_vector(y_name)
    if x_vector is None or y_vector is None:
        return False, False
    return (
        float(np.dot(x_vector, right)) < 0,
        float(np.dot(y_vector, screen_up)) < 0,
    )


def _render_camera_persistent_plotly(
    container,
    fig: go.Figure,
    *,
    key: str,
    camera_storage_key: str,
    height: int,
    file_stem: str,
    export_width: int = 1200,
    export_height: int | None = None,
    shared_camera_storage_key: str | None = None,
    apply_sync_nonce: int | None = None,
    show_download: bool = False,
    show_cache_view: bool = True,
) -> dict | None:
    _apply_plotly_colorbar_height(fig)
    storage_key = f"bo_viewer_camera:{camera_storage_key}"
    shared_storage_key = shared_camera_storage_key or _SHARED_3D_CAMERA_STORAGE_KEY
    camera_state_key = _plotly_camera_state_key(storage_key)
    current_camera = _valid_plotly_camera(st.session_state.get(camera_state_key))
    apply_nonce = (
        int(apply_sync_nonce)
        if apply_sync_nonce is not None
        else int(st.session_state.get("bo_3d_perspective_snap_nonce", 0))
    )
    sync_camera = (
        _valid_plotly_camera(
            st.session_state.get(_plotly_camera_state_key(shared_storage_key))
        )
        if apply_nonce > 0 else None
    )
    if sync_camera is not None:
        fig.update_layout(scene_camera=sync_camera)
        current_camera = sync_camera
        st.session_state[camera_state_key] = sync_camera
    component_figure = json.loads(
        json.dumps(fig.to_plotly_json(), cls=PlotlyJSONEncoder)
    )
    component_key = f"{key}_camera_component"

    def render_component():
        return _plotly_camera_capture(
            figure=component_figure,
            storage_key=storage_key,
            shared_storage_key=shared_storage_key,
            camera_storage_key=camera_storage_key,
            component_id=component_key,
            camera=current_camera,
            sync_camera=sync_camera,
            height=int(height),
            apply_sync_nonce=apply_nonce,
            show_cache_view=bool(show_cache_view),
            show_download=bool(show_download),
            download_file_stem=_safe_download_stem(file_stem),
            download_width=int(export_width),
            download_height=int(export_height or height),
            default=None,
            key=component_key,
        )

    if hasattr(container, "__enter__") and hasattr(container, "__exit__"):
        with container:
            returned_camera = render_component()
    else:
        returned_camera = render_component()
    if isinstance(returned_camera, dict) and returned_camera.get("type") == "cache_view":
        cached_camera = _valid_plotly_camera(returned_camera.get("camera"))
        if cached_camera is not None:
            _store_plotly_camera(storage_key, cached_camera)
            _store_plotly_camera(shared_storage_key, cached_camera)
            returned_shared_storage_key = returned_camera.get("shared_storage_key")
            if isinstance(returned_shared_storage_key, str):
                _store_plotly_camera(returned_shared_storage_key, cached_camera)
            st.session_state[f"{_plotly_camera_state_key(shared_storage_key)}_cached"] = True
            current_camera = cached_camera
        return current_camera
    stored_camera = _store_plotly_camera(storage_key, returned_camera)
    if stored_camera is not None:
        current_camera = stored_camera
    return current_camera


def _render_downloadable_plotly(
    container,
    fig: go.Figure,
    *,
    key: str,
    file_stem: str,
    width_percent: int,
    export_width: int = 1200,
    export_height: int | None = None,
    on_select: str = "ignore",
    selection_mode: str | tuple[str, ...] = "points",
    camera_storage_key: str | None = None,
    eager_png: bool = True,
) -> Any:
    plot_column = _sized_plot_container(container, width_percent)
    _apply_plotly_colorbar_height(fig)
    if camera_storage_key:
        rendered_camera = _render_camera_persistent_plotly(
            plot_column,
            fig,
            key=key,
            camera_storage_key=camera_storage_key,
            height=export_height or int(fig.layout.height or 800),
            file_stem=file_stem,
            export_width=export_width,
            export_height=export_height,
            show_download=False,
        )
        event = None
        download_camera = _stored_plotly_camera(camera_storage_key) or rendered_camera
        download_fig = go.Figure(fig)
        _apply_plotly_camera(download_fig, download_camera)
        try:
            png_bytes = _plotly_png_bytes(
                download_fig,
                width=export_width,
                height=export_height or int(fig.layout.height or 800),
            )
            _render_browser_download_link(
                plot_column,
                "Download plot",
                png_bytes,
                file_name=f"{_safe_download_stem(file_stem)}.png",
                mime="image/png",
            )
            if download_camera is None:
                plot_column.caption(
                    "Click Cache view after rotating to export the current perspective."
                )
        except RuntimeError as exc:
            plot_column.caption(str(exc))
        eager_png = False
    else:
        event = plot_column.plotly_chart(
            fig,
            use_container_width=True,
            on_select=on_select,
            selection_mode=selection_mode,
            key=key,
        )
    if eager_png:
        try:
            png_bytes = _plotly_png_bytes(
                fig,
                width=export_width,
                height=export_height or int(fig.layout.height or 800),
            )
            _render_browser_download_link(
                plot_column,
                "Download plot",
                png_bytes,
                file_name=f"{_safe_download_stem(file_stem)}.png",
                mime="image/png",
            )
        except RuntimeError as exc:
            plot_column.caption(str(exc))
    return event


def _preserve_valid_widget_value(
    key: str,
    options: list,
    default=None,
) -> None:
    """Keep a widget selection across reruns without losing invalid preferences."""
    _prepare_preferred_widget_value(
        key,
        f"{key}__preferred",
        options,
        default,
    )


def _seed_session_state_value(target_key: str, source_key: str) -> None:
    """Initialize a shared widget key from an older scoped key when present."""
    if target_key not in st.session_state and source_key in st.session_state:
        st.session_state[target_key] = st.session_state[source_key]


def _initialize_preference(
    preference_key: str,
    *source_keys: str | None,
    default=None,
) -> None:
    """Seed a durable preference from current or legacy widget state."""
    if preference_key in st.session_state:
        return
    for source_key in source_keys:
        if source_key and source_key in st.session_state:
            st.session_state[preference_key] = st.session_state[source_key]
            return
    st.session_state[preference_key] = default


def _prepare_preferred_widget_value(
    widget_key: str,
    preference_key: str,
    options: list,
    default=None,
) -> tuple[bool, Any]:
    """Set a widget to the preferred value when valid without losing preference."""
    if not options:
        return False, None
    fallback_key = f"{preference_key}__fallback_display"
    current_widget_value = st.session_state.get(widget_key)
    fallback_display = st.session_state.get(fallback_key)
    if (
        current_widget_value in options
        and current_widget_value != fallback_display
        and current_widget_value != st.session_state.get(preference_key)
    ):
        st.session_state[preference_key] = current_widget_value
    preferred = st.session_state.get(preference_key, default)
    preference_valid = preferred in options
    display_value = (
        preferred
        if preference_valid
        else default if default in options else options[0]
    )
    if preference_valid:
        st.session_state.pop(fallback_key, None)
    else:
        st.session_state[fallback_key] = display_value
    st.session_state[widget_key] = display_value
    return preference_valid, display_value


def _sync_preferred_widget_value(
    widget_key: str,
    preference_key: str,
    preference_valid: bool,
    display_value: Any,
) -> None:
    """Persist user changes while ignoring automatic session-switch fallbacks."""
    current_value = st.session_state.get(widget_key)
    if preference_valid or current_value != display_value:
        st.session_state[preference_key] = current_value
        st.session_state.pop(f"{preference_key}__fallback_display", None)


def _prepare_preferred_multiselect_value(
    widget_key: str,
    preference_key: str,
    options: list,
    default: list,
) -> tuple[bool, list]:
    fallback_key = f"{preference_key}__fallback_display"
    current_widget_value = st.session_state.get(widget_key)
    fallback_display = st.session_state.get(fallback_key)
    if isinstance(current_widget_value, (list, tuple, set)):
        current_list = list(current_widget_value)
        current_valid_values = [
            value for value in current_list if value in options
        ]
        if (
            current_list != fallback_display
            and current_valid_values == current_list
            and current_list != st.session_state.get(preference_key)
        ):
            st.session_state[preference_key] = current_list
    preferred = st.session_state.get(preference_key, default)
    if not isinstance(preferred, (list, tuple, set)):
        preferred = [preferred]
    valid_values = [value for value in preferred if value in options]
    preference_valid = bool(valid_values) or list(preferred) == []
    display_values = valid_values if valid_values else default
    if preference_valid:
        st.session_state.pop(fallback_key, None)
    else:
        st.session_state[fallback_key] = display_values
    st.session_state[widget_key] = display_values
    return preference_valid, display_values


def _reset_bo_group_channel_selector_defaults(session_token: str) -> None:
    """Start each loaded BO session with all groups/channels selected."""
    marker_key = "bo_group_channel_defaults_session"
    if st.session_state.get(marker_key) == session_token:
        return

    exact_keys = {
        "bo_channel_group_scope",
        "bo_channel_group_scope__preferred",
        "bo_observation_group_scope",
        "bo_observation_group_scope__preferred",
        "bo_observation_group_scope_compact_session",
        "bo_surrogate_groups",
        "bo_surrogate_pref_groups",
    }
    prefixes = (
        "bo_trend_channels_",
        "bo_hp_response_channels_",
        "bo_paired_channels_",
        "bo_chronological_channels_",
        "bo_trace_channels_",
        "bo_real_groups_",
        "bo_real_channels_",
        "bo_sim_real_channels",
        "bo_trend_iteration_start_",
        "bo_trend_iteration_end_",
    )
    suffixes = (
        "__preferred",
        "__preferred__fallback_display",
        "__fallback_display",
    )
    keys_to_clear = []
    for key in list(st.session_state.keys()):
        if key in exact_keys or key.startswith(prefixes):
            keys_to_clear.append(key)
            continue
        if key.endswith(suffixes):
            base_key = key
            for suffix in suffixes:
                if base_key.endswith(suffix):
                    base_key = base_key[: -len(suffix)]
                    break
            if base_key in exact_keys or base_key.startswith(prefixes):
                keys_to_clear.append(key)
    for key in keys_to_clear:
        st.session_state.pop(key, None)
    st.session_state["bo_channel_group_scope"] = "all"
    st.session_state["bo_channel_group_scope__preferred"] = "all"
    st.session_state["bo_observation_group_scope"] = "all"
    st.session_state["bo_observation_group_scope__preferred"] = "all"
    st.session_state[marker_key] = session_token


def _capture_widget_preference(widget_key: str, preference_key: str) -> None:
    if widget_key in st.session_state:
        st.session_state[preference_key] = st.session_state[widget_key]


def _prepare_numeric_widget_preference(
    widget_key: str,
    preference_key: str,
    *,
    default: float,
    minimum: float,
    maximum: float,
    cast=float,
) -> None:
    _initialize_preference(
        preference_key,
        widget_key,
        default=default,
    )
    _capture_widget_preference(widget_key, preference_key)
    try:
        value = cast(st.session_state.get(preference_key, default))
    except (TypeError, ValueError):
        value = cast(default)
    st.session_state[widget_key] = cast(min(maximum, max(minimum, value)))


def _progress_fraction(
    current: int,
    total: int,
    *,
    start: float = 0.0,
    end: float = 1.0,
) -> float:
    """Map a completed/total count onto a bounded Streamlit progress fraction."""
    total = max(1, int(total or 0))
    current = max(0, min(int(current or 0), total))
    start = float(start)
    end = float(end)
    if end < start:
        start, end = end, start
    return min(end, max(start, start + (end - start) * current / total))


def _stabilize_gif_figure_layout(figure) -> None:
    """Pin legends before GIF rasterization so they do not jump per frame."""
    if isinstance(figure, go.Figure):
        base_margin = (
            figure.layout.margin.to_plotly_json()
            if figure.layout.margin is not None
            else {}
        )
        base_margin["b"] = max(int(base_margin.get("b") or 0), 120)
        figure.update_layout(
            margin=base_margin,
            legend={
                "orientation": "h",
                "x": 0.0,
                "xanchor": "left",
                "y": -0.16,
                "yanchor": "top",
                "traceorder": "normal",
            },
        )
        return

    axes = getattr(figure, "axes", [])
    for ax in axes:
        legend = ax.get_legend()
        if legend is None:
            continue
        handles, labels = ax.get_legend_handles_labels()
        if not handles:
            continue
        title = legend.get_title().get_text()
        fontsize = legend.get_texts()[0].get_fontsize() if legend.get_texts() else 7
        title_fontsize = legend.get_title().get_fontsize()
        legend.remove()
        ax.legend(
            handles,
            labels,
            title=title or None,
            loc="upper right",
            bbox_to_anchor=(1.0, 1.0),
            fontsize=fontsize,
            title_fontsize=title_fontsize,
        )


def _figures_to_gif(
    figures,
    duration_ms: int,
    *,
    plotly_width: int = 1000,
    plotly_height: int = 700,
    plotly_camera: dict | None = None,
    total_frames: int | None = None,
    progress_callback=None,
) -> bytes:
    """Render Matplotlib/Plotly figures and encode an animated GIF."""
    from PIL import Image

    frames = []
    for frame_index, figure in enumerate(figures, start=1):
        _stabilize_gif_figure_layout(figure)
        buffer = BytesIO()
        if isinstance(figure, go.Figure):
            _apply_plotly_3d_turntable_dragmode(figure)
            _apply_plotly_camera(figure, plotly_camera)
            try:
                png = figure.to_image(
                    format="png",
                    width=plotly_width,
                    height=plotly_height,
                    scale=1,
                )
            except Exception as exc:
                raise RuntimeError(
                    "Plotly GIF export requires kaleido==0.2.1. "
                    "Install the updated requirements and restart the app."
                ) from exc
            buffer.write(png)
            buffer.seek(0)
        else:
            figure.savefig(
                buffer,
                format="png",
                dpi=110,
            )
            buffer.seek(0)
            plt.close(figure)
        with Image.open(buffer) as image:
            frames.append(image.convert("RGB").copy())
        if progress_callback is not None:
            progress_callback(frame_index, total_frames or frame_index)
    if not frames:
        raise ValueError("No compatible iteration frames were available.")
    maximum_width = max(frame.width for frame in frames)
    maximum_height = max(frame.height for frame in frames)
    if any(
        frame.size != (maximum_width, maximum_height)
        for frame in frames
    ):
        padded_frames = []
        for frame in frames:
            canvas = Image.new(
                "RGB",
                (maximum_width, maximum_height),
                "white",
            )
            canvas.paste(
                frame,
                (
                    (maximum_width - frame.width) // 2,
                    (maximum_height - frame.height) // 2,
                ),
            )
            padded_frames.append(canvas)
        frames = padded_frames
    frames = [
        frame.quantize(
            colors=128,
            method=Image.Quantize.FASTOCTREE,
        )
        for frame in frames
    ]
    output = BytesIO()
    frames[0].save(
        output,
        format="GIF",
        save_all=True,
        append_images=frames[1:],
        duration=int(duration_ms),
        loop=0,
        optimize=False,
    )
    return output.getvalue()


def render_bo_session_app() -> None:
    """Render the complete BO viewer. Called after Analysis mode is set to BO."""
    st.title("⚡ Bayesian Optimization Session Analysis")
    with st.sidebar:
        st.subheader("BO Session")
        browse_label = "Browse (macOS)" if sys.platform == "darwin" else "Browse (Windows)"
        if st.button(
            browse_label,
            use_container_width=True,
            disabled=not (sys.platform == "darwin" or sys.platform.startswith("win")),
        ):
            try:
                picked = _pick_session_folder()
                if picked:
                    st.session_state.bo_session_folder = picked
            except subprocess.CalledProcessError:
                # Native pickers return a non-zero status when the user cancels.
                pass
            except Exception as exc:
                st.error(f"Folder picker failed: {exc}")
        folder = st.text_input(
            "Experiment or session folder",
            key="bo_session_folder",
            placeholder=".../experiment_folder or .../bo_session_<name>",
            help=(
                "Choose a BO session folder containing bo_state.json, or an "
                "experiment folder containing one or more BO session folders."
            ),
        )

    if not folder:
        st.info("Enter a BO experiment or session folder in the sidebar to load its results.")
        return
    try:
        session_folders = discover_bo_session_folders(folder)
    except Exception as exc:
        st.error(str(exc))
        return
    if not session_folders:
        st.error(
            "No BO sessions found. Choose a folder containing bo_state.json or "
            "an experiment folder with BO session subfolders."
        )
        return

    search_root = Path(folder).expanduser().resolve()
    selected_session_folder = session_folders[0]
    with st.sidebar:
        if len(session_folders) > 1:
            st.markdown("**BO sessions**")
            st.markdown(
                """
                <style>
                section[data-testid="stSidebar"] div.stButton > button {
                    min-height: 34px;
                    height: 34px;
                    overflow: hidden;
                    justify-content: flex-start;
                    padding: 0.35rem 0.55rem;
                }
                section[data-testid="stSidebar"] div.stButton > button p {
                    white-space: nowrap;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    display: block;
                    max-width: 100%;
                }
                section[data-testid="stSidebar"] .bo-session-active-row {
                    background: #e8f0fe;
                    border-left: 4px solid #1a73e8;
                    border-radius: 4px;
                    padding: 7px 8px;
                    margin: 4px 0;
                    font-weight: 600;
                    color: #1f2937;
                    white-space: nowrap;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    line-height: 20px;
                    height: 34px;
                    box-sizing: border-box;
                }
                </style>
                """,
                unsafe_allow_html=True,
            )
            selected_session_key = f"bo_selected_session_folder_{search_root}"
            session_options = [str(path) for path in session_folders]
            if st.session_state.get(selected_session_key) not in session_options:
                st.session_state[selected_session_key] = session_options[0]
            for index, session_path_text in enumerate(session_options):
                session_path = Path(session_path_text)
                session_label = _bo_session_choice_label(
                    session_path,
                    search_root,
                )
                if session_path_text == st.session_state[selected_session_key]:
                    st.markdown(
                        (
                            "<div class='bo-session-active-row' title='"
                            f"{html.escape(session_label)}"
                            "'>"
                            f"{html.escape(session_label)}"
                            "</div>"
                        ),
                        unsafe_allow_html=True,
                    )
                elif st.button(
                    session_label,
                    key=f"{selected_session_key}_{index}",
                    use_container_width=True,
                ):
                    st.session_state[selected_session_key] = session_path_text
                    st.rerun()
            selected_session_folder = Path(st.session_state[selected_session_key])
        else:
            st.caption(
                f"Loaded BO session: "
                f"{_bo_session_choice_label(selected_session_folder, search_root)}"
            )
    try:
        session = load_bo_session(selected_session_folder)
    except Exception as exc:
        st.error(str(exc))
        return
    _reset_bo_group_channel_selector_defaults(
        str(Path(selected_session_folder).expanduser().resolve())
    )

    full_session = session
    groups = _session_channel_groups(session)
    with st.sidebar:
        st.divider()
        if len(groups) > 1:
            group_ids = [group["id"] for group in groups]
            _preserve_valid_widget_value(
                "bo_channel_group_scope",
                ["all", *group_ids],
                "all",
            )
            selected_group_scope = st.selectbox(
                "Channel groups",
                ["all", *group_ids],
                format_func=lambda group_id: next(
                    (
                        f"{group['name']} (channels "
                        f"{', '.join(map(str, group['channels']))})"
                        for group in groups
                        if group["id"] == group_id
                    ),
                    "All channel groups" if group_id == "all" else f"Group {group_id}",
                ),
                key="bo_channel_group_scope",
            )
            if selected_group_scope != "all":
                session = _session_for_channel_group(session, selected_group_scope)
        correction_source = st.radio(
            "Corrected trace processing",
            ["BO session settings", "Analysis app settings"],
            help=(
                "Both options process the raw SWV CSVs with the analysis app's "
                "native algorithm. Choose whether to use the settings saved by "
                "the BO run or editable SWV-analysis settings."
            ),
        )
        if correction_source == "Analysis app settings":
            trace_analysis = _native_analysis_settings_sidebar()
            correction_label = "analysis app settings"
        else:
            trace_analysis = _bo_analysis_settings(session["config"])
            correction_label = "BO session settings"
            st.caption(
                "Using the analysis parameters recorded in bo_config_snapshot.json."
            )
        st.divider()
        _prepare_numeric_widget_preference(
            "bo_plot_width_percent",
            "bo_plot_width_percent__preferred",
            default=80,
            minimum=40,
            maximum=100,
            cast=int,
        )
        plot_width_percent = st.slider(
            "Plot width",
            min_value=40,
            max_value=100,
            value=80,
            step=5,
            format="%d%%",
            help="Width of plots relative to the space available in the current tab or column.",
            key="bo_plot_width_percent",
        )
        st.session_state["bo_plot_width_percent__preferred"] = plot_width_percent
        _prepare_numeric_widget_preference(
            "bo_plot_3d_height",
            "bo_plot_3d_height__preferred",
            default=620,
            minimum=400,
            maximum=1500,
            cast=int,
        )
        plot_3d_height = st.slider(
            "3D plot height",
            min_value=400,
            max_value=1500,
            value=620,
            step=20,
            format="%d px",
            help="Canvas height used for 3D tensor plots.",
            key="bo_plot_3d_height",
        )
        st.session_state["bo_plot_3d_height__preferred"] = plot_3d_height
        st.session_state.setdefault("bo_3d_perspective_snap_nonce", 0)
        st.session_state.pop("bo_sync_3d_perspective", None)
        if st.button(
            "Sync 3D perspectives now",
            help=(
                "Applies the most recently adjusted 3D Plotly camera to 3D "
                "plots once. Later rotations remain local to the plot you edit."
            ),
            key="bo_snap_3d_perspective",
        ):
            st.session_state["bo_3d_perspective_snap_nonce"] = (
                int(st.session_state.get("bo_3d_perspective_snap_nonce", 0)) + 1
            )
            st.rerun()
        _prepare_numeric_widget_preference(
            "bo_plot_dot_size",
            "bo_plot_dot_size__preferred",
            default=6,
            minimum=2,
            maximum=20,
            cast=int,
        )
        plot_dot_size = st.slider(
            "1D/3D dot size",
            min_value=2,
            max_value=20,
            value=6,
            step=1,
            help="Marker diameter for 1D slice and 3D tensor plots.",
            key="bo_plot_dot_size",
        )
        st.session_state["bo_plot_dot_size__preferred"] = plot_dot_size
        _prepare_numeric_widget_preference(
            "bo_plot_dot_opacity",
            "bo_plot_dot_opacity__preferred",
            default=0.45,
            minimum=0.05,
            maximum=1.0,
            cast=float,
        )
        plot_dot_opacity = st.slider(
            "1D/3D dot opacity",
            min_value=0.05,
            max_value=1.0,
            value=0.45,
            step=0.05,
            format="%.2f",
            help="Marker opacity for 1D slice and 3D tensor plots.",
            key="bo_plot_dot_opacity",
        )
        st.session_state["bo_plot_dot_opacity__preferred"] = plot_dot_opacity
        _prepare_numeric_widget_preference(
            "bo_colorbar_height_percent",
            "bo_colorbar_height_percent__preferred",
            default=100,
            minimum=20,
            maximum=100,
            cast=int,
        )
        colorbar_height_percent = st.slider(
            "Colorbar height",
            min_value=20,
            max_value=100,
            value=100,
            step=5,
            format="%d%%",
            help="Height of Plotly colorbars relative to each plot.",
            key="bo_colorbar_height_percent",
        )
        st.session_state["bo_colorbar_height_percent__preferred"] = (
            colorbar_height_percent
        )

    observations = session["observations"]
    history = _observation_table(session)
    if not observations:
        st.warning("This channel group has no completed observations.")
        return
    selected_group_id = session.get("selected_group_id")
    if selected_group_id is not None:
        selected_group = next(
            group for group in groups if group["id"] == selected_group_id
        )
        st.caption(
            f"Showing {selected_group['name']} — channels "
            f"{', '.join(map(str, selected_group['channels']))}"
        )
    paired_objective = any(
        str(obs.get("objective", "")).lower() == "paired_response"
        for obs in observations
    )
    q_values = [float(obs.get("Q_run", np.nan)) for obs in observations]
    best_index = int(np.nanargmax(q_values))
    best = observations[best_index]
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Completed observations", len(observations))
    c2.metric("Best Q", f"{best.get('Q_run', 0):.4g}")
    best_group_name = best.get("group_name") or f"Group {best.get('group_id', 1)}"
    best_label = (
        f"{best_group_name} iter {best.get('iteration')}"
        if len(groups) > 1 and selected_group_id is None
        else best.get("iteration")
    )
    c3.metric("Best observation", best_label)
    c4.metric("Candidates", session["state"].get("candidate_count", "—"))
    simulation_channel_optima = _simulation_channel_optima_frame(full_session)
    if not simulation_channel_optima.empty:
        st.markdown("#### Simulation ground-truth optima")
        st.dataframe(
            simulation_channel_optima,
            use_container_width=True,
            hide_index=True,
            column_config={
                "Maximum possible Q": st.column_config.NumberColumn(format="%.4g"),
                "Best frequency": st.column_config.NumberColumn(format="%.6g Hz"),
                "Best amplitude": st.column_config.NumberColumn(format="%.6g V"),
                "Best step size": st.column_config.NumberColumn(format="%.6g V"),
            },
        )

    all_groups_scope = len(groups) > 1 and selected_group_id is None
    observation_group_ids = sorted({
        int(obs.get("group_id", 1)) for obs in observations
    })
    observation_group_metadata = _channel_group_optimization_metadata(
        full_session,
        groups,
    )
    observation_group_family_options = _observation_group_family_options(
        observation_group_metadata,
        set(observation_group_ids),
    )
    observation_selector_columns = st.columns(2)
    with observation_selector_columns[0]:
        observation_group_options = [
            "all",
            *observation_group_family_options.keys(),
            *observation_group_ids,
        ]
        default_observation_group_scope = "all"

        def observation_group_scope_label(scope: Any) -> str:
            if scope == "all":
                return "All groups"
            if isinstance(scope, str) and scope in observation_group_family_options:
                return observation_group_family_options[scope]["label"]
            return next(
                (
                    f"{group['name']} (channels "
                    f"{', '.join(map(str, group['channels']))})"
                    for group in groups
                    if int(group["id"]) == int(scope)
                ),
                f"Group {scope}",
            )

        _preserve_valid_widget_value(
            "bo_observation_group_scope",
            observation_group_options,
            default_observation_group_scope,
        )
        selected_observation_group_scope = st.selectbox(
            "Observation group",
            observation_group_options,
            format_func=observation_group_scope_label,
            key="bo_observation_group_scope",
        )
    if selected_observation_group_scope == "all":
        selected_observation_group_ids = set(observation_group_ids)
    elif (
        isinstance(selected_observation_group_scope, str)
        and selected_observation_group_scope in observation_group_family_options
    ):
        selected_observation_group_ids = set(
            observation_group_family_options[
                selected_observation_group_scope
            ]["ids"]
        )
    else:
        selected_observation_group_ids = {
            int(selected_observation_group_scope)
        }
    selected_observation_group_scope_label = observation_group_scope_label(
        selected_observation_group_scope
    )
    group_scoped_observations = [
        obs for obs in observations
        if int(obs.get("group_id", 1)) in selected_observation_group_ids
    ]
    scoped_iterations = sorted({
        int(obs["iteration"]) for obs in group_scoped_observations
    })
    with observation_selector_columns[1]:
        observation_iteration_options = [*scoped_iterations, "all"]
        observation_iteration_key = (
            f"bo_observation_iteration_{selected_observation_group_scope}"
        )
        _preserve_valid_widget_value(
            observation_iteration_key,
            observation_iteration_options,
            scoped_iterations[-1] if scoped_iterations else "all",
        )
        selected_iteration_scope = st.selectbox(
            "Observation iteration",
            observation_iteration_options,
            format_func=lambda iteration: (
                "All iterations" if iteration == "all" else f"Iteration {iteration}"
            ),
            key=observation_iteration_key,
        )
    selected_observations = [
        obs for obs in group_scoped_observations
        if (
            selected_iteration_scope == "all"
            or int(obs["iteration"]) == int(selected_iteration_scope)
        )
    ]
    observation = selected_observations[-1]
    selected_observation_group = int(observation.get("group_id", 1))
    selected_iteration = int(observation["iteration"])
    observation_is_single = len(selected_observations) == 1
    iteration_options = scoped_iterations
    iteration_state_key = "bo_requested_observation_iteration"
    overview, metadata_tab, traces, real_data, surrogate, simulation, gifs, pdf_export = st.tabs(
        [
            "History & scores",
            "Optimization metadata",
            "SWV traces",
            "Real data landscapes",
            "Surrogate",
            "Simulation",
            "GIFs",
            "PDF Export",
        ]
    )

    with metadata_tab:
        st.subheader("Channel-group optimization metadata")
        optimization_metadata = _channel_group_optimization_metadata(
            full_session,
            groups,
        )
        metadata_summary = pd.DataFrame([
            {
                "Group": item["name"],
                "Channels": ", ".join(map(str, item["channels"])),
                "Explore weight": item["exploration"],
                "Exploit weight": item["exploitation"],
                "Initial-point mode": item["initial_point_mode"],
                "Initial random points": item["n_initial_points"],
                "Candidate pool": item["candidate_pool_size"],
                "Local candidate pool": item["local_candidate_pool_size"],
                "Use GP": item["use_gp"],
                "GP optimizer restarts": item["gp_optimizer_restarts"],
                "GP noise": item.get("gp_noise_level"),
                "Simulation seed": item.get("simulation_seed"),
                "Simulation replicate": item.get("simulation_replicate"),
            }
            for item in optimization_metadata
        ])
        st.dataframe(
            metadata_summary,
            use_container_width=True,
            hide_index=True,
            column_config={
                "Explore weight": st.column_config.NumberColumn(format="%.3f"),
                "Exploit weight": st.column_config.NumberColumn(format="%.3f"),
            },
        )
        parameter_config = (full_session.get("config") or {}).get("parameters") or {}
        falloff_parameters = [
            name for name in PARAMETERS
            if any(
                name in item["gp_falloff_fractions"]
                for item in optimization_metadata
            )
        ]
        st.markdown("#### GP falloff fractions")
        if falloff_parameters:
            falloff_rows = []
            for item in optimization_metadata:
                row = {
                    "Group": item["name"],
                    "Channels": ", ".join(map(str, item["channels"])),
                }
                row.update({
                    (parameter_config.get(name) or {}).get("label") or name:
                    item["gp_falloff_fractions"].get(name)
                    for name in falloff_parameters
                })
                falloff_rows.append(row)
            st.table(pd.DataFrame(falloff_rows).set_index("Group"))
            st.caption(
                "Each value is the saved GP falloff fraction for that parameter "
                "and channel group."
            )
        else:
            st.info("No GP falloff fractions were saved for this session.")

        st.markdown("#### Starting points and parameter details")
        first_observations_by_group = {}
        for recorded_observation in full_session["observations"]:
            try:
                group_id = int(recorded_observation.get("group_id", 1))
                iteration = int(recorded_observation.get("iteration", 0))
            except (TypeError, ValueError):
                continue
            current = first_observations_by_group.get(group_id)
            if current is None or iteration < int(current.get("iteration", 0)):
                first_observations_by_group[group_id] = recorded_observation

        start_parameter_names = [
            name for name in PARAMETERS
            if any(name in item["initial_parameters"] for item in optimization_metadata)
        ]
        first_parameter_names = [
            name for name in PARAMETERS
            if any(
                name in (first_observations_by_group.get(int(item["id"])) or {}).get(
                    "params",
                    {},
                )
                for item in optimization_metadata
            )
        ]
        if start_parameter_names:
            start_rows = []
            for item in optimization_metadata:
                row = {
                    "Group": item["name"],
                    "Channels": ", ".join(map(str, item["channels"])),
                    "Initial-point mode": item["initial_point_mode"],
                }
                row.update({
                    (parameter_config.get(name) or {}).get("label") or name:
                    item["initial_parameters"].get(name)
                    for name in start_parameter_names
                })
                start_rows.append(row)
            st.dataframe(
                pd.DataFrame(start_rows),
                use_container_width=True,
                hide_index=True,
            )
            st.caption(
                "Configured starting parameters saved for each channel group."
            )
        else:
            st.info("No configured starting parameters were saved for this session.")

        if first_parameter_names:
            first_rows = []
            for item in optimization_metadata:
                first_observation = first_observations_by_group.get(int(item["id"]))
                first_iteration_params = (
                    dict(first_observation.get("params") or {})
                    if first_observation is not None
                    else {}
                )
                first_rows.append({
                    "Group": item["name"],
                    "Channels": ", ".join(map(str, item["channels"])),
                    "First completed iteration": (
                        first_observation.get("iteration")
                        if first_observation is not None
                        else None
                    ),
                    **{
                        (parameter_config.get(name) or {}).get("label") or name:
                        first_iteration_params.get(name)
                        for name in first_parameter_names
                    },
                })
            st.dataframe(
                pd.DataFrame(first_rows),
                use_container_width=True,
                hide_index=True,
            )
            st.caption(
                "First completed iteration values show the actual parameters "
                "recorded at the start of each channel-group run."
            )

        st.markdown("##### Parameter bounds and GP details")
        parameter_detail_rows = []
        for item in optimization_metadata:
            first_observation = first_observations_by_group.get(int(item["id"]))
            first_iteration_params = (
                dict(first_observation.get("params") or {})
                if first_observation is not None
                else {}
            )
            parameter_names = [
                name for name in PARAMETERS
                if (
                    name in item["initial_parameters"]
                    or name in first_iteration_params
                    or name in item["gp_falloff_fractions"]
                    or name in item["gp_length_scales"]
                )
            ]
            for name in parameter_names:
                definition = parameter_config.get(name) or {}
                parameter_detail_rows.append({
                    "Group": item["name"],
                    "Channels": ", ".join(map(str, item["channels"])),
                    "Parameter": definition.get("label") or name,
                    "Mode": definition.get("mode"),
                    "Start": item["initial_parameters"].get(name),
                    "First iteration": first_iteration_params.get(name),
                    "Unit": definition.get("unit"),
                    "Minimum": definition.get("min"),
                    "Maximum": definition.get("max"),
                    "GP falloff fraction": item[
                        "gp_falloff_fractions"
                    ].get(name),
                    "GP length scale": item["gp_length_scales"].get(name),
                })
        if parameter_detail_rows:
            st.dataframe(
                pd.DataFrame(parameter_detail_rows),
                use_container_width=True,
                hide_index=True,
            )
        else:
            st.caption(
                "No parameter-level starting-point or GP metadata was saved."
            )

        st.divider()
        st.markdown("#### How explore vs exploit affects candidate selection")
        st.write(
            "For every candidate x, the optimizer predicts mean mu(x) and "
            "standard deviation sigma(x). With exploration weight alpha, "
            "it maximizes:"
        )
        st.code(
            "A(x) = (1 - alpha) * [mu(x) + 0.25 * EI(x)]"
            " + alpha * sigma(x)\n"
            "EI(x) = I(x) * Phi(z) + sigma(x) * phi(z)\n"
            "I(x) = mu(x) - Q_best - 0.01\n"
            "z = I(x) / sigma(x)",
            language=None,
        )
        st.write(
            "alpha is the explore weight and (1 - alpha) is the exploit "
            "weight. alpha = 0 favors high predicted Q plus expected "
            "improvement. alpha = 1 favors high GP uncertainty. Phi and phi "
            "are the standard-normal CDF and PDF."
        )
        st.markdown("#### How GP falloff fractions affect the surrogate")
        st.write(
            "Each parameter is mapped to a normalized coordinate from 0 to 1. "
            "Its falloff fraction ell_j is the fixed Matérn-5/2 length scale:"
        )
        st.code(
            "r(x, x') = sqrt(sum_j(((x_j - x'_j) / ell_j)^2))\n"
            "k(x, x') = (1 + sqrt(5)*r + 5*r^2/3) * exp(-sqrt(5)*r)",
            language=None,
        )
        st.write(
            "A smaller ell_j makes correlation fall off quickly when that "
            "parameter changes, allowing a more rapidly varying surrogate. "
            "A larger ell_j makes the GP smoother and extends the influence "
            "of observations along that parameter. Because coordinates are "
            "normalized, ell_j = 0.2 is roughly one fifth of the configured "
            "parameter range."
        )

    with overview:
        trend_history = history
        if (
            selected_observation_group_scope != "all"
            and "group_id" in history.columns
        ):
            history_group_ids = pd.to_numeric(
                history["group_id"],
                errors="coerce",
            )
            trend_history = history.loc[
                history_group_ids.isin(selected_observation_group_ids)
            ].reset_index(drop=True)
        trend_scope_key = str(selected_observation_group_scope)
        available_trend_iterations = pd.to_numeric(
            trend_history.get("iteration", pd.Series(dtype=float)),
            errors="coerce",
        ).dropna().astype(int)
        if available_trend_iterations.empty:
            iteration_start = iteration_end = 0
            plot_observations = []
        else:
            minimum_iteration = int(available_trend_iterations.min())
            maximum_iteration = int(available_trend_iterations.max())
            default_iteration_start = (
                1
                if minimum_iteration <= 1 <= maximum_iteration
                else minimum_iteration
            )
            range_columns = st.columns(2)
            range_key = trend_scope_key
            trend_start_key = f"bo_trend_iteration_start_{range_key}"
            trend_end_key = f"bo_trend_iteration_end_{range_key}"
            trend_start_preference_key = f"{trend_start_key}__preferred"
            trend_end_preference_key = f"{trend_end_key}__preferred"
            _capture_widget_preference(
                trend_start_key,
                trend_start_preference_key,
            )
            _capture_widget_preference(
                trend_end_key,
                trend_end_preference_key,
            )
            preferred_start = int(st.session_state.get(
                trend_start_preference_key,
                default_iteration_start,
            ))
            preferred_end = int(st.session_state.get(
                trend_end_preference_key,
                maximum_iteration,
            ))
            st.session_state[trend_start_key] = min(
                maximum_iteration,
                max(minimum_iteration, preferred_start),
            )
            st.session_state[trend_end_key] = min(
                maximum_iteration,
                max(minimum_iteration, preferred_end),
            )
            iteration_start = int(range_columns[0].number_input(
                "Plot iteration start",
                min_value=minimum_iteration,
                max_value=maximum_iteration,
                value=default_iteration_start,
                step=1,
                key=trend_start_key,
            ))
            iteration_end = int(range_columns[1].number_input(
                "Plot iteration end",
                min_value=minimum_iteration,
                max_value=maximum_iteration,
                value=maximum_iteration,
                step=1,
                key=trend_end_key,
            ))
            st.session_state[trend_start_preference_key] = iteration_start
            st.session_state[trend_end_preference_key] = iteration_end
            if iteration_start > iteration_end:
                st.warning(
                    "Iteration start is greater than iteration end; "
                    "the bounds are being applied in ascending order."
                )
                iteration_start, iteration_end = iteration_end, iteration_start
            trend_iterations = pd.to_numeric(
                trend_history["iteration"],
                errors="coerce",
            )
            trend_history = trend_history.loc[
                trend_iterations.between(iteration_start, iteration_end)
            ].reset_index(drop=True)
            plot_observations = [
                observation
                for observation in group_scoped_observations
                if iteration_start
                <= int(observation.get("iteration", 0))
                <= iteration_end
            ]
        channel_metrics = _channel_metric_columns(trend_history)
        if selected_observation_group_scope != "all":
            selected_trend_groups = [
                group for group in groups
                if int(group["id"]) in selected_observation_group_ids
            ]
            configured_channels = {
                str(channel)
                for group in selected_trend_groups
                for channel in group.get("channels", [])
            }
            if configured_channels:
                channel_metrics = {
                    metric_name: {
                        channel: column
                        for channel, column in columns.items()
                        if channel in configured_channels
                    }
                    for metric_name, columns in channel_metrics.items()
                }
                channel_metrics = {
                    metric_name: columns
                    for metric_name, columns in channel_metrics.items()
                    if columns
                }
        channel_column_names = {
            column for column in trend_history.columns
            if (
                re.fullmatch(r"Q_ch\d+", str(column), re.IGNORECASE)
                or re.fullmatch(r"ch\d+_.+", str(column), re.IGNORECASE)
            )
        }
        global_metrics = [
            metric for metric in _numeric_columns(trend_history)
            if metric not in channel_column_names
        ]
        metric_options = (
            [f"global::{metric}" for metric in global_metrics]
            + [f"channel::{metric}" for metric in channel_metrics]
        )
        if metric_options:
            default_metric = (
                "global::Q_run"
                if "Q_run" in global_metrics
                else metric_options[0]
            )
            trend_metric_key = f"bo_trend_metric_{trend_scope_key}"
            _preserve_valid_widget_value(
                trend_metric_key,
                metric_options,
                default_metric,
            )
            metric_choice = st.selectbox(
                "Trend metric",
                metric_options,
                format_func=lambda choice: _metric_label(choice.split("::", 1)[1]),
                key=trend_metric_key,
            )
        else:
            st.info("No trend metrics change within the current group scope.")
            metric_choice = "global::__no_changing_metric__"
        metric_kind, metric = metric_choice.split("::", 1)
        plot_metric_kind = metric_kind
        plot_metric = metric
        ground_truth_trend_channels = (
            sorted(
                trend_history["ground_truth_channel"].dropna().astype(str).unique(),
                key=_channel_sort_key,
            )
            if "ground_truth_channel" in trend_history.columns
            else []
        )
        q_run_channel_view = None
        global_channel_view = None
        if (
            metric_kind == "global"
            and metric == "Q_run"
            and "Q_channel" in channel_metrics
        ):
            q_display_options = [
                "Run-level Q",
                "Average channel Q",
                "Overlay channel Q",
                "Separate channel Q plots",
            ]
            q_display_key = f"bo_q_run_display_{trend_scope_key}"
            _preserve_valid_widget_value(
                q_display_key,
                q_display_options,
                q_display_options[0],
            )
            q_run_channel_view = st.radio(
                "Q series",
                q_display_options,
                horizontal=True,
                key=q_display_key,
                help=(
                    "Chooses whether Q run is shown as the saved run-level "
                    "objective or expanded into channel Q traces."
                ),
            )
            if q_run_channel_view != "Run-level Q":
                plot_metric_kind = "channel"
                plot_metric = "Q_channel"
        elif (
            metric_kind == "global"
            and metric in trend_history.columns
            and len(ground_truth_trend_channels) > 1
        ):
            metric_display_label = _metric_label(metric)
            global_display_options = [
                f"Run-level {metric_display_label}",
                f"Average channel {metric_display_label}",
                f"Overlay channel {metric_display_label}",
                f"Separate channel {metric_display_label} plots",
            ]
            global_display_key = (
                f"bo_global_channel_display_{trend_scope_key}_{metric}"
            )
            _preserve_valid_widget_value(
                global_display_key,
                global_display_options,
                global_display_options[0],
            )
            global_channel_view = st.radio(
                f"{metric_display_label} series",
                global_display_options,
                horizontal=True,
                key=global_display_key,
                help=(
                    "Chooses whether this parameter trend is shown as saved "
                    "simulation-run rows or expanded into real-channel traces."
                ),
            )
            if global_channel_view != global_display_options[0]:
                plot_metric_kind = "channel"
                plot_metric = metric
                channel_metrics[plot_metric] = {
                    channel: metric
                    for channel in ground_truth_trend_channels
                }
        group_layout = "Plot groups overlaid"
        group_color_values = None
        group_color_label = None
        group_average_values = None
        group_average_label = None
        has_multiple_trend_groups = (
            metric in trend_history.columns
            and
            "group_id" in trend_history.columns
            and trend_history["group_id"].nunique(dropna=True) > 1
        )
        if has_multiple_trend_groups:
            trend_group_metadata = _channel_group_optimization_metadata(
                full_session,
                groups,
            )
            is_simulated_trend_session = bool(
                ((full_session.get("config") or {}).get("records") or {}).get(
                    "simulated_session"
                )
            )

            def group_layout_display_label(option: str) -> str:
                if not is_simulated_trend_session:
                    return option
                return (
                    option
                    .replace("groups", "simulation runs")
                    .replace("Groups", "Simulation runs")
                    .replace("group", "simulation run")
                    .replace("Group", "Simulation run")
                )

            group_layout_options = [
                "Plot groups overlaid",
                "Plot groups separately",
                "Average groups together",
            ]
            metadata_group_options: dict[str, tuple[dict[int, float], str]] = {}
            initial_values = {
                item["id"]: float(item["n_initial_points"])
                for item in trend_group_metadata
                if _finite_float(item.get("n_initial_points")) is not None
            }
            if initial_values:
                metadata_group_options[
                    "Average groups with same initial maximin points"
                ] = (initial_values, "Initial maximin")
            exploration_values = {
                item["id"]: float(item["exploration"])
                for item in trend_group_metadata
                if item["exploration"] is not None
            }
            if exploration_values:
                metadata_group_options[
                    "Average groups with same exploration weight"
                ] = (exploration_values, "Exploration")
            parameter_config = (
                (full_session.get("config") or {}).get("parameters") or {}
            )
            for parameter in PARAMETERS:
                falloff_values = {
                    item["id"]: float(item["gp_falloff_fractions"][parameter])
                    for item in trend_group_metadata
                    if parameter in item["gp_falloff_fractions"]
                    and _finite_float(item["gp_falloff_fractions"][parameter])
                    is not None
                }
                if falloff_values:
                    parameter_label = (
                        (parameter_config.get(parameter) or {}).get("label")
                        or parameter
                    )
                    metadata_group_options[
                        f"Average groups with same GP falloff — {parameter_label}"
                    ] = (falloff_values, f"{parameter_label} GP falloff")
            group_layout_options.extend(metadata_group_options)
            group_layout_key = f"bo_trend_group_layout_{trend_scope_key}_{metric}"
            _preserve_valid_widget_value(
                group_layout_key,
                group_layout_options,
                group_layout_options[0],
            )
            group_layout = st.selectbox(
                "Simulation run display" if is_simulated_trend_session else "Group display",
                group_layout_options,
                format_func=group_layout_display_label,
                key=group_layout_key,
                help=(
                    "Controls how repeated simulation runs are arranged. "
                    "For per-channel sweeps, each exploration-rate/channel "
                    "combination is one simulation run."
                    if is_simulated_trend_session
                    else None
                ),
            )
            if group_layout in metadata_group_options:
                group_average_values, group_average_label = metadata_group_options[
                    group_layout
                ]
            if group_layout != "Average groups together":
                color_options: dict[str, tuple[dict[int, float] | None, str | None]] = {
                    "Default categorical colors": (None, None),
                    "Initial random/maximin points": (
                        {
                            item["id"]: float(item["n_initial_points"])
                            for item in trend_group_metadata
                            if _finite_float(item.get("n_initial_points")) is not None
                        },
                        "Initial points",
                    ),
                    "Exploration weight": (
                        {
                            item["id"]: float(item["exploration"])
                            for item in trend_group_metadata
                            if item["exploration"] is not None
                        },
                        "Exploration",
                    ),
                    "Exploitation weight": (
                        {
                            item["id"]: float(item["exploitation"])
                            for item in trend_group_metadata
                            if item["exploitation"] is not None
                        },
                        "Exploitation",
                    ),
                }
                for parameter in PARAMETERS:
                    values = {
                        item["id"]: float(
                            item["gp_falloff_fractions"][parameter]
                        )
                        for item in trend_group_metadata
                        if parameter in item["gp_falloff_fractions"]
                    }
                    if values:
                        parameter_label = (
                            (parameter_config.get(parameter) or {}).get("label")
                            or parameter
                        )
                        option_label = f"GP falloff — {parameter_label}"
                        color_options[option_label] = (
                            values,
                            f"{parameter_label} GP falloff",
                        )
                group_color_key = (
                    f"bo_trend_group_colormap_{trend_scope_key}_{metric}"
                )
                _preserve_valid_widget_value(
                    group_color_key,
                    list(color_options),
                    "Default categorical colors",
                )
                group_color_choice = st.selectbox(
                    "Group colormap metadata metric",
                    list(color_options),
                    key=group_color_key,
                )
                group_color_values, group_color_label = color_options[
                    group_color_choice
                ]
        chart_key_suffix = metric
        simulation_optimum_reference = _session_simulation_optimum_reference(full_session)
        simulation_group_optimum_references = (
            _session_simulation_group_optimum_references(
                full_session,
                trend_history,
            )
        )
        trend_reference_value = None
        trend_reference_label = None
        trend_reference_values_by_group: dict[int, float] = {}
        if plot_metric_kind == "global":
            reference_metric = "Q_run" if metric == "Q_run" else metric
            if reference_metric in {
                "Q_run",
                "frequency",
                "amplitude",
                "step_potential",
            }:
                trend_reference_label = (
                    "Best possible Q"
                    if reference_metric == "Q_run"
                    else f"Best-Q {_metric_label(reference_metric)}"
                )
                trend_reference_values_by_group = {
                    group_id: float(reference[reference_metric])
                    for group_id, reference
                    in simulation_group_optimum_references.items()
                    if _finite_float(reference.get(reference_metric)) is not None
                }
                displayed_group_ids = set()
                if "group_id" in trend_history.columns:
                    displayed_group_ids = {
                        int(group_id)
                        for group_id in pd.to_numeric(
                            trend_history["group_id"],
                            errors="coerce",
                        ).dropna().unique()
                    }
                if (
                    trend_reference_values_by_group
                    and displayed_group_ids
                    and len(displayed_group_ids) == 1
                ):
                    only_group_id = next(iter(displayed_group_ids))
                    trend_reference_value = trend_reference_values_by_group.get(
                        only_group_id
                    )
                    trend_reference_values_by_group = {}
                elif not trend_reference_values_by_group:
                    trend_reference_value = (
                        simulation_optimum_reference or {}
                    ).get(reference_metric)
        elif plot_metric_kind == "channel" and plot_metric in {
            "Q_channel",
            "classic_Q",
            "frequency",
            "amplitude",
            "step_potential",
        }:
            reference_metric = (
                "Q_run"
                if plot_metric in {"Q_channel", "classic_Q"}
                else plot_metric
            )
            trend_reference_label = (
                "Best possible Q"
                if reference_metric == "Q_run"
                else f"Best-Q {_metric_label(reference_metric)}"
            )
            trend_reference_values_by_group = {
                group_id: float(reference[reference_metric])
                for group_id, reference
                in simulation_group_optimum_references.items()
                if _finite_float(reference.get(reference_metric)) is not None
            }
            displayed_group_ids = set()
            if "group_id" in trend_history.columns:
                displayed_group_ids = {
                    int(group_id)
                    for group_id in pd.to_numeric(
                        trend_history["group_id"],
                        errors="coerce",
                    ).dropna().unique()
                }
            if (
                trend_reference_values_by_group
                and displayed_group_ids
                and len(displayed_group_ids) == 1
            ):
                only_group_id = next(iter(displayed_group_ids))
                trend_reference_value = trend_reference_values_by_group.get(
                    only_group_id
                )
                trend_reference_values_by_group = {}
            elif not trend_reference_values_by_group:
                trend_reference_value = (
                    simulation_optimum_reference or {}
                ).get(reference_metric)
        trend_trace_opacity = float(st.slider(
            "Trend plot opacity",
            min_value=0.05,
            max_value=1.0,
            value=1.0,
            step=0.05,
            format="%.2f",
            key=f"bo_trend_trace_opacity_{trend_scope_key}_{plot_metric_kind}_{plot_metric}",
            help=(
                "Transparency for the metric-vs-iteration trend traces. "
                "Reference lines remain fully opaque."
            ),
        ))
        if plot_metric_kind == "channel":
            available_metric_channels = sorted(
                channel_metrics[plot_metric],
                key=_channel_sort_key,
            )
            trend_channels_key = f"bo_trend_channels_{trend_scope_key}_{plot_metric}"
            trend_channels_valid, trend_channels_display = (
                _prepare_preferred_multiselect_value(
                    trend_channels_key,
                    f"{trend_channels_key}__preferred",
                    available_metric_channels,
                    available_metric_channels,
                )
            )
            trend_channels = st.multiselect(
                "Trend channels",
                available_metric_channels,
                default=trend_channels_display,
                format_func=lambda channel: f"Ch {channel}",
                key=trend_channels_key,
            )
            _sync_preferred_widget_value(
                trend_channels_key,
                f"{trend_channels_key}__preferred",
                trend_channels_valid,
                trend_channels_display,
            )
            if global_channel_view is not None:
                metric_display_label = _metric_label(plot_metric)
                channel_layout = {
                    f"Average channel {metric_display_label}": (
                        "Average selected channels"
                    ),
                    f"Overlay channel {metric_display_label}": (
                        "Overlay selected channels"
                    ),
                    f"Separate channel {metric_display_label} plots": (
                        "Separate plots"
                    ),
                }[global_channel_view]
            elif q_run_channel_view is None:
                channel_layout_options = [
                    "Overlay selected channels",
                    "Separate plots",
                    "Average selected channels",
                ]
                channel_layout_key = f"bo_trend_layout_{trend_scope_key}_{plot_metric}"
                _preserve_valid_widget_value(
                    channel_layout_key,
                    channel_layout_options,
                    channel_layout_options[0],
                )
                channel_layout = st.radio(
                    "Channel display",
                    channel_layout_options,
                    horizontal=True,
                    key=channel_layout_key,
                )
            else:
                channel_layout = {
                    "Average channel Q": "Average selected channels",
                    "Overlay channel Q": "Overlay selected channels",
                    "Separate channel Q plots": "Separate plots",
                }[q_run_channel_view]
            if trend_channels:
                trend_figure = _plot_channel_trend(
                    trend_history,
                    plot_metric,
                    channel_metrics[plot_metric],
                    trend_channels,
                    channel_layout,
                    group_layout,
                    group_color_values,
                    group_color_label,
                    group_average_values,
                    group_average_label,
                    reference_values_by_group=trend_reference_values_by_group,
                    reference_label=trend_reference_label,
                    trace_opacity=trend_trace_opacity,
                )
            else:
                trend_figure = go.Figure()
                trend_figure.add_annotation(
                    text="Select at least one trend channel.",
                    x=.5, y=.5, xref="paper", yref="paper", showarrow=False,
                )
                trend_figure.update_layout(height=340)
            chart_key_suffix = (
                f"{metric}_{plot_metric}_{channel_layout}_"
                f"{group_layout}_{group_color_label or 'categorical'}_"
                f"{group_average_label or 'no_metadata_average'}_"
                f"{'_'.join(trend_channels) or 'none'}"
            )
        else:
            trend_figure = _plot_trend(
                trend_history,
                metric,
                group_layout,
                group_color_values,
                group_color_label,
                group_average_values,
                group_average_label,
                reference_value=trend_reference_value,
                reference_label=trend_reference_label,
                reference_values_by_group=trend_reference_values_by_group,
                trace_opacity=trend_trace_opacity,
            )
            chart_key_suffix = (
                f"{metric}_{group_layout}_{group_color_label or 'categorical'}_"
                f"{group_average_label or 'no_metadata_average'}"
            )
        chart_key_suffix = (
            f"{trend_scope_key}_{iteration_start}_{iteration_end}_"
            f"{chart_key_suffix}"
        )
        if group_color_values is None:
            trend_figure = _strip_categorical_plot_colorbars(trend_figure)
        trend_y_limits = _manual_y_axis_range_control(
            "trend",
            f"bo_trend_{trend_scope_key}_{metric}",
            [trend_figure],
        )
        if trend_y_limits is not None:
            _apply_y_axis_range(trend_figure, *trend_y_limits)
            chart_key_suffix = (
                f"{chart_key_suffix}_ylim_{trend_y_limits[0]:g}_{trend_y_limits[1]:g}"
            )
        trend_events = [
            _render_downloadable_plotly(
                st,
                trend_figure,
                key=f"bo_trend_{chart_key_suffix}",
                file_stem=f"history_scores_trend_{chart_key_suffix}",
                width_percent=plot_width_percent,
                export_height=int(trend_figure.layout.height or 520),
                on_select="rerun",
                selection_mode="points",
            )
        ]
        trend_q_kind = _metric_q_kind(metric, paired_objective)
        if trend_q_kind:
            _render_q_equation(session["config"], trend_q_kind)

        @st.fragment
        def _render_hyperparameter_response_fragment() -> None:
            hyperparameter_columns = _hyperparameter_response_columns(trend_history)
            hyper_metric_options = list(metric_options)
            has_best_q_source = any(
                column in trend_history.columns
                for column in ("Q_run", "best_Q", "best_so_far", "observed_value")
            )
            if has_best_q_source:
                for parameter in ("frequency", "amplitude", "step_potential"):
                    if parameter in trend_history.columns:
                        hyper_metric_options.append(
                            f"derived::{parameter}_at_best_q"
                        )
            if len(hyperparameter_columns) >= 2 and hyper_metric_options:
                st.divider()
                st.subheader("Hyperparameter response")
                hp_columns = st.columns(7)
                default_hp_metric = (
                    "global::Q_run" if "global::Q_run" in hyper_metric_options
                    else "global::best_so_far" if "global::best_so_far" in hyper_metric_options
                    else hyper_metric_options[0]
                )
                _preserve_valid_widget_value(
                    "bo_hp_response_metric",
                    hyper_metric_options,
                    default_hp_metric,
                )
                hp_metric = hp_columns[0].selectbox(
                    "Response metric",
                    hyper_metric_options,
                    format_func=lambda choice: _metric_label(choice.split("::", 1)[1]),
                    key="bo_hp_response_metric",
                )
                hp_metric_kind, hp_metric_name = hp_metric.split("::", 1)
                hp_metric_key = hp_metric.split("::", 1)[1]
                hp_metric_label = _metric_label(hp_metric_name)
                hp_at_best_q_parameter = (
                    hp_metric_name.removesuffix("_at_best_q")
                    if hp_metric_kind == "derived"
                    and hp_metric_name.endswith("_at_best_q")
                    else None
                )
                hp_view_options = (
                    ["2D heatmap", "3D heatmap"]
                    if len(hyperparameter_columns) >= 3
                    else ["2D heatmap"]
                )
                _preserve_valid_widget_value(
                    "bo_hp_response_view",
                    hp_view_options,
                    hp_view_options[0],
                )
                hp_view = hp_columns[1].selectbox(
                    "View",
                    hp_view_options,
                    key="bo_hp_response_view",
                )
                _preserve_valid_widget_value(
                    "bo_hp_response_x",
                    hyperparameter_columns,
                    (
                        "gp_falloff_value"
                        if "gp_falloff_value" in hyperparameter_columns
                        else hyperparameter_columns[0]
                    ),
                )
                hp_x = hp_columns[2].selectbox(
                    "X hyperparameter",
                    hyperparameter_columns,
                    format_func=_metric_label,
                    key="bo_hp_response_x",
                )
                hp_y_options = [
                    column for column in hyperparameter_columns if column != hp_x
                ]
                _preserve_valid_widget_value(
                    "bo_hp_response_y",
                    hp_y_options,
                    (
                        "exploration"
                        if "exploration" in hp_y_options
                        else hp_y_options[0]
                    ),
                )
                hp_y = hp_columns[3].selectbox(
                    "Y hyperparameter",
                    hp_y_options,
                    format_func=_metric_label,
                    key="bo_hp_response_y",
                )
                hp_z = None
                hp_2d_slice_column = None
                hp_2d_slice_value = None
                hp_3d_slice_axis = None
                hp_3d_slice_value = None
                hp_3d_slice_value_key = None
                hp_3d_slice_values = []
                hp_3d_mouse_mode = "Rotate/view 3D plot"
                hp_voxel_face_opacity = 0.1
                hp_voxel_internal_opacity = 1.0
                hp_voxel_internal_point_size = 20
                hp_voxel_internal_point_count = 1
                if hp_view == "3D heatmap":
                    hp_z_options = [
                        column for column in hyperparameter_columns
                        if column not in {hp_x, hp_y}
                    ]
                    _preserve_valid_widget_value(
                        "bo_hp_response_z",
                        hp_z_options,
                        hp_z_options[0],
                    )
                    hp_z = hp_columns[4].selectbox(
                        "Z hyperparameter",
                        hp_z_options,
                        format_func=_metric_label,
                        key="bo_hp_response_z",
                    )
                    hp_3d_slice_axes = [hp_x, hp_y, hp_z]
                    hp_3d_slice_axis_choices = [
                        NO_HIGHLIGHTED_SLICE_LABEL,
                        *hp_3d_slice_axes,
                    ]
                    slice_control_columns = st.columns(3)
                    _preserve_valid_widget_value(
                        "bo_hp_response_3d_slice_axis",
                        hp_3d_slice_axis_choices,
                        NO_HIGHLIGHTED_SLICE_LABEL,
                    )
                    hp_3d_slice_axis_choice = slice_control_columns[0].selectbox(
                        "Highlighted slice axis",
                        hp_3d_slice_axis_choices,
                        format_func=lambda value: (
                            value
                            if value == NO_HIGHLIGHTED_SLICE_LABEL
                            else _metric_label(value)
                        ),
                        key="bo_hp_response_3d_slice_axis",
                        help=(
                            "Click a 3D heatmap point to set the slice value "
                            "for this axis. The selected slice is drawn as a "
                            "transparent red plane."
                        ),
                    )
                    hp_3d_slice_axis = (
                        None
                        if hp_3d_slice_axis_choice == NO_HIGHLIGHTED_SLICE_LABEL
                        else hp_3d_slice_axis_choice
                    )
                    mouse_mode_options = [
                        "Rotate/view 3D plot",
                        "Pick slice by clicking",
                    ]
                    _preserve_valid_widget_value(
                        "bo_hp_response_3d_mouse_mode",
                        mouse_mode_options,
                        mouse_mode_options[0],
                    )
                    hp_3d_mouse_mode = slice_control_columns[2].selectbox(
                        "Mouse mode",
                        mouse_mode_options,
                        key="bo_hp_response_3d_mouse_mode",
                        help=(
                            "Use rotate/view for normal 3D interaction. Switch "
                            "to click-pick only when selecting a slice from the "
                            "plot with the mouse."
                        ),
                    )
                    st.caption(
                        "Default mouse mode preserves 3D rotate/pan/zoom. To "
                        "select with the mouse, switch to Pick slice by clicking, "
                        "choose the slice axis, then click a 3D point."
                    )
                    if hp_3d_slice_axis is not None:
                        hp_3d_slice_values = sorted(
                            pd.to_numeric(
                                trend_history[hp_3d_slice_axis],
                                errors="coerce",
                            ).dropna().unique().tolist()
                        )
                    if hp_3d_slice_axis is not None and hp_3d_slice_values:
                        hp_3d_slice_value_key = (
                            f"bo_hp_response_3d_slice_value_"
                            f"{hp_x}_{hp_y}_{hp_z}_{hp_3d_slice_axis}"
                        )
                        _preserve_valid_widget_value(
                            hp_3d_slice_value_key,
                            hp_3d_slice_values,
                            hp_3d_slice_values[0],
                        )
                        hp_3d_slice_value = float(
                            slice_control_columns[1].selectbox(
                                f"Slice {_metric_label(hp_3d_slice_axis)}",
                                hp_3d_slice_values,
                                format_func=lambda value: f"{float(value):g}",
                                key=hp_3d_slice_value_key,
                            )
                        )
                    render_settings_key = "bo_hp_response_3d_render_settings"
                    st.session_state.setdefault(
                        render_settings_key,
                        {
                            "face_opacity": 0.1,
                            "internal_opacity": 1.0,
                            "point_size": 20,
                            "point_count": 1,
                        },
                    )
                    applied_render_settings = dict(
                        st.session_state[render_settings_key]
                    )
                    applied_render_settings.setdefault("face_opacity", 0.1)
                    applied_render_settings.setdefault("internal_opacity", 1.0)
                    applied_render_settings.setdefault("point_size", 20)
                    applied_render_settings.setdefault("point_count", 1)
                    opacity_columns = st.columns(4)
                    draft_face_opacity = float(opacity_columns[0].slider(
                        "Voxel face alpha",
                        min_value=0.0,
                        max_value=1.0,
                        value=float(applied_render_settings["face_opacity"]),
                        step=0.05,
                        key="bo_hp_response_voxel_face_opacity_draft",
                    ))
                    draft_internal_opacity = float(opacity_columns[1].slider(
                        "Internal point opacity",
                        min_value=0.0,
                        max_value=1.0,
                        value=float(applied_render_settings["internal_opacity"]),
                        step=0.05,
                        key="bo_hp_response_voxel_internal_opacity_draft",
                    ))
                    draft_point_size = int(opacity_columns[2].slider(
                        "Internal point size",
                        min_value=1,
                        max_value=50,
                        value=int(applied_render_settings["point_size"]),
                        step=1,
                        key="bo_hp_response_voxel_internal_point_size_draft",
                    ))
                    point_count_options = [1, 4, 27, 64]
                    draft_point_count = int(opacity_columns[3].selectbox(
                        "Internal point number",
                        point_count_options,
                        index=point_count_options.index(
                            int(applied_render_settings["point_count"])
                            if int(applied_render_settings["point_count"]) in point_count_options
                            else 27
                        ),
                        key="bo_hp_response_voxel_internal_point_count_draft",
                    ))
                    hp_voxel_face_opacity = draft_face_opacity
                    hp_voxel_internal_opacity = draft_internal_opacity
                    hp_voxel_internal_point_size = draft_point_size
                    hp_voxel_internal_point_count = draft_point_count
                if hp_view == "2D heatmap":
                    hp_2d_slice_options = [
                        column for column in hyperparameter_columns
                        if column not in {hp_x, hp_y}
                    ]
                    if hp_2d_slice_options:
                        slice_columns = st.columns(2)
                        hp_2d_slice_choices = [
                            *hp_2d_slice_options,
                            "Average all other unplotted values",
                        ]
                        hp_2d_slice_column_key = (
                            f"bo_hp_response_2d_slice_column_{hp_x}_{hp_y}"
                        )
                        _preserve_valid_widget_value(
                            hp_2d_slice_column_key,
                            hp_2d_slice_choices,
                            hp_2d_slice_options[0],
                        )
                        hp_2d_slice_choice = slice_columns[0].selectbox(
                            "Fixed third parameter",
                            hp_2d_slice_choices,
                            format_func=lambda choice: (
                                choice
                                if choice == "Average all other unplotted values"
                                else _metric_label(choice)
                            ),
                            key=hp_2d_slice_column_key,
                        )
                        if hp_2d_slice_choice != "Average all other unplotted values":
                            hp_2d_slice_column = hp_2d_slice_choice
                            hp_2d_slice_values = sorted(
                                pd.to_numeric(
                                    trend_history[hp_2d_slice_column],
                                    errors="coerce",
                                ).dropna().unique().tolist()
                            )
                            if hp_2d_slice_values:
                                hp_2d_slice_value_key = (
                                    f"bo_hp_response_2d_slice_value_"
                                    f"{hp_x}_{hp_y}_{hp_2d_slice_column}"
                                )
                                hp_2d_slice_options_key = (
                                    f"{hp_2d_slice_value_key}__options"
                                )
                                hp_2d_slice_options_signature = tuple(
                                    round(float(value), 12)
                                    for value in hp_2d_slice_values
                                )
                                if (
                                    st.session_state.get(hp_2d_slice_options_key)
                                    != hp_2d_slice_options_signature
                                ):
                                    st.session_state.pop(
                                        f"{hp_2d_slice_value_key}__preferred",
                                        None,
                                    )
                                    st.session_state[hp_2d_slice_options_key] = (
                                        hp_2d_slice_options_signature
                                    )
                                _preserve_valid_widget_value(
                                    hp_2d_slice_value_key,
                                    hp_2d_slice_values,
                                    hp_2d_slice_values[0],
                                )
                                hp_2d_slice_value = float(
                                    slice_columns[1].selectbox(
                                        f"Fixed {_metric_label(hp_2d_slice_column)}",
                                        hp_2d_slice_values,
                                        format_func=lambda value: f"{float(value):g}",
                                        key=hp_2d_slice_value_key,
                                    )
                                )
                hp_crop_ranges: dict[str, tuple[float, float]] = {}
                hp_crop_axes = [
                    axis for axis in [hp_x, hp_y, hp_z]
                    if axis is not None
                ]
                with st.expander("Crop heatmap/tensor by parameter", expanded=False):
                    hp_crop_enabled = st.checkbox(
                        "Enable parameter crop",
                        key=(
                            f"bo_hp_response_crop_enabled_{trend_scope_key}_"
                            f"{hp_view}_{hp_x}_{hp_y}_{hp_z or 'none'}"
                        ),
                    )
                    if hp_crop_enabled:
                        st.caption(
                            "Crop limits are applied before aggregation and plotting."
                        )
                        crop_columns = st.columns(len(hp_crop_axes))
                        for axis_index, axis_name in enumerate(hp_crop_axes):
                            axis_values = pd.to_numeric(
                                trend_history[axis_name],
                                errors="coerce",
                            ).dropna()
                            if axis_values.empty:
                                continue
                            axis_min = float(axis_values.min())
                            axis_max = float(axis_values.max())
                            axis_step = max(
                                abs(axis_max - axis_min) / 100.0,
                                1e-9,
                            )
                            with crop_columns[axis_index]:
                                st.markdown(f"**{_metric_label(axis_name)}**")
                                crop_min = float(st.number_input(
                                    "Min",
                                    value=axis_min,
                                    step=axis_step,
                                    format="%.8g",
                                    key=(
                                        f"bo_hp_response_crop_min_"
                                        f"{trend_scope_key}_{hp_view}_"
                                        f"{hp_x}_{hp_y}_{hp_z or 'none'}_{axis_name}"
                                    ),
                                ))
                                crop_max = float(st.number_input(
                                    "Max",
                                    value=axis_max,
                                    step=axis_step,
                                    format="%.8g",
                                    key=(
                                        f"bo_hp_response_crop_max_"
                                        f"{trend_scope_key}_{hp_view}_"
                                        f"{hp_x}_{hp_y}_{hp_z or 'none'}_{axis_name}"
                                    ),
                                ))
                            if crop_min > crop_max:
                                crop_min, crop_max = crop_max, crop_min
                            hp_crop_ranges[axis_name] = (crop_min, crop_max)
                if hp_at_best_q_parameter is not None:
                    hp_summary_options = ["At best Q"]
                    hp_threshold_metric = False
                else:
                    hp_summary_options = [
                        "Final iteration",
                        "Best over iterations",
                        "Mean over iterations",
                        "Specific iteration",
                    ]
                    hp_threshold_metric = "q" in hp_metric_name.lower()
                    if hp_threshold_metric:
                        hp_summary_options.append("Iterations to Q target")
                _preserve_valid_widget_value(
                    "bo_hp_response_summary",
                    hp_summary_options,
                    "Final iteration",
                )
                hp_summary = hp_columns[5].selectbox(
                    "Run summary",
                    hp_summary_options,
                    key="bo_hp_response_summary",
                )
                hp_aggregate_options = ["Mean", "Median", "Maximum", "Minimum"]
                _preserve_valid_widget_value(
                    "bo_hp_response_aggregate",
                    hp_aggregate_options,
                    "Mean",
                )
                hp_aggregate = hp_columns[6].selectbox(
                    "Repeat aggregation",
                    hp_aggregate_options,
                    key="bo_hp_response_aggregate",
                )
                hp_iteration = None
                if hp_summary == "Specific iteration" and not available_trend_iterations.empty:
                    hp_iteration = int(st.number_input(
                        "Hyperparameter response iteration",
                        min_value=int(available_trend_iterations.min()),
                        max_value=int(available_trend_iterations.max()),
                        value=int(available_trend_iterations.max()),
                        step=1,
                        key="bo_hp_response_iteration",
                    ))
                hp_q_target = None
                hp_include_misses = False
                if hp_summary == "Iterations to Q target":
                    threshold_columns = st.columns([1, 1])
                    hp_q_target = float(threshold_columns[0].number_input(
                        "Target Q score",
                        value=0.8,
                        step=0.01,
                        format="%.6g",
                        key=f"bo_hp_response_q_target_{trend_scope_key}_{hp_metric_key}",
                        help=(
                            "Plots the first BO iteration where the run's best "
                            "Q reaches or exceeds this value."
                        ),
                    ))
                    hp_include_misses = threshold_columns[1].checkbox(
                        "Plot runs that do not reach target",
                        value=True,
                        key=(
                            f"bo_hp_response_q_target_include_misses_"
                            f"{trend_scope_key}_{hp_metric_key}"
                        ),
                        help=(
                            "Unreached runs are shown as one iteration past "
                            "that run's last available iteration."
                        ),
                    )
                hp_force_render_key = (
                    f"bo_hp_response_force_render_{trend_scope_key}"
                )
                hp_pending_gif_key = (
                    f"bo_hp_response_generate_gif_pending_{trend_scope_key}"
                )
                hp_apply_response_settings = st.button(
                    "Render hyperparameter response",
                    type="primary",
                    key="bo_hp_response_render_button",
                ) or bool(st.session_state.pop(hp_force_render_key, False))
                if hp_apply_response_settings and hp_view == "3D heatmap":
                    st.session_state[render_settings_key] = {
                        "face_opacity": draft_face_opacity,
                        "internal_opacity": draft_internal_opacity,
                        "point_size": draft_point_size,
                        "point_count": draft_point_count,
                    }
                    applied_render_settings = dict(
                        st.session_state[render_settings_key]
                    )
                    hp_voxel_face_opacity = float(
                        applied_render_settings["face_opacity"]
                    )
                    hp_voxel_internal_opacity = float(
                        applied_render_settings["internal_opacity"]
                    )
                    hp_voxel_internal_point_size = int(
                        applied_render_settings["point_size"]
                    )
                    hp_voxel_internal_point_count = int(
                        applied_render_settings.get("point_count", 1)
                    )
                hp_render_cache_key = (
                    f"bo_hp_response_render_cache_{trend_scope_key}"
                )
                hp_cached_render = st.session_state.get(hp_render_cache_key)
                hp_needs_render_compute = (
                    hp_apply_response_settings or hp_cached_render is not None
                )
                hp_response_history = trend_history
                if hp_metric_kind == "channel":
                    hp_channel_options = sorted(
                        channel_metrics.get(hp_metric_name, {}),
                        key=_channel_sort_key,
                    )
                    hp_channel_key = f"bo_hp_response_channels_{hp_metric_name}"
                    hp_valid_channels, hp_display_channels = (
                        _prepare_preferred_multiselect_value(
                            hp_channel_key,
                            f"{hp_channel_key}__preferred",
                            hp_channel_options,
                            hp_channel_options,
                        )
                    )
                    hp_selected_channels = st.multiselect(
                        "Response channels",
                        hp_channel_options,
                        default=hp_display_channels,
                        format_func=lambda channel: f"Ch {channel}",
                        key=hp_channel_key,
                    )
                    _sync_preferred_widget_value(
                        hp_channel_key,
                        f"{hp_channel_key}__preferred",
                        hp_valid_channels,
                        hp_display_channels,
                    )
                    if hp_needs_render_compute:
                        hp_selected_columns = [
                            channel_metrics[hp_metric_name][channel]
                            for channel in hp_selected_channels
                            if channel in channel_metrics.get(hp_metric_name, {})
                        ]
                        hp_metric_key = "__hp_channel_response_metric"
                        hp_metric_label = _metric_label(hp_metric_name)
                        hp_response_history = trend_history.copy()
                        hp_response_history[hp_metric_key] = (
                            hp_response_history[hp_selected_columns]
                            .apply(pd.to_numeric, errors="coerce")
                            .mean(axis=1)
                            if hp_selected_columns
                            else np.nan
                        )
                if not hp_apply_response_settings and hp_cached_render is None:
                    st.info(
                        "Click Render hyperparameter response to generate the plot "
                        "for the current controls."
                    )
                else:
                    response_frame = _hyperparameter_response_frame(
                        hp_response_history,
                        hp_metric_key,
                        hp_summary,
                        iteration=hp_iteration,
                        q_target=hp_q_target,
                        include_misses=hp_include_misses,
                        at_best_q_parameter=hp_at_best_q_parameter,
                    )
                    if response_frame.empty:
                        st.info(
                            "No run-level hyperparameter response values are available "
                            "for the current scope and iteration range."
                        )
                    else:
                        plot_response_frame = response_frame
                        hp_slice_tokens: list[str] = []
                        hp_slice_filters: dict[str, float | None] = {}
                        hp_crop_tokens: list[str] = []
                        for crop_axis, (crop_min, crop_max) in hp_crop_ranges.items():
                            if crop_axis not in plot_response_frame.columns:
                                continue
                            crop_values = pd.to_numeric(
                                plot_response_frame[crop_axis],
                                errors="coerce",
                            )
                            plot_response_frame = plot_response_frame[
                                crop_values.between(
                                    float(crop_min),
                                    float(crop_max),
                                    inclusive="both",
                                )
                            ]
                            hp_crop_tokens.append(
                                f"{crop_axis}={float(crop_min):g}:{float(crop_max):g}"
                            )
                        if (
                            hp_view == "2D heatmap"
                            and hp_2d_slice_column is not None
                            and hp_2d_slice_value is not None
                            and hp_2d_slice_column in response_frame.columns
                        ):
                            plot_response_frame = plot_response_frame[
                                np.isclose(
                                    pd.to_numeric(
                                        plot_response_frame[hp_2d_slice_column],
                                        errors="coerce",
                                    ),
                                    float(hp_2d_slice_value),
                                    rtol=1e-9,
                                    atol=1e-12,
                                    equal_nan=False,
                                )
                            ]
                            hp_slice_tokens.append(
                                f"{hp_2d_slice_column}={float(hp_2d_slice_value):g}"
                            )
                            hp_slice_filters[hp_2d_slice_column] = float(hp_2d_slice_value)
                        elif hp_view == "2D heatmap":
                            hp_slice_tokens.append("all_unplotted=average")
                        if plot_response_frame.empty:
                            st.info(
                                "No hyperparameter response values match the selected "
                                "crop or 2D slice filters."
                            )
                        else:
                            hp_render_signature = (
                                trend_scope_key,
                                iteration_start,
                                iteration_end,
                                hp_metric_key,
                                hp_view,
                                hp_x,
                                hp_y,
                                hp_z,
                                hp_summary,
                                hp_aggregate,
                                hp_iteration,
                                hp_q_target,
                                hp_include_misses,
                                hp_3d_slice_axis,
                                hp_3d_slice_value,
                                hp_voxel_face_opacity,
                                hp_voxel_internal_opacity,
                                hp_voxel_internal_point_size,
                                hp_voxel_internal_point_count,
                                tuple(hp_crop_tokens),
                                tuple(hp_slice_tokens),
                            )
                            hp_render_cache_key = (
                                f"bo_hp_response_render_cache_{trend_scope_key}"
                            )
                            cached_render = st.session_state.get(
                                hp_render_cache_key
                            )
                            use_cached_render = (
                                cached_render is not None
                                and not hp_apply_response_settings
                                and cached_render.get("signature")
                                == hp_render_signature
                            )
                            if use_cached_render:
                                hp_figure = cached_render["figure"]
                                rendered_response_frame = cached_render["response_frame"]
                                rendered_sort_columns = cached_render["sort_columns"]
                                rendered_key_suffix = cached_render["key_suffix"]
                            else:
                                hp_plot_metric_label = (
                                    "Iterations to target Q"
                                    if hp_summary == "Iterations to Q target"
                                    else hp_metric_label
                                )
                                hp_figure = _plot_hyperparameter_response(
                                    plot_response_frame,
                                    x_axis=hp_x,
                                    y_axis=hp_y,
                                    z_axis=hp_z,
                                    metric_label=hp_plot_metric_label,
                                    aggregate=hp_aggregate,
                                    voxel_face_opacity=hp_voxel_face_opacity,
                                    voxel_internal_opacity=hp_voxel_internal_opacity,
                                    voxel_internal_point_size=hp_voxel_internal_point_size,
                                    voxel_internal_point_count=hp_voxel_internal_point_count,
                                    slice_axis=hp_3d_slice_axis,
                                    slice_value=hp_3d_slice_value,
                                )
                                if hp_summary == "Iterations to Q target":
                                    hp_figure.update_layout(
                                        title=(
                                            f"{hp_aggregate} iterations to "
                                            f"{hp_metric_label} >= "
                                            f"{float(hp_q_target):g}"
                                        )
                                    )
                                rendered_response_frame = plot_response_frame
                                rendered_sort_columns = [
                                    column for column in [hp_z, hp_y, hp_x]
                                    if column is not None
                                    and column in rendered_response_frame.columns
                                ]
                                rendered_key_suffix = (
                                    f"{iteration_end}_{hp_metric_key}_{hp_view}_{hp_x}_{hp_y}_"
                                    f"{hp_z or 'none'}_{hp_summary}_{hp_aggregate}_"
                                    f"{hp_iteration}_{hp_q_target}_{int(hp_include_misses)}_"
                                    f"{hp_3d_slice_axis or 'no_slice'}_{hp_3d_slice_value}_"
                                    f"{hp_voxel_face_opacity:g}_"
                                    f"{hp_voxel_internal_opacity:g}_"
                                    f"{hp_voxel_internal_point_size}_"
                                    f"{hp_voxel_internal_point_count}_"
                                    f"{'_'.join(hp_crop_tokens) or 'no_crop'}_"
                                    f"{'_'.join(hp_slice_tokens) or 'all_slices'}"
                                )
                                rendered_gif_key = (
                                    f"bo_hp_response_gif_{trend_scope_key}_"
                                    f"{hp_metric_key}_{hp_view}_{hp_x}_{hp_y}_"
                                    f"{hp_z or 'none'}_{hp_aggregate}_"
                                    f"{iteration_start}_{iteration_end}_"
                                    f"{hp_q_target}_{int(hp_include_misses)}_"
                                    f"{hp_3d_slice_axis or 'no_slice'}_{hp_3d_slice_value}_"
                                    f"{hp_voxel_face_opacity:g}_"
                                    f"{hp_voxel_internal_opacity:g}_"
                                    f"{hp_voxel_internal_point_size}_"
                                    f"{hp_voxel_internal_point_count}_"
                                    f"{'_'.join(hp_crop_tokens) or 'no_crop'}_"
                                    f"{'_'.join(hp_slice_tokens) or 'all_slices'}"
                                )
                                st.session_state[hp_render_cache_key] = {
                                    "figure": hp_figure,
                                    "response_frame": rendered_response_frame,
                                    "sort_columns": rendered_sort_columns,
                                    "key_suffix": rendered_key_suffix,
                                    "signature": hp_render_signature,
                                    "gif_key": rendered_gif_key,
                                    "allow_gif": hp_summary != "Iterations to Q target",
                                }
                            hp_plot_column = _sized_plot_container(
                                st,
                                plot_width_percent,
                            )
                            hp_plot_event = None
                            hp_clicked_points = None
                            hp_plot_key = (
                                f"bo_hp_response_{trend_scope_key}_{iteration_start}_"
                                f"{rendered_key_suffix}"
                            )
                            hp_click_pick_enabled = (
                                hp_view == "3D heatmap"
                                and hp_3d_slice_axis is not None
                                and hp_3d_mouse_mode == "Pick slice by clicking"
                            )
                            hp_plot_key = (
                                f"{hp_plot_key}_click_pick"
                                if hp_click_pick_enabled
                                else f"{hp_plot_key}_rotate"
                            )
                            if hp_click_pick_enabled and plotly_events is not None:
                                _apply_plotly_colorbar_height(hp_figure)
                                with hp_plot_column:
                                    hp_clicked_points = plotly_events(
                                        hp_figure,
                                        click_event=True,
                                        hover_event=False,
                                        select_event=False,
                                        override_height=plot_3d_height,
                                        override_width="100%",
                                        key=hp_plot_key,
                                    )
                            elif hp_view == "3D heatmap":
                                hp_file_stem = (
                                    f"hyperparameter_response_{hp_metric_label}_"
                                    f"{hp_x}_{hp_y}_{hp_z or 'none'}"
                                )
                                hp_camera_storage_key = (
                                    f"hyperparameter_response_3d_{trend_scope_key}_"
                                    f"{rendered_key_suffix}"
                                )
                                hp_shared_camera_storage_key = (
                                    f"bo_viewer_camera:shared:{hp_camera_storage_key}"
                                )
                                hp_cached_camera = _valid_plotly_camera(
                                    st.session_state.get(
                                        _plotly_camera_state_key(
                                            hp_shared_camera_storage_key
                                        )
                                    )
                                )
                                hp_rendered_camera = _render_camera_persistent_plotly(
                                    hp_plot_column,
                                    hp_figure,
                                    key=hp_plot_key,
                                    camera_storage_key=hp_camera_storage_key,
                                    shared_camera_storage_key=(
                                        hp_shared_camera_storage_key
                                    ),
                                    height=plot_3d_height,
                                    file_stem=hp_file_stem,
                                    export_width=1200,
                                    export_height=plot_3d_height,
                                    show_download=False,
                                )
                                hp_download_camera = (
                                    hp_cached_camera
                                    if hp_cached_camera is not None
                                    else hp_rendered_camera
                                )
                                hp_download_figure = go.Figure(hp_figure)
                                _apply_plotly_camera(
                                    hp_download_figure,
                                    hp_download_camera,
                                )
                                try:
                                    hp_png_bytes = _plotly_png_bytes(
                                        hp_download_figure,
                                        width=1200,
                                        height=plot_3d_height,
                                        scale=2,
                                    )
                                    _render_browser_download_link(
                                        hp_plot_column,
                                        "Download plot",
                                        hp_png_bytes,
                                        file_name=(
                                            f"{_safe_download_stem(hp_file_stem)}.png"
                                        ),
                                        mime="image/png",
                                    )
                                    if hp_download_camera is None:
                                        hp_plot_column.caption(
                                            "Click Cache view after rotating to export "
                                            "the current perspective."
                                        )
                                    else:
                                        eye = hp_download_camera.get("eye", {})
                                        hp_plot_column.caption(
                                            "Download uses cached 3D view "
                                            f"(eye x={float(eye.get('x', 0.0)):.3g}, "
                                            f"y={float(eye.get('y', 0.0)):.3g}, "
                                            f"z={float(eye.get('z', 0.0)):.3g})."
                                        )
                                except RuntimeError as exc:
                                    hp_plot_column.caption(str(exc))
                            else:
                                hp_plot_event = _plotly_chart_with_colorbars(
                                    hp_plot_column,
                                    hp_figure,
                                    use_container_width=True,
                                    key=hp_plot_key,
                                    on_select=(
                                        "rerun"
                                        if hp_click_pick_enabled
                                        else "ignore"
                                    ),
                                    selection_mode="points",
                                )
                            if hp_click_pick_enabled and plotly_events is None:
                                st.caption(
                                    "Mouse click slice picking requires "
                                    "`streamlit-plotly-events`; install the "
                                    "updated requirements and restart Streamlit."
                                )
                            if (
                                hp_view == "3D heatmap"
                                and hp_3d_slice_axis is not None
                                and hp_3d_slice_value_key is not None
                                and hp_3d_slice_values
                                and hp_click_pick_enabled
                            ):
                                selected_slice_coordinate = (
                                    _clicked_3d_coordinate(
                                        hp_clicked_points,
                                        hp_3d_slice_axis,
                                        (hp_x, hp_y, hp_z),
                                    )
                                    if hp_clicked_points is not None
                                    else _selected_3d_coordinate(
                                        hp_plot_event,
                                        hp_3d_slice_axis,
                                        (hp_x, hp_y, hp_z),
                                    )
                                )
                                if selected_slice_coordinate is not None:
                                    nearest_slice_value = min(
                                        hp_3d_slice_values,
                                        key=lambda value: abs(
                                            float(value)
                                            - float(selected_slice_coordinate)
                                        ),
                                    )
                                    slice_preference_key = (
                                        f"{hp_3d_slice_value_key}__preferred"
                                    )
                                    if (
                                        st.session_state.get(slice_preference_key)
                                        != nearest_slice_value
                                    ):
                                        st.session_state[slice_preference_key] = (
                                            nearest_slice_value
                                        )
                                        st.rerun()
                            if (
                                hp_view == "3D heatmap"
                                and hp_3d_slice_axis is not None
                                and hp_3d_slice_value is not None
                                and hp_3d_slice_axis in rendered_response_frame.columns
                            ):
                                slice_heatmap_key = (
                                    f"bo_hp_response_2d_slice_heatmap_"
                                    f"{trend_scope_key}_{rendered_key_suffix}"
                                )
                                generate_slice_heatmap = st.button(
                                    "Generate 2D heatmap for highlighted slice",
                                    key=f"{slice_heatmap_key}_button",
                                )
                                if generate_slice_heatmap:
                                    slice_remaining_axes = [
                                        axis for axis in (hp_x, hp_y, hp_z)
                                        if axis != hp_3d_slice_axis
                                    ]
                                    slice_frame = rendered_response_frame[
                                        np.isclose(
                                            pd.to_numeric(
                                                rendered_response_frame[
                                                    hp_3d_slice_axis
                                                ],
                                                errors="coerce",
                                            ),
                                            float(hp_3d_slice_value),
                                            rtol=1e-9,
                                            atol=1e-12,
                                            equal_nan=False,
                                        )
                                    ].copy()
                                    if len(slice_remaining_axes) == 2 and not slice_frame.empty:
                                        slice_metric_label = (
                                            "Iterations to target Q"
                                            if hp_summary == "Iterations to Q target"
                                            else hp_metric_label
                                        )
                                        slice_figure = _plot_hyperparameter_response(
                                            slice_frame,
                                            x_axis=slice_remaining_axes[0],
                                            y_axis=slice_remaining_axes[1],
                                            z_axis=None,
                                            metric_label=slice_metric_label,
                                            aggregate=hp_aggregate,
                                        )
                                        slice_figure.update_layout(
                                            title=(
                                                f"{hp_aggregate} {slice_metric_label} | "
                                                f"{hp_3d_slice_axis}="
                                                f"{float(hp_3d_slice_value):g}"
                                            )
                                        )
                                        st.session_state[slice_heatmap_key] = {
                                            "figure": slice_figure,
                                            "frame": slice_frame,
                                            "sort_columns": [
                                                slice_remaining_axes[1],
                                                slice_remaining_axes[0],
                                            ],
                                        }
                                    else:
                                        st.session_state.pop(
                                            slice_heatmap_key,
                                            None,
                                        )
                                        st.warning(
                                            "No response values match the highlighted "
                                            "3D slice."
                                        )
                                slice_heatmap = st.session_state.get(
                                    slice_heatmap_key
                                )
                                if slice_heatmap is not None:
                                    st.markdown("##### Highlighted slice heatmap")
                                    _plotly_chart_with_colorbars(
                                        _sized_plot_container(
                                            st,
                                            plot_width_percent,
                                        ),
                                        slice_heatmap["figure"],
                                        use_container_width=True,
                                        key=f"{slice_heatmap_key}_plot",
                                    )
                                    with st.expander("Highlighted slice table"):
                                        st.dataframe(
                                            slice_heatmap["frame"].sort_values(
                                                slice_heatmap["sort_columns"]
                                            ),
                                            use_container_width=True,
                                            hide_index=True,
                                        )
                            with st.expander("Hyperparameter response table"):
                                st.dataframe(
                                    rendered_response_frame.sort_values(
                                        rendered_sort_columns
                                    ),
                                    use_container_width=True,
                                    hide_index=True,
                                )
                            gif_iterations = sorted(
                                pd.to_numeric(
                                    trend_history.get(
                                        "iteration",
                                        pd.Series(dtype=float),
                                    ),
                                    errors="coerce",
                                ).dropna().astype(int).unique().tolist()
                            )
                            if (
                                gif_iterations
                                and hp_summary != "Iterations to Q target"
                            ):
                                st.markdown("##### Hyperparameter response GIF")
                                gif_controls = st.columns(3)
                                hp_gif_duration = int(gif_controls[0].slider(
                                    "Frame duration (ms)",
                                    min_value=100,
                                    max_value=1500,
                                    value=350,
                                    step=50,
                                    key=(
                                        f"bo_hp_response_gif_duration_"
                                        f"{trend_scope_key}_{hp_view}"
                                    ),
                                ))
                                hp_gif_width = int(gif_controls[1].number_input(
                                    "GIF width",
                                    min_value=500,
                                    max_value=1800,
                                    value=1000,
                                    step=100,
                                    key=(
                                        f"bo_hp_response_gif_width_"
                                        f"{trend_scope_key}_{hp_view}"
                                    ),
                                ))
                                hp_gif_height = int(gif_controls[2].number_input(
                                    "GIF height",
                                    min_value=400,
                                    max_value=1400,
                                    value=700 if hp_view == "3D heatmap" else 560,
                                    step=100,
                                    key=(
                                        f"bo_hp_response_gif_height_"
                                        f"{trend_scope_key}_{hp_view}"
                                    ),
                                ))
                                hp_gif_key = rendered_gif_key
                                generate_hp_gif = st.button(
                                    "Generate hyperparameter response GIF",
                                    key=f"{hp_gif_key}_button",
                                ) or bool(
                                    st.session_state.pop(
                                        hp_pending_gif_key,
                                        False,
                                    )
                                )
                                if generate_hp_gif:
                                    try:
                                        progress = st.progress(
                                            0.0,
                                            text="Preparing hyperparameter response frames...",
                                        )
                                        frame_rows: list[tuple[int, pd.DataFrame]] = []
                                        for prep_index, frame_iteration in enumerate(
                                            gif_iterations,
                                            start=1,
                                        ):
                                            progress.progress(
                                                0.02
                                                + 0.18
                                                * prep_index
                                                / max(1, len(gif_iterations)),
                                                text=(
                                                    "Preparing hyperparameter response "
                                                    f"frame {prep_index}/"
                                                    f"{len(gif_iterations)}..."
                                                ),
                                            )
                                            frame_response = _hyperparameter_response_frame(
                                                hp_response_history,
                                                hp_metric_key,
                                                "Specific iteration",
                                                iteration=frame_iteration,
                                                at_best_q_parameter=(
                                                    hp_at_best_q_parameter
                                                ),
                                            )
                                            if frame_response.empty:
                                                continue
                                            for slice_column, slice_value in (
                                                hp_slice_filters.items()
                                            ):
                                                if slice_value is None:
                                                    continue
                                                frame_response = frame_response[
                                                    np.isclose(
                                                        pd.to_numeric(
                                                            frame_response[slice_column],
                                                            errors="coerce",
                                                        ),
                                                        float(slice_value),
                                                        rtol=1e-9,
                                                        atol=1e-12,
                                                        equal_nan=False,
                                                    )
                                                ]
                                            if not frame_response.empty:
                                                frame_rows.append(
                                                    (frame_iteration, frame_response)
                                                )
                                        if not frame_rows:
                                            raise ValueError(
                                                "No iteration frames match the current "
                                                "hyperparameter response settings."
                                            )

                                        def hp_gif_figures():
                                            total = max(1, len(frame_rows))
                                            for frame_index, (
                                                frame_iteration,
                                                frame_response,
                                            ) in enumerate(frame_rows, start=1):
                                                progress.progress(
                                                    0.20
                                                    + 0.30
                                                    * (frame_index - 1)
                                                    / total,
                                                    text=(
                                                        "Building hyperparameter response "
                                                        f"figure {frame_index}/{total}..."
                                                    ),
                                                )
                                                figure = _plot_hyperparameter_response(
                                                    frame_response,
                                                    x_axis=hp_x,
                                                    y_axis=hp_y,
                                                    z_axis=hp_z,
                                                    metric_label=hp_metric_label,
                                                    aggregate=hp_aggregate,
                                                    voxel_face_opacity=hp_voxel_face_opacity,
                                                    voxel_internal_opacity=(
                                                        hp_voxel_internal_opacity
                                                    ),
                                                    voxel_internal_point_size=(
                                                        hp_voxel_internal_point_size
                                                    ),
                                                    voxel_internal_point_count=(
                                                        hp_voxel_internal_point_count
                                                    ),
                                                )
                                                figure.update_layout(
                                                    title=(
                                                        f"{hp_aggregate} {hp_metric_label} "
                                                        "by hyperparameters | "
                                                        f"iteration {frame_iteration}"
                                                    )
                                                )
                                                yield figure

                                        def hp_gif_progress(done: int, total: int) -> None:
                                            progress.progress(
                                                0.50 + 0.45 * done / max(1, total),
                                                text=(
                                                    "Encoding hyperparameter response GIF: "
                                                    f"frame {done}/{total}"
                                                ),
                                            )

                                        gif_bytes = _figures_to_gif(
                                            hp_gif_figures(),
                                            hp_gif_duration,
                                            plotly_width=hp_gif_width,
                                            plotly_height=hp_gif_height,
                                            total_frames=len(frame_rows),
                                            progress_callback=hp_gif_progress,
                                        )
                                        progress.progress(
                                            1.0,
                                            text=(
                                                "Hyperparameter response GIF complete "
                                                f"({len(frame_rows)} frames)."
                                            ),
                                        )
                                        st.session_state[hp_gif_key] = gif_bytes
                                    except Exception as exc:
                                        st.session_state.pop(hp_gif_key, None)
                                        st.error(
                                            "Hyperparameter response GIF generation "
                                            f"failed: {exc}"
                                        )
                                hp_gif_bytes = st.session_state.get(hp_gif_key)
                                if hp_gif_bytes:
                                    st.image(hp_gif_bytes)
                                    safe_hp_gif_name = re.sub(
                                        r"[^A-Za-z0-9._-]+",
                                        "_",
                                        (
                                            f"{hp_metric_label}_{hp_view}_{hp_x}_"
                                            f"{hp_y}_{hp_z or '2d'}"
                                        ),
                                    ).strip("_")
                                    st.download_button(
                                        "Download hyperparameter response GIF",
                                        data=hp_gif_bytes,
                                        file_name=(
                                            f"hyperparameter_response_"
                                            f"{safe_hp_gif_name}.gif"
                                        ),
                                        mime="image/gif",
                                        key=f"{hp_gif_key}_download",
                                    )

        _render_hyperparameter_response_fragment()
        clicked_iteration = next(
            (
                iteration
                for iteration in (_clicked_iteration(event) for event in trend_events)
                if iteration is not None
            ),
            None,
        )
        click_state_key = (
            f"bo_last_trend_click_{session['state'].get('session_id', 'session')}_"
            f"{selected_group_id}_{chart_key_suffix}"
        )
        last_clicked_iteration = st.session_state.get(click_state_key)
        if clicked_iteration is not None and clicked_iteration != last_clicked_iteration:
            st.session_state[click_state_key] = clicked_iteration
        is_new_plot_click = (
            clicked_iteration is not None
            and clicked_iteration != last_clicked_iteration
        )
        if (
            not all_groups_scope
            and
            is_new_plot_click
            and clicked_iteration in iteration_options
            and clicked_iteration != selected_iteration
        ):
            st.session_state[iteration_state_key] = (
                f"g{selected_observation_group}:i{clicked_iteration}"
            )
            st.rerun()

        if any(
            str(obs.get("objective", "")).lower() == "paired_response"
            for obs in plot_observations
        ):
            st.divider()
            st.subheader("Buffer vs target trends")
            paired_metric_options = _q_relevant_metrics(
                PAIRED_TREND_METRICS,
                session["config"],
                paired_objective=True,
            )
            _preserve_valid_widget_value(
                "bo_paired_trend_metric",
                paired_metric_options,
                paired_metric_options[0],
            )
            paired_metric = st.selectbox(
                "Buffer/target metric",
                paired_metric_options,
                key="bo_paired_trend_metric",
            )
            paired_series = _paired_trend_values(
                plot_observations,
                paired_metric,
            )
            paired_channels = sorted(paired_series, key=_channel_sort_key)
            paired_channels_key = f"bo_paired_channels_{paired_metric}"
            paired_channels_valid, paired_channels_display = (
                _prepare_preferred_multiselect_value(
                    paired_channels_key,
                    f"{paired_channels_key}__preferred",
                    paired_channels,
                    paired_channels,
                )
            )
            selected_paired_channels = st.multiselect(
                "Buffer/target channels",
                paired_channels,
                default=paired_channels_display,
                format_func=lambda channel: f"Ch {channel}",
                key=paired_channels_key,
            )
            _sync_preferred_widget_value(
                paired_channels_key,
                f"{paired_channels_key}__preferred",
                paired_channels_valid,
                paired_channels_display,
            )
            paired_layout_options = [
                "Overlay selected channels",
                "Separate plots",
                "Average selected channels",
            ]
            paired_layout_key = f"bo_paired_layout_{paired_metric}"
            _preserve_valid_widget_value(
                paired_layout_key,
                paired_layout_options,
                paired_layout_options[0],
            )
            paired_layout = st.radio(
                "Buffer/target display",
                paired_layout_options,
                horizontal=True,
                key=paired_layout_key,
            )
            if selected_paired_channels:
                paired_figure = _plot_paired_phase_trend(
                    paired_series,
                    paired_metric,
                    selected_paired_channels,
                    paired_layout,
                )
            else:
                paired_figure = go.Figure()
                paired_figure.add_annotation(
                    text="Select at least one buffer/target channel.",
                    x=.5, y=.5, xref="paper", yref="paper", showarrow=False,
                )
                paired_figure.update_layout(height=360)
            paired_chart_suffix = (
                f"{iteration_start}_{iteration_end}_{paired_metric}_{paired_layout}_"
                f"{'_'.join(selected_paired_channels) or 'none'}"
            )
            paired_figures = [paired_figure]
            paired_overlay_figure = None
            paired_separate_figure = None
            if (
                paired_layout == "Average selected channels"
                and selected_paired_channels
            ):
                paired_overlay_figure = _plot_paired_phase_trend(
                    paired_series,
                    paired_metric,
                    selected_paired_channels,
                    "Overlay selected channels",
                )
                paired_separate_figure = _plot_paired_phase_trend(
                    paired_series,
                    paired_metric,
                    selected_paired_channels,
                    "Separate plots",
                )
                paired_figures.extend([
                    paired_overlay_figure,
                    paired_separate_figure,
                ])
            paired_y_limits = _manual_y_axis_range_control(
                "buffer/target trend",
                f"bo_paired_trend_{paired_metric}_{paired_layout}",
                paired_figures,
            )
            if paired_y_limits is not None:
                for figure in paired_figures:
                    _apply_y_axis_range(figure, *paired_y_limits)
                paired_chart_suffix = (
                    f"{paired_chart_suffix}_ylim_"
                    f"{paired_y_limits[0]:g}_{paired_y_limits[1]:g}"
                )
            paired_events = []
            if (
                paired_layout == "Average selected channels"
                and selected_paired_channels
            ):
                average_column, overlay_column = st.columns(2)
                paired_events.append(_plotly_chart_with_colorbars(
                    _sized_plot_container(average_column, plot_width_percent),
                    paired_figure,
                    use_container_width=True,
                    on_select="rerun",
                    selection_mode="points",
                    key=f"bo_paired_trend_{paired_chart_suffix}_average",
                ))
                paired_events.append(_plotly_chart_with_colorbars(
                    _sized_plot_container(overlay_column, plot_width_percent),
                    paired_overlay_figure,
                    use_container_width=True,
                    on_select="rerun",
                    selection_mode="points",
                    key=f"bo_paired_trend_{paired_chart_suffix}_overlay",
                ))
                paired_events.append(_plotly_chart_with_colorbars(
                    _sized_plot_container(st, plot_width_percent),
                    paired_separate_figure,
                    use_container_width=True,
                    on_select="rerun",
                    selection_mode="points",
                    key=f"bo_paired_trend_{paired_chart_suffix}_separate",
                ))
            else:
                paired_events.append(_plotly_chart_with_colorbars(
                    _sized_plot_container(st, plot_width_percent),
                    paired_figure,
                    use_container_width=True,
                    on_select="rerun",
                    selection_mode="points",
                    key=f"bo_paired_trend_{paired_chart_suffix}",
                ))
            if paired_metric == "Classic Q":
                _render_q_equation(session["config"], "classic")
            paired_clicked_iteration = next(
                (
                    iteration
                    for iteration in (
                        _clicked_iteration(event) for event in paired_events
                    )
                    if iteration is not None
                ),
                None,
            )
            paired_click_key = (
                f"bo_last_paired_click_{session['state'].get('session_id', 'session')}_"
                f"{selected_group_id}_{paired_chart_suffix}"
            )
            last_paired_click = st.session_state.get(paired_click_key)
            if (
                paired_clicked_iteration is not None
                and paired_clicked_iteration != last_paired_click
            ):
                st.session_state[paired_click_key] = paired_clicked_iteration
                if (
                    not all_groups_scope
                    and
                    paired_clicked_iteration in iteration_options
                    and paired_clicked_iteration != selected_iteration
                ):
                    st.session_state[iteration_state_key] = (
                        f"g{selected_observation_group}:i{paired_clicked_iteration}"
                    )
                    st.rerun()

            st.divider()
            st.subheader("Chronological plot")
            chronological_metric_options = _q_relevant_metrics(
                PAIRED_TREND_METRICS,
                session["config"],
                paired_objective=True,
            )
            _preserve_valid_widget_value(
                "bo_chronological_metric",
                chronological_metric_options,
                chronological_metric_options[0],
            )
            chronological_metric = st.selectbox(
                "Chronological metric",
                chronological_metric_options,
                key="bo_chronological_metric",
            )
            chronological_channels = _real_data_channels(
                plot_observations
            )
            chronological_channels_key = (
                f"bo_chronological_channels_{chronological_metric}"
            )
            chronological_channels_valid, chronological_channels_display = (
                _prepare_preferred_multiselect_value(
                    chronological_channels_key,
                    f"{chronological_channels_key}__preferred",
                    chronological_channels,
                    chronological_channels,
                )
            )
            selected_chronological_channels = st.multiselect(
                "Chronological channels",
                chronological_channels,
                default=chronological_channels_display,
                format_func=lambda channel: f"Ch {channel}",
                key=chronological_channels_key,
            )
            _sync_preferred_widget_value(
                chronological_channels_key,
                f"{chronological_channels_key}__preferred",
                chronological_channels_valid,
                chronological_channels_display,
            )
            chronological_mode_options = [
                "Overlay selected channels",
                "Separate plots",
                "Average selected channels",
            ]
            chronological_mode_key = f"bo_chronological_mode_{chronological_metric}"
            _preserve_valid_widget_value(
                chronological_mode_key,
                chronological_mode_options,
                chronological_mode_options[0],
            )
            chronological_mode = st.radio(
                "Chronological display",
                chronological_mode_options,
                horizontal=True,
                key=chronological_mode_key,
            )
            chronological_points, phase_transitions = _chronological_points(
                plot_observations,
                session["config"],
                chronological_metric,
                selected_chronological_channels,
                average_channels=chronological_mode == "Average selected channels",
            )
            chronological_raw_points = None
            if (
                chronological_mode == "Average selected channels"
                and selected_chronological_channels
            ):
                chronological_raw_points, _ = _chronological_points(
                    plot_observations,
                    session["config"],
                    chronological_metric,
                    selected_chronological_channels,
                    average_channels=False,
                )
            if chronological_points.empty:
                st.info("No chronological values are available for this selection.")
            else:
                chronological_suffix = (
                    f"{iteration_start}_{iteration_end}_"
                    f"{chronological_metric}_{chronological_mode}_"
                    f"{'_'.join(selected_chronological_channels)}"
                )
                if chronological_raw_points is not None:
                    chronological_average_figure = _plot_chronological(
                        chronological_points,
                        phase_transitions,
                        chronological_metric,
                        "Average selected channels",
                    )
                    chronological_overlay_figure = _plot_chronological(
                        chronological_raw_points,
                        phase_transitions,
                        chronological_metric,
                        "Overlay selected channels",
                    )
                    chronological_separate_figure = _plot_chronological(
                        chronological_raw_points,
                        phase_transitions,
                        chronological_metric,
                        "Separate plots",
                    )
                    chronological_figures = [
                        chronological_average_figure,
                        chronological_overlay_figure,
                        chronological_separate_figure,
                    ]
                else:
                    chronological_figure = _plot_chronological(
                        chronological_points,
                        phase_transitions,
                        chronological_metric,
                        chronological_mode,
                    )
                    chronological_figures = [chronological_figure]
                chronological_y_limits = _manual_y_axis_range_control(
                    "chronological",
                    f"bo_chronological_{chronological_metric}_{chronological_mode}",
                    chronological_figures,
                )
                if chronological_y_limits is not None:
                    for figure in chronological_figures:
                        _apply_y_axis_range(figure, *chronological_y_limits)
                    chronological_suffix = (
                        f"{chronological_suffix}_ylim_"
                        f"{chronological_y_limits[0]:g}_{chronological_y_limits[1]:g}"
                    )
                chronological_events = []
                if chronological_raw_points is not None:
                    average_column, overlay_column = st.columns(2)
                    chronological_events.append(_plotly_chart_with_colorbars(
                        _sized_plot_container(average_column, plot_width_percent),
                        chronological_average_figure,
                        use_container_width=True,
                        on_select="rerun",
                        selection_mode="points",
                        key=f"bo_chronological_{chronological_suffix}_average",
                    ))
                    chronological_events.append(_plotly_chart_with_colorbars(
                        _sized_plot_container(overlay_column, plot_width_percent),
                        chronological_overlay_figure,
                        use_container_width=True,
                        on_select="rerun",
                        selection_mode="points",
                        key=f"bo_chronological_{chronological_suffix}_overlay",
                    ))
                    chronological_events.append(_plotly_chart_with_colorbars(
                        _sized_plot_container(st, plot_width_percent),
                        chronological_separate_figure,
                        use_container_width=True,
                        on_select="rerun",
                        selection_mode="points",
                        key=f"bo_chronological_{chronological_suffix}_separate",
                    ))
                else:
                    chronological_events.append(_plotly_chart_with_colorbars(
                        _sized_plot_container(st, plot_width_percent),
                        chronological_figure,
                        use_container_width=True,
                        on_select="rerun",
                        selection_mode="points",
                        key=f"bo_chronological_{chronological_suffix}",
                    ))
                if chronological_metric == "Classic Q":
                    _render_q_equation(session["config"], "classic")
                chronological_iteration = next(
                    (
                        iteration
                        for iteration in (
                            _clicked_iteration(event)
                            for event in chronological_events
                        )
                        if iteration is not None
                    ),
                    None,
                )
                chronological_click_key = (
                    f"bo_last_chronological_click_"
                    f"{session['state'].get('session_id', 'session')}_"
                    f"{selected_group_id}_{chronological_suffix}"
                )
                last_chronological_click = st.session_state.get(chronological_click_key)
                if (
                    chronological_iteration is not None
                    and chronological_iteration != last_chronological_click
                ):
                    st.session_state[chronological_click_key] = chronological_iteration
                    if (
                        not all_groups_scope
                        and
                        chronological_iteration in iteration_options
                        and chronological_iteration != selected_iteration
                    ):
                        st.session_state[iteration_state_key] = (
                            f"g{selected_observation_group}:i{chronological_iteration}"
                        )
                        st.rerun()

        st.subheader("History")
        if history.empty:
            st.info("No history rows are available.")
        else:
            preferred_history_columns = [
                column for column in [
                    "group_id",
                    "group_name",
                    "iteration",
                    "Q_run",
                    "best_Q",
                    "best_so_far",
                    "exploration",
                    "initial_random_points",
                    "gp_falloff_parameter",
                    "gp_falloff_value",
                    "selection_mode",
                    "objective",
                ]
                if column in history.columns
            ]
            if not preferred_history_columns:
                preferred_history_columns = list(history.columns[:12])
            history_column_key = f"bo_history_columns_{trend_scope_key}"
            history_columns_valid, history_columns_display = (
                _prepare_preferred_multiselect_value(
                    history_column_key,
                    f"{history_column_key}__preferred",
                    list(history.columns),
                    preferred_history_columns,
                )
            )
            history_controls = st.columns([2, 1, 1])
            selected_history_columns = history_controls[0].multiselect(
                "History columns",
                list(history.columns),
                default=history_columns_display,
                key=history_column_key,
            )
            _sync_preferred_widget_value(
                history_column_key,
                f"{history_column_key}__preferred",
                history_columns_valid,
                history_columns_display,
            )
            history_row_options = [100, 250, 500, 1000, 2500, 5000]
            history_rows_key = f"bo_history_preview_rows_{trend_scope_key}"
            _preserve_valid_widget_value(
                history_rows_key,
                history_row_options,
                500,
            )
            history_row_limit = history_controls[1].selectbox(
                "Rows to show",
                history_row_options,
                key=history_rows_key,
            )
            history_order_key = f"bo_history_preview_order_{trend_scope_key}"
            history_order_options = ["Most recent first", "Original order"]
            _preserve_valid_widget_value(
                history_order_key,
                history_order_options,
                history_order_options[0],
            )
            history_order = history_controls[2].selectbox(
                "Table order",
                history_order_options,
                key=history_order_key,
            )
            history_preview = history[
                selected_history_columns or preferred_history_columns
            ].copy()
            if history_order == "Most recent first" and "iteration" in history.columns:
                sort_columns = [
                    column for column in ["group_id", "iteration"]
                    if column in history_preview.columns
                ]
                if sort_columns:
                    history_preview = history_preview.sort_values(
                        sort_columns,
                        ascending=False,
                        kind="mergesort",
                    )
                else:
                    history_preview = history_preview.iloc[::-1]
            history_preview = history_preview.head(int(history_row_limit))
            st.caption(
                f"Showing {len(history_preview):,} of {len(history):,} rows "
                f"and {len(history_preview.columns):,} of {len(history.columns):,} columns."
            )
            st.dataframe(history_preview, use_container_width=True, hide_index=True)
            st.download_button(
                "Download displayed history CSV",
                data=history_preview.to_csv(index=False).encode(),
                file_name="bo_history_preview.csv",
                mime="text/csv",
                key=f"bo_history_download_{trend_scope_key}",
            )
        if not observation_is_single:
            st.info(
                "Select one group and one iteration to inspect per-channel "
                "scores for a single observation."
            )
        else:
            st.subheader(
                f"{observation.get('group_name', f'Group {selected_observation_group}')} "
                f"iteration {selected_iteration} per-channel scores"
            )
            channel_frame = _channel_table(observation)
            if channel_frame.empty:
                st.info("No per-channel scores were recorded for this iteration.")
            else:
                st.dataframe(channel_frame, use_container_width=True, hide_index=True)

    with traces:
        trace_observations = selected_observations
        trace_all_mode = not observation_is_single
        selected_group_label = selected_observation_group_scope_label
        selected_iteration_label = (
            "all iterations"
            if selected_iteration_scope == "all"
            else f"iteration {selected_iteration_scope}"
        )
        trace_selection_label = (
            f"{selected_group_label} — {selected_iteration_label}"
        )
        qualify_trace_channels = (
            len({
                int(item.get("group_id", 1))
                for item in trace_observations
            }) > 1
        )
        with st.spinner("Locating SWV traces..."):
            trace_entries = [
                (
                    trace_observation,
                    _group_qualified_trace(
                        trace_observation,
                        trace,
                        qualify_trace_channels,
                    ),
                )
                for trace_observation in trace_observations
                for trace in _trace_paths(full_session, trace_observation)
            ]
        available_traces = [trace for _observation, trace in trace_entries]
        available_channels = sorted(
            {_trace_channel_key(item) for item in available_traces},
            key=_channel_sort_key,
        )
        if not available_traces:
            st.info(
                "No locally accessible raw SWV files were found for this selection. "
                "The recorded CSVs must remain inside or beside the experiment folder."
            )
        else:
            trace_phase_options = {
                "Buffer and target": ("buffer", "target"),
                "Buffer only": ("buffer",),
                "Target only": ("target",),
            }
            trace_has_paired_phases = any(
                str(trace.get("phase", "")).lower() in ("buffer", "target")
                for trace in available_traces
            )
            selected_trace_phase_label = "Buffer and target"
            selected_trace_phases = None
            if trace_has_paired_phases:
                trace_phase_key = (
                    f"bo_trace_phase_filter_{selected_observation_group_scope}_"
                    f"{selected_iteration_scope}"
                )
                _preserve_valid_widget_value(
                    trace_phase_key,
                    list(trace_phase_options),
                    selected_trace_phase_label,
                )
                selected_trace_phase_label = st.radio(
                    "Paired trace phases",
                    list(trace_phase_options),
                    horizontal=True,
                    key=trace_phase_key,
                )
                selected_trace_phases = trace_phase_options[
                    selected_trace_phase_label
                ]
            selected_trace_phase_set = (
                {phase.lower() for phase in selected_trace_phases}
                if selected_trace_phases is not None
                else None
            )
            display_trace_entries = [
                (trace_observation, trace)
                for trace_observation, trace in trace_entries
                if (
                    selected_trace_phase_set is None
                    or str(trace.get("phase", "")).lower()
                    in selected_trace_phase_set
                )
            ]
            display_available_traces = [
                trace for _observation, trace in display_trace_entries
            ]
            trace_channels_key = (
                f"bo_trace_channels_{selected_observation_group_scope}_"
                f"{selected_iteration_scope}_{selected_trace_phase_label}"
            )
            available_channels = sorted(
                {_trace_channel_key(item) for item in display_available_traces},
                key=_channel_sort_key,
            )
            trace_channels_valid, trace_channels_display = (
                _prepare_preferred_multiselect_value(
                    trace_channels_key,
                    f"{trace_channels_key}__preferred",
                    available_channels,
                    available_channels,
                )
            )
            selected_channels = st.multiselect(
                "Channels to display",
                available_channels,
                default=trace_channels_display,
                format_func=_trace_channel_label,
                key=trace_channels_key,
            )
            _sync_preferred_widget_value(
                trace_channels_key,
                f"{trace_channels_key}__preferred",
                trace_channels_valid,
                trace_channels_display,
            )
            trace_layout_options = [
                "Overlay selected channels",
                "Separate plot per channel",
            ]
            if trace_all_mode:
                trace_layout_options.append("Chronological diagonal stack")
            trace_layout_key = (
                f"bo_trace_layout_{selected_observation_group_scope}_"
                f"{selected_iteration_scope}"
            )
            _preserve_valid_widget_value(
                trace_layout_key,
                trace_layout_options,
                trace_layout_options[0],
            )
            trace_layout = st.radio(
                "Plot layout",
                trace_layout_options,
                horizontal=True,
                key=trace_layout_key,
            )
            selected_trace_type = st.radio(
                "Trace type",
                [
                    "Raw",
                    "Offset raw",
                    "Corrected",
                    "Normalized corrected",
                    "Normalized raw",
                ],
                horizontal=True,
                key=(
                    f"bo_trace_type_{selected_observation_group_scope}_"
                    f"{selected_iteration_scope}"
                ),
            )
            corrected = selected_trace_type != "Raw"
            offset_to_baseline = selected_trace_type == "Offset raw"
            normalize_to_peak = selected_trace_type in {
                "Normalized corrected",
                "Normalized raw",
            }
            corrected_trace_key = (
                "corrected_current"
                if selected_trace_type in {"Offset raw", "Normalized raw"}
                else "smoothed_corrected_current"
            )
            trace_transform_key = _safe_download_stem(selected_trace_type)
            analysis_settings = _bo_analysis_settings(session["config"])
            trace_voltage_columns = st.columns(2)
            trace_voltage_min = float(trace_voltage_columns[0].number_input(
                "Voltage crop min (V)",
                value=float(analysis_settings["crop_min_v"]),
                step=0.01,
                format="%.4f",
                key=(
                    f"bo_trace_voltage_min_"
                    f"{selected_observation_group_scope}_{selected_iteration_scope}"
                ),
            ))
            trace_voltage_max = float(trace_voltage_columns[1].number_input(
                "Voltage crop max (V)",
                value=float(analysis_settings["crop_max_v"]),
                step=0.01,
                format="%.4f",
                key=(
                    f"bo_trace_voltage_max_"
                    f"{selected_observation_group_scope}_{selected_iteration_scope}"
                ),
            ))
            if trace_voltage_min > trace_voltage_max:
                st.warning(
                    "Voltage crop min is greater than max; applying the "
                    "bounds in ascending order."
                )
                trace_voltage_min, trace_voltage_max = (
                    trace_voltage_max,
                    trace_voltage_min,
                )
            stack_x_offset = None
            stack_y_offset = None
            stack_trace_height = 1.0
            stack_voltage_min = trace_voltage_min
            stack_voltage_max = trace_voltage_max
            stack_y_min = None
            stack_y_max = None
            stack_phase_display = "Overlay buffer and target"
            if trace_layout == "Chronological diagonal stack":
                if selected_trace_phase_set == {"buffer", "target"}:
                    stack_phase_display = st.radio(
                        "Paired trace display",
                        [
                            "Overlay buffer and target",
                            "Separate buffer and target plots",
                        ],
                        horizontal=True,
                        key=(
                            f"bo_trace_stack_phase_display_"
                            f"{selected_observation_group_scope}_"
                            f"{selected_iteration_scope}"
                        ),
                    )
                offset_columns = st.columns(3)
                stack_x_offset = offset_columns[0].number_input(
                    "X offset per iteration (V)",
                    value=0.002,
                    step=0.001,
                    format="%.4f",
                    key=(
                        f"bo_trace_stack_x_offset_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}"
                    ),
                    help="Positive values shift newer traces to the right; negative values shift them left.",
                )
                stack_y_offset = offset_columns[1].number_input(
                    "Y offset per iteration",
                    value=0.02 if normalize_to_peak else 0.1,
                    step=0.01,
                    format="%.4f",
                    key=(
                        f"bo_trace_stack_y_offset_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}_"
                        f"{trace_transform_key}"
                    ),
                    help="Positive values shift newer traces upward; negative values shift them downward.",
                )
                stack_trace_height = offset_columns[2].slider(
                    "Trace height",
                    min_value=0.1,
                    max_value=5.0,
                    value=1.0,
                    step=0.1,
                    key=(
                        f"bo_trace_stack_height_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}_"
                        f"{trace_transform_key}"
                    ),
                    help="Scales each SWV vertically before applying the chronological offset.",
                )
                manual_stack_y_limits = st.checkbox(
                    "Crop each SWV trace by current before stacking",
                    key=(
                        f"bo_trace_stack_manual_y_limits_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}_"
                        f"{trace_transform_key}"
                    ),
                )
                if manual_stack_y_limits:
                    default_stack_y_min = -0.2 if normalize_to_peak else -1.0
                    default_stack_y_max = 1.2 if normalize_to_peak else 1.0
                    stack_bounds_loaded, _stack_bounds_errors, _stack_bounds_entries = (
                        _chronological_swv_stack_entries(
                            display_trace_entries,
                            corrected,
                            selected_channels,
                            trace_analysis,
                            session["config"],
                            normalize_to_peak,
                            corrected_trace_key,
                            offset_to_baseline,
                            stack_trace_height,
                            stack_voltage_min,
                            stack_voltage_max,
                            selected_phases=selected_trace_phases,
                        )
                    )
                    if stack_bounds_loaded and not normalize_to_peak:
                        stack_current_values = np.concatenate([
                            row["current"] for row in stack_bounds_loaded
                        ])
                        default_stack_y_min = float(np.nanmin(stack_current_values))
                        default_stack_y_max = float(np.nanmax(stack_current_values))
                        stack_y_padding = max(
                            (default_stack_y_max - default_stack_y_min) * 0.05,
                            1e-9,
                        )
                        default_stack_y_min -= stack_y_padding
                        default_stack_y_max += stack_y_padding
                    y_limit_columns = st.columns(2)
                    stack_y_min_key = (
                        f"bo_trace_stack_trace_y_min_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}_"
                        f"{trace_transform_key}"
                    )
                    stack_y_max_key = (
                        f"bo_trace_stack_trace_y_max_"
                        f"{selected_observation_group_scope}_{selected_iteration_scope}_"
                        f"{trace_transform_key}"
                    )
                    st.session_state.setdefault(
                        stack_y_min_key,
                        default_stack_y_min,
                    )
                    st.session_state.setdefault(
                        stack_y_max_key,
                        default_stack_y_max,
                    )
                    stack_y_min = float(y_limit_columns[0].number_input(
                        "Per-trace current minimum",
                        value=float(st.session_state[stack_y_min_key]),
                        step=0.1,
                        format="%.4f",
                        key=stack_y_min_key,
                    ))
                    stack_y_max = float(y_limit_columns[1].number_input(
                        "Per-trace current maximum",
                        value=float(st.session_state[stack_y_max_key]),
                        step=0.1,
                        format="%.4f",
                        key=stack_y_max_key,
                    ))
                    if stack_y_min >= stack_y_max:
                        st.warning(
                            "Per-trace current minimum must be less than the "
                            "maximum; no current crop is being applied."
                        )
                        stack_y_min = None
                        stack_y_max = None
            trace_gif_duration = st.slider(
                "SWV GIF frame duration (ms)",
                min_value=100,
                max_value=1500,
                value=350,
                step=50,
                key=(
                    f"bo_trace_gif_duration_{selected_observation_group_scope}_"
                    f"{selected_iteration_scope}"
                ),
                disabled=not trace_all_mode,
            )

            channel_groups = (
                [[channel] for channel in selected_channels]
                if trace_layout in (
                    "Separate plot per channel",
                    "Chronological diagonal stack",
                )
                else [selected_channels]
            )
            if not selected_channels:
                st.info("Select at least one channel to display traces.")
            for channel_group in channel_groups:
                phase_targets = [(None, selected_trace_phases)]
                if (
                    trace_layout == "Chronological diagonal stack"
                    and stack_phase_display == "Separate buffer and target plots"
                ):
                    phase_targets = [
                        ("buffer", ("buffer",)),
                        ("target", ("target",)),
                    ]
                if trace_layout in (
                    "Separate plot per channel",
                    "Chronological diagonal stack",
                ):
                    channel = channel_group[0]
                    st.markdown(
                        f"#### {_trace_channel_label(channel)}"
                    )
                for phase_label, selected_stack_phases in phase_targets:
                    if phase_label is not None:
                        st.markdown(f"**{phase_label.title()}**")
                    with st.spinner(
                        "Processing corrected traces..."
                        if corrected
                        else "Loading raw traces..."
                    ):
                        if trace_layout == "Chronological diagonal stack":
                            figure, errors = _plot_chronological_swv_stack(
                                display_trace_entries,
                                corrected,
                                channel_group,
                                trace_analysis,
                                session["config"],
                                correction_label,
                                trace_selection_label,
                                normalize_to_peak,
                                corrected_trace_key,
                                offset_to_baseline,
                                stack_x_offset,
                                stack_y_offset,
                                stack_trace_height,
                                stack_voltage_min,
                                stack_voltage_max,
                                stack_y_min,
                                stack_y_max,
                                selected_stack_phases,
                            )
                        elif trace_all_mode:
                            figure, errors = _plot_iteration_trace_overlay(
                                display_trace_entries,
                                corrected,
                                channel_group,
                                trace_analysis,
                                correction_label,
                                trace_selection_label,
                                normalize_to_peak,
                                corrected_trace_key,
                                offset_to_baseline,
                                trace_voltage_min,
                                trace_voltage_max,
                            )
                        else:
                            figure, errors = _plot_traces(
                                session,
                                observation,
                                corrected,
                                channel_group,
                                trace_analysis,
                                correction_label,
                                trace_layout == "Overlay selected channels",
                                display_available_traces,
                                normalize_to_peak,
                                corrected_trace_key,
                                offset_to_baseline,
                                trace_voltage_min,
                                trace_voltage_max,
                            )
                    trace_file_stem = (
                        f"swv_traces_{selected_trace_type}_{trace_layout}_"
                        f"{selected_group_label}_{selected_iteration_label}_"
                        f"{selected_trace_phase_label}_"
                        f"{trace_voltage_min:g}_{trace_voltage_max:g}_"
                        f"{phase_label + '_' if phase_label else ''}"
                        f"{'_'.join(map(str, channel_group)) or 'all_channels'}"
                    )
                    _render_downloadable_pyplot(
                        st,
                        figure,
                        key=(
                            f"bo_trace_plot_{selected_observation_group_scope}_"
                            f"{selected_iteration_scope}_{trace_layout}_"
                            f"{selected_trace_type}_{phase_label or 'all'}_"
                            f"{selected_trace_phase_label}_"
                            f"{trace_voltage_min:g}_{trace_voltage_max:g}_"
                            f"{'_'.join(map(str, channel_group))}"
                        ),
                        file_stem=trace_file_stem,
                        width_percent=plot_width_percent,
                    )
                    for error in errors:
                        st.warning(error)

            if trace_all_mode and selected_channels:
                trace_gif_key = (
                    f"bo_trace_gif_{selected_observation_group_scope}_"
                    f"{selected_iteration_scope}_{trace_layout}_{selected_trace_type}_"
                    f"{selected_trace_phase_label}_"
                    f"{trace_voltage_min:g}_{trace_voltage_max:g}_"
                    f"{'_'.join(selected_channels)}"
                )
                if st.button(
                    "Generate SWV GIF",
                    key=f"{trace_gif_key}_button",
                ):
                    with st.spinner("Rendering SWV trace frames..."):
                        try:
                            trace_progress = st.progress(
                                0.0,
                                text="Preparing SWV frames...",
                            )
                            frame_observations = sorted(
                                trace_observations,
                                key=lambda item: (
                                    int(item.get("group_id", 1)),
                                    int(item.get("iteration", 0)),
                                ),
                            )
                            trace_progress.progress(
                                0.02,
                                text="Calculating shared SWV y-axis range...",
                            )
                            selected_raw_channels = sorted(
                                {
                                    trace["channel"]
                                    for _trace_observation, trace in display_trace_entries
                                    if _trace_channel_key(trace) in selected_channels
                                },
                                key=_channel_sort_key,
                            )
                            gif_y_limits = _swv_global_y_limits(
                                frame_observations,
                                full_session,
                                selected_raw_channels,
                                corrected,
                                trace_analysis,
                                normalize_to_peak,
                                corrected_trace_key,
                                offset_to_baseline,
                                selected_trace_phases,
                                trace_voltage_min,
                                trace_voltage_max,
                            )

                            def swv_frames():
                                for frame_observation in frame_observations:
                                    frame_iteration = int(
                                        frame_observation.get("iteration", 0)
                                    )
                                    frame_group = str(
                                        frame_observation.get("group_name")
                                        or f"Group {frame_observation.get('group_id', 1)}"
                                    )
                                    frame_traces = _trace_paths(
                                        full_session,
                                        frame_observation,
                                    )
                                    frame_traces = [
                                        _group_qualified_trace(
                                            frame_observation,
                                            trace,
                                            qualify_trace_channels,
                                        )
                                        for trace in frame_traces
                                    ]
                                    if selected_trace_phase_set is not None:
                                        frame_traces = [
                                            trace for trace in frame_traces
                                            if str(trace.get("phase", "")).lower()
                                            in selected_trace_phase_set
                                        ]
                                    if not frame_traces:
                                        continue
                                    if trace_layout == "Separate plot per channel":
                                        figures = []
                                        for single_channel in selected_channels:
                                            fig, errors = _plot_traces(
                                                full_session,
                                                frame_observation,
                                                corrected,
                                                [single_channel],
                                                trace_analysis,
                                                correction_label,
                                                overlaid=False,
                                                trace_items=frame_traces,
                                                normalize_to_peak=normalize_to_peak,
                                                corrected_trace_key=corrected_trace_key,
                                                offset_to_baseline=offset_to_baseline,
                                                voltage_min=trace_voltage_min,
                                                voltage_max=trace_voltage_max,
                                            )
                                            if errors:
                                                fig.text(
                                                    .02,
                                                    .01,
                                                    " | ".join(errors[:3]),
                                                    fontsize=6,
                                                )
                                            if gif_y_limits is not None and fig.axes:
                                                fig.axes[0].set_ylim(*gif_y_limits)
                                            figures.append((single_channel, fig))
                                        if not figures:
                                            continue
                                        rows = len(figures)
                                        combined, axes = plt.subplots(
                                            rows,
                                            1,
                                            figsize=(8, max(3.2, 3.0 * rows)),
                                            squeeze=False,
                                        )
                                        for ax, (single_channel, fig) in zip(axes.flat, figures):
                                            source_ax = fig.axes[0] if fig.axes else None
                                            if source_ax is not None:
                                                for line in source_ax.get_lines():
                                                    ax.plot(
                                                        line.get_xdata(),
                                                        line.get_ydata(),
                                                        color=line.get_color(),
                                                        linewidth=line.get_linewidth(),
                                                        linestyle=line.get_linestyle(),
                                                        alpha=line.get_alpha(),
                                                    )
                                                ax.set_xlim(source_ax.get_xlim())
                                                ax.set_ylim(
                                                        *(gif_y_limits or source_ax.get_ylim())
                                                    )
                                                ax.set_xlabel(source_ax.get_xlabel())
                                                ax.set_ylabel(source_ax.get_ylabel())
                                            ax.set_title(
                                                _trace_channel_label(single_channel)
                                            )
                                            ax.grid(alpha=.25)
                                            plt.close(fig)
                                        combined.suptitle(
                                            f"{frame_group} iteration {frame_iteration} — {selected_trace_type}",
                                            fontsize=12,
                                        )
                                        combined.tight_layout()
                                        yield combined
                                    else:
                                        fig, errors = _plot_traces(
                                            full_session,
                                            frame_observation,
                                            corrected,
                                            selected_channels,
                                            trace_analysis,
                                            correction_label,
                                            overlaid=True,
                                            trace_items=frame_traces,
                                            normalize_to_peak=normalize_to_peak,
                                            corrected_trace_key=corrected_trace_key,
                                            offset_to_baseline=offset_to_baseline,
                                            voltage_min=trace_voltage_min,
                                            voltage_max=trace_voltage_max,
                                        )
                                        if errors:
                                            fig.text(
                                                .02,
                                                .01,
                                                " | ".join(errors[:3]),
                                                fontsize=6,
                                            )
                                        if gif_y_limits is not None and fig.axes:
                                            fig.axes[0].set_ylim(*gif_y_limits)
                                        yield fig

                            gif_bytes = _figures_to_gif(
                                swv_frames(),
                                trace_gif_duration,
                                total_frames=len(frame_observations),
                                progress_callback=(
                                    lambda current, total:
                                    trace_progress.progress(
                                        _progress_fraction(
                                            current,
                                            total,
                                            start=0.05,
                                            end=0.95,
                                        ),
                                        text=(
                                            f"Rendering SWV frame {current}/"
                                            f"{max(total, current)}"
                                        ),
                                    )
                                ),
                            )
                            trace_progress.progress(
                                1.0,
                                text=f"SWV GIF complete ({len(frame_observations)} frames)",
                            )
                            st.session_state[trace_gif_key] = gif_bytes
                        except Exception as exc:
                            st.session_state.pop(trace_gif_key, None)
                            st.error(f"SWV GIF generation failed: {exc}")
                trace_gif_bytes = st.session_state.get(trace_gif_key)
                if trace_gif_bytes:
                    st.image(trace_gif_bytes)
                    safe_trace_name = re.sub(
                        r"[^A-Za-z0-9._-]+",
                        "_",
                        f"{selected_trace_type}_{trace_layout}",
                    ).strip("_")
                    st.download_button(
                        "Download SWV GIF",
                        data=trace_gif_bytes,
                        file_name=f"swv_traces_{safe_trace_name}.gif",
                        mime="image/gif",
                        key=f"{trace_gif_key}_download",
                    )

    with real_data:
        st.caption(
            "These plots use completed experimental observations only; no surrogate predictions are shown."
        )
        show_real_observation_group_filter = (
            bool(
                ((full_session.get("config") or {}).get("records") or {}).get(
                    "simulated_session"
                )
            )
            and len(observation_group_ids) > 1
        )
        real_selected_observation_group_ids = set(selected_observation_group_ids)
        real_scope_key = str(selected_observation_group_scope)
        if show_real_observation_group_filter:
            real_group_filter_options = [
                "all",
                *observation_group_family_options.keys(),
                *observation_group_ids,
            ]
            real_group_filter_default = (
                [selected_observation_group_scope]
                if selected_observation_group_scope in real_group_filter_options
                else ["all"]
            )
            real_group_filter_key = "bo_real_observation_group_filters"
            real_group_filter_valid, real_group_filter_display = (
                _prepare_preferred_multiselect_value(
                    real_group_filter_key,
                    f"{real_group_filter_key}__preferred",
                    real_group_filter_options,
                    real_group_filter_default,
                )
            )
            selected_real_group_filters = st.multiselect(
                "Real-data observation groups",
                real_group_filter_options,
                default=real_group_filter_display,
                format_func=observation_group_scope_label,
                key=real_group_filter_key,
                help=(
                    "Filters the observation groups used only in this Real Data "
                    "Landscapes tab. This is useful for multi-parameter "
                    "simulation sweeps with many saved simulation runs."
                ),
            )
            _sync_preferred_widget_value(
                real_group_filter_key,
                f"{real_group_filter_key}__preferred",
                real_group_filter_valid,
                selected_real_group_filters,
            )
            if not selected_real_group_filters or "all" in selected_real_group_filters:
                real_selected_observation_group_ids = set(observation_group_ids)
                real_scope_key = "all"
            else:
                real_selected_observation_group_ids = set()
                for group_filter in selected_real_group_filters:
                    if (
                        isinstance(group_filter, str)
                        and group_filter in observation_group_family_options
                    ):
                        real_selected_observation_group_ids.update(
                            observation_group_family_options[group_filter]["ids"]
                        )
                    else:
                        real_selected_observation_group_ids.add(int(group_filter))
                real_group_token = "_".join(
                    str(group_id)
                    for group_id in sorted(real_selected_observation_group_ids)
                )
                real_scope_key = (
                    f"groups_{real_group_token}"
                    if len(real_selected_observation_group_ids) <= 8
                    else "groups_" + hashlib.sha1(
                        real_group_token.encode("utf-8")
                    ).hexdigest()[:12]
                )
            if not real_selected_observation_group_ids:
                st.info("Select at least one observation group for Real Data Landscapes.")
        all_real_observations = [
            obs for obs in observations
            if int(obs.get("group_id", 1)) in real_selected_observation_group_ids
        ] if show_real_observation_group_filter else group_scoped_observations
        real_observations = [
            observation
            for observation in all_real_observations
            if (
                selected_iteration_scope == "all"
                or int(observation.get("iteration", 0))
                <= int(selected_iteration_scope)
            )
        ]

        def real_iteration_path_frame(observations: list[dict]) -> pd.DataFrame:
            return pd.DataFrame([
                {
                    "iteration": int(observation.get("iteration", 0)),
                    "group_id": int(observation.get("group_id", 1)),
                    **{
                        parameter: float(value)
                        for parameter, value in (
                            observation.get("params") or {}
                        ).items()
                        if parameter in PARAMETERS and value is not None
                    },
                }
                for observation in observations
            ])

        real_iteration_path = real_iteration_path_frame(real_observations)
        real_axis_ranges = {}
        for parameter in PARAMETERS:
            parameter_values = [
                float((observation.get("params") or {})[parameter])
                for observation in all_real_observations
                if (observation.get("params") or {}).get(parameter) is not None
            ]
            if parameter_values:
                real_axis_ranges[parameter] = (
                    min(parameter_values),
                    max(parameter_values),
                )
        real_metric_options = [
            metric for metric in _q_relevant_metrics(
                REAL_DATA_METRICS,
                session["config"],
                paired_objective,
                phase=None,
            )
            if paired_objective or metric != "Paired Q"
        ] + [
            "Count",
        ]
        _preserve_valid_widget_value(
            "bo_real_metric",
            real_metric_options,
            real_metric_options[0],
        )
        real_metric = st.selectbox(
            "Measured metric",
            real_metric_options,
            key="bo_real_metric",
        )
        count_mode = real_metric == "Count"
        paired_q_mode = real_metric == "Paired Q"
        if count_mode:
            real_phase = "measurement"
            st.caption(
                "Count uses completed observation occurrences and is independent "
                "of buffer/target measurement phase."
            )
            bin_columns = st.columns(3)
            count_bin_sizes = {
                "frequency": float(bin_columns[0].number_input(
                    "Frequency bin size (Hz)",
                    min_value=0.001,
                    value=50.0,
                    format="%.3f",
                    key="bo_count_frequency_bin",
                )),
                "amplitude": float(bin_columns[1].number_input(
                    "Amplitude bin size (V)",
                    min_value=0.000001,
                    value=0.005,
                    format="%.6f",
                    key="bo_count_amplitude_bin",
                )),
                "step_potential": float(bin_columns[2].number_input(
                    "Step-size bin (V)",
                    min_value=0.000001,
                    value=0.001,
                    format="%.6f",
                    key="bo_count_step_bin",
                )),
            }
        elif paired_q_mode:
            real_phase = "measurement"
            count_bin_sizes = {}
            st.caption(
                "Paired Q is independent of buffer/target phase. Channel and "
                "group plots use stored per-channel paired Q values when "
                "available, with run-level Q_run as a fallback."
            )
        else:
            real_phase_options = (
                ["buffer", "target", "both"]
                if paired_objective
                else ["measurement"]
            )
            _preserve_valid_widget_value(
                "bo_real_phase",
                real_phase_options,
                real_phase_options[0],
            )
            real_phase = st.radio(
                "Measurement phase",
                real_phase_options,
                horizontal=True,
                format_func=str.title,
                key="bo_real_phase",
            )
            count_bin_sizes = {}
        observed_group_ids = {
            int(observation.get("group_id", 1))
            for observation in real_observations
        }
        real_groups = [
            group for group in groups if group["id"] in observed_group_ids
        ]
        handling_options = [
            "Average selected channels",
            "Overlay selected channels",
            "Plot channels individually",
        ]
        if real_groups and not count_mode:
            handling_options.append("Plot channel groups")
        real_channel_mode_key = f"bo_real_channel_mode_{real_metric}_{real_phase}"
        _preserve_valid_widget_value(
            real_channel_mode_key,
            handling_options,
            handling_options[0],
        )
        real_channel_mode = st.radio(
            "Channel handling",
            handling_options,
            horizontal=True,
            key=real_channel_mode_key,
        )
        selected_real_groups = []
        selected_real_channels = []
        if real_channel_mode == "Plot channel groups":
            real_group_options = [group["id"] for group in real_groups]
            real_groups_key = (
                f"bo_real_groups_{real_scope_key}_{real_metric}_{real_phase}"
            )
            real_groups_valid, real_groups_display = (
                _prepare_preferred_multiselect_value(
                    real_groups_key,
                    f"{real_groups_key}__preferred",
                    real_group_options,
                    real_group_options,
                )
            )
            selected_group_ids = st.multiselect(
                "Metric channel groups",
                real_group_options,
                default=real_groups_display,
                format_func=lambda group_id: next(
                    (
                        f"{group['name']} (channels "
                        f"{', '.join(map(str, group['channels']))})"
                        for group in real_groups
                        if group["id"] == group_id
                    ),
                    f"Group {group_id}",
                ),
                key=real_groups_key,
            )
            _sync_preferred_widget_value(
                real_groups_key,
                f"{real_groups_key}__preferred",
                real_groups_valid,
                real_groups_display,
            )
            selected_real_groups = [
                group for group in real_groups
                if group["id"] in selected_group_ids
            ]
        else:
            real_channels = _real_data_channels(all_real_observations)
            real_channels_key = (
                f"bo_real_channels_{real_scope_key}_{real_metric}_{real_phase}"
            )
            real_channels_valid, real_channels_display = (
                _prepare_preferred_multiselect_value(
                    real_channels_key,
                    f"{real_channels_key}__preferred",
                    real_channels,
                    real_channels,
                )
            )
            selected_real_channels = st.multiselect(
                "Metric channels",
                real_channels,
                default=real_channels_display,
                format_func=lambda channel: f"Ch {channel}",
                key=real_channels_key,
            )
            _sync_preferred_widget_value(
                real_channels_key,
                f"{real_channels_key}__preferred",
                real_channels_valid,
                real_channels_display,
            )
        selected_real_run_group_ids: set[int] | None = None
        show_real_simulation_run_selector = (
            _is_loaded_simulated_sweep_session(full_session)
            and real_channel_mode != "Plot channel groups"
            and bool(selected_real_channels)
        )
        if show_real_simulation_run_selector:
            selected_channel_set = set(map(str, selected_real_channels))
            run_options = [
                group["id"]
                for group in real_groups
                if selected_channel_set.intersection(
                    str(channel) for channel in group.get("channels", [])
                )
            ]
            run_options = sorted(dict.fromkeys(run_options))
            if run_options:
                real_run_default = (
                    run_options[:1]
                    if len(selected_channel_set) == 1 and len(run_options) > 1
                    else run_options
                )
                selected_channel_token = "_".join(
                    re.sub(r"[^0-9A-Za-z]+", "-", str(channel)).strip("-")
                    or "channel"
                    for channel in sorted(
                        selected_channel_set,
                        key=_channel_sort_key,
                    )
                )
                real_run_key = (
                    f"bo_real_simulation_runs_{real_scope_key}_"
                    f"{real_metric}_{real_phase}_{real_channel_mode}_"
                    f"{selected_channel_token}"
                )
                real_run_valid, real_run_display = (
                    _prepare_preferred_multiselect_value(
                        real_run_key,
                        f"{real_run_key}__preferred",
                        run_options,
                        real_run_default,
                    )
                )
                selected_real_run_ids = st.multiselect(
                    "Simulation runs",
                    run_options,
                    default=real_run_display,
                    format_func=lambda group_id: next(
                        (
                            group["name"]
                            for group in real_groups
                            if int(group["id"]) == int(group_id)
                        ),
                        f"Simulation run {group_id}",
                    ),
                    key=real_run_key,
                    help=(
                        "Filters repeated simulation traces within the selected "
                        "real channel(s). For example, Ch 1 with three "
                        "exploration settings appears as three simulation runs."
                    ),
                )
                _sync_preferred_widget_value(
                    real_run_key,
                    f"{real_run_key}__preferred",
                    real_run_valid,
                    selected_real_run_ids,
                )
                selected_real_run_group_ids = {
                    int(group_id) for group_id in selected_real_run_ids
                }
                real_observations = [
                    observation
                    for observation in real_observations
                    if int(observation.get("group_id", 1))
                    in selected_real_run_group_ids
                ]
                real_iteration_path = real_iteration_path_frame(real_observations)
                if not selected_real_run_group_ids:
                    st.info("Select at least one simulation run to plot.")
        real_color_by = "Measured value"
        real_group_color_values = None
        real_group_color_label = None
        if real_channel_mode == "Overlay selected channels":
            real_metadata = _channel_group_optimization_metadata(
                full_session,
                groups,
            )
            real_color_options: dict[
                str,
                tuple[dict[int, float] | None, str | None],
            ] = {
                "Measured value": (None, None),
                "Channel": (None, None),
                "Group": (None, None),
                "Exploration weight": (
                    {
                        item["id"]: float(item["exploration"])
                        for item in real_metadata
                        if item["exploration"] is not None
                    },
                    "Exploration",
                ),
                "Exploitation weight": (
                    {
                        item["id"]: float(item["exploitation"])
                        for item in real_metadata
                        if item["exploitation"] is not None
                    },
                    "Exploitation",
                ),
            }
            parameter_config = (
                (full_session.get("config") or {}).get("parameters") or {}
            )
            for parameter in PARAMETERS:
                metadata_values = {
                    item["id"]: float(item["gp_falloff_fractions"][parameter])
                    for item in real_metadata
                    if parameter in item["gp_falloff_fractions"]
                }
                if metadata_values:
                    parameter_label = (
                        (parameter_config.get(parameter) or {}).get("label")
                        or parameter
                    )
                    real_color_options[f"GP falloff — {parameter_label}"] = (
                        metadata_values,
                        f"{parameter_label} GP falloff",
                    )
            real_color_key = f"bo_real_overlay_color_{real_metric}_{real_phase}"
            _preserve_valid_widget_value(
                real_color_key,
                list(real_color_options),
                "Measured value",
            )
            real_color_by = st.selectbox(
                "Overlay color",
                list(real_color_options),
                key=real_color_key,
            )
            real_group_color_values, real_group_color_label = (
                real_color_options[real_color_by]
            )
        requested_phases = ("buffer", "target") if real_phase == "both" else (real_phase,)
        if count_mode:
            count_channels = (
                [
                    str(channel)
                    for group in selected_real_groups
                    for channel in group.get("channels", [])
                ]
                if real_channel_mode == "Plot channel groups"
                else selected_real_channels
            )
            real_points_by_phase = {
                "measurement": _real_count_occurrences(
                    real_observations,
                    count_channels,
                )
            }
        elif (
            real_channel_mode != "Plot channel groups"
            and not selected_real_channels
        ):
            real_points_by_phase = {
                phase: pd.DataFrame()
                for phase in requested_phases
            }
        else:
            real_points_by_phase = {
                phase: (
                    _real_group_metric_points(
                        real_observations,
                        real_metric,
                        phase,
                        selected_real_groups,
                    )
                    if real_channel_mode == "Plot channel groups"
                    else _real_metric_points(
                        real_observations,
                        real_metric,
                        phase,
                        selected_real_channels,
                        average_channels=real_channel_mode == "Average selected channels",
                    )
                )
                for phase in requested_phases
            }
        real_movie_source_by_phase = {
            phase: points.copy()
            for phase, points in real_points_by_phase.items()
        }
        combined_real_points = pd.concat(
            [
                points.assign(phase=phase)
                for phase, points in real_points_by_phase.items()
                if not points.empty
            ],
            ignore_index=True,
        ) if any(not points.empty for points in real_points_by_phase.values()) else pd.DataFrame()
        display_real_metric = real_metric
        active_comparison_payload = None
        comparison_overview_points = pd.DataFrame()
        st.markdown("#### Session comparison")
        st.caption(
            "Cache the current real-data metric table, load another BO session, "
            "then load the cached values to plot current minus cached values."
        )
        comparison_controls = st.columns([1, 1, 1])
        if comparison_controls[0].button(
            "Cache comparison values",
            disabled=combined_real_points.empty,
            use_container_width=True,
            key="bo_real_cache_comparison_values",
        ):
            st.session_state["bo_real_comparison_cached"] = _real_comparison_payload(
                combined_real_points,
                metric=real_metric,
                phase=real_phase,
                channel_mode=real_channel_mode,
                session_path=selected_session_folder,
            )
            st.session_state.pop("bo_real_comparison_active", None)
            st.success(
                f"Cached {len(combined_real_points):,} {real_metric} row(s) "
                "for comparison."
            )
        cached_comparison_payload = st.session_state.get(
            "bo_real_comparison_cached"
        )
        if comparison_controls[1].button(
            "Load comparison values",
            disabled=not cached_comparison_payload or combined_real_points.empty,
            use_container_width=True,
            key="bo_real_load_comparison_values",
        ):
            st.session_state["bo_real_comparison_active"] = cached_comparison_payload
        if comparison_controls[2].button(
            "Clear comparison",
            disabled=not st.session_state.get("bo_real_comparison_active"),
            use_container_width=True,
            key="bo_real_clear_comparison_values",
        ):
            st.session_state.pop("bo_real_comparison_active", None)
            st.rerun()
        if combined_real_points.empty:
            st.caption(
                "Cache comparison values is disabled until the current metric, "
                "phase, and channel selection produces rows."
            )
        if cached_comparison_payload:
            comparison_controls[0].caption(
                f"Cached {cached_comparison_payload.get('row_count', 0):,} "
                f"{cached_comparison_payload.get('metric', 'metric')} row(s)."
            )
        active_comparison_payload = st.session_state.get(
            "bo_real_comparison_active"
        )
        if active_comparison_payload and not combined_real_points.empty:
            cached_metric = active_comparison_payload.get("metric")
            if cached_metric != real_metric:
                st.warning(
                    "Cached comparison metric is "
                    f"{cached_metric}; select {cached_metric} to compare values."
                )
            else:
                comparison_points, comparison_error = _real_comparison_delta_points(
                    combined_real_points,
                    active_comparison_payload["points"],
                )
                if comparison_error:
                    st.warning(comparison_error)
                if not comparison_points.empty:
                    comparison_overview_points = comparison_points
                    st.success(
                        f"Loaded comparison values: {len(comparison_points):,} "
                        "cached coordinate(s) evaluated with current-session RBF interpolation."
                    )
        real_value_colorscale = "Viridis"
        unsliced_real_points_by_phase = {
            phase: points.copy()
            for phase, points in real_points_by_phase.items()
        }
        unsliced_real_iteration_path = real_iteration_path.copy()
        if combined_real_points.empty:
            st.info(
                "No recorded values are available for this metric, phase, "
                "and channel or group selection."
            )
        else:
            real_dimensions = [
                parameter
                for parameter in PARAMETERS
                if parameter in combined_real_points.columns
                and combined_real_points[parameter].nunique(dropna=True) > 1
                and (
                    not count_mode
                    or parameter in (
                        "frequency",
                        "amplitude",
                        "step_potential",
                    )
                )
            ]
            if not real_dimensions:
                st.info("No experimental parameter varied in the recorded observations.")
            else:
                comparison_3d_active = {
                    "cached_value",
                    "current_value",
                    "comparison_delta",
                }.issubset(comparison_overview_points.columns)
                if comparison_3d_active and len(real_dimensions) >= 3:
                    st.markdown("#### Comparison 3D overview")
                    st.caption(
                        "Cached metric values and current-session RBF-evaluated "
                        "values are shown at the cached session's parameter "
                        "coordinates. In individual-channel mode, each channel "
                        "gets its own set of synced 3D views."
                    )
                    preferred_comparison_axes = [
                        parameter
                        for parameter in (
                            "frequency",
                            "amplitude",
                            "step_potential",
                        )
                        if parameter in real_dimensions
                    ]
                    for parameter in real_dimensions:
                        if parameter not in preferred_comparison_axes:
                            preferred_comparison_axes.append(parameter)
                    preferred_comparison_axes = preferred_comparison_axes[:3]
                    comparison_axis_columns = st.columns(3)
                    comparison_x_key = (
                        f"bo_real_comparison_3d_x_{real_scope_key}_{real_metric}"
                    )
                    _preserve_valid_widget_value(
                        comparison_x_key,
                        real_dimensions,
                        preferred_comparison_axes[0],
                    )
                    comparison_x = comparison_axis_columns[0].selectbox(
                        "Comparison 3D X",
                        real_dimensions,
                        key=comparison_x_key,
                    )
                    comparison_y_options = [
                        name for name in real_dimensions if name != comparison_x
                    ]
                    comparison_y_key = (
                        f"bo_real_comparison_3d_y_{real_scope_key}_{real_metric}"
                    )
                    _preserve_valid_widget_value(
                        comparison_y_key,
                        comparison_y_options,
                        next(
                            (
                                axis for axis in preferred_comparison_axes
                                if axis in comparison_y_options
                            ),
                            comparison_y_options[0],
                        ),
                    )
                    comparison_y = comparison_axis_columns[1].selectbox(
                        "Comparison 3D Y",
                        comparison_y_options,
                        key=comparison_y_key,
                    )
                    comparison_z_options = [
                        name for name in real_dimensions
                        if name not in {comparison_x, comparison_y}
                    ]
                    comparison_z_key = (
                        f"bo_real_comparison_3d_z_{real_scope_key}_{real_metric}"
                    )
                    _preserve_valid_widget_value(
                        comparison_z_key,
                        comparison_z_options,
                        next(
                            (
                                axis for axis in preferred_comparison_axes
                                if axis in comparison_z_options
                            ),
                            comparison_z_options[0],
                        ),
                    )
                    comparison_z = comparison_axis_columns[2].selectbox(
                        "Comparison 3D Z",
                        comparison_z_options,
                        key=comparison_z_key,
                    )
                    if (
                        real_channel_mode == "Plot channels individually"
                        and "channel" in comparison_overview_points.columns
                    ):
                        channel_groups = [
                            (str(channel), channel_points.copy())
                            for channel, channel_points in sorted(
                                comparison_overview_points.groupby(
                                    "channel",
                                    sort=False,
                                ),
                                key=lambda item: _channel_sort_key(str(item[0])),
                            )
                        ]
                        channel_options = [
                            channel for channel, _points in channel_groups
                        ]
                        comparison_channel_key = (
                            f"bo_real_comparison_3d_channel_{real_scope_key}_"
                            f"{real_metric}"
                        )
                        _preserve_valid_widget_value(
                            comparison_channel_key,
                            channel_options,
                            channel_options[0],
                        )
                        selected_comparison_channel = st.selectbox(
                            "Comparison overview channel",
                            channel_options,
                            format_func=lambda channel: f"Ch {channel}",
                            key=comparison_channel_key,
                        )
                        comparison_series = [
                            (
                                f"Ch {channel}",
                                f"channel_{_safe_download_stem(channel)}",
                                channel_points,
                            )
                            for channel, channel_points in channel_groups
                            if channel == str(selected_comparison_channel)
                        ]
                    else:
                        comparison_series = [("", "all", comparison_overview_points)]
                    for series_label, series_token, series_points in comparison_series:
                        if series_points.empty:
                            continue
                        if series_label:
                            st.markdown(f"##### {series_label}")
                        classic_values = pd.to_numeric(
                            pd.concat([
                                series_points["cached_value"],
                                series_points["current_value"],
                            ]),
                            errors="coerce",
                        )
                        classic_values = classic_values[np.isfinite(classic_values)]
                        classic_range = (
                            (float(classic_values.min()), float(classic_values.max()))
                            if not classic_values.empty
                            else None
                        )
                        comparison_camera_storage_key = (
                            f"real_comparison_3d_{real_scope_key}_{real_metric}_"
                            f"{series_token}_{comparison_x}_{comparison_y}_"
                            f"{comparison_z}"
                        )
                        comparison_shared_storage_key = (
                            f"bo_viewer_camera:shared:{comparison_camera_storage_key}"
                        )
                        comparison_cached_camera = _valid_plotly_camera(
                            st.session_state.get(
                                _plotly_camera_state_key(
                                    comparison_shared_storage_key
                                )
                            )
                        )
                        sync_nonce_key = (
                            f"bo_real_comparison_3d_sync_nonce_{real_scope_key}_"
                            f"{real_metric}_{series_token}_{comparison_x}_"
                            f"{comparison_y}_{comparison_z}"
                        )
                        st.session_state.setdefault(sync_nonce_key, 0)
                        comparison_sync_nonce = int(
                            st.session_state.get(sync_nonce_key, 0)
                        )
                        st.caption(
                            (
                                "Cached 3D view is ready for sync."
                                if comparison_cached_camera is not None
                                else (
                                    "Click Cache view below one plot first. "
                                    "Sync is enabled after the cached view reaches Streamlit."
                                )
                            )
                        )
                        if st.button(
                            "Sync 3D perspectives now",
                            disabled=comparison_cached_camera is None,
                            help=(
                                "Applies the most recently cached comparison "
                                "3D camera for this overview set only."
                            ),
                            key=f"{sync_nonce_key}_button",
                        ):
                            comparison_sync_nonce = (
                                int(st.session_state.get(sync_nonce_key, 0)) + 1
                            )
                            st.session_state[sync_nonce_key] = comparison_sync_nonce
                        comparison_slice_axis_key = (
                            f"bo_real_comparison_3d_slice_axis_{real_scope_key}_"
                            f"{real_metric}_{series_token}_{comparison_x}_"
                            f"{comparison_y}_{comparison_z}"
                        )
                        comparison_slice_axis_options = [
                            NO_HIGHLIGHTED_SLICE_LABEL,
                            comparison_x,
                            comparison_y,
                            comparison_z,
                        ]
                        comparison_selected_slice_axis = None
                        comparison_selected_slice_value = None
                        current_comparison_slice_axis_choice = (
                            st.session_state.get(
                                comparison_slice_axis_key,
                                NO_HIGHLIGHTED_SLICE_LABEL,
                            )
                        )
                        if (
                            current_comparison_slice_axis_choice
                            in comparison_slice_axis_options
                            and current_comparison_slice_axis_choice
                            != NO_HIGHLIGHTED_SLICE_LABEL
                        ):
                            comparison_selected_slice_axis = (
                                current_comparison_slice_axis_choice
                            )
                            comparison_slice_value_key = (
                                f"{comparison_slice_axis_key}_value_"
                                f"{comparison_selected_slice_axis}"
                            )
                            comparison_slice_values = _numeric_slice_values(
                                series_points,
                                comparison_selected_slice_axis,
                            )
                            current_comparison_slice_value = (
                                st.session_state.get(comparison_slice_value_key)
                            )
                            if (
                                current_comparison_slice_value
                                in comparison_slice_values
                            ):
                                comparison_selected_slice_value = float(
                                    current_comparison_slice_value
                                )
                            elif comparison_slice_values:
                                comparison_selected_slice_value = float(
                                    comparison_slice_values[0]
                                )
                        overview_columns = st.columns(3)
                        overview_specs = [
                            (
                                overview_columns[0],
                                "cached_value",
                                f"Cached {real_metric}",
                                "Viridis",
                                classic_range,
                            ),
                            (
                                overview_columns[1],
                                "current_value",
                                f"Current RBF {real_metric}",
                                "Viridis",
                                classic_range,
                            ),
                            (
                                overview_columns[2],
                                "comparison_delta",
                                f"Δ {real_metric}",
                                "Magma",
                                None,
                            ),
                        ]
                        for (
                            overview_column,
                            value_column,
                            value_label,
                            colorscale,
                            value_range,
                        ) in overview_specs:
                            plot_camera_storage_key = (
                                f"{comparison_camera_storage_key}_{value_column}"
                            )
                            comparison_fig = _plot_real_comparison_3d(
                                series_points,
                                value_column=value_column,
                                value_label=value_label,
                                x_name=comparison_x,
                                y_name=comparison_y,
                                z_name=comparison_z,
                                colorscale=colorscale,
                                value_range=value_range,
                                slice_axis=comparison_selected_slice_axis,
                                slice_value=comparison_selected_slice_value,
                            )
                            rendered_camera = _render_camera_persistent_plotly(
                                overview_column,
                                comparison_fig,
                                key=(
                                    f"bo_real_comparison_3d_{value_column}_"
                                    f"{real_scope_key}_{real_metric}_{series_token}_"
                                    f"{comparison_x}_{comparison_y}_{comparison_z}"
                                ),
                                camera_storage_key=plot_camera_storage_key,
                                shared_camera_storage_key=comparison_shared_storage_key,
                                apply_sync_nonce=comparison_sync_nonce,
                                height=int(comparison_fig.layout.height or 440),
                                file_stem=(
                                    f"real_comparison_3d_{value_column}_"
                                    f"{real_metric}_{series_token}_{comparison_x}_"
                                    f"{comparison_y}_{comparison_z}"
                                ),
                                show_download=False,
                            )
                            download_camera = (
                                comparison_cached_camera
                                if comparison_cached_camera is not None
                                else rendered_camera
                            )
                            download_fig = go.Figure(comparison_fig)
                            _apply_plotly_camera(download_fig, download_camera)
                            try:
                                png_bytes = _plotly_png_bytes(
                                    download_fig,
                                    width=900,
                                    height=700,
                                    scale=2,
                                )
                                _render_browser_download_link(
                                    overview_column,
                                    "Download plot",
                                    png_bytes,
                                    file_name=(
                                        f"{_safe_download_stem('real_comparison_3d')}_"
                                        f"{_safe_download_stem(value_column)}_"
                                        f"{_safe_download_stem(real_metric)}_"
                                        f"{_safe_download_stem(series_token)}_"
                                        f"{_safe_download_stem(comparison_x)}_"
                                        f"{_safe_download_stem(comparison_y)}_"
                                        f"{_safe_download_stem(comparison_z)}.png"
                                    ),
                                    mime="image/png",
                                )
                            except RuntimeError as exc:
                                overview_column.caption(str(exc))
                        if comparison_sync_nonce > 0:
                            st.session_state[sync_nonce_key] = 0
                        _preserve_valid_widget_value(
                            comparison_slice_axis_key,
                            comparison_slice_axis_options,
                            NO_HIGHLIGHTED_SLICE_LABEL,
                        )
                        comparison_slice_axis_choice = st.selectbox(
                            "Comparison highlighted slice axis",
                            comparison_slice_axis_options,
                            format_func=lambda value: (
                                value
                                if value == NO_HIGHLIGHTED_SLICE_LABEL
                                else _metric_label(value)
                            ),
                            key=comparison_slice_axis_key,
                        )
                        comparison_slice_axis = (
                            None
                            if (
                                comparison_slice_axis_choice
                                == NO_HIGHLIGHTED_SLICE_LABEL
                            )
                            else comparison_slice_axis_choice
                        )
                        if comparison_slice_axis is not None:
                            comparison_slice_values = _numeric_slice_values(
                                series_points,
                                comparison_slice_axis,
                            )
                            if not comparison_slice_values:
                                st.info(
                                    "No comparison slice values are available for "
                                    f"{_metric_label(comparison_slice_axis)}."
                                )
                            else:
                                comparison_slice_value_key = (
                                    f"{comparison_slice_axis_key}_value_"
                                    f"{comparison_slice_axis}"
                                )
                                _preserve_valid_widget_value(
                                    comparison_slice_value_key,
                                    comparison_slice_values,
                                    comparison_slice_values[0],
                                )
                                comparison_slice_value = float(st.selectbox(
                                    (
                                        "Comparison slice "
                                        f"{_metric_label(comparison_slice_axis)}"
                                    ),
                                    comparison_slice_values,
                                    format_func=lambda value: f"{float(value):g}",
                                    key=comparison_slice_value_key,
                                ))
                                comparison_slice_axes = [
                                    axis for axis in (
                                        comparison_x,
                                        comparison_y,
                                        comparison_z,
                                    )
                                    if axis != comparison_slice_axis
                                ]
                                if len(comparison_slice_axes) == 2:
                                    st.markdown(
                                        "##### Comparison highlighted slice 2D maps"
                                    )
                                    comparison_log_frequency = bool(
                                        st.session_state.get(
                                            "bo_real_log_frequency__preferred",
                                            st.session_state.get(
                                                "bo_real_log_frequency",
                                                False,
                                            ),
                                        )
                                    )
                                    slice_columns = st.columns(3)
                                    for slice_index, (
                                        _overview_column,
                                        value_column,
                                        value_label,
                                        colorscale,
                                        value_range,
                                    ) in enumerate(overview_specs):
                                        slice_fig = _plot_real_comparison_2d_slice(
                                            series_points,
                                            value_column=value_column,
                                            value_label=value_label,
                                            x_name=comparison_slice_axes[0],
                                            y_name=comparison_slice_axes[1],
                                            slice_axis=comparison_slice_axis,
                                            slice_value=comparison_slice_value,
                                            colorscale=colorscale,
                                            value_range=value_range,
                                            log_frequency=comparison_log_frequency,
                                        )
                                        _apply_plotly_slice_perimeter_style(
                                            slice_fig,
                                            "rgba(255,59,48,1)",
                                            thickness=3,
                                        )
                                        _render_downloadable_plotly(
                                            slice_columns[slice_index],
                                            slice_fig,
                                            key=(
                                                f"bo_real_comparison_2d_slice_"
                                                f"{value_column}_{real_scope_key}_"
                                                f"{real_metric}_{series_token}_"
                                                f"{comparison_slice_axis}_"
                                                f"{comparison_slice_value:g}_"
                                                f"{comparison_slice_axes[0]}_"
                                                f"{comparison_slice_axes[1]}"
                                            ),
                                            file_stem=(
                                                f"real_comparison_2d_slice_"
                                                f"{value_column}_{real_metric}_"
                                                f"{series_token}_"
                                                f"{comparison_slice_axis}_"
                                                f"{comparison_slice_value:g}_"
                                                f"{comparison_slice_axes[0]}_"
                                                f"{comparison_slice_axes[1]}"
                                            ),
                                            width_percent=100,
                                            export_width=800,
                                            export_height=int(round(
                                                800 / SURROGATE_2D_FIGURE_ASPECT
                                            )),
                                        )
                real_view_options = ["1D slice"]
                if len(real_dimensions) >= 2:
                    real_view_options.append("2D map")
                if len(real_dimensions) >= 3:
                    real_view_options.append("3D tensor")
                _preserve_valid_widget_value(
                    "bo_real_view",
                    real_view_options,
                    "1D slice",
                )
                real_view = st.radio(
                    "Real-data view",
                    real_view_options,
                    horizontal=True,
                    key="bo_real_view",
                )
                _preserve_valid_widget_value(
                    "bo_real_x",
                    real_dimensions,
                    real_dimensions[0],
                )
                real_x = st.selectbox("Real-data X", real_dimensions, key="bo_real_x")
                real_y_options = [name for name in real_dimensions if name != real_x]
                if real_view != "1D slice":
                    _preserve_valid_widget_value(
                        "bo_real_y",
                        real_y_options,
                        real_y_options[0],
                    )
                real_y = (
                    st.selectbox("Real-data Y", real_y_options, key="bo_real_y")
                    if real_view != "1D slice" else None
                )
                real_z_options = [
                    name for name in real_dimensions if name not in (real_x, real_y)
                ]
                if real_view == "3D tensor":
                    _preserve_valid_widget_value(
                        "bo_real_z",
                        real_z_options,
                        real_z_options[0],
                    )
                real_z = (
                    st.selectbox("Real-data Z", real_z_options, key="bo_real_z")
                    if real_view == "3D tensor" else None
                )
                real_2d_slice_column = None
                real_2d_slice_value = None
                real_2d_sweep_values: list[float] = []
                real_2d_sweep_token = "no_sweep"
                real_2d_slice_token = "all_unplotted"
                real_2d_title_note = None
                real_show_2d_measured_points = False
                real_3d_slice_axis = None
                real_3d_slice_value = None
                real_3d_slice_values: list[float] = []
                real_3d_slice_sweep_values: list[float] = []
                real_3d_slice_token = "no_slice"
                real_3d_slice_sweep_token = "no_sweep"
                if real_view == "2D map":
                    real_show_2d_measured_points = st.checkbox(
                        "Show measured points on 2D map",
                        value=False,
                        key=(
                            f"bo_real_show_2d_points_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_channel_mode}_"
                            f"{real_x}_{real_y}"
                        ),
                    )
                    real_2d_slice_options = [
                        name for name in real_dimensions
                        if name not in {real_x, real_y}
                    ]
                    if real_2d_slice_options:
                        slice_columns = st.columns(2)
                        real_2d_slice_choices = [
                            "Average all other unplotted values",
                            *real_2d_slice_options,
                        ]
                        real_2d_slice_column_key = (
                            f"bo_real_2d_slice_column_{real_scope_key}_"
                            f"{real_metric}_{real_x}_{real_y}"
                        )
                        _preserve_valid_widget_value(
                            real_2d_slice_column_key,
                            real_2d_slice_choices,
                            real_2d_slice_choices[0],
                        )
                        real_2d_slice_choice = slice_columns[0].selectbox(
                            "Fixed unplotted parameter",
                            real_2d_slice_choices,
                            format_func=lambda value: (
                                value if value.startswith("Average")
                                else _metric_label(value)
                            ),
                            key=real_2d_slice_column_key,
                        )
                        if (
                            real_2d_slice_choice
                            != "Average all other unplotted values"
                        ):
                            real_2d_slice_column = real_2d_slice_choice
                            real_2d_slice_values = _numeric_slice_values(
                                combined_real_points,
                                real_2d_slice_column,
                            )
                            if real_2d_slice_values:
                                real_2d_slice_value_key = (
                                    f"bo_real_2d_slice_value_{real_scope_key}_"
                                    f"{real_metric}_{real_x}_{real_y}_"
                                    f"{real_2d_slice_column}"
                                )
                                _preserve_valid_widget_value(
                                    real_2d_slice_value_key,
                                    real_2d_slice_values,
                                    real_2d_slice_values[0],
                                )
                                real_2d_slice_value = float(
                                    slice_columns[1].selectbox(
                                        f"Fixed {_metric_label(real_2d_slice_column)}",
                                        real_2d_slice_values,
                                        format_func=lambda value: f"{float(value):g}",
                                        key=real_2d_slice_value_key,
                                    )
                                )
                                real_2d_slice_token = _numeric_slice_token(
                                    real_2d_slice_column,
                                    real_2d_slice_value,
                                )
                                real_2d_title_note = _numeric_slice_title_note(
                                    real_2d_slice_column,
                                    real_2d_slice_value,
                                )
                                real_2d_sweep_key = (
                                    f"bo_real_2d_slice_sweep_{real_scope_key}_"
                                    f"{real_metric}_{real_x}_{real_y}_"
                                    f"{real_2d_slice_column}"
                                )
                                real_2d_sweep_valid, real_2d_sweep_display = (
                                    _prepare_preferred_multiselect_value(
                                        real_2d_sweep_key,
                                        f"{real_2d_sweep_key}__preferred",
                                        real_2d_slice_values,
                                        [real_2d_slice_value],
                                    )
                                )
                                real_2d_sweep_display = slice_columns[1].multiselect(
                                    "Slice sweep values",
                                    real_2d_slice_values,
                                    default=real_2d_sweep_display,
                                    format_func=lambda value: f"{float(value):g}",
                                    key=real_2d_sweep_key,
                                )
                                _sync_preferred_widget_value(
                                    real_2d_sweep_key,
                                    f"{real_2d_sweep_key}__preferred",
                                    real_2d_sweep_valid,
                                    real_2d_sweep_display,
                                )
                                real_2d_sweep_values = [
                                    float(value)
                                    for value in real_2d_sweep_display
                                ]
                                real_2d_sweep_token = _numeric_slice_values_token(
                                    real_2d_slice_column,
                                    real_2d_sweep_values,
                                )
                        else:
                            slice_columns[1].caption(
                                "2D map aggregates over unplotted parameters."
                            )
                if real_view == "3D tensor":
                    st.markdown("#### Highlighted slice")
                    real_3d_slice_axes = [real_x, real_y, real_z]
                    real_3d_slice_axis_choices = [
                        NO_HIGHLIGHTED_SLICE_LABEL,
                        *real_3d_slice_axes,
                    ]
                    real_3d_slice_columns = st.columns(2)
                    real_3d_slice_axis_key = (
                        f"bo_real_3d_slice_axis_{real_scope_key}_"
                        f"{real_metric}_{real_phase}_{real_channel_mode}_"
                        f"{real_x}_{real_y}_{real_z}"
                    )
                    _preserve_valid_widget_value(
                        real_3d_slice_axis_key,
                        real_3d_slice_axis_choices,
                        NO_HIGHLIGHTED_SLICE_LABEL,
                    )
                    real_3d_slice_axis_choice = real_3d_slice_columns[0].selectbox(
                        "Highlighted slice axis",
                        real_3d_slice_axis_choices,
                        format_func=lambda value: (
                            value if value == NO_HIGHLIGHTED_SLICE_LABEL
                            else _metric_label(value)
                        ),
                        key=real_3d_slice_axis_key,
                    )
                    real_3d_slice_axis = (
                        None
                        if real_3d_slice_axis_choice == NO_HIGHLIGHTED_SLICE_LABEL
                        else real_3d_slice_axis_choice
                    )
                    real_3d_slice_values = (
                        _numeric_slice_values(
                            combined_real_points,
                            real_3d_slice_axis,
                        )
                        if real_3d_slice_axis is not None
                        else []
                    )
                    if real_3d_slice_axis is not None and real_3d_slice_values:
                        real_3d_slice_value_key = (
                            f"bo_real_3d_slice_value_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_channel_mode}_"
                            f"{real_x}_{real_y}_{real_z}_{real_3d_slice_axis}"
                        )
                        _preserve_valid_widget_value(
                            real_3d_slice_value_key,
                            real_3d_slice_values,
                            real_3d_slice_values[0],
                        )
                        real_3d_slice_value = float(
                            real_3d_slice_columns[1].selectbox(
                                f"Slice {_metric_label(real_3d_slice_axis)}",
                                real_3d_slice_values,
                                format_func=lambda value: f"{float(value):g}",
                                key=real_3d_slice_value_key,
                            )
                        )
                        real_3d_slice_token = _numeric_slice_token(
                            real_3d_slice_axis,
                            real_3d_slice_value,
                        )
                        real_3d_slice_sweep_key = (
                            f"bo_real_3d_slice_sweep_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_channel_mode}_"
                            f"{real_x}_{real_y}_{real_z}_{real_3d_slice_axis}"
                        )
                        (
                            real_3d_sweep_valid,
                            real_3d_sweep_display,
                        ) = _prepare_preferred_multiselect_value(
                            real_3d_slice_sweep_key,
                            f"{real_3d_slice_sweep_key}__preferred",
                            real_3d_slice_values,
                            [real_3d_slice_value],
                        )
                        real_3d_sweep_display = real_3d_slice_columns[1].multiselect(
                            "Highlighted slice sweep values",
                            real_3d_slice_values,
                            default=real_3d_sweep_display,
                            format_func=lambda value: f"{float(value):g}",
                            key=real_3d_slice_sweep_key,
                        )
                        _sync_preferred_widget_value(
                            real_3d_slice_sweep_key,
                            f"{real_3d_slice_sweep_key}__preferred",
                            real_3d_sweep_valid,
                            real_3d_sweep_display,
                        )
                        real_3d_slice_sweep_values = [
                            float(value)
                            for value in real_3d_sweep_display
                        ]
                        if not any(
                            np.isclose(
                                float(value),
                                float(real_3d_slice_value),
                                rtol=1e-9,
                                atol=1e-12,
                            )
                            for value in real_3d_slice_sweep_values
                        ):
                            real_3d_slice_sweep_values.append(
                                real_3d_slice_value
                            )
                        real_3d_slice_sweep_values = sorted(
                            real_3d_slice_sweep_values
                        )
                        real_3d_slice_sweep_token = _numeric_slice_values_token(
                            real_3d_slice_axis,
                            real_3d_slice_sweep_values,
                        )
                if real_2d_slice_column is not None and real_2d_slice_value is not None:
                    real_points_by_phase = {
                        phase: _apply_numeric_slice(
                            points,
                            real_2d_slice_column,
                            real_2d_slice_value,
                        ).reset_index(drop=True)
                        for phase, points in real_points_by_phase.items()
                    }
                    real_movie_source_by_phase = {
                        phase: _apply_numeric_slice(
                            points,
                            real_2d_slice_column,
                            real_2d_slice_value,
                        ).reset_index(drop=True)
                        for phase, points in real_movie_source_by_phase.items()
                    }
                    real_iteration_path = _apply_numeric_slice(
                        real_iteration_path,
                        real_2d_slice_column,
                        real_2d_slice_value,
                    ).reset_index(drop=True)
                    combined_real_points = pd.concat(
                        [
                            points.assign(phase=phase)
                            for phase, points in real_points_by_phase.items()
                            if not points.empty
                        ],
                        ignore_index=True,
                    ) if any(
                        not points.empty for points in real_points_by_phase.values()
                    ) else pd.DataFrame()
                    if combined_real_points.empty:
                        st.info(
                            "The selected 2D slice has no real-data points for "
                            "this metric, phase, and channel selection."
                        )
                if count_mode:
                    count_dimensions = [
                        dimension
                        for dimension in (real_x, real_y, real_z)
                        if dimension is not None
                    ]
                    real_points_by_phase = {
                        phase: _bin_real_count_points(
                            points,
                            count_dimensions,
                            count_bin_sizes,
                            average_channels=(
                                real_channel_mode
                                == "Average selected channels"
                            ),
                        )
                        for phase, points in real_points_by_phase.items()
                    }
                    combined_real_points = pd.concat(
                        [
                            points.assign(phase=phase)
                            for phase, points in real_points_by_phase.items()
                            if not points.empty
                        ],
                        ignore_index=True,
                    )
                if count_mode:
                    full_range_points = _real_count_occurrences(
                        all_real_observations,
                        count_channels,
                    )
                    full_range_points = _apply_numeric_slice(
                        full_range_points,
                        real_2d_slice_column,
                        real_2d_slice_value,
                    )
                    full_range_points = _bin_real_count_points(
                        full_range_points,
                        count_dimensions,
                        count_bin_sizes,
                        average_channels=(
                            real_channel_mode == "Average selected channels"
                        ),
                    )
                    for dimension in count_dimensions:
                        if not full_range_points.empty:
                            half_bin = count_bin_sizes[dimension] / 2.0
                            real_axis_ranges[dimension] = (
                                float(full_range_points[dimension].min())
                                - half_bin,
                                float(full_range_points[dimension].max())
                                + half_bin,
                            )
                    full_value_frames = [full_range_points.assign(phase="measurement")]
                else:
                    full_value_frames = []
                    for phase in requested_phases:
                        full_points = (
                            _real_group_metric_points(
                                all_real_observations,
                                real_metric,
                                phase,
                                selected_real_groups,
                            )
                            if real_channel_mode == "Plot channel groups"
                            else _real_metric_points(
                                all_real_observations,
                                real_metric,
                                phase,
                                selected_real_channels,
                                average_channels=(
                                    real_channel_mode
                                    == "Average selected channels"
                                ),
                            )
                        )
                        full_points = _apply_numeric_slice(
                            full_points,
                            real_2d_slice_column,
                            real_2d_slice_value,
                        )
                        if not full_points.empty:
                            full_value_frames.append(full_points.assign(phase=phase))
                real_crop_axes = [
                    dimension
                    for dimension in (real_x, real_y, real_z)
                    if dimension is not None
                ]
                real_crop_ranges = _parameter_crop_ranges(
                    combined_real_points,
                    real_crop_axes,
                    key_prefix=(
                        f"bo_real_parameter_crop_{real_scope_key}_"
                        f"{real_metric}_{real_phase}_{real_channel_mode}_"
                        f"{real_view}_{real_x}_{real_y or 'none'}_"
                        f"{real_z or 'none'}_{real_2d_slice_token}"
                    ),
                    label="Crop landscape by parameter",
                    help_text=(
                        "Crop limits are applied to the real-data landscape, "
                        "interpolation source, data table, and generated GIF."
                    ),
                )
                if real_crop_ranges:
                    real_points_by_phase = {
                        phase: _apply_parameter_crop(
                            points,
                            real_crop_ranges,
                        ).reset_index(drop=True)
                        for phase, points in real_points_by_phase.items()
                    }
                    real_movie_source_by_phase = {
                        phase: _apply_parameter_crop(
                            points,
                            real_crop_ranges,
                        ).reset_index(drop=True)
                        for phase, points in real_movie_source_by_phase.items()
                    }
                    real_iteration_path = _apply_parameter_crop(
                        real_iteration_path,
                        real_crop_ranges,
                    ).reset_index(drop=True)
                    full_value_frames = [
                        _apply_parameter_crop(
                            points,
                            real_crop_ranges,
                        ).reset_index(drop=True)
                        for points in full_value_frames
                    ]
                    combined_real_points = pd.concat(
                        [
                            points.assign(phase=phase)
                            for phase, points in real_points_by_phase.items()
                            if not points.empty
                        ],
                        ignore_index=True,
                    ) if any(
                        not points.empty for points in real_points_by_phase.values()
                    ) else pd.DataFrame()
                    if combined_real_points.empty:
                        st.info(
                            "The current parameter crop excludes all real-data "
                            "points for this selection."
                        )
                    real_axis_ranges = {
                        **real_axis_ranges,
                        **real_crop_ranges,
                    }
                full_values = pd.concat(
                    full_value_frames,
                    ignore_index=True,
                )["value"] if full_value_frames else pd.Series(dtype=float)
                full_values = pd.to_numeric(
                    full_values,
                    errors="coerce",
                )
                full_values = full_values[np.isfinite(full_values)]
                real_auto_value_range = (
                    (float(full_values.min()), float(full_values.max()))
                    if not full_values.empty
                    else None
                )
                real_value_range = None
                if real_auto_value_range is not None:
                    manual_real_value_range = st.checkbox(
                        "Set measured metric display range manually",
                        key=(
                            f"bo_real_manual_value_range_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_channel_mode}"
                        ),
                        help=(
                            "Sets the color scale range for maps/tensors and "
                            "the y-axis range for 1D slices."
                        ),
                    )
                    if manual_real_value_range:
                        value_range_columns = st.columns(2)
                        real_value_min = float(value_range_columns[0].number_input(
                            f"{display_real_metric} minimum",
                            value=float(real_auto_value_range[0]),
                            format="%.6g",
                            key=(
                                f"bo_real_value_min_{real_scope_key}_"
                                f"{real_metric}_{real_phase}_{real_channel_mode}"
                            ),
                        ))
                        real_value_max = float(value_range_columns[1].number_input(
                            f"{display_real_metric} maximum",
                            value=float(real_auto_value_range[1]),
                            format="%.6g",
                            key=(
                                f"bo_real_value_max_{real_scope_key}_"
                                f"{real_metric}_{real_phase}_{real_channel_mode}"
                            ),
                        ))
                        if real_value_min < real_value_max:
                            real_value_range = (real_value_min, real_value_max)
                        else:
                            st.warning(
                                "Measured metric range minimum must be less "
                                "than the maximum; using per-plot autoscaling."
                            )
                real_log_frequency_key = "bo_real_log_frequency"
                real_log_frequency_preference_key = (
                    f"{real_log_frequency_key}__preferred"
                )
                _initialize_preference(
                    real_log_frequency_preference_key,
                    real_log_frequency_key,
                    default=False,
                )
                _capture_widget_preference(
                    real_log_frequency_key,
                    real_log_frequency_preference_key,
                )
                st.session_state[real_log_frequency_key] = bool(
                    st.session_state.get(real_log_frequency_preference_key, False)
                )
                real_log_frequency = st.checkbox(
                    "Log-scale frequency axis",
                    value=False,
                    disabled="frequency" not in (real_x, real_y, real_z),
                    help="Uses a logarithmic axis whenever frequency is a displayed dimension.",
                    key=real_log_frequency_key,
                )
                st.session_state[real_log_frequency_preference_key] = (
                    real_log_frequency
                )
                real_iteration_path_key = "bo_real_show_iteration_path"
                real_iteration_path_preference_key = (
                    f"{real_iteration_path_key}__preferred"
                )
                _initialize_preference(
                    real_iteration_path_preference_key,
                    real_iteration_path_key,
                    default=True,
                )
                _capture_widget_preference(
                    real_iteration_path_key,
                    real_iteration_path_preference_key,
                )
                st.session_state[real_iteration_path_key] = bool(
                    st.session_state.get(real_iteration_path_preference_key, True)
                )
                real_show_iteration_path = st.checkbox(
                    "Show iteration path",
                    value=True,
                    key=real_iteration_path_key,
                    help="Shows the chronological red-to-black path and iteration colorbar.",
                )
                st.session_state[real_iteration_path_preference_key] = (
                    real_show_iteration_path
                )
                def real_2d_tensor_source(
                    phase: str,
                    series_name: Any = None,
                    *,
                    require_2d_slice: bool = True,
                ) -> pd.DataFrame | None:
                    if (
                        count_mode
                        or real_view != "2D map"
                        and require_2d_slice
                    ):
                        return None
                    if (
                        require_2d_slice
                        and (
                            real_2d_slice_column is None
                            or real_2d_slice_value is None
                        )
                    ):
                        return None
                    source = unsliced_real_points_by_phase.get(
                        phase,
                        pd.DataFrame(),
                    )
                    if source.empty:
                        return None
                    source = source.copy()
                    if real_crop_ranges:
                        source = _apply_parameter_crop(
                            source,
                            real_crop_ranges,
                        ).reset_index(drop=True)
                    if (
                        series_name is not None
                        and "channel" in source.columns
                        ):
                        source = source.loc[
                            source["channel"].astype(str) == str(series_name)
                        ].reset_index(drop=True)
                    return source if not source.empty else None

                loaded_real_sweep_runs: list[dict] = []
                real_show_selected_channel_paths = False
                real_selected_path_available = (
                    _is_loaded_simulated_sweep_session(full_session)
                    and real_channel_mode == "Overlay selected channels"
                    and len(selected_real_channels) > 1
                    and real_view in {"2D map", "3D tensor"}
                    and not count_mode
                )
                if real_selected_path_available:
                    loaded_real_sweep_metadata = (
                        (full_session.get("state") or {})
                        .get("simulation_metadata")
                        or {}
                    )
                    loaded_real_sweep_axes = [
                        str(axis)
                        for axis in (
                            loaded_real_sweep_metadata.get("axes")
                            or (full_session.get("state") or {}).get(
                                "active_parameters"
                            )
                            or []
                        )
                        if axis is not None
                    ][:3]
                    if len(loaded_real_sweep_axes) == 3:
                        loaded_real_sweep_runs = (
                            _filter_simulation_runs_for_channels(
                                _simulation_loaded_sweep_runs(
                                    full_session,
                                    loaded_real_sweep_axes,
                                ),
                                selected_real_channels,
                            )
                        )
                        if selected_real_run_group_ids is not None:
                            loaded_real_sweep_runs = [
                                run for run in loaded_real_sweep_runs
                                if _finite_float(run.get("group_id")) is not None
                                and int(_finite_float(run.get("group_id")))
                                in selected_real_run_group_ids
                            ]
                if loaded_real_sweep_runs:
                    real_path_controls = st.columns(5)
                    real_show_selected_channel_paths = real_path_controls[0].checkbox(
                        "Show selected channel iteration paths",
                        value=True,
                        key=(
                            f"bo_real_selected_channel_paths_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                        help=(
                            "Overlays all selected simulated channel paths on the "
                            "current real-data 2D or 3D landscape using fixed "
                            "rainbow channel colors with less transparent later "
                            "iterations."
                        ),
                    )
                    real_selected_path_style_label = real_path_controls[1].selectbox(
                        "Path display",
                        ["Start/end + fading tail", "Full paths"],
                        key=(
                            f"bo_real_selected_channel_path_style_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                    )
                    real_selected_path_style = (
                        "start_end_tail"
                        if real_selected_path_style_label == "Start/end + fading tail"
                        else "full"
                    )
                    real_selected_path_line_width = int(real_path_controls[2].slider(
                        "Path line width",
                        min_value=1,
                        max_value=10,
                        value=4,
                        step=1,
                        key=(
                            f"bo_real_selected_channel_path_width_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                    ))
                    real_selected_path_marker_size = int(real_path_controls[3].slider(
                        "Path marker size",
                        min_value=3,
                        max_value=14,
                        value=6,
                        step=1,
                        key=(
                            f"bo_real_selected_channel_path_marker_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                    ))
                    real_selected_path_tail_length = int(real_path_controls[4].slider(
                        "Tail points",
                        min_value=2,
                        max_value=20,
                        value=8,
                        step=1,
                        disabled=real_selected_path_style != "start_end_tail",
                        key=(
                            f"bo_real_selected_channel_path_tail_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                    ))
                else:
                    real_selected_path_style = "full"
                    real_selected_path_line_width = 4
                    real_selected_path_marker_size = 6
                    real_selected_path_tail_length = 8
                real_global_optimum_reference = (
                    _session_simulation_optimum_reference(full_session)
                )
                real_can_show_global_optimum = (
                    real_global_optimum_reference is not None
                    and real_view in {"2D map", "3D tensor"}
                    and real_x is not None
                    and real_y is not None
                    and (real_view != "3D tensor" or real_z is not None)
                )
                real_show_global_optimum = (
                    st.checkbox(
                        "Show global optimum",
                        value=True,
                        key=(
                            f"bo_real_show_global_optimum_{real_scope_key}_"
                            f"{real_metric}_{real_phase}_{real_view}"
                        ),
                        help=(
                            "Marks the saved ground-truth optimum "
                            "(best frequency, amplitude, and step size)."
                        ),
                    )
                    if real_can_show_global_optimum else False
                )

                real_show_channel_iteration_paths = (
                    real_show_iteration_path
                    and not loaded_real_sweep_runs
                    and not bool(
                        (
                            ((full_session.get("config") or {}).get("records") or {})
                            .get("simulated_session")
                        )
                    )
                    and real_channel_mode == "Overlay selected channels"
                    and len(selected_real_channels) > 1
                    and real_view == "3D tensor"
                    and real_z is not None
                    and not count_mode
                )
                real_effective_show_iteration_path = (
                    real_show_iteration_path
                    and not real_show_selected_channel_paths
                    and not real_show_channel_iteration_paths
                )

                def add_real_selected_channel_paths(
                    fig: go.Figure,
                    *,
                    plot_x: str | None = None,
                    plot_y: str | None = None,
                    plot_z: str | None = None,
                    view: str | None = None,
                    slice_axis: str | None = None,
                    slice_value: float | None = None,
                ) -> None:
                    if not real_show_selected_channel_paths:
                        return
                    if not loaded_real_sweep_runs:
                        return
                    path_view = view or real_view
                    path_x = plot_x or real_x
                    path_y = plot_y or real_y
                    path_z = plot_z if plot_z is not None else real_z
                    if path_view == "3D tensor" and path_z is not None:
                        _add_simulation_sweep_paths(
                            fig,
                            loaded_real_sweep_runs,
                            path_x,
                            path_y,
                            path_z,
                            line_width=real_selected_path_line_width,
                            marker_size=real_selected_path_marker_size,
                            path_style=real_selected_path_style,
                            tail_length=real_selected_path_tail_length,
                        )
                    elif path_view == "2D map":
                        _add_simulation_sweep_paths(
                            fig,
                            loaded_real_sweep_runs,
                            path_x,
                            path_y,
                            None,
                            slice_axis=(
                                slice_axis
                                if slice_axis is not None
                                else real_2d_slice_column
                            ),
                            slice_value=(
                                slice_value
                                if slice_value is not None
                                else real_2d_slice_value
                            ),
                            line_width=real_selected_path_line_width,
                            marker_size=real_selected_path_marker_size,
                            path_style=real_selected_path_style,
                            tail_length=real_selected_path_tail_length,
                        )

                def add_real_channel_iteration_paths(
                    fig: go.Figure,
                    points: pd.DataFrame,
                ) -> None:
                    if not real_show_channel_iteration_paths:
                        return
                    _add_real_channel_iteration_paths(
                        fig,
                        points,
                        real_x,
                        real_y,
                        real_z,
                        line_width=real_selected_path_line_width,
                        marker_size=real_selected_path_marker_size,
                    )

                def add_real_global_optimum_marker(fig: go.Figure) -> None:
                    if not real_show_global_optimum:
                        return
                    _add_global_optimum_marker(
                        fig,
                        real_global_optimum_reference,
                        real_x,
                        real_y,
                        real_z if real_view == "3D tensor" else None,
                        slice_axis=(
                            real_2d_slice_column
                            if real_view == "2D map" else None
                        ),
                        slice_value=(
                            real_2d_slice_value
                            if real_view == "2D map" else None
                        ),
                    )

                real_plot_state_key = (
                    f"v3_{real_color_by}_{real_group_color_label or 'categorical'}_"
                    f"log{int(bool(real_log_frequency))}_"
                    f"path{int(bool(real_show_iteration_path))}_"
                    f"selectedpaths{int(bool(real_show_selected_channel_paths))}_"
                    f"channelpaths{int(bool(real_show_channel_iteration_paths))}_"
                    f"globalopt{int(bool(real_show_global_optimum))}_"
                    f"{real_3d_slice_token}_{real_3d_slice_sweep_token}"
                )

                real_3d_slice_plot_key = None
                highlighted_real_3d_slice_plot = None
                real_3d_slice_axes = []
                real_3d_slice_plots = []
                real_3d_slice_perimeter_thickness = 3
                if (
                    real_view == "3D tensor"
                    and not count_mode
                    and real_3d_slice_axis is not None
                    and real_3d_slice_value is not None
                ):
                    real_3d_slice_plot_key = (
                        f"bo_real_highlighted_2d_slice_{real_scope_key}_"
                        f"{real_metric}_{real_phase}_{real_channel_mode}_"
                        f"{real_x}_{real_y}_{real_z}_"
                        f"{real_3d_slice_token}_{real_3d_slice_sweep_token}_"
                        f"log{int(bool(real_log_frequency))}"
                    )
                    real_3d_slice_perimeter_thickness = int(
                        st.session_state.get(
                            f"{real_3d_slice_plot_key}_perimeter_thickness",
                            3,
                        )
                    )
                    highlighted_real_3d_slice_plot = st.session_state.get(
                        real_3d_slice_plot_key
                    )
                    if highlighted_real_3d_slice_plot is not None:
                        real_3d_slice_axes = (
                            highlighted_real_3d_slice_plot.get("axes", [])
                        )
                        real_3d_slice_plots = (
                            highlighted_real_3d_slice_plot.get("plots", [])
                        )

                def render_real_highlighted_slice_plot(
                    container,
                    slice_plot_index: int,
                    slice_plot: dict,
                    *,
                    show_heading: bool,
                    display_width_percent: int | None = None,
                ) -> None:
                    slice_value_label = float(slice_plot["slice_value"])
                    effective_width_percent = (
                        plot_width_percent
                        if display_width_percent is None
                        else display_width_percent
                    )
                    if show_heading:
                        series_name = slice_plot.get("series_name")
